/**
 * propValue — 属性值的形态判定、摘要，以及「契约字段名单」的描述与合并。
 *
 * ## 为什么抽出来
 *
 * 三处都要判断"这个值是不是三维量"，但用途不同：
 * - `PropTree` 用它决定渲染成横排还是折叠分组
 * - `ChunkInspector` 用它决定下层要不要拆子项（三维量必须整行横排，**不能**拆成 x / y / z 三行）
 * - `PropKeyList` 用它生成右侧摘要
 *
 * 若各写一份，规则一旦不同步就会出现"树里是横排、清单里却拆开了"这种自相矛盾的显示。
 *
 * ## 契约字段名单（`FieldSpec` / `mergeFieldEntries`）
 *
 * 块数据里只有"已经配过的"字段，而用户需要看见"这个维度还能配什么"。`FieldSpec` 就是
 * 那份"有哪些字段、各是什么形态"的描述（由 `utils/chunkTemplate` 按维度提供），
 * `mergeFieldEntries` 把它与块数据合并 —— 数据里缺的键标 `unset`，面板据此显示「未配置」行。
 *
 * 合并逻辑放这里而不是 `chunkTemplate`：它是**面板侧**的概念（决定列哪一行、用什么控件），
 * 要在 `ChunkInspector` / `PropKeyList` / `PropTree` 三处共用，放这边它们不必依赖维度表。
 *
 * @changelog
 * | 版本   | 变更说明                                              | 关联                          |
 * | v1.0.0 | 从 PropTree 抽出：三维量判定 + 单行摘要                | REQ: map-editor-chunk-editing |
 * | v1.1.0 | 新增 FieldSpec / PropEntry / mergeFieldEntries（未配置字段名单）| REQ: map-editor-chunk-editing |
 * /@changelog
 *
 * @author v_weiqinlin
 */

/** 恰好含 x / y / z 三个 number 键的对象 */
export function isXyzObject(v: unknown): v is { x: number; y: number; z: number } {
  if (typeof v !== 'object' || v === null || Array.isArray(v)) return false
  const keys = Object.keys(v)
  if (keys.length !== 3) return false
  const o = v as Record<string, unknown>
  return (
    keys.every((k) => k === 'x' || k === 'y' || k === 'z') &&
    typeof o.x === 'number' &&
    typeof o.y === 'number' &&
    typeof o.z === 'number'
  )
}

/** 长度 ≤3 且全为 number 的数组 */
export function isNumericTuple(v: unknown): v is number[] {
  return (
    Array.isArray(v) && v.length > 0 && v.length <= 3 && v.every((x) => typeof x === 'number')
  )
}

/**
 * 三维量：`[x,y,z]` 元组 或 `{x,y,z}` 对象。
 *
 * 两种写法都要认：契约里混着用 —— `shadow.followDirectional.offset` 是元组，
 * 而 `direction` / `position` 是对象，同一个清单里都有。
 */
export function isVec3(v: unknown): boolean {
  return isXyzObject(v) || isNumericTuple(v)
}

/** 值是否为可拆子项的容器（对象 / 数组，且不是三维量） */
export function isContainer(v: unknown): boolean {
  if (isVec3(v)) return false
  return Array.isArray(v) || (typeof v === 'object' && v !== null)
}

/**
 * 单行摘要：标量直接显示、容器显示项数。
 *
 * 让"这个字段有没有内容、内容大概长什么样"在清单里不点开就能判断。
 */
export function valueSummary(v: unknown): string {
  if (v === null || v === undefined) return '未设置'
  if (typeof v === 'string') return v === '' ? '(空)' : v
  if (typeof v === 'number' || typeof v === 'boolean') return String(v)
  if (Array.isArray(v)) return `${v.length} 项`
  if (typeof v === 'object') return `${Object.keys(v as object).length} 项`
  return String(v)
}

/* ---------- 契约字段名单（属性面板的「未配置」行）---------- */

/**
 * 契约里某个字段的形态描述（不含值）。
 *
 * ## 为什么形状里不带值
 *
 * 未配置字段**不写进块数据**，所以这里不能有任何"默认值"可用：`opacity = 0` 会让块
 * 全透明、`intensity = 0` 会关灯，凭空补默认值是数据污染。形状只回答"有哪些字段、
 * 各是什么形态"，值一律来自用户输入（见 `ChunkInspector.onTreeUpdate`）。
 *
 * ## `required` 的用途
 *
 * 只被 `chunkTemplate.skeletonForKind` 用来派生"新建块时写进 asset 的必填骨架"；
 * 属性面板不区分必填与可选（未配置的必填字段同样要能填上）。
 */
export type FieldSpec =
  | { kind: 'string' | 'number' | 'boolean'; required?: boolean }
  /**
   * 定长数字元组。`size` 是分量个数（契约里 vec2 / vec3 都有）；
   * `as` 决定未配置时按什么形态写回 —— `offset` / `center` 契约是元组 `[..]`，
   * 而 `direction` / `position` 是对象 `{x,y,z}`，混错了下游读不到值。默认元组。
   */
  | {
      kind: 'vec'
      size: 2 | 3
      as?: 'tuple' | 'object'
      required?: boolean
    }
  | { kind: 'object'; required?: boolean; fields: Record<string, FieldSpec> }
  /**
   * 数组。**只描述到"这是一行数组"为止**：元素增删不在属性面板范围内，
   * 面板对它的处理是列一行 + 提示去 JSON 模式（见 `PropTree` 的未配置分支）。
   */
  | { kind: 'array'; required?: boolean }

/** 属性面板的一行（上半段清单与下半段值区共用） */
export interface PropEntry {
  /** 字段名（对象键）或数组下标 */
  key: string | number
  /** 值；`unset` 为 true 时是 undefined */
  value: unknown
  /** 契约里有、块数据里还没有：面板显示「未配置」，用户填了才写进数据 */
  unset?: boolean
  /**
   * 本行是一组字段的**开始**：面板在它上方画一条分隔线。
   *
   * 用来区分"块级字段"（`id` / `shape`，五个维度都有）与"该维度特有的字段" ——
   * 两块混在一起排，用户看不出哪些是每块都有的、哪些是这个清单独有的。
   */
  groupStart?: boolean
}

/**
 * 合并「块数据里已有的键」与「契约字段名单」。
 *
 * 已有键按原顺序在前（保住 JSON 里的字段顺序），契约里缺的键追加在后并标 `unset` ——
 * 两段式清单因此天然呈现"配过的在前、待配的在后"，用户扫一眼就知道还差什么。
 *
 * `fields` 为空（工具栏模板是 `auto`）时原样返回已有键，即退化为"只展示数据里有的字段"。
 */
export function mergeFieldEntries(
  actual: Record<string, unknown> | undefined,
  fields?: Record<string, FieldSpec>
): PropEntry[] {
  const entries: PropEntry[] = []
  const seen = new Set<string>()
  for (const [key, value] of Object.entries(actual ?? {})) {
    seen.add(key)
    entries.push({ key, value })
  }
  for (const key of Object.keys(fields ?? {})) {
    if (seen.has(key)) continue
    entries.push({ key, value: undefined, unset: true })
  }
  return entries
}
