<script setup lang="ts">
/**
 * PropKeyList — 属性面板**上半段**：该块的顶层字段清单。
 *
 * ## 为什么单独一层清单，而不是把所有字段摊平成一棵树
 *
 * 这是照 meta 编辑器「场景层级 + 属性面板」的两段式：上面先把全部顶层字段一眼看全
 * （带值摘要），点哪一个、下面就编辑哪一个。
 *
 * 摊平成一棵树时，light 这种有 10 个子块的维度要滚很久才能翻到目标字段；而清单把
 * 每个字段压成一行，一屏就能看完整块的结构。
 *
 * ## 右侧摘要
 *
 * 标量直接显示值、容器显示项数 —— 让"有没有内容、内容大概是什么样"不点开就能判断。
 * 长值（如 url）靠 `title` 悬停看全。
 *
 * ## 未配置行
 *
 * 契约里有、块数据里还没有的字段（`unset`）以灰色排在末尾，摘要固定显示「未配置」，
 * 并在这一组的第一行前插一条标题写明来源。**必须标明是"未配置"**：不标的话用户会以为
 * 文件里本来就有这个字段（而它其实还不存在，只是契约允许配），从而误判清单内容。
 *
 * ## 字号与列宽是四处联动的
 *
 * 本组件的 `6rem` 左列 / `text-[14px]` 与 `PropRow` / `PropGroup` / `PropTree` 必须一致 ——
 * 上下两段的行对不齐时，眼睛会误读成"两套不同的列表"。要调字号就四处一起调
 * （用户已两次反馈字号偏小，故当前基准是 14px 而非最初的 11px）。
 *
 * @changelog
 * | 版本   | 变更说明                                          | 关联                          |
 * | v1.0.0 | 初始实现：顶层字段清单（值摘要 + 点选高亮）         | REQ: map-editor-chunk-editing |
 * | v1.1.0 | entries 改收 PropEntry[]：新增未配置行与分组标题    | REQ: map-editor-chunk-editing |
 * | v1.2.0 | 字号放大到 14px（键）/ 13px（摘要），左列 4.5rem→6rem | REQ: map-editor-chunk-editing |
 * | v1.3.0 | 支持分组分隔线（块级字段与维度字段分开显示）              | REQ: map-editor-chunk-editing |
 * /@changelog
 *
 * @author v_weiqinlin
 */
import { computed } from 'vue'
import { valueSummary, type PropEntry } from '../utils/propValue'

const props = defineProps<{
  /** 字段行：顺序即渲染顺序（调用方保证已配置在前、未配置在后） */
  entries: PropEntry[]
  /** 当前选中的字段名 */
  selected: string
}>()

const emit = defineEmits<{
  /** 点选了某个字段 */
  (e: 'select', key: string): void
}>()

/**
 * 渲染行 = 原字段行 + 两个由位置决定的装饰：
 *
 * - `divider`：调用方标了 `groupStart` 的行，上方画一条分隔线（块级字段 / 维度字段的分界）
 * - `unsetTitle`：未配置组的第一行，上方插一条「模板字段 · 未配置」标题
 *
 * 在模板里靠下标去比较前后两行会把逻辑塞进模板，且 `v-for` 里的下标比较可读性差；
 * 预先算成数据，模板只管渲染。
 */
const rows = computed(() =>
  props.entries.map((entry, i) => ({
    ...entry,
    divider: entry.groupStart === true && i > 0,
    unsetTitle: entry.unset === true && props.entries[i - 1]?.unset !== true
  }))
)
</script>

<template>
  <div class="flex flex-col">
    <template v-for="row in rows" :key="row.key">
      <!--
        组间分隔线：上面是块级字段（id / shape，五个维度都有），下面是这份清单维度特有的
        字段。不分开的话，两者混排看不出"哪些每块都有、哪些是这个维度才有的"。
      -->
      <div v-if="row.divider" class="my-1.5 border-t border-white/10" />

      <!-- 未配置分组标题：说明这几行的来源与"尚未写入"的事实 -->
      <div
        v-if="row.unsetTitle"
        class="px-1.5 pt-2 pb-1 font-mono text-[12px] tracking-wide text-slate-600"
        title="这些字段来自这份清单的维度（契约里有），块数据里还没有；填入后才会写进块数据"
      >
        模板字段 · 未配置
      </div>

      <button
        type="button"
        class="w-full grid grid-cols-[6rem_minmax(0,1fr)] gap-2 items-center min-h-[30px] py-1 pl-1.5 text-left cursor-pointer transition-colors border-l-2"
        :class="
          String(row.key) === selected
            ? 'border-violet-400 bg-violet-500/15'
            : 'border-transparent hover:bg-white/[0.04]'
        "
        :title="
          row.unset
            ? `${String(row.key)} — 未配置（填入后写入块数据）`
            : `${String(row.key)} = ${valueSummary(row.value)}`
        "
        @click="emit('select', String(row.key))"
      >
        <span
          class="min-w-0 truncate font-mono text-[14px]"
          :class="
            row.unset
              ? 'text-slate-500'
              : String(row.key) === selected
                ? 'text-violet-200'
                : 'text-slate-300'
          "
        >
          {{ row.key }}
        </span>
        <span
          class="min-w-0 truncate font-mono text-[13px]"
          :class="row.unset ? 'text-slate-600' : 'text-slate-500'"
        >
          {{ row.unset ? '未配置' : valueSummary(row.value) }}
        </span>
      </button>
    </template>
  </div>
</template>
