/**
 * usePolyToModule — 把 navmesh polygon 集合映射到 module。
 *
 * 设计要点：
 * - 用 polygon centroid 与 module.worldBox 的 AABB 命中判定做"归属"。这是已知会
 *   在跨 module 边界 polygon 上误判的简化策略，对实验对比工具足够；UI 上单独显示
 *   `crossModulePolyCount` 提示用户哪些 polygon 跨模块。
 * - "跨模块"定义：检查 polygon 的 4 个角点（取 bmin/bmax 的 XZ 四角，Y 取中点）
 *   是否分别落在不同的 module 里；只要有 ≥2 个角点归属不同 module，就计入
 *   `crossModulePolyCount`。这种探测方式开销小（每 poly 4 次 module 命中），且不
 *   引入"完整多边形 vs AABB 求交"的复杂度。
 * - **可达 module**：reachable polyRef 集合命中到的 module。
 * - **不可达 module**：被 navmesh 覆盖（即有任意 polygon centroid 落在内）但不在
 *   reachable 集合内的 module。用于 UI 上的"绿色 vs 红色"对比高亮。
 * - 仅依赖 ModuleRuntime.worldBox（与 group 加载状态无关），所以即便 collision
 *   GLB 还没加载完，只要 manifest 已提供 worldBox 就能映射。
 *
 * @changelog
 * | 版本   | 变更说明                                                      | 关联                                                       |
 * | v1.0.0 | 初始实现：polygon centroid → module AABB 命中 + 跨模块统计   | REQ: navmesh-experiment-page TECH: plan §关键技术决策     |
 * /@changelog
 *
 * @author linfan
 */
import type { ModuleRuntime } from '../types/modules'
import type { PolyRecord } from '../stores/navmesh'

export interface PolyToModuleResult {
  /** polyRef → moduleName 的映射（仅 centroid 命中的；未命中的 poly 不在 map 中） */
  polyModuleMap: Map<number, string>
  /** 可达 module（按 ModuleRuntime.name 索引） */
  reachableModuleIds: Set<string>
  /** 被 navmesh 覆盖但不可达的 module（绿/红对比用） */
  unreachableModuleIds: Set<string>
  /** 每 module 的统计：polygon 总数 / 可达 polygon 数 */
  perModuleStats: Map<string, { total: number; reachable: number }>
  /** 跨 module 边界的 polygon 数（角点归属不一致） */
  crossModulePolyCount: number
}

/**
 * 主映射入口。
 *
 * @param polygons         烘焙产出的所有 polygon
 * @param reachablePolyRefs flood fill 输出的可达集合
 * @param modules          所有 module（必须有有效 worldBox；未加载完的 module 也会参与）
 */
export function mapPolyToModule(
  polygons: PolyRecord[],
  reachablePolyRefs: Set<number>,
  modules: ModuleRuntime[]
): PolyToModuleResult {
  const polyModuleMap = new Map<number, string>()
  const reachableModuleIds = new Set<string>()
  const perModuleStats = new Map<string, { total: number; reachable: number }>()
  const coveredModuleIds = new Set<string>()
  let crossModulePolyCount = 0

  // 预收集 worldBox 不为空的 module（empty worldBox 的 module 无法做命中）
  const candidates = modules.filter((m) => !m.worldBox.isEmpty())
  if (candidates.length === 0 || polygons.length === 0) {
    return {
      polyModuleMap,
      reachableModuleIds,
      unreachableModuleIds: new Set(),
      perModuleStats,
      crossModulePolyCount: 0
    }
  }

  // 临时变量复用，减少 GC
  for (const poly of polygons) {
    const { centroid } = poly
    // 1) centroid 命中：找第一个 AABB 包含 centroid 的 module
    const hitName = findContainingModule(candidates, centroid.x, centroid.z)
    if (hitName) {
      polyModuleMap.set(poly.ref, hitName)
      coveredModuleIds.add(hitName)

      // 累计统计
      let stat = perModuleStats.get(hitName)
      if (!stat) {
        stat = { total: 0, reachable: 0 }
        perModuleStats.set(hitName, stat)
      }
      stat.total += 1

      if (reachablePolyRefs.has(poly.ref)) {
        stat.reachable += 1
        reachableModuleIds.add(hitName)
      }
    }

    // 2) 跨模块检测：取 bmin/bmax 的 XZ 四角，看归属是否一致
    //    （只看 XZ；Y 用 centroid.y 避开高度差影响）
    if (hitName) {
      const corners: Array<[number, number]> = [
        [poly.bmin.x, poly.bmin.z],
        [poly.bmin.x, poly.bmax.z],
        [poly.bmax.x, poly.bmin.z],
        [poly.bmax.x, poly.bmax.z]
      ]
      let crossed = false
      for (const [cx, cz] of corners) {
        const cornerHit = findContainingModule(candidates, cx, cz)
        if (cornerHit && cornerHit !== hitName) {
          crossed = true
          break
        }
      }
      if (crossed) crossModulePolyCount += 1
    }
  }

  // 不可达 = 被 navmesh 覆盖但不在 reachable 集合
  const unreachableModuleIds = new Set<string>()
  for (const name of coveredModuleIds) {
    if (!reachableModuleIds.has(name)) {
      unreachableModuleIds.add(name)
    }
  }

  return {
    polyModuleMap,
    reachableModuleIds,
    unreachableModuleIds,
    perModuleStats,
    crossModulePolyCount
  }
}

/**
 * 在 candidates 中找第一个 XZ AABB 包含 (x, z) 的 module，返回 name；无命中返回 null。
 *
 * 注意：仅判 XZ，忽略 Y。多层楼场景同一 (x, z) 可能落在多个 module 的 worldBox 里，
 * 这里取数组中的"第一个命中"。对实验对比工具足够；如果将来需要按 Y 区分，把 centroid.y
 * 也带进来加 Y 范围判定即可。
 */
function findContainingModule(
  candidates: ModuleRuntime[],
  x: number,
  z: number
): string | null {
  for (const m of candidates) {
    const box = m.worldBox
    if (
      x >= box.min.x &&
      x <= box.max.x &&
      z >= box.min.z &&
      z <= box.max.z
    ) {
      return m.name
    }
  }
  return null
}
