<script setup lang="ts">
/**
 * SubFlowToolbar — 子流程切换栏（横跨场景查看区 + 属性面板上方）。
 *
 * ## 职责边界
 *
 * 此组件负责**切换子流程**，并提供一条横条承载**当前子流程的产物操作**：
 *
 * ```
 * [子流程下拉] │ [导出 .bin]              ← bin
 * [子流程下拉] │ [选起点][选终点][导出可达区] ← reach
 * [子流程下拉] │ [切块参数 ▾][清除切块]     ← chunk
 * ```
 *
 * 依据界面布局约定：
 * - 标题栏：存档导入导出等基础操作；
 * - 左侧主流程区：**仅主流程**（导入 GLB → 烘焙 navmesh → 生成中线），恒定不变；
 * - 本栏：切换子流程 + 承载该子流程的产物操作（操作由 `#default` 插槽注入）；
 * - 中间：场景查看；右侧：属性面板（未开发）。
 *
 * 操作之所以在这里而不是左栏：左栏的含义是"主流程步骤"，导出类操作混进去会
 * 让同一个区域既像流程又像工具箱；也不能放右侧，右栏是留给"选中对象属性"的。
 * 子流程状态仍在 store：本组件负责写入，`NavmeshView` 监听它并同步插槽内容与场景附加物可见性。
 *
 * ## 为什么下拉是自绘而不是原生 `<select>`
 *
 * 原生 `<select>` 的展开面板由操作系统 / 浏览器绘制，深色主题下的 option 样式不可控。
 * 用"按钮 + 绝对定位列表"才能与暗色玻璃视觉统一。
 *
 * @changelog
 * | 版本   | 变更说明                                                        | 关联                     |
 * | v1.0.0 | 初始实现：子流程下拉（4 项）+ actions / view 双插槽               | REQ: map-editor-ui-shell |
 * | v1.1.0 | 原生 select 换自绘下拉：暗色玻璃风格 + 勾选态 + 外点/Esc 关闭      | REQ: map-editor-ui-shell |
 * | v2.0.0 | 按界面布局收敛职责：移除 actions / view 插槽，仅保留子流程切换     | REQ: map-editor-ui-shell |
 * | v2.1.0 | 明确分工：子流程产物操作归本栏，左栏只留主流程步骤，右栏留给属性     | REQ: map-editor-ui-shell |
 * | v2.2.0 | 重新引入默认插槽承载子流程产物操作（导出 bin / 可达区 / chunk）      | REQ: map-editor-ui-shell |
 * /@changelog
 *
 * @author linfan
 */
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { Check, ChevronDown, Workflow } from 'lucide-vue-next'
import {
  SUB_FLOW_LABELS,
  SUB_FLOW_ORDER,
  useNavmeshStore,
  type SubFlow
} from '../stores/navmesh'

const store = useNavmeshStore()
const options = SUB_FLOW_ORDER.map((f) => ({ key: f, label: SUB_FLOW_LABELS[f] }))
const currentLabel = computed(() => SUB_FLOW_LABELS[store.subFlow])

const open = ref(false)
const rootRef = ref<HTMLElement | null>(null)

function pick(f: SubFlow) {
  store.setSubFlow(f)
  open.value = false
}

function onDocMouseDown(e: MouseEvent) {
  if (!open.value) return
  const el = rootRef.value
  if (el && !el.contains(e.target as Node)) open.value = false
}

function onDocKeydown(e: KeyboardEvent) {
  if (e.key === 'Escape') open.value = false
}

onMounted(() => {
  document.addEventListener('mousedown', onDocMouseDown)
  document.addEventListener('keydown', onDocKeydown)
})
onBeforeUnmount(() => {
  document.removeEventListener('mousedown', onDocMouseDown)
  document.removeEventListener('keydown', onDocKeydown)
})
</script>

<template>
  <div
    class="shrink-0 flex items-center px-2 py-1 rounded-xl bg-black/30 border border-white/10 backdrop-blur-glass"
  >
    <div ref="rootRef" class="relative shrink-0">
      <button
        type="button"
        class="flex items-center gap-1.5 pl-2 pr-1.5 py-1 rounded-md text-[11px] font-medium border transition-colors cursor-pointer"
        :class="
          open
            ? 'bg-cyan-glow/10 border-cyan-glow/60 text-cyan-glow'
            : 'bg-white/5 border-white/10 text-slate-200 hover:border-cyan-glow/50'
        "
        aria-haspopup="listbox"
        :aria-expanded="open"
        title="切换子流程：切换时场景查看区的附加物会按该流程的默认可见性重放"
        @click="open = !open"
      >
        <Workflow
          class="w-3.5 h-3.5 shrink-0"
          :class="open ? 'text-cyan-glow' : 'text-cyan-glow/70'"
        />
        <span class="min-w-[3.5rem] text-left">{{ currentLabel }}</span>
        <ChevronDown
          class="w-3 h-3 shrink-0 transition-transform"
          :class="open ? 'rotate-180' : ''"
        />
      </button>

      <ul
        v-if="open"
        class="absolute left-0 top-full mt-1 z-40 min-w-full py-1 rounded-lg border border-white/10 bg-[#0b1120]/95 backdrop-blur-glass shadow-glass animate-fade-in"
        role="listbox"
      >
        <li v-for="o in options" :key="o.key">
          <button
            type="button"
            class="w-full flex items-center gap-1.5 px-2.5 py-1.5 text-[11px] whitespace-nowrap transition-colors cursor-pointer"
            :class="
              o.key === store.subFlow
                ? 'text-cyan-glow bg-cyan-glow/10'
                : 'text-slate-300 hover:text-slate-100 hover:bg-white/5'
            "
            role="option"
            :aria-selected="o.key === store.subFlow"
            @click="pick(o.key)"
          >
            <Check v-if="o.key === store.subFlow" class="w-3 h-3 shrink-0" />
            <span v-else class="w-3 shrink-0" />
            {{ o.label }}
          </button>
        </li>
      </ul>
    </div>

    <!--
      当前子流程的产物操作（导出 bin / 可达区 / chunk 切块参数）。
      由编排层注入，本组件只提供容器与样式 —— 保持"工具栏承载子流程操作"的分工。
    -->
    <slot />
  </div>
</template>
