/**
 * useNavmeshDataExport — 把烘焙出的 navmesh 导出为 Detour 导航数据（.bin）。
 *
 * 为什么是二进制而不是 glb：glb 只是「导航多边形的三角面几何」，丢失 Detour 的
 * poly / link / tile 拓扑，运行时无法直接寻路。真正的导航数据是 recast-navigation
 * 的 `exportNavMesh()` 产物（Detour NAVMESHDATA 序列化），运行时用
 * `importNavMesh(data)` → `new NavMeshQuery(navMesh)` 即可直接寻路。
 *
 * 关键设计：
 * - 复用烘焙产物 `NavMesh` 实例本身（store.navMeshRef），无需额外的几何转换。
 * - `exportNavMesh` / `importNavMesh` 由 recast-navigation 顶层导出（内部走
 *   @recast-navigation/core 的 serdes），与烘焙所用 wasm 同一份，版本自洽。
 * - **导出后立即反序列化自校验**：`.bin` 二进制肉眼无法检查，若数据损坏或
 *   序列化异常，问题会拖到运行时才暴露。这里用 importNavMesh 往返一次，
 *   确认「可重建 + 能读到 polygon」，并把 poly 数回传供 UI 提示。
 * - 同步导出（无异步），失败直接抛出交由调用方提示。
 *
 * @changelog
 * | 版本   | 变更说明                                                          | 关联                                 |
 * | v1.0.0 | 初始实现：navmesh 导出 Detour 导航数据（.bin）                     | REQ: navmesh-editor-meta-integration |
 * | v1.1.0 | 新增导出后自校验：importNavMesh 往返反序列化 + 统计 polygon 数     | REQ: navmesh-editor-meta-integration |
 * | v1.2.0 | 下载逻辑抽到 utils/download，与可达区 / 存档导出共用一份实现         | REQ: map-editor-ui-shell |
 * /@changelog
 *
 * @author v_weiqinlin
 */
import { exportNavMesh, importNavMesh, type NavMesh } from 'recast-navigation'
import { triggerDownload } from '../utils/download'

export interface NavmeshExportResult {
  /** 导出字节数 */
  bytes: number
  /** 自校验（反序列化）读到的 polygon 数；未通过为 0 */
  polyCount: number
  /** 自校验是否通过：反序列化成功且能读到 polygon */
  verified: boolean
}

/**
 * 导出 navmesh 为 Detour 导航数据二进制并触发浏览器下载（含自校验）。
 *
 * @param navMesh 当前烘焙产物实例（store.navMeshRef）
 * @param filename 缺省为 navmesh-<timestamp>.bin
 * @returns 导出结果（字节数 + 自校验结果）
 */
export function exportNavmeshData(navMesh: NavMesh, filename?: string): NavmeshExportResult {
  const data = exportNavMesh(navMesh)
  if (!data || data.byteLength === 0) {
    throw new Error('exportNavMesh 返回空数据')
  }

  // TS 下 Uint8Array<ArrayBufferLike> 不满足 BlobPart（可能被推断为 SharedArrayBuffer），
  // 显式切出独立 ArrayBuffer 段（slice 会拷贝一份，避免与 wasm 内存视图共享生命周期）
  const buffer = data.buffer.slice(
    data.byteOffset,
    data.byteOffset + data.byteLength
  ) as ArrayBuffer
  const blob = new Blob([buffer], { type: 'application/octet-stream' })
  triggerDownload(blob, filename ?? `navmesh-${tsLabel()}.bin`)

  const verify = verifyExportedData(data)
  return { bytes: data.byteLength, polyCount: verify.polyCount, verified: verify.ok }
}

/**
 * 自校验：把导出的字节流立刻反序列化一次，确认可用。
 *
 * 注意 poly 数**不做**与 PolyRecord 数的严格相等断言——PolyRecord 提取时跳过了
 * off-mesh connection 与 flags===0 的 polygon（见 useNavmeshBaker.extractPolygons），
 * 而这里统计的是 tile 内 polygon 总数，两者语义不同，强比会误报。
 * 此处只保证「反序列化成功且读到 polygon」。
 */
function verifyExportedData(data: Uint8Array): { ok: boolean; polyCount: number } {
  let imported: NavMesh | null = null
  try {
    imported = importNavMesh(data)?.navMesh ?? null
    if (!imported) return { ok: false, polyCount: 0 }
    const polyCount = countPolys(imported)
    return { ok: polyCount > 0, polyCount }
  } catch (e) {
    console.warn('[navmesh] 导出数据自校验失败（反序列化异常）', e)
    return { ok: false, polyCount: 0 }
  } finally {
    try {
      imported?.destroy()
    } catch {
      /* no-op：校验副本释放失败不影响导出结果 */
    }
  }
}

/** 统计 navmesh 内所有 tile 的 polygon 数 */
function countPolys(navMesh: NavMesh): number {
  let count = 0
  const maxTiles = navMesh.getMaxTiles()
  for (let tileIdx = 0; tileIdx < maxTiles; tileIdx++) {
    const tile = navMesh.getTile(tileIdx)
    const header = tile.header()
    if (!header) continue
    count += header.polyCount()
  }
  return count
}

function tsLabel(): string {
  return new Date().toISOString().replace(/[:.]/g, '-').replace('T', '_').slice(0, 19)
}
