/**
 * 全局注入 three-mesh-bvh 加速 Raycaster。
 *
 * 作用：
 *  - 给 `BufferGeometry` 装 `computeBoundsTree / disposeBoundsTree`
 *  - 把 `Mesh.prototype.raycast` 替换成基于 BVH 的加速版本
 *  - 之后任何 mesh 只要其 geometry.boundsTree 存在，Raycaster 就走 O(log n) 路径
 *
 * 为什么独立成一个文件 + 在 main.ts 顶部 import：
 *   - 必须在任何 Mesh/Raycaster 真正被使用之前打补丁，否则 `Mesh.prototype.raycast`
 *     已经被部分实例缓存到原型链查找时机外（这种情况极少，但保险起见放到入口）
 *
 * 性能数字（地形 mesh 50 万面级）：
 *   - 原生（无 BVH）：单次 Raycaster.intersectObjects ~0.2~0.3ms
 *   - 加 BVH 后：单次 ~0.005~0.02ms（10~50× 提升）
 *   - 落到"计算邻接"流程：栅格化 + 段落检测 raycast 总量 ~9w 次 →
 *     由 ~21s 降到 <2s
 *
 * 副作用 / 注意：
 *   1) `computeBoundsTree()` 本身有一次性开销（50w 面约 200~600ms，分摊到加载阶段一次），
 *      之后所有 raycast 复用。
 *   2) `boundsTree` 会随 geometry 留在内存；卸载 mesh 时调用 `disposeBoundsTree()` 释放。
 *   3) 我们**不**开 `firstHitOnly`：栅格化与段落检测都依赖"穿过屋顶取下层地面"，
 *      需要完整 hits 列表，BVH 仍能在收集所有 hits 时做空间剪枝，加速依然显著。
 */

import { BufferGeometry, Mesh } from 'three'
import {
  acceleratedRaycast,
  computeBoundsTree,
  disposeBoundsTree
} from 'three-mesh-bvh'

// 扩展 BufferGeometry 的方法：computeBoundsTree / disposeBoundsTree
// 用 any 是因为 three-mesh-bvh 的类型补丁并不通过 module augmentation 自动合并到 three 的类型
;(BufferGeometry.prototype as unknown as {
  computeBoundsTree: typeof computeBoundsTree
  disposeBoundsTree: typeof disposeBoundsTree
}).computeBoundsTree = computeBoundsTree
;(BufferGeometry.prototype as unknown as {
  computeBoundsTree: typeof computeBoundsTree
  disposeBoundsTree: typeof disposeBoundsTree
}).disposeBoundsTree = disposeBoundsTree

// 用 BVH 加速的 raycast 替换默认实现
//
// 类型断言原因：
//   仓库内可能同时存在多份 `@types/three`（本子包私有 + workspace 根 hoisted），
//   `three-mesh-bvh` 解析到的 `Raycaster / BufferAttribute / Vector3 / ...` 与
//   本子包从 'three' 解析到的同名类型来自不同路径，TS 视作名义上不同的类型
//   （甚至 `BufferAttribute.id` 字段在两个版本间还有 optional 差异），赋值会报错。
//   运行期只有一个 three 实例，签名完全一致；这里做一次结构等价断言即可。
//   根治办法是统一 workspace 中 `@types/three` 版本（属于依赖治理，不在本次改动范围）。
Mesh.prototype.raycast = acceleratedRaycast as unknown as typeof Mesh.prototype.raycast
