/**
 * useNavmeshPreview — Navmesh 实验台的 3D 预览渲染 hook（轻量版）。
 *
 * 与 usePreview 的区别：
 * - usePreview 强耦合 anchor 系统，所以单开一份给 navmesh 用
 * - 同样基于 useThreeScene 提供的全局 scene（这样地形 GLB 自动可见）
 * - 暴露拾取回调：onPick(worldPoint)，用于起点/终点选择
 *
 * 设计：
 * - 起独立 WebGLRenderer + PerspectiveCamera + OrbitControls
 * - 复用全局 scene（terrain GLB 已在其中）
 * - mount 时根据 terrain bbox / module bbox 自动 frame
 * - click 事件做 raycaster pick → 调用 options.onPick(point)
 *
 * 两类交互叠加在同一个画布上，顺序固定为「叠加物 → 地表」：
 * 1. `onPickOverlay`：先给切块等叠加物一次机会（点中块就选中该块）
 * 2. `onPick`：都没命中时才落到地表拾取（起点 / 终点 / 补线）
 * 否则块浮在地表之上却永远点不中。
 *
 * 另提供 `chunkGizmo`：单块拖动用的 TransformControls（平移 / 绕 Y 旋转 / 缩放）。
 * 它在**拖动结束**才回调 commit，拖动中只走 onDrag —— 避免每帧写 store、重绘整批块。
 *
 * @changelog
 * | 版本   | 变更说明                                                          | 关联                          |
 * | v1.0.0 | 从 usePreview 分出 navmesh 专用预览：拾取地表点用于起点/终点        | REQ: navmesh-editor          |
 * | v1.1.0 | 新增 onPickOverlay（叠加物优先拾取）与 chunkGizmo（单块拖动）      | REQ: map-editor-chunk-editing |
 * | v1.2.0 | 新增 WASD 键盘移动相机（Q/E 升降、Shift 加速），解决远端 chunk 视角到不了 | REQ: map-editor-ui-shell |
 * | v1.3.0 | focusBox 支持平滑飞行；新增 project（世界→屏幕）与 onAfterRender（标签跟随）| REQ: map-editor-chunk-editing |
 * | v1.4.0 | 拖动姿态支持三轴（rotation 三元组贯通）；手柄回到默认大小；旋转改用局部参考系（拖单轴只改单个角度） | REQ: map-editor-chunk-editing |
 * | v1.4.1 | 撤销"单轴约束"：强制只改一个欧拉分量会让转轴偏离用户拖的环（向下拖却左右转）；数值联动是欧拉角表示法的固有现象，用属性面板输入角度可精确控制 | REQ: map-editor-chunk-editing |
 * /@changelog
 *
 * @author linfan
 */
import { onBeforeUnmount, onMounted, watch } from 'vue'
import {
  Box3,
  GridHelper,
  type Mesh,
  Object3D,
  PerspectiveCamera,
  Raycaster,
  Vector2,
  Vector3,
  WebGLRenderer
} from 'three'
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js'
import { TransformControls } from 'three/examples/jsm/controls/TransformControls.js'
import { useThreeScene } from './useThreeScene'
import { useTerrainStore } from '../stores/terrain'
import { useModulesStore } from '../stores/modules'

/**
 * 相机远裁剪面（米）。
 *
 * 为什么定成常量而不是各处写死：`frameCamera` / `focusBox` 都会按场景尺寸重设 `far`，
 * 只在构造时改一次会被随后的自适应覆盖掉 —— 远处地形在缩放时突然被裁掉，很难查。
 * 公里级地图（如 sanyapo 那种几千单位跨度的场景）必须留够余量。
 */
const CAMERA_FAR = 10000

/**
 * 相机键盘移动的按键（`event.code`）。
 *
 * W/A/S/D 水平前后左右，Q/E 升降（3D 工具惯例）；Shift 作为加速修饰键。
 * 用 `code` 而非 `key`：后者受键盘布局与输入法影响 —— 中文输入法下 `key` 可能不是 'w'。
 */
const MOVE_KEYS = new Set(['KeyW', 'KeyA', 'KeyS', 'KeyD', 'KeyQ', 'KeyE'])
const SPEED_UP_KEYS = new Set(['ShiftLeft', 'ShiftRight'])

/** 按住 Shift 时的速度倍数（跨场景快速穿越用） */
const SPEED_UP_FACTOR = 8

export interface NavmeshPreviewOptions {
  canvasRef: () => HTMLCanvasElement | null
  containerRef: () => HTMLElement | null
  /** 用户点击地表时回调（命中世界坐标） */
  onPick?: (point: { x: number; y: number; z: number }) => void
  /**
   * 叠加物优先拾取：点击时**先**给这里一次机会（例如点中切块 → 选中该块）。
   *
   * 返回 true = 本次点击已被消费，不再落到地表拾取。
   * 为什么需要这一层：块浮在地表之上，若先做地表拾取就永远点不中块；而射线只能在这里算
   * （相机 / 画布由本 hook 持有）。
   */
  onPickOverlay?: (ctx: {
    origin: { x: number; y: number; z: number }
    dir: { x: number; y: number; z: number }
  }) => boolean
  /**
   * 点击**没落到地面**时（天空 / 场景外）的回调。
   *
   * 为什么需要：`onPickOverlay` 在"放块模式"下会让路（否则点哪都被块抢走、永远放不下新块），
   * 于是"点空白"这条路没人管 —— 选中与坐标轴会一直挂在那儿，点几次都收不起来。
   */
  onPickMiss?: () => void
}

/**
 * 块拖动 gizmo 的实时参数。
 *
 * `rotation` 是**弧度、Three 手性**（与 `gizmoProxy.rotation` 直接一致、也与
 * `RenderChunk.rotation` 一致）—— 手性转换只在"进 / 出编辑器数据"的两个边界做：
 * 读 `ChunkItem` 时取负（`itemToRenderChunk`）、写回时再取负（`applyGizmoPatch`）。
 * 中间整条链保持同一约定，避免多处各修一次、正好抵消。
 */
export interface ChunkGizmoPatch {
  center: { x: number; y: number; z: number }
  size: number
  height: number
  rotation: { x: number; y: number; z: number }
}

/** 拖动模式：平移 / 绕 Y 旋转 / 缩放 */
export type ChunkGizmoMode = 'translate' | 'rotate' | 'scale'

export interface ChunkGizmoHandle {
  /** 设置（或清除）拖动目标；target = null 时隐藏 gizmo */
  setTarget(target: ChunkGizmoPatch | null, mode?: ChunkGizmoMode): void
  /** 拖动过程中的实时回调（用于实时重绘，不写 store） */
  onDrag(fn: ((patch: ChunkGizmoPatch) => void) | null): void
  /** 拖动结束的回调（此时才写回 store） */
  onCommit(fn: ((patch: ChunkGizmoPatch) => void) | null): void
}

export function useNavmeshPreview({
  canvasRef,
  containerRef,
  onPick,
  onPickOverlay,
  onPickMiss
}: NavmeshPreviewOptions) {
  const { scene } = useThreeScene()
  const terrainStore = useTerrainStore()
  const modulesStore = useModulesStore()

  let renderer: WebGLRenderer | null = null
  let camera: PerspectiveCamera | null = null
  let controls: OrbitControls | null = null
  let grid: GridHelper | null = null
  let rafId = 0
  let resizeObserver: ResizeObserver | null = null
  let hasFramedOnce = false
  let clickHandler: ((e: MouseEvent) => void) | null = null
  let pointerDownHandler: ((e: PointerEvent) => void) | null = null
  let moveKeyDownHandler: ((e: KeyboardEvent) => void) | null = null
  let moveKeyUpHandler: ((e: KeyboardEvent) => void) | null = null
  let blurHandler: (() => void) | null = null
  /**
   * 最近一次 pointerdown 的位置：用于把"点击"与"拖动"分开。
   *
   * 为什么必须分：按下与抬起都落在 canvas 上时，浏览器**无论中间移动多远都会补一个 click**。
   * 于是"按住左键旋转相机"也会被当成"点了一下空地"→ 取消选中，这与用户意图相反。
   */
  const pointerDownPos = { x: 0, y: 0 }

  /* ---------- 单块拖动 gizmo ---------- */
  let gizmo: TransformControls | null = null
  let gizmoProxy: Object3D | null = null
  let gizmoMode: ChunkGizmoMode = 'translate'
  /** 拖动开始时的块参数：缩放 / 旋转要按比例换算回去，必须记住基准 */
  let gizmoBase: ChunkGizmoPatch | null = null
  let onGizmoDrag: ((patch: ChunkGizmoPatch) => void) | null = null
  let onGizmoCommit: ((patch: ChunkGizmoPatch) => void) | null = null
  /**
   * 手柄松开的时间戳：用来吞掉紧随其后的那次 `click`。
   *
   * 为什么必须吞：pointerdown / pointerup 落在同一个 canvas 上时，浏览器还会补发一个
   * `click`；而拾取是挂在 `click` 上的，于是"松手"会被当成"点击松手位置"——
   * 那里若是别的块就跳过去、若是空地就取消选中。
   */
  let gizmoReleaseAt = 0

  /**
   * 相机平滑飞行状态（`focusBox(box, true)` 用）。
   *
   * 为什么按「时长 + 归一化进度」而不是每帧固定插值系数：后者在 60fps 与 120fps 下的
   * 实际飞行时长不一致 —— 高刷屏上"嗖"地到位，用户看不出是从哪飞到哪的。
   */
  let camTween: {
    fromPos: Vector3
    toPos: Vector3
    fromTarget: Vector3
    toTarget: Vector3
    t: number
    dur: number
  } | null = null

  /** 飞行时长（秒）：再短看不出方向、再长显得拖沓 */
  const FLY_SECONDS = 0.45

  /** 每帧渲染后的回调（地块名字标签跟随投影用） */
  let afterRenderFn: (() => void) | null = null

  const projV = new Vector3()

  const raycaster = new Raycaster()
  const mouseNDC = new Vector2()

  function fitCanvas() {
    if (!renderer || !camera || !containerRef()) return
    const c = containerRef() as HTMLElement
    const w = c.clientWidth
    const h = c.clientHeight
    if (w <= 0 || h <= 0) return
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2))
    renderer.setSize(w, h, false)
    camera.aspect = w / h
    camera.updateProjectionMatrix()
  }

  function computeFitBox(): Box3 | null {
    // 优先用 modules merged box；其次用 terrain merged box
    if (modulesStore.mergedCollisionBox && !modulesStore.mergedCollisionBox.isEmpty()) {
      return modulesStore.mergedCollisionBox.clone()
    }
    const box = new Box3()
    let inited = false
    for (const t of terrainStore.terrains) {
      if (t.box.isEmpty()) continue
      if (!inited) {
        box.copy(t.box)
        inited = true
      } else {
        box.union(t.box)
      }
    }
    return inited ? box : null
  }

  function frameCamera(force = false) {
    if (!camera || !controls) return
    const box = computeFitBox()
    if (!box) return
    const center = new Vector3()
    box.getCenter(center)
    const size = new Vector3()
    box.getSize(size)
    const maxSize = Math.max(size.x, size.y, size.z) || 1
    const dist = maxSize * 1.6

    if (force || !hasFramedOnce) {
      camera.position.set(center.x + dist * 0.6, center.y + dist * 0.8, center.z + dist * 0.6)
      controls.target.copy(center)
      controls.update()
      hasFramedOnce = true
    }

    // 远近裁剪面也跟着调；远面不小于 CAMERA_FAR（自适应只能放大、不能缩小）
    camera.near = Math.max(0.1, maxSize * 0.001)
    camera.far = Math.max(CAMERA_FAR, maxSize * 20)
    camera.updateProjectionMatrix()

    // grid 跟着场景大小走
    if (grid) {
      scene.remove(grid)
      grid.geometry.dispose()
      ;(grid.material as { dispose: () => void }).dispose()
      grid = null
    }
    const gridSize = Math.max(50, Math.ceil(maxSize * 1.5))
    grid = new GridHelper(gridSize, 50, 0x334155, 0x1e293b)
    grid.position.set(center.x, box.min.y - 0.01, center.z)
    ;(grid.material as { transparent: boolean; opacity: number }).transparent = true
    ;(grid.material as { transparent: boolean; opacity: number }).opacity = 0.25
    scene.add(grid)
  }

  /* ---------- 键盘：WASD 移动相机 ---------- */

  /** 当前按下的移动键（keydown/keyup 维护，渲染循环里按帧应用） */
  const pressedMoveKeys = new Set<string>()
  /** 上一帧时间戳：用于算 dt，避免不同刷新率下移动速度不一致 */
  let lastFrameT = 0

  /**
   * 移动速度（米/秒）：以「相机到目标的距离」为基准。
   *
   * 为什么不写死：场景尺度差异极大（几十米的室内到几千米的地图），固定速度要么在大场景里
   * 挪不动、要么在小场景里一按就飞出视野。以观察距离为基准，手感在各种尺度下都一致。
   *
   * 系数取 0.3（≈ 每秒移动 1/3 个观察距离）：实测 1.2 太快 —— 按住 1.5 秒就把整块地形
   * 甩出视野，人会瞬间失去方位感。跨大场景请按住 Shift（8 倍）。
   */
  function moveSpeed(): number {
    if (!camera || !controls) return 1
    return Math.max(0.5, camera.position.distanceTo(controls.target) * 0.3)
  }

  function hasSpeedUp(): boolean {
    for (const k of SPEED_UP_KEYS) if (pressedMoveKeys.has(k)) return true
    return false
  }

  /**
   * 按帧把按键换算成相机位移。
   *
   * 两个关键点：
   * 1. **`controls.target` 必须跟着一起平移**：OrbitControls 是"绕目标转"，只挪相机的话，
   *    下一帧它会把视角拉回原目标 —— 表现为"按了 WASD 但画面弹回去"。
   * 2. **水平方向要抹掉 Y 分量**：否则俯视时按 W 会往地里钻，而不是沿地面走。
   */
  function applyKeyboardMove(dt: number) {
    if (!camera || !controls || pressedMoveKeys.size === 0 || dt <= 0) return

    let fx = 0
    let fz = 0
    let fy = 0
    if (pressedMoveKeys.has('KeyW')) fz += 1
    if (pressedMoveKeys.has('KeyS')) fz -= 1
    if (pressedMoveKeys.has('KeyD')) fx += 1
    if (pressedMoveKeys.has('KeyA')) fx -= 1
    if (pressedMoveKeys.has('KeyE')) fy += 1
    if (pressedMoveKeys.has('KeyQ')) fy -= 1
    if (fx === 0 && fz === 0 && fy === 0) return

    const forward = new Vector3()
    camera.getWorldDirection(forward)
    forward.y = 0
    if (forward.lengthSq() < 1e-9) forward.set(0, 0, -1)
    forward.normalize()
    const right = new Vector3().crossVectors(forward, camera.up).normalize()

    const delta = new Vector3()
    delta.addScaledVector(forward, fz)
    delta.addScaledVector(right, fx)
    delta.y += fy
    if (delta.lengthSq() < 1e-9) return

    delta.normalize().multiplyScalar(moveSpeed() * (hasSpeedUp() ? SPEED_UP_FACTOR : 1) * dt)

    camera.position.add(delta)
    controls.target.add(delta)
  }

  /**
   * 推进相机平滑飞行（`focusBox(box, true)` 的后续帧）。
   *
   * 缓动取 easeInOutCubic：起步与收尾都平缓，比线性更像"飞过去"而不是"被瞬移"。
   */
  function applyCameraTween(dt: number) {
    if (!camTween || !camera || !controls) return
    camTween.t += dt
    const k = Math.min(1, camTween.t / camTween.dur)
    const e = k < 0.5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2
    camera.position.lerpVectors(camTween.fromPos, camTween.toPos, e)
    controls.target.lerpVectors(camTween.fromTarget, camTween.toTarget, e)
    if (k >= 1) camTween = null
  }

  function loop(t = 0) {
    if (!renderer || !camera) return
    // dt 上限 0.1s：切走标签页再回来时时间差可能是几秒，不限制会让相机瞬移
    const dt = lastFrameT ? Math.min((t - lastFrameT) / 1000, 0.1) : 0
    lastFrameT = t
    applyKeyboardMove(dt)
    applyCameraTween(dt)
    controls?.update()
    renderer.render(scene, camera)
    // 标签要跟场景严格同步（否则相机一动标签就"漂"在后面），故放在 render 之后、同帧内定位
    afterRenderFn?.()
    rafId = requestAnimationFrame(loop)
  }

  /** 把鼠标事件换算成世界射线（相机 / 画布只有本 hook 有） */
  function buildRay(e: MouseEvent): {
    origin: { x: number; y: number; z: number }
    dir: { x: number; y: number; z: number }
  } | null {
    if (!renderer || !camera || !containerRef()) return null
    const c = containerRef() as HTMLElement
    const rect = c.getBoundingClientRect()
    mouseNDC.x = ((e.clientX - rect.left) / rect.width) * 2 - 1
    mouseNDC.y = -((e.clientY - rect.top) / rect.height) * 2 + 1
    raycaster.setFromCamera(mouseNDC, camera)
    const o = raycaster.ray.origin
    const d = raycaster.ray.direction
    return { origin: { x: o.x, y: o.y, z: o.z }, dir: { x: d.x, y: d.y, z: d.z } }
  }

  function pickWorldPoint(e: MouseEvent): { x: number; y: number; z: number } | null {
    const ray = buildRay(e)
    if (!ray) return null
    // 仅对 terrain mesh 做 raycast：
    // 1) 全局已通过 bootstrapBVH 把 Mesh.prototype.raycast 替换为 acceleratedRaycast，
    //    fallback 路径对没有 boundsTree 的辅助 mesh（navmesh fill / wire / halo / marker / grid）
    //    会抛 "Fallback raycast function not found"。
    // 2) 与 useRasterizer / useAnchorSnap 同源，确保拾取语义一致：起点必须落在地表上。
    const meshes: Mesh[] = []
    const roots: Object3D[] = terrainStore.terrains.map((t) => t.object3D)
    for (const root of roots) {
      root.updateMatrixWorld(true)
      root.traverse((obj) => {
        const m = obj as Mesh
        if (m.isMesh && m.geometry) meshes.push(m)
      })
    }
    if (meshes.length === 0) return null
    const hits = raycaster.intersectObjects(meshes, false)
    if (hits.length === 0) return null
    const h = hits[0]
    return { x: h.point.x, y: h.point.y, z: h.point.z }
  }

  /* ---------- gizmo 实现 ---------- */

  /** 懒创建：只有真的选中块时才需要它，避免无谓的对象与事件 */
  function ensureGizmo(): boolean {
    if (gizmo) return true
    const canvas = canvasRef()
    if (!camera || !canvas) return false

    gizmoProxy = new Object3D()
    gizmoProxy.visible = false
    scene.add(gizmoProxy)

    gizmo = new TransformControls(camera, canvas)
    // 用 Three 的默认大小（1）。
    //
    // 曾经放大到 1.35「好抓一点」，但手柄的**拾取体**本来就比视觉粗一圈（如旋转环的圆环
    // picker 管径约为视觉线的十倍），再整体放大后"鼠标离环还挺远就已经抓住"，
    // 反而容易误拖。回到默认值才是所见即所得。
    gizmo.size = 1
    // Three 0.169 起 TransformControls 不是 Object3D（extends Controls），
    // 要把它内部的可视部分 getHelper() 加进场景，直接 scene.add(gizmo) 不显示
    scene.add(gizmo.getHelper())
    buildGizmoBVH()

    gizmo.addEventListener('dragging-changed', (e) => {
      if (!controls) return
      // 拖动期间禁用轨道控制，否则相机会跟着一起转
      controls.enabled = !e.value
      // OrbitControls 与手柄监听的是同一个 canvas 的 pointerdown，它可能已经先一步进入
      // 拖动状态；这里显式 update 一次让它在"已禁用"下重算，避免松手后视角跳一下。
      if (e.value) controls.update()
    })
    gizmo.addEventListener('objectChange', () => {
      syncScaleAxis()
      const patch = readGizmoPatch()
      if (patch) onGizmoDrag?.(patch)
    })
    gizmo.addEventListener('mouseUp', () => {
      gizmoReleaseAt = performance.now()
      const patch = readGizmoPatch()
      if (patch) onGizmoCommit?.(patch)
    })
    return true
  }

  /**
   * 给手柄的拾取网格补 `boundsTree` —— **不加这一步，拖动手柄完全不可用**。
   *
   * 原因：`bootstrapBVH` 把 `Mesh.prototype.raycast` 全局替换成了 `acceleratedRaycast`，
   * 而没有 `boundsTree` 的 mesh 会走 fallback 并抛 "BVH: Fallback raycast function not found"。
   * 而 TransformControls 判断"鼠标有没有落在手柄上"正是靠 raycast ——
   * 一抛异常 `pointerHover` 就中断，手柄永远抓不住，事件全留给 OrbitControls，
   * 表现为「拖轴时块不动、只有相机在转」。
   *
   * 与 `utils/chunkPick.ts` 的取舍相反是合理的：那边块有数千个、且每次编辑重建，
   * 建 BVH 不划算，所以自己算 slab；这边手柄只有十几个固定网格、且只建一次，
   * 直接补 BVH 最省事。
   */
  function buildGizmoBVH() {
    if (!gizmo) return
    gizmo.getHelper().traverse((obj) => {
      const m = obj as Mesh
      if (!m.isMesh || !m.geometry) return
      const geom = m.geometry as unknown as {
        boundsTree?: unknown
        computeBoundsTree?: () => void
      }
      if (geom.boundsTree) return
      geom.computeBoundsTree?.()
    })
  }

  /** 缩放模式：块在 XZ 上是正方形，两个水平轴必须同步 */
  function syncScaleAxis() {
    if (gizmoMode !== 'scale' || !gizmoProxy) return
    const s = gizmoProxy.scale
    // 以"偏离 1 更多"的那个轴为准：用户拖哪根手柄，就听哪根
    const v = Math.abs(s.x - 1) >= Math.abs(s.z - 1) ? s.x : s.z
    s.x = v
    s.z = v
  }

  /** 把代理对象的当前变换读回块参数 */
  function readGizmoPatch(): ChunkGizmoPatch | null {
    if (!gizmoProxy || !gizmoBase) return null
    const t = gizmoProxy
    if (gizmoMode === 'translate') {
      return {
        ...gizmoBase,
        center: { x: t.position.x, y: t.position.y, z: t.position.z }
      }
    }
    if (gizmoMode === 'rotate') {
      // 直接读三个分量：`ChunkGizmoPatch.rotation` 与 gizmoProxy 同约定（Three 手性），
      // 手性转换不在这里做（见 ChunkGizmoPatch 的说明）
      return {
        ...gizmoBase,
        rotation: { x: t.rotation.x, y: t.rotation.y, z: t.rotation.z }
      }
    }
    return {
      ...gizmoBase,
      size: gizmoBase.size * ((t.scale.x + t.scale.z) / 2),
      height: gizmoBase.height * t.scale.y
    }
  }

  function applyGizmoMode(): void {
    if (!gizmo) return
    gizmo.setMode(gizmoMode)
    // 三个轴都放开。早先旋转只开 Y（对齐"地块只摆朝向"的用法），但契约里 `rotation`
    // 本来就是三元组，摆不出俯仰 / 翻滚反而束手束脚。
    gizmo.showX = true
    gizmo.showY = true
    gizmo.showZ = true
    // 旋转用**局部**参考系：环贴着块自身的轴，拖 X 环就只改 `rotation.x`。
    // 用世界轴（Three 的默认）时，块一旦已有其他轴的旋转，绕世界某轴再转会被分解到
    // 另外两个欧拉角上 —— 数值看起来"三个一起变"（姿态是对的，但没法按轴微调）。
    // 平移 / 缩放仍用世界轴：局部轴随姿态倾斜后，拖动方向会与屏幕直觉不符。
    gizmo.setSpace(gizmoMode === 'rotate' ? 'local' : 'world')
  }

  const chunkGizmo: ChunkGizmoHandle = {
    setTarget(target, mode) {
      if (mode) gizmoMode = mode
      if (!target) {
        gizmo?.detach()
        if (gizmo) gizmo.enabled = false
        gizmoBase = null
        return
      }
      if (!ensureGizmo() || !gizmo || !gizmoProxy) return
      gizmoBase = { ...target, center: { ...target.center }, rotation: { ...target.rotation } }
      gizmoProxy.position.set(target.center.x, target.center.y, target.center.z)
      gizmoProxy.rotation.set(target.rotation.x, target.rotation.y, target.rotation.z)
      gizmoProxy.scale.set(1, 1, 1)
      gizmo.enabled = true
      applyGizmoMode()
      gizmo.attach(gizmoProxy)
    },
    onDrag(fn) {
      onGizmoDrag = fn
    },
    onCommit(fn) {
      onGizmoCommit = fn
    }
  }

  onMounted(() => {
    const canvas = canvasRef()
    const container = containerRef()
    if (!canvas || !container) return

    renderer = new WebGLRenderer({ canvas, antialias: true, alpha: true })
    renderer.setClearColor(0x0b1020, 0)
    camera = new PerspectiveCamera(50, 1, 0.1, CAMERA_FAR)
    camera.position.set(50, 50, 50)
    controls = new OrbitControls(camera, canvas)
    controls.enableDamping = true
    controls.dampingFactor = 0.08

    fitCanvas()
    frameCamera(true)
    loop()

    resizeObserver = new ResizeObserver(() => fitCanvas())
    resizeObserver.observe(container)

    clickHandler = (e: MouseEvent) => {
      // 仅左键单击当点击
      if (e.button !== 0) return
      // 刚拖完手柄：这次 click 只是"松手"的副产物，丢掉它，否则会误改选中
      if (performance.now() - gizmoReleaseAt < 300) return
      // 按下到抬起之间移动过 = 在转相机 / 拖视角，不是点击
      if (Math.hypot(e.clientX - pointerDownPos.x, e.clientY - pointerDownPos.y) > 4) return
      // 叠加物优先（点中切块 → 选中）；消费掉就不再落到地表拾取
      if (onPickOverlay) {
        const ray = buildRay(e)
        if (ray && onPickOverlay(ray)) return
      }
      const pt = pickWorldPoint(e)
      if (pt) onPick?.(pt)
      // 没点到地面（天空 / 场景外）：不是"点了某处"，应当收起选中与手柄
      else onPickMiss?.()
    }
    canvas.addEventListener('click', clickHandler)

    pointerDownHandler = (e: PointerEvent) => {
      pointerDownPos.x = e.clientX
      pointerDownPos.y = e.clientY
    }
    canvas.addEventListener('pointerdown', pointerDownHandler)

    // 移动键挂在 window 上：鼠标不在画布上时也要能按键移动视角
    moveKeyDownHandler = (e: KeyboardEvent) => {
      const el = e.target as HTMLElement | null
      if (el && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA' || el.isContentEditable))
        return
      if (MOVE_KEYS.has(e.code) || SPEED_UP_KEYS.has(e.code)) pressedMoveKeys.add(e.code)
    }
    moveKeyUpHandler = (e: KeyboardEvent) => {
      pressedMoveKeys.delete(e.code)
    }
    // 失焦清空：否则"按着 W 切到别的窗口"回来时，视角还在自己飘
    blurHandler = () => pressedMoveKeys.clear()
    window.addEventListener('keydown', moveKeyDownHandler)
    window.addEventListener('keyup', moveKeyUpHandler)
    window.addEventListener('blur', blurHandler)
  })

  // terrain / modules 变化时如果还没 frame 过，自动 frame；已 frame 则按需扩展裁剪面
  watch(
    () => [terrainStore.count, modulesStore.loadedModuleCount],
    () => {
      if (!hasFramedOnce) frameCamera()
      else frameCamera(false)
    }
  )

  onBeforeUnmount(() => {
    cancelAnimationFrame(rafId)
    resizeObserver?.disconnect()
    if (clickHandler && canvasRef()) {
      canvasRef()!.removeEventListener('click', clickHandler)
    }
    if (pointerDownHandler && canvasRef()) {
      canvasRef()!.removeEventListener('pointerdown', pointerDownHandler)
    }
    if (moveKeyDownHandler) window.removeEventListener('keydown', moveKeyDownHandler)
    if (moveKeyUpHandler) window.removeEventListener('keyup', moveKeyUpHandler)
    if (blurHandler) window.removeEventListener('blur', blurHandler)
    pressedMoveKeys.clear()
    if (gizmo) {
      gizmo.detach()
      scene.remove(gizmo.getHelper())
      gizmo.dispose()
      gizmo = null
    }
    if (gizmoProxy) {
      scene.remove(gizmoProxy)
      gizmoProxy = null
    }
    if (grid) {
      scene.remove(grid)
      grid.geometry.dispose()
      ;(grid.material as { dispose: () => void }).dispose()
      grid = null
    }
    controls?.dispose()
    renderer?.dispose()
    renderer = null
    camera = null
    controls = null
  })

  /**
   * 把相机平滑对准给定 box（module 选中聚焦用）。
   * 与 frameCamera(true) 不同：这里只看一个 module，距离按 module 自身尺寸算，
   * 视角保持俯斜 45° 左右，OrbitControls.target 落到 box 中心。
   */
  function focusBox(box: Box3, smooth = false) {
    if (!camera || !controls) return
    if (box.isEmpty()) return
    const center = new Vector3()
    box.getCenter(center)
    const size = new Vector3()
    box.getSize(size)
    const maxSize = Math.max(size.x, size.y, size.z) || 1
    // 距离比 frameCamera 更近，让单个 module 占满主视口
    const dist = Math.max(maxSize * 1.4, 8)
    const toPos = new Vector3(
      center.x + dist * 0.55,
      center.y + dist * 0.85,
      center.z + dist * 0.55
    )
    // 远近裁剪面跟随调整，避免大世界 z-fighting / clipping
    camera.near = Math.max(0.1, maxSize * 0.001)
    camera.far = Math.max(CAMERA_FAR, camera.far, maxSize * 50)
    camera.updateProjectionMatrix()

    if (smooth) {
      // 只记录起止点，实际位移交给渲染循环 —— 这样飞行期间相机仍可被别的操作（WASD）接管
      camTween = {
        fromPos: camera.position.clone(),
        toPos,
        fromTarget: controls.target.clone(),
        toTarget: center.clone(),
        t: 0,
        dur: FLY_SECONDS
      }
    } else {
      camTween = null
      camera.position.copy(toPos)
      controls.target.copy(center)
    }
    controls.update()
  }

  /**
   * 世界坐标 → 画布内 CSS 像素坐标（左上角原点）。
   *
   * `behind` = 落在相机背后：此时 `project` 的结果会左右翻转（是数学上的镜像点），
   * 直接拿来定位会把标签摆到完全错误的地方，故由调用方判断后隐藏。
   */
  function project(p: {
    x: number
    y: number
    z: number
  }): { x: number; y: number; behind: boolean } | null {
    if (!camera || !containerRef()) return null
    const c = containerRef() as HTMLElement
    const w = c.clientWidth
    const h = c.clientHeight
    if (w <= 0 || h <= 0) return null
    projV.set(p.x, p.y, p.z).project(camera)
    return {
      x: (projV.x * 0.5 + 0.5) * w,
      y: (-projV.y * 0.5 + 0.5) * h,
      behind: projV.z > 1
    }
  }

  /** 注册每帧渲染后的回调（传 null 解除）。同帧内调用，标签定位靠它 */
  function onAfterRender(fn: (() => void) | null) {
    afterRenderFn = fn
  }

  return {
    frameCamera,
    focusBox,
    chunkGizmo,
    project,
    onAfterRender
  }
}
