<script setup lang="ts">
/**
 * SplitHandle — 列宽拖拽分隔条。
 *
 * ## 为什么抽成组件
 *
 * 界面重构后左右各有一条分隔条（主流程区 / 属性面板）。抽出来有两个好处：
 * - 视觉与命中区完全一致，不会"左边好拖、右边难拖"；
 * - 后续若再加可拖拽列，直接复用，不必再复制一份事件绑定与样式。
 *
 * 组件本身**无状态**：拖拽状态机在父级（`NavmeshView`），本组件只负责
 * "长什么样"与把 `mousedown` 抛出去。
 *
 * ## 为什么要有"常驻细线 + 五点抓手"
 *
 * 早期只有一个 `2px × 40px` 的小横线，且只在 hover 时才明显 —— 实测结果是
 * **用户根本没发现右侧属性面板也能拖**（以为只有左侧可拖）。
 * 因此改为：
 * - **常驻细线**：不悬浮也能看出"这里有一条分界"，明确两条列的边界；
 * - **五点抓手**：竖向排列的点是通用的"可拖拽"符号，比一条线段更容易被识别；
 * - hover / 拖拽中整体变青色，给出即时反馈。
 *
 * @changelog
 * | 版本   | 变更说明                                                       | 关联                     |
 * | v1.0.0 | 从 NavmeshView 的内联分隔条抽出，支持 active 高亮                 | REQ: map-editor-ui-shell |
 * | v1.1.0 | 增强可发现性：常驻边界细线 + 五点抓手 + hover/拖拽高亮            | REQ: map-editor-ui-shell |
 * /@changelog
 *
 * @author linfan
 */
defineProps<{
  /** 是否正在拖拽本条（用于高亮） */
  active?: boolean
  /** 悬浮提示文案 */
  title?: string
}>()

const emit = defineEmits<{
  (e: 'dragStart', ev: MouseEvent): void
}>()
</script>

<template>
  <div
    class="group relative shrink-0 w-2 cursor-col-resize flex items-center justify-center"
    :class="active ? 'bg-cyan-glow/10' : 'hover:bg-white/5'"
    :title="title ?? '拖动调整宽度'"
    role="separator"
    aria-orientation="vertical"
    @mousedown="emit('dragStart', $event)"
  >
    <!-- 常驻边界细线：不用悬浮也能看出列的分界 -->
    <span
      class="absolute inset-y-3 left-1/2 -translate-x-1/2 w-px transition-colors"
      :class="active ? 'bg-cyan-glow/70' : 'bg-white/10 group-hover:bg-cyan-glow/40'"
    />

    <!-- 五点抓手：通用的"可拖拽"符号 -->
    <span
      class="relative flex flex-col items-center gap-[3px] px-[3px] py-1.5 rounded transition-colors"
      :class="active ? 'bg-cyan-glow/20' : 'group-hover:bg-white/10'"
    >
      <span
        v-for="i in 5"
        :key="i"
        class="w-[3px] h-[3px] rounded-full transition-colors"
        :class="active ? 'bg-cyan-glow' : 'bg-white/30 group-hover:bg-cyan-glow/80'"
      />
    </span>
  </div>
</template>
