<script setup lang="ts">
/**
 * SpineActions — 脊线动作按钮组（生成骨架 / 补线 / 撤销 / 清除），位于左栏「③ 生成中线」。
 *
 * ## 为什么回到左栏
 *
 * 这组动作一度被搬去子流程工具栏，理由是左栏可滚动、③ 可能被挤出可视区。但按流程图，
 * 「生成中线」属于**主流程**，而子流程工具栏是"各子流程产物操作"的位置 —— 把主流程步骤
 * 放进去，会让工具栏同时扮演"流程切换"和"主流程操作"两个角色，语义就糊了。
 *
 * 现在 ① 加载已收敛为纯数据面板（缩略图 / GLB / manifest），③ 在常规窗口下可见，
 * 因此回归左栏，与「导入 GLB → 生成 navmesh → 生成中线」连成一条完整主线。
 *
 * ## 按钮规格
 *
 * 两枚主按钮都是**整行按钮**（`w-full` + 主色底 + 同色描边 + `font-semibold` + 图标），
 * 与 `NavmeshParamsPanel` 的「应用并烘焙」同规格 —— 左栏里的执行类动作需要一眼可见，
 * 小号文字按钮在深色底上几乎看不见。生成骨架是主操作（cyan-glow），补线是模式开关
 * （lime，与补线渲染色同源），激活时换亮底并把文案改成「补线中 · 点两下成段」。
 *
 * 撤销 / 清除是收尾动作，仅在有补线时出现，两枚并排各占半行。
 *
 * ## 纯展示组件
 *
 * 自身不读 store、不碰渲染层：状态用 props 传入，动作 emit 给编排层（`NavmeshView`）。
 * 骨架生成 / 补线数据都活在编排层（`lastSpineLines`、`renderHandle`），组件不该也无法代管。
 *
 * @changelog
 * | 版本   | 变更说明                                                       | 关联                     |
 * | v1.0.0 | 从 NavmeshView「③ 生成脊线」卡片的按钮组抽出，供两处复用          | REQ: navmesh-chunking    |
 * | v1.1.0 | 去重：左栏入口删除，成为工具栏专用动作组（单一入口）               | REQ: navmesh-chunking    |
 * | v1.2.0 | 归位：随主流程回到左栏「③ 生成中线」（工具栏只留子流程产物操作）    | REQ: map-editor-ui-shell |
 * | v1.3.0 | 按钮改整行规格（主色底 + 同色描边 + 加粗），对齐「应用并烘焙」         | REQ: map-editor-ui-shell |
 * /@changelog
 *
 * @author linfan
 */
import { Network, PenLine, Undo2, X } from 'lucide-vue-next'

defineProps<{
  /** 是否可操作（navmesh 未就绪时整体置灰） */
  disabled?: boolean
  /** 是否正处于补线模式（激活时高亮） */
  pickActive?: boolean
  /** 已手动补的段数；> 0 才显示「撤销 / 清除」 */
  manualCount?: number
}>()

const emit = defineEmits<{
  (e: 'generate'): void
  (e: 'pick'): void
  (e: 'undo'): void
  (e: 'clear'): void
}>()
</script>

<template>
  <div class="flex flex-col gap-1.5">
    <!-- 主操作：与「应用并烘焙」同规格（整行、主色底 + 同色描边 + 加粗） -->
    <button
      type="button"
      class="w-full flex items-center justify-center gap-1.5 py-1.5 rounded-md text-[11px] font-semibold transition-all border"
      :class="
        disabled
          ? 'bg-white/5 text-slate-500 border-white/5 cursor-not-allowed'
          : 'bg-cyan-glow/15 text-cyan-200 border-cyan-glow/40 hover:bg-cyan-glow/25 cursor-pointer shadow-cyan-glow'
      "
      :disabled="disabled"
      title="用 poly 邻接图生成连通骨架（楼梯/空旷区都不断），并作为切块的脊线"
      @click="emit('generate')"
    >
      <Network class="w-3.5 h-3.5" />
      生成骨架
    </button>

    <!-- 模式开关（补线）：整行次要按钮，激活时换亮色并改文案，避免"开着却看不出来" -->
    <button
      type="button"
      class="w-full flex items-center justify-center gap-1.5 py-1.5 rounded-md text-[11px] font-semibold transition-all border"
      :class="
        pickActive
          ? 'bg-lime-400/25 text-lime-200 border-lime-400/60 cursor-pointer'
          : disabled
            ? 'bg-white/5 text-slate-500 border-white/5 cursor-not-allowed'
            : 'bg-lime-400/15 text-lime-300 border-lime-400/35 hover:bg-lime-400/25 cursor-pointer'
      "
      :disabled="disabled"
      title="手动补线：点两下连一段（自动吸附到附近的骨架游离端点）；参与切块，可撤销。再点一次本按钮或按 ESC 退出补线模式"
      @click="emit('pick')"
    >
      <PenLine class="w-3.5 h-3.5" />
      {{ pickActive ? '补线中 · 点两下成段（再点退出）' : '补线' }}
    </button>

    <!-- 已有补线时才出现的收尾动作：两枚并排，各占半行 -->
    <div v-if="manualCount && manualCount > 0" class="flex items-center gap-1.5">
      <button
        type="button"
        class="flex-1 py-1 rounded-md text-[11px] text-slate-400 hover:text-lime-300 hover:bg-lime-500/10 flex items-center justify-center gap-1.5 cursor-pointer transition-all border border-white/5"
        title="撤销最后一段手动补线"
        @click="emit('undo')"
      >
        <Undo2 class="w-3 h-3" />
        撤销
      </button>
      <button
        type="button"
        class="flex-1 py-1 rounded-md text-[11px] text-slate-400 hover:text-red-300 hover:bg-red-500/10 flex items-center justify-center gap-1.5 cursor-pointer transition-all border border-white/5"
        :title="`清除全部 ${manualCount} 段手动补线（自动骨架保留）`"
        @click="emit('clear')"
      >
        <X class="w-3 h-3" />
        清除 {{ manualCount }}
      </button>
    </div>
  </div>
</template>
