/**
 * useNavmeshChunking — 沿脊线（拓扑骨架）把地块切成"块"（正方体），用于 chunk 化。
 *
 * ## 目标
 *
 * 让每个块**一定包裹玩家的可达区域**，且**所有可达区都被某个块覆盖**（不能有空洞）。
 * 块的位置沿脊线串联（骨架覆盖每个 poly，块心必可走），尺寸随局部通道宽度自适应。
 *
 * ## 三段式生成（关键设计）
 *
 * ⓪ **骨架串链**：骨架输出是「每条树边一条 2 点线段」，直接逐段布块会让每段最多布 1 块
 *    （段长常小于 `边长 × stepRatio`），**块间距退化成段长、与块尺寸脱钩**。
 *    故先按端点度数把短段串成连续折线（分叉点处断开）。
 *
 * ① **脊线采样**：沿串好的折线按 `step = 块边长 × stepRatio` 走线布块。
 *    块心取骨架上的点（必可走），边长取 `2 × 局部半宽 × sizeScale`（固定模式取常量）。
 *    同时做**去重抑制**：与已有块中心近于允许最小间距的块直接丢弃，
 *    避免骨架**分叉汇聚处**堆出中心几乎重合的块。
 *
 * ② **覆盖自检 + 补块**：把可达区栅格化，逐格检查是否被某个块覆盖；
 *    未覆盖的格子在原地补一个块（尺寸同样自适应）。补块本身按栅格去重。
 *
 * **为什么必须有 ②**：脊线是"线"，对"面"的覆盖不可能完美（尤其骨架未及的开阔角落）；
 * 有了 ②，"全覆盖"就是**结构性保证**，不依赖脊线是否完美 —— 这正是切分用途的硬要求。
 *
 * ## 坐标与 Y（多层场景）
 *
 * 块在 XZ 上是正方形（轴对齐，便于 AABB 索引），Y 方向以落脚面高度为中心上下各
 * `boxHeight / 2`。多层场景靠 Y 区分，因此同一 XZ 的上下层会得到不同的块。
 *
 * ⚠️ **覆盖判定与去重都必须按「层」做**：层高由场景 Y 跨度均分而来（`computeLayerHeight`），
 * 落脚面高度按它量化成层号。若只按 XZ 判断，下层布了块就会把正上方的格子也标成"已覆盖"，
 * 上层就**永远补不到块**（表现为"高处有青色可行走面却一个块都没有"）。
 * 层号用 Int32 位掩码存，因此网格内存与单层时相同。
 *
 * @changelog
 * | 版本   | 变更说明                                                     | 关联                    |
 * | v1.0.0 | 初始实现：骨架采样布块 + 覆盖自检补块 + 覆盖率统计              | REQ: navmesh-chunking   |
 * | v1.0.1 | 修复：空旷区正中搜不到边界时半宽返回 0 → 块被夹成 minSize 小碎块  | REQ: navmesh-chunking   |
 * | v1.1.0 | 修复块间距与尺寸脱钩：骨架串链 + 分叉汇聚处去重；固定模式不再被 maxSize 夹 | REQ: navmesh-chunking |
 * | v1.2.0 | 覆盖判定与去重改为按层（Y 位掩码，层高由场景 Y 跨度均分）：修多层场景高层补不到块 | REQ: navmesh-chunking |
 * | v1.3.0 | 新增「朝向」选项：块可沿脊线切线旋转；覆盖判定支持旋转正方形并修 offset 错位 | REQ: navmesh-chunking |
 * /@changelog
 *
 * @author v_weiqinlin
 */
import type { PolyRecord } from '../stores/navmesh'
import { collectBoundaryEdges, type BoundaryEdge } from './useNavmeshBoundary'
import { pointInPolygon2D, pointSegmentDistanceXZ2 } from '../utils/polygonContainment'

export interface ChunkParams {
  /** 尺寸模式：自适应（随局部宽度）/ 固定 */
  sizeMode: 'adaptive' | 'fixed'
  /** 自适应时：边长 = 2 × 局部半宽 × sizeScale */
  sizeScale: number
  /** 固定模式下的边长（米） */
  fixedSize: number
  /** 边长下限（米） */
  minSize: number
  /** 边长上限（米） */
  maxSize: number
  /** 块高度（米），以落脚面为中心上下各一半 */
  boxHeight: number
  /**
   * 块的水平朝向。
   *
   * - `axis`    **轴对齐**：XZ 正方形与坐标轴平行。便于 AABB 索引，**默认**
   * - `tangent` **沿切线**：绕 Y 轴旋转到该处**脊线切线方向**，斜走廊 / 弧形通道里
   *             块与通道走向一致，观感明显更合理
   *
   * ⚠️ `tangent` 会破坏"轴对齐"这一前提：块的 XZ 占用变成旋转正方形，
   * 下游若要按 AABB 索引需自行处理（本模块内部的去重与覆盖判定已按旋转后处理）。
   */
  orientMode: 'axis' | 'tangent'
  /** 间距系数：间距 = 边长 × 该值（0.5 = 相邻块重叠 50%） */
  stepRatio: number
  /** 沿骨架的相位偏移（0~1 倍步长）：整体把块前后挪 */
  phase: number
  /** 整体平移 X（米） */
  offsetX: number
  /** 整体平移 Z（米） */
  offsetZ: number
  /** 是否做覆盖自检补块（关掉则只显示骨架布块，用于对比调参） */
  fillGaps: boolean
}

export const DEFAULT_CHUNK_PARAMS: ChunkParams = {
  sizeMode: 'adaptive',
  sizeScale: 1.3,
  fixedSize: 4,
  minSize: 2,
  maxSize: 12,
  boxHeight: 4,
  orientMode: 'axis',
  stepRatio: 0.5,
  phase: 0,
  offsetX: 0,
  offsetZ: 0,
  fillGaps: true
}

/** 一个块：XZ 上是正方形（默认轴对齐），Y 方向高 `height` */
export interface Chunk {
  center: { x: number; y: number; z: number }
  /** XZ 正方形边长（米） */
  size: number
  /** 高度（米） */
  height: number
  /**
   * 绕 Y 轴的朝向（弧度）。
   *
   * - `0` = 轴对齐
   * - `orientMode: 'tangent'` 时 = 该处**脊线切线**方向（补块则继承就近块的朝向）
   *
   * **旋转约定**（渲染与覆盖判定必须一致）：局部 → 世界为 XZ 平面上的标准逆时针旋转
   * `worldX = lx·cos − lz·sin`、`worldZ = lx·sin + lz·cos`。
   * 于是 `yaw = atan2(切线z, 切线x)` 时块的局部 x 轴正好指向切线方向。
   */
  yaw: number
  /** 来源：骨架采样 / 覆盖补块 */
  source: 'spine' | 'fill'
}

export interface ChunkResult {
  chunks: Chunk[]
  /** 骨架布块阶段的可达区覆盖率（0~1）：反映脊线覆盖得好不好，用于调参 */
  coverageBefore: number
  /** 覆盖自检补出来的块数：越小说明骨架布块越贴合 */
  fillCount: number
  /** 可达采样格总数 */
  sampleTotal: number
  /** 补块后仍未被覆盖的格数（正常情况下为 0） */
  uncoveredFinal: number
  /**
   * 因「与已有块中心过近」被抑制掉的冗余块数。
   *
   * 骨架是一棵树，分支在分叉点汇聚，各分支独立布块时会在汇聚处堆出中心几乎重合的块 ——
   * 这些块对覆盖没有贡献，只会让块数虚高、视觉糊成一团。该数字越大说明脊线分叉越密。
   */
  redundantSkipped: number
  /** 串链后的连续折线条数（= 布块真正走过的路径条数） */
  chainCount: number
  elapsedMs: number
}

/** 块数硬上限（防御异常参数导致爆炸） */
const MAX_CHUNKS = 20000

/** 覆盖自检的栅格边长下限（米）：越小越精细越慢 */
const MIN_COVER_CELL = 0.4

/** 覆盖栅格单边最大格数：地图很大时自动放大 cell，防止内存爆炸 */
const MAX_COVER_CELLS_PER_AXIS = 1400

export function generateChunks(
  polys: PolyRecord[],
  spineLines: Float32Array[],
  params: ChunkParams
): ChunkResult {
  const t0 = performance.now()
  const empty: ChunkResult = {
    chunks: [],
    coverageBefore: 0,
    fillCount: 0,
    sampleTotal: 0,
    uncoveredFinal: 0,
    redundantSkipped: 0,
    chainCount: 0,
    elapsedMs: 0
  }
  if (polys.length === 0 || spineLines.length === 0) return empty

  const edges = collectBoundaryEdges(polys)
  const edgeGrid = buildEdgeGrid(edges)
  const chunks: Chunk[] = []

  // ① 沿骨架布块
  //
  // 先**串链**再布块：骨架的输出是「每段一条 2 点线段」，
  // 若把每段都当独立路径布块，段长（门到门 1~5m）通常小于 `边长 × stepRatio`，
  // 该段就只能布出 1 块 → 实际块间距退化成「段长」，与块尺寸脱钩：
  // 表现为「调大 size 但间距不变、块越调越重叠」。
  // 串成连续折线后，间距才真正等于 `边长 × stepRatio`。
  // 层高：把场景的 Y 跨度均分成 LAYER_STRIDE 份，用于**按层**的覆盖判定与去重。
  //
  // ⚠️ 不能用 `boxHeight` 当层高：楼层间距（常见 3m）常小于 `boxHeight`（默认 4m），
  // 那样相邻楼层会落进同一层，"下层顶替上层"的问题会原样复现。
  const layerHeight = computeLayerHeight(polys)
  const chains = chainSpineLines(spineLines)
  const dedup = createDedupIndex(params, layerHeight)
  let redundantSkipped = 0
  for (const line of chains) {
    redundantSkipped += placeAlongLine(line, params, edges, edgeGrid, chunks, dedup)
    if (chunks.length >= MAX_CHUNKS) break
  }

  // ② 覆盖自检 + 补块
  const cover = buildCoverage(polys, chunks, params, layerHeight)
  const coverageBefore = cover.walkableCount > 0 ? cover.coveredBefore / cover.walkableCount : 1

  let fillCount = 0
  if (params.fillGaps && chunks.length < MAX_CHUNKS) {
    fillCount = fillUncovered(cover, params, edges, edgeGrid, polys, dedup, chunks)
  }

  const uncoveredFinal = countUncovered(cover)

  return {
    chunks,
    coverageBefore,
    fillCount,
    sampleTotal: cover.walkableCount,
    uncoveredFinal,
    redundantSkipped,
    chainCount: chains.length,
    elapsedMs: performance.now() - t0
  }
}

/* ============================================================
 * ① 沿骨架布块
 * ============================================================ */

/**
 * 沿一条**串好的**骨架折线走线布块，返回因"与已有块过近"被抑制的块数。
 *
 * 步长是**自适应**的：每布一块，用该处的局部宽度算出边长，再按 `边长 × stepRatio` 前进。
 * 这样窄处块小且密、宽处块大且疏，块数随通道宽度自然伸缩。
 *
 * ⚠️ 前提：入参折线必须**足够长**（`chainSpineLines` 串链后的结果）。
 * 若把"一条骨架短段"直接传进来，段长往往小于 `边长 × stepRatio`，
 * 该段就只会布出 1 块 —— **间距退化成段长，与块尺寸脱钩**。
 */
function placeAlongLine(
  line: Float32Array,
  params: ChunkParams,
  edges: BoundaryEdge[],
  edgeGrid: EdgeGrid,
  out: Chunk[],
  dedup: DedupIndex
): number {
  const count = line.length / 3
  if (count < 2) return 0

  // 相位偏移：跳过开头 phase 倍步长的距离
  const startSize = blockSizeAt(line[0], line[2], params, edges, edgeGrid)
  let nextAt = params.phase * startSize * params.stepRatio
  let acc = 0
  let skipped = 0

  for (let i = 0; i + 1 < count; i++) {
    const ax = line[i * 3]
    const ay = line[i * 3 + 1]
    const az = line[i * 3 + 2]
    const bx = line[(i + 1) * 3]
    const by = line[(i + 1) * 3 + 1]
    const bz = line[(i + 1) * 3 + 2]

    const segLen = Math.hypot(bx - ax, bz - az)
    if (segLen < 1e-6) continue

    while (nextAt <= acc + segLen) {
      const t = (nextAt - acc) / segLen
      const x = ax + (bx - ax) * t
      const y = ay + (by - ay) * t
      const z = az + (bz - az) * t

      const size = blockSizeAt(x, z, params, edges, edgeGrid)
      // 朝向：沿切线时取**当前段**的方向。正方形对 180° 无差别，故方向正负不影响观感。
      const yaw = params.orientMode === 'tangent' ? Math.atan2(bz - az, bx - ax) : 0
      if (isRedundant(dedup, x, y, z, size, params.stepRatio)) {
        // 与已有块过近（近于允许的最小间距）→ 冗余，跳过
        skipped++
      } else {
        out.push({
          center: { x: x + params.offsetX, y, z: z + params.offsetZ },
          size,
          height: params.boxHeight,
          yaw,
          source: 'spine'
        })
        addToDedup(dedup, x, y, z, size, yaw)
        if (out.length >= MAX_CHUNKS) return skipped
      }

      // 自适应步长：按当前位置的块尺寸前进（被抑制时同样前进，否则会原地打转）
      nextAt += Math.max(size * params.stepRatio, 1e-3)
    }

    acc += segLen
  }

  return skipped
}

/**
 * 该点应使用的块边长。
 *
 * - **固定模式**：直接返回 `fixedSize`，**不再被 min/maxSize 夹**。
 *   早期实现对固定模式也套了 `[minSize, maxSize]`，于是滑杆能拖到 30 而 `maxSize` 默认为 12 时
 *   实际边长恒为 12 —— 表现为「调大 size 没反应」。
 * - **自适应模式**：边长 = 2 × 局部半宽 × `sizeScale`，再夹到 `[minSize, maxSize]`。
 *   此模式只需知道「半宽是否已超过 maxSize 对应的阈值」——超过就该夹到 maxSize，再多搜无意义，
 *   故环形搜索圈数由参数反推（见 `ringLimitFor`），既省查询又保证
 *   "搜不到 ⇒ 一定该取 maxSize"这个推断成立。
 */
function blockSizeAt(
  x: number,
  z: number,
  params: ChunkParams,
  edges: BoundaryEdge[],
  edgeGrid: EdgeGrid
): number {
  if (params.sizeMode === 'fixed') return params.fixedSize

  const halfWidth = distanceToNearestEdge(
    x,
    z,
    edges,
    edgeGrid,
    ringLimitFor(params, edgeGrid.cell)
  )
  const size = 2 * halfWidth * params.sizeScale
  return Math.min(params.maxSize, Math.max(params.minSize, size))
}

/* ============================================================
 * 布块去重：抑制分叉汇聚处的堆叠
 * ============================================================ */

/** 已布块的空间索引（按 XZ 分格 + **层**，避免 O(块数²) 的互相检查） */
interface DedupIndex {
  cell: number
  /** 层高（米）：与覆盖判定同一套分层 —— 否则会把不同楼层当成"同一个位置" */
  layerHeight: number
  map: Map<string, Array<{ x: number; y: number; z: number; size: number; yaw: number }>>
}

/** 建索引：格边长取"最大可能块边长"，保证 3×3 邻域足以覆盖一个块的查询半径 */
function createDedupIndex(params: ChunkParams, layerHeight: number): DedupIndex {
  const maxBlock = params.sizeMode === 'fixed' ? params.fixedSize : params.maxSize
  return { cell: Math.max(1, maxBlock), layerHeight, map: new Map() }
}

/** 索引 key：XZ 分格 + 层（同 XZ 不同楼层必须落在不同的桶里） */
function dedupKey(idx: DedupIndex, x: number, y: number, z: number): string {
  return `${Math.floor(x / idx.cell)},${layerOf(y, idx.layerHeight)},${Math.floor(z / idx.cell)}`
}

/**
 * 该位置是否与已有块"过近"（应抑制）。
 *
 * 判据：**同层**、且与已有块中心的 XZ 距离 < `min(两者边长) × stepRatio`。
 * 阈值正好等于**允许的最小间距**，因此不会误伤正常相邻的块 ——
 * 它们的距离恰好等于该阈值，而这里用严格小于，所以照旧保留。
 *
 * 为什么需要：骨架是一棵树，**分支在分叉点汇聚**，各分支独立布块会在汇聚处
 * 堆出中心几乎重合的块。这些块对覆盖没有贡献，只会让块数虚高、视觉糊成一团。
 *
 * ⚠️ 「同层」这个条件不能省：不同楼层（屋顶 vs 地面）XZ 可能完全重叠，
 * 若不看层就会把上层的块误判为冗余而整片丢弃。
 */
function isRedundant(
  idx: DedupIndex,
  x: number,
  y: number,
  z: number,
  size: number,
  ratio: number
): boolean {
  const cx = Math.floor(x / idx.cell)
  const cz = Math.floor(z / idx.cell)
  const layer = layerOf(y, idx.layerHeight)
  for (let ox = -1; ox <= 1; ox++) {
    for (let oz = -1; oz <= 1; oz++) {
      const list = idx.map.get(`${cx + ox},${layer},${cz + oz}`)
      if (!list) continue
      for (const c of list) {
        if (Math.hypot(c.x - x, c.z - z) < Math.min(size, c.size) * ratio) return true
      }
    }
  }
  return false
}

function addToDedup(
  idx: DedupIndex,
  x: number,
  y: number,
  z: number,
  size: number,
  yaw: number
): void {
  const key = dedupKey(idx, x, y, z)
  const item = { x, y, z, size, yaw }
  const list = idx.map.get(key)
  if (list) list.push(item)
  else idx.map.set(key, [item])
}

/**
 * 取就近已布块的朝向（补块用来"继承"脊线块的方向）。
 *
 * 为什么补块需要它：补块出现在脊线没覆盖到的开阔处，本身没有切线可依据。
 * 若一律给 0（轴对齐），同一片区域里就会混着旋转块与轴对齐块，反而更乱。
 * 继承就近块的朝向能让整片区域方向一致；实在找不到就近块（离脊线很远）才退回 0。
 */
function nearestYaw(idx: DedupIndex, x: number, y: number, z: number): number {
  const cx = Math.floor(x / idx.cell)
  const cz = Math.floor(z / idx.cell)
  const layer = layerOf(y, idx.layerHeight)
  let bestYaw = 0
  let bestD = Infinity
  for (let ox = -1; ox <= 1; ox++) {
    for (let oz = -1; oz <= 1; oz++) {
      const list = idx.map.get(`${cx + ox},${layer},${cz + oz}`)
      if (!list) continue
      for (const c of list) {
        const d = Math.hypot(c.x - x, c.z - z)
        if (d < bestD) {
          bestD = d
          bestYaw = c.yaw
        }
      }
    }
  }
  return bestYaw
}

/* ============================================================
 * ⓪ 骨架串链：把"每段一条"的独立短段接成连续折线
 * ============================================================ */

/** 端点量化精度（米）：用于端点匹配，消除浮点误差 */
const ENDPOINT_EPS = 1e-3

/** 某条折线的某一端：line = 折线索引，end = 0 起点 / 1 终点 */
interface LineEnd {
  line: number
  end: 0 | 1
}

/**
 * 把骨架的独立短段串成**连续折线**，在「分叉点」处断开。
 *
 * ## 为什么必须串
 *
 * 骨架（`buildGraphSkeleton`）的输出是「每条树边一条 2 点线段」—— 这是**渲染**需要的形态
 * （相邻段共享端点，视觉上连续）。但**布块**需要"能连续走较长距离的路径"：
 * 若把每个 2 点段当独立路径，`placeAlongLine` 的 `nextAt` 每段都从 0 重来，
 * 而段长（门到门 1~5m）通常小于 `边长 × stepRatio` → 每段只能布出 1 块
 * → **实际块间距退化成「段长」，与块尺寸脱钩**（调大 size 只会让块互相重叠）。
 *
 * ## 串法
 *
 * 端点量化后统计度数：度 ≠ 2 的点（叶子 / 分叉）作为链的**起止点**，
 * 度 = 2 的点一路走下去，直到遇到下一个度 ≠ 2 的点。纯环（所有端点度 = 2）单独成链。
 *
 * 结果条数 ≈「叶子数 + 分叉分支数」，远小于原来的段数（数百 → 数十）。
 */
function chainSpineLines(lines: Float32Array[]): Float32Array[] {
  if (lines.length <= 1) return lines

  const keyOf = (x: number, y: number, z: number) =>
    `${Math.round(x / ENDPOINT_EPS)},${Math.round(y / ENDPOINT_EPS)},${Math.round(z / ENDPOINT_EPS)}`

  const endsAt = new Map<string, LineEnd[]>()
  const startKeys: string[] = []
  const endKeys: string[] = []
  const usable = new Uint8Array(lines.length)

  const pushEnd = (key: string, e: LineEnd) => {
    const list = endsAt.get(key)
    if (list) list.push(e)
    else endsAt.set(key, [e])
  }

  for (let i = 0; i < lines.length; i++) {
    const l = lines[i]
    const n = l.length / 3
    if (n < 2) continue
    usable[i] = 1
    startKeys[i] = keyOf(l[0], l[1], l[2])
    endKeys[i] = keyOf(l[(n - 1) * 3], l[(n - 1) * 3 + 1], l[(n - 1) * 3 + 2])
    pushEnd(startKeys[i], { line: i, end: 0 })
    pushEnd(endKeys[i], { line: i, end: 1 })
  }

  const used = new Uint8Array(lines.length)
  const out: Float32Array[] = []

  /** 从 fromKey 出发、沿 first 这条线开始走，直到分叉点 / 端点 / 回到起点 */
  const walk = (fromKey: string, first: LineEnd): void => {
    const pts: number[] = []
    let cur: LineEnd | undefined = first

    for (;;) {
      if (!cur || used[cur.line]) break
      const curLine: number = cur.line
      const curEnd: 0 | 1 = cur.end
      used[curLine] = 1

      const l = lines[curLine]
      const n = l.length / 3
      const forward: boolean = curEnd === 0
      // 续接时跳过首点（与前一条线的末点重合，避免折线里堆积重复点）
      for (let k = pts.length > 0 ? 1 : 0; k < n; k++) {
        const src: number = forward ? k : n - 1 - k
        pts.push(l[src * 3], l[src * 3 + 1], l[src * 3 + 2])
      }

      const farKey: string = forward ? endKeys[curLine] : startKeys[curLine]
      if (farKey === fromKey) break // 闭环
      const cands: LineEnd[] = (endsAt.get(farKey) ?? []).filter(
        (e) => usable[e.line] && !used[e.line]
      )
      // 0 条 = 走到端点；≥2 条 = 分叉点，链在这里断开
      if (cands.length !== 1) break
      cur = cands[0]
    }

    if (pts.length >= 6) out.push(new Float32Array(pts))
  }

  // 先从"非度 2"的端点起走（叶子 / 分叉点），保证每条链都从端头开始
  for (const [key, list] of endsAt) {
    if (list.length === 2) continue
    for (const e of list) {
      if (!usable[e.line] || used[e.line]) continue
      walk(key, e)
    }
  }
  // 剩下的都是纯环（每个端点度 = 2）：任选一条线起走
  for (let i = 0; i < lines.length; i++) {
    if (!usable[i] || used[i]) continue
    walk(startKeys[i], { line: i, end: 0 })
  }

  return out
}

/**
 * 环形搜索需要的圈数：刚好覆盖「半宽达到 size = maxSize」所需的距离。
 *
 * 推导：size = 2 × halfWidth × sizeScale ≤ maxSize ⇒ halfWidth ≤ maxSize / (2 × sizeScale)。
 * 因此半径只要够到 `maxSize / (2 × sizeScale)` 就够了（+1 圈补边界效应）。
 * 例：maxSize 12 / sizeScale 1.3 → 阈值 4.6m，cell 4m → 3 圈，与原实现同量级。
 */
function ringLimitFor(params: ChunkParams, cell: number): number {
  const threshold = params.maxSize / (2 * Math.max(params.sizeScale, 1e-6))
  return Math.ceil(threshold / cell) + 1
}

/* ---------- 边界边的空间网格：把 O(边数) 的最近边查询降到 O(邻域边数) ---------- */

interface EdgeGrid {
  cell: number
  map: Map<string, number[]>
}

/** 建边网格（边长 4m）：边界边按 AABB 落格；查询时只需扫邻域几圈 */
function buildEdgeGrid(edges: BoundaryEdge[]): EdgeGrid {
  const cell = 4
  const map = new Map<string, number[]>()
  for (let i = 0; i < edges.length; i++) {
    const e = edges[i]
    const x0 = Math.floor(Math.min(e.ax, e.bx) / cell)
    const x1 = Math.floor(Math.max(e.ax, e.bx) / cell)
    const z0 = Math.floor(Math.min(e.az, e.bz) / cell)
    const z1 = Math.floor(Math.max(e.az, e.bz) / cell)
    for (let cx = x0; cx <= x1; cx++) {
      for (let cz = z0; cz <= z1; cz++) {
        const key = `${cx},${cz}`
        const list = map.get(key)
        if (list) list.push(i)
        else map.set(key, [i])
      }
    }
  }
  return { cell, map }
}

/**
 * 点到最近 navmesh 边界边的水平距离（= 局部半宽）。
 *
 * 用边网格圈层扩展：命中第一圈有边的层就返回。对"给块定尺寸"这个用途精度足够，
 * 且把最坏情况从「边数 × 块数」降到「邻域边数 × 块数」。
 *
 * **搜满 `ringLimit` 圈仍无边界时返回 `Infinity`（不是 0）**：
 * 说明半宽已超过 `maxSize / (2 × sizeScale)`，块本该取 `maxSize`。
 * 早期版本返回 0，导致空旷区正中（离墙超过搜索半径）被夹成 `minSize`，
 * 在最开阔处反而冒出一撮最小碎块。
 *
 * @param ringLimit 环形扩展的最大圈数，由 `ringLimitFor` 按参数反推
 */
function distanceToNearestEdge(
  x: number,
  z: number,
  edges: BoundaryEdge[],
  grid: EdgeGrid,
  ringLimit: number
): number {
  const cx = Math.floor(x / grid.cell)
  const cz = Math.floor(z / grid.cell)

  for (let ring = 0; ring <= ringLimit; ring++) {
    let minSq = Infinity
    for (let ox = -ring; ox <= ring; ox++) {
      for (let oz = -ring; oz <= ring; oz++) {
        // 只扫当前圈层（ring=0 只有中心格）
        if (ring > 0 && Math.abs(ox) !== ring && Math.abs(oz) !== ring) continue
        const list = grid.map.get(`${cx + ox},${cz + oz}`)
        if (!list) continue
        for (const idx of list) {
          const e = edges[idx]
          const d2 = pointSegmentDistanceXZ2(x, z, e.ax, e.az, e.bx, e.bz)
          if (d2 < minSq) minSq = d2
        }
      }
    }
    if (Number.isFinite(minSq)) return Math.sqrt(minSq)
  }
  // 搜索范围内没有边界 ⇒ 半宽大到足以夹到 maxSize（见 blockSizeAt）
  return Infinity
}

/* ============================================================
 * ② 覆盖自检 + 补块
 * ============================================================ */

/**
 * 层索引的层数上限（Int32 位掩码）。
 *
 * 32 层 × `boxHeight`（默认 4m）= 128m 的高度跨度，足够覆盖任何室内 / 城镇场景。
 * 超出会被夹到最后一层（多层重叠，等价于退化回 2D 判定）。
 */
const LAYER_STRIDE = 32

/**
 * 把落脚面高度量化成"层"。
 *
 * ## 为什么必须分层
 *
 * 场景是**多层**的（屋顶 / 平台 / 地面），而"某处是否已被覆盖"必须在**三维**上判断。
 * 早期实现只按 XZ 判断：下层布了块就把正上方的格子也标成"已覆盖"，
 * 于是上层**永远补不到块** —— 表现为「高处明明是青色可行走面，却一个块都没有」。
 */
function layerOf(y: number, layerHeight: number): number {
  const l = Math.floor(y / Math.max(layerHeight, 1e-3))
  return l < 0 ? 0 : l >= LAYER_STRIDE ? LAYER_STRIDE - 1 : l
}

/** 位掩码里 1 的个数（= 有几个层） */
function popcount(v: number): number {
  let x = v
  let n = 0
  while (x) {
    x &= x - 1
    n++
  }
  return n
}

/** 一个块在 Y 上覆盖到的**层位掩码**（块高 = boxHeight，通常跨 1~2 层） */
function layerMaskOfChunk(c: Chunk, layerHeight: number): number {
  const lo = layerOf(c.center.y - c.height / 2, layerHeight)
  const hi = layerOf(c.center.y + c.height / 2, layerHeight)
  let mask = 0
  for (let l = lo; l <= hi; l++) mask |= 1 << l
  return mask
}

/**
 * 覆盖判定所用的**坐标系参数**。
 *
 * 抽出来单独传，是因为 `markChunkCovered` 在 `buildCoverage` 里（那时 Coverage 还没构造完）
 * 与 `fillUncovered` 里都要用，长参数列表容易传错顺序。
 *
 * ⚠️ `offsetX/offsetZ` 必须在这里：块中心带整体平移量，而覆盖网格建在**未平移**的
 * poly 坐标系上。早期实现漏了这一项 —— 一旦设置平移，覆盖判定就整体错位：
 * 已在覆盖区内的格子仍被判"未覆盖"，于是凭空多出一批补块。
 */
interface CoverSpace {
  minX: number
  minZ: number
  cell: number
  nx: number
  nz: number
  /** 层高（米）：由场景 Y 跨度均分而来，见 `computeLayerHeight` */
  layerHeight: number
  /** 块中心整体平移 X（米）：用于把块中心还原回未平移坐标 */
  offsetX: number
  /** 块中心整体平移 Z（米） */
  offsetZ: number
}

interface Coverage extends CoverSpace {
  /** 每格的**可走层**位掩码（bit i = 第 i 层有可行走面；0 = 该格完全不可走） */
  walkable: Int32Array
  /** 每格的**已覆盖层**位掩码 */
  covered: Int32Array
  /** (格索引 × LAYER_STRIDE + 层) → 该格该层所属 poly 索引，用于取落脚面高度 */
  polyAt: Map<number, number>
  /** 「格 × 层」形式的可走单元总数 */
  walkableCount: number
  coveredBefore: number
}

/**
 * 层高：把场景的 Y 跨度均分成 `LAYER_STRIDE - 2` 份（留 2 层余量防边界溢出）。
 *
 * 为什么按场景算而不是固定值：
 * - 固定值太小 → 层数不够，高场景会溢出到同一层；
 * - 固定值太大 → 楼层间距小于它时相邻楼层落进同一层，"下层顶替上层"复现。
 *
 * 例：Y 跨度 25m → 层高 ≈ 0.83m，3m 的楼层间距相隔约 4 层，足够分离。
 * 下限 0.5m 防止全平场景层数过密。
 */
function computeLayerHeight(polys: PolyRecord[]): number {
  let minY = Infinity
  let maxY = -Infinity
  for (const p of polys) {
    if (p.centroid.y < minY) minY = p.centroid.y
    if (p.centroid.y > maxY) maxY = p.centroid.y
  }
  if (!Number.isFinite(minY)) return 1
  const span = Math.max(maxY - minY, 0)
  return Math.max(0.5, span / (LAYER_STRIDE - 2))
}

/** 把可行走区与已布块栅格化，得到覆盖率与未覆盖单元（**按「格 × 层」计**） */
function buildCoverage(
  polys: PolyRecord[],
  chunks: Chunk[],
  params: ChunkParams,
  layerHeight: number
): Coverage {
  let minX = Infinity
  let maxX = -Infinity
  let minZ = Infinity
  let maxZ = -Infinity
  for (const p of polys) {
    if (p.bmin.x < minX) minX = p.bmin.x
    if (p.bmax.x > maxX) maxX = p.bmax.x
    if (p.bmin.z < minZ) minZ = p.bmin.z
    if (p.bmax.z > maxZ) maxZ = p.bmax.z
  }
  if (!Number.isFinite(minX)) {
    return {
      minX: 0,
      minZ: 0,
      cell: MIN_COVER_CELL,
      nx: 0,
      nz: 0,
      layerHeight,
      offsetX: params.offsetX,
      offsetZ: params.offsetZ,
      walkable: new Int32Array(0),
      covered: new Int32Array(0),
      polyAt: new Map(),
      walkableCount: 0,
      coveredBefore: 0
    }
  }

  const spanX = Math.max(maxX - minX, MIN_COVER_CELL)
  const spanZ = Math.max(maxZ - minZ, MIN_COVER_CELL)
  const cell = Math.max(MIN_COVER_CELL, spanX / MAX_COVER_CELLS_PER_AXIS, spanZ / MAX_COVER_CELLS_PER_AXIS)
  const nx = Math.ceil(spanX / cell) + 1
  const nz = Math.ceil(spanZ / cell) + 1

  const walkable = new Int32Array(nx * nz)
  const covered = new Int32Array(nx * nz)
  const polyAt = new Map<number, number>()

  // 标记可走单元：格心落在某 poly 内 →「该格 × 该 poly 所在层」可走
  for (let pi = 0; pi < polys.length; pi++) {
    const p = polys[pi]
    const layer = layerOf(p.centroid.y, layerHeight)
    const bit = 1 << layer
    const cx0 = Math.max(0, Math.floor((p.bmin.x - minX) / cell))
    const cx1 = Math.min(nx - 1, Math.ceil((p.bmax.x - minX) / cell))
    const cz0 = Math.max(0, Math.floor((p.bmin.z - minZ) / cell))
    const cz1 = Math.min(nz - 1, Math.ceil((p.bmax.z - minZ) / cell))
    for (let cx = cx0; cx <= cx1; cx++) {
      for (let cz = cz0; cz <= cz1; cz++) {
        const idx = cz * nx + cx
        // 同一层已被更早的 poly 占掉就跳过；**不同层互不影响**（这是修复的关键）
        if ((walkable[idx] & bit) !== 0) continue
        const px = minX + cx * cell
        const pz = minZ + cz * cell
        if (pointInPolygon2D(px, pz, p.vertices)) {
          walkable[idx] |= bit
          polyAt.set(idx * LAYER_STRIDE + layer, pi)
        }
      }
    }
  }

  let walkableCount = 0
  for (let i = 0; i < walkable.length; i++) walkableCount += popcount(walkable[i])

  const space: CoverSpace = {
    minX,
    minZ,
    cell,
    nx,
    nz,
    layerHeight,
    offsetX: params.offsetX,
    offsetZ: params.offsetZ
  }

  // 标记已覆盖单元（只标记块自身 Y 跨度覆盖到的层）
  for (const c of chunks) markChunkCovered(c, space, covered)

  let coveredBefore = 0
  for (let i = 0; i < walkable.length; i++) coveredBefore += popcount(walkable[i] & covered[i])

  return { ...space, walkable, covered, polyAt, walkableCount, coveredBefore }
}

/**
 * 把一个块覆盖到的「格 × 层」标记为已覆盖。
 *
 * - **层**由块自身的 Y 跨度决定（`layerMaskOfChunk`）
 * - **XZ** 按块**旋转后的正方形**逐格心判定：把格心变换到块的局部坐标，
 *   落在 `|lx| ≤ size/2 且 |lz| ≤ size/2` 内才算覆盖。
 *   轴对齐（`yaw = 0`）时即普通正方形，所以 `orientMode` 两种模式共用这一条路径。
 * - 块中心先减去整体平移量，还原到覆盖网格所在（未平移）的坐标系
 */
function markChunkCovered(c: Chunk, space: CoverSpace, covered: Int32Array): void {
  const { minX, minZ, cell, nx, nz, layerHeight, offsetX, offsetZ } = space
  const mask = layerMaskOfChunk(c, layerHeight)
  const half = c.size / 2
  const cxw = c.center.x - offsetX
  const czw = c.center.z - offsetZ
  const cos = Math.cos(c.yaw)
  const sin = Math.sin(c.yaw)

  // 旋转正方形的 AABB 半宽：仅用于**限定扫描范围**，实际判定用下面的局部坐标
  const ex = Math.abs(cos * half) + Math.abs(sin * half)
  const ez = Math.abs(sin * half) + Math.abs(cos * half)

  const cx0 = Math.max(0, Math.floor((cxw - ex - minX) / cell))
  const cx1 = Math.min(nx - 1, Math.ceil((cxw + ex - minX) / cell))
  const cz0 = Math.max(0, Math.floor((czw - ez - minZ) / cell))
  const cz1 = Math.min(nz - 1, Math.ceil((czw + ez - minZ) / cell))

  for (let cx = cx0; cx <= cx1; cx++) {
    for (let cz = cz0; cz <= cz1; cz++) {
      const dx = minX + cx * cell - cxw
      const dz = minZ + cz * cell - czw
      const lx = dx * cos + dz * sin
      const lz = -dx * sin + dz * cos
      if (Math.abs(lx) <= half && Math.abs(lz) <= half) covered[cz * nx + cx] |= mask
    }
  }
}

/**
 * 给未覆盖的「格 × 层」补块（贪心）：逐格逐层检查，未覆盖就在该格中心补一个自适应尺寸的块。
 * 补块会立即标记覆盖，因此后续若已被新块罩住就跳过 —— 避免重复堆块。
 *
 * 为什么按层补：多层场景里同 XZ 的不同高度是**不同的落脚面**，必须各自有块。
 *
 * 朝向：补块出现在脊线没覆盖到的开阔处，本身没有切线可依据，故**继承就近已布块的朝向**
 * （`nearestYaw`），使同一片区域方向一致；离脊线太远取不到时才退回轴对齐。
 */
function fillUncovered(
  cover: Coverage,
  params: ChunkParams,
  edges: BoundaryEdge[],
  edgeGrid: EdgeGrid,
  polys: PolyRecord[],
  dedup: DedupIndex,
  out: Chunk[]
): number {
  const { minX, minZ, cell, nx, nz, walkable, covered, polyAt } = cover
  let added = 0

  for (let idx = 0; idx < walkable.length; idx++) {
    const unmet = walkable[idx] & ~covered[idx]
    if (unmet === 0) continue

    const cx = idx % nx
    const cz = Math.floor(idx / nx)
    const x = minX + cx * cell
    const z = minZ + cz * cell
    const size = blockSizeAt(x, z, params, edges, edgeGrid)

    for (let layer = 0; layer < LAYER_STRIDE; layer++) {
      if ((unmet & (1 << layer)) === 0) continue

      // 落脚面高度取该格该层所属 poly 的平均高度（与骨架布块同一套 Y 语义）
      const pi = polyAt.get(idx * LAYER_STRIDE + layer)
      const groundY = pi !== undefined ? (polys[pi]?.centroid.y ?? 0) : 0
      const yaw = params.orientMode === 'tangent' ? nearestYaw(dedup, x, groundY, z) : 0
      const chunk: Chunk = {
        center: { x: x + params.offsetX, y: groundY, z: z + params.offsetZ },
        size,
        height: params.boxHeight,
        yaw,
        source: 'fill'
      }
      out.push(chunk)
      // 也登记进索引，让后续补块能继续继承朝向
      addToDedup(dedup, x, groundY, z, size, yaw)
      markChunkCovered(chunk, cover, covered)
      added++
      if (out.length >= MAX_CHUNKS) return added
    }
  }

  return added
}

/** 统计补块后仍未覆盖的「格 × 层」数 */
function countUncovered(cover: Coverage): number {
  let n = 0
  for (let i = 0; i < cover.walkable.length; i++) {
    n += popcount(cover.walkable[i] & ~cover.covered[i])
  }
  return n
}
