/**
 * useChunkIO — chunk 与文件之间的读写：几何换算、格式识别、清单拼装、导出前体检。
 *
 * ## 为什么不引入 zod 或直接复用 viewer-sdk 的 schema
 *
 * 运行时侧用 zod（`viewer-sdk/src/types/gs.schema.ts`）校验配置，但 map-editor 的依赖里
 * 既没有 zod 也没有 viewer-sdk：为一个"载入 + 导出"面板拉进整包运行时（或再加一个 schema
 * 库）不划算。这里的策略是**薄校验 + 原样透传**：
 * - 只校验编辑器真正要解释的字段（`id` / `shape` 的几何数值）；
 * - 其余字段一律不解读，收进 `asset` 原样写回（见 `types/chunk.ts` 的「字段保真」）；
 * - 因此 schema 演进（新增维度字段）不需要同步改这里 —— 代价是不做严格合法性拒绝，
 *   非法字段会照样落盘，由下游 validate-chunk-configs 报错。
 *
 * ## 载入时自动识别的三种形态
 *
 * 1. `runtime-manifest`：顶层 `{ modules: [...] }` —— 外链清单（如
 *    `chunked-collision-manifest-sanyapo.json`）
 * 2. `inline`：`{ chunks: { modules: [...] } }` —— 场景配置里的内联形态
 * 3. `editor`：顶层带 `format: 'map-editor-chunks'` —— 编辑器格式（多带 origin / source）
 *
 * 三者最终都归一到 `ChunkItem[]`，所以载入之后的行为完全一致。
 *
 * @changelog
 * | 版本   | 变更说明                                                       | 关联                          |
 * | v1.0.0 | 初始实现：几何换算 + 三种格式识别 + 清单拼装 + 导出前体检       | REQ: map-editor-chunk-editing |
 * /@changelog
 *
 * @author v_weiqinlin
 */
import type { Chunk } from './useNavmeshChunking'
import {
  CHUNK_EDITOR_FORMAT,
  CHUNK_EDITOR_FORMAT_VERSION,
  type ChunkBoxShape,
  type ChunkItem,
  type ChunkManifestFile,
  type ChunkOrigin
} from '../types/chunk'

/* ============================================================
 * 几何换算（算法 Chunk ↔ 契约 shape）
 * ============================================================ */

const RAD_TO_DEG = 180 / Math.PI
const DEG_TO_RAD = Math.PI / 180

/**
 * 算法产出的块 → 编辑器块。
 *
 * 唯一一处"弧度 → 角度"的换算：算法用 `yaw`（弧度，绕 Y），契约用
 * `transform.rotation`（角度制三元组）。放在这里而不是让调用方各自乘 180/π。
 */
export function chunkToItem(
  c: Chunk,
  id: string,
  origin: ChunkOrigin = 'generated'
): ChunkItem {
  return {
    id,
    shape: {
      type: 'box',
      // 落盘值统一取整到厘米级（见 roundCm）。算法内部用的仍是全精度值 ——
      // 布块、去重、覆盖自检都在 `generateChunks` 里完成，这里只是"写进块对象"的收口，
      // 因此取整不改变切块行为，只是让显示 / 导出 / 存档的数值干净。
      width: roundCm(c.size),
      height: roundCm(c.height),
      depth: roundCm(c.size),
      transform: {
        position: [roundCm(c.center.x), roundCm(c.center.y), roundCm(c.center.z)],
        rotation: [0, roundCm(c.yaw * RAD_TO_DEG), 0],
        scale: [1, 1, 1]
      }
    },
    asset: {},
    origin,
    source: c.source
  }
}

/**
 * 渲染层需要的块形态（与 `useNavmeshRender.setChunks` 的入参一致）。
 *
 * ## 为什么 `rotation` 的 `y` 已经取过负
 *
 * 编辑器的 `rotation[1]` 与 Three 的 Y 旋转手性相反（见 `useNavmeshRender.setChunks` 的
 * 手性说明）。渲染与拾取都直接吃这个值，所以手性修正在这里做**一次**就够了 ——
 * 若两边各修一次，会正好抵消成"看起来是对的"，以后改任何一处都会突然崩掉。
 */
export interface RenderChunk {
  center: { x: number; y: number; z: number }
  size: number
  height: number
  /** 姿态（弧度，X/Y/Z 顺序）；`y` 已按 Three 手性取负 */
  rotation: [number, number, number]
  source?: 'spine' | 'fill'
}

/**
 * 编辑器块 → 渲染形态。
 *
 * ⚠️ 编辑器与算法都只产**正方形**块（XZ 宽 = 深），故这里用 `width` 同时充当渲染的 `size`。
 * 若载入的外部数据宽深不等，解析阶段会给出提示（见 `parseChunkText` 的 warnings），
 * 渲染仍按正方形显示 —— 非正方形块不在本工具的编辑范围内。
 */
export function itemToRenderChunk(item: ChunkItem): RenderChunk {
  const [x, y, z] = item.shape.transform.position
  const [rx, ry, rz] = item.shape.transform.rotation
  return {
    center: { x, y, z },
    size: item.shape.width,
    height: item.shape.height,
    // 存储侧是角度、渲染侧要弧度；Y 再取负（见 RenderChunk.rotation 的说明）
    rotation: [rx * DEG_TO_RAD, -ry * DEG_TO_RAD, rz * DEG_TO_RAD],
    source: item.source ?? undefined
  }
}

/** 批量转换（渲染用） */
export function itemsToRenderChunks(items: ChunkItem[]): RenderChunk[] {
  return items.map(itemToRenderChunk)
}

/**
 * 数值取整到 2 位小数（厘米级）。
 *
 * 为什么在**写入侧**就取整、而不是只在显示时格式化：拖动产生的坐标是浮点长串
 * （如 0.29847687030008974），只改显示的话，导出 / 存档里仍是那一长串 ——
 * 下游读到的值与编辑器里看到的对不上，过后排查很费劲。厘米级对米级场景完全够用。
 */
export function roundCm(v: number): number {
  return Math.round(v * 100) / 100
}

/** 取一个未被占用的块 id（`chunk_<n>`），用于手工新增 */
export function nextChunkId(items: ChunkItem[], prefix = 'chunk'): string {
  const used = new Set(items.map((it) => it.id))
  let n = items.length + 1
  while (used.has(`${prefix}_${n}`)) n++
  return `${prefix}_${n}`
}

/* ============================================================
 * 载入：解析 + 识别
 * ============================================================ */

/** 识别出的文件形态 */
export type ChunkFileFormat = 'runtime-manifest' | 'inline' | 'editor'

export interface ParsedChunkFile {
  format: ChunkFileFormat
  items: ChunkItem[]
  baseUrl?: string
  transform?: Record<string, unknown>
  loadConfig?: Record<string, unknown>
  /** 解析过程中的提示（跳过的不合法块、非正方形块等），供 UI 展示 */
  warnings: string[]
}

/** 形态中文名（提示文案用） */
export const CHUNK_FORMAT_LABELS: Record<ChunkFileFormat, string> = {
  'runtime-manifest': '运行时清单',
  inline: '内联清单',
  editor: '编辑器格式'
}

/**
 * 解析 chunk 文件文本。
 *
 * 失败（JSON 非法 / 结构无法识别 / 一个块都没解析出来）时抛错，错误文案可直接展示；
 * 局部不合法（个别块缺 shape）不抛错，改为记入 `warnings` 并跳过 —— 否则一个坏块会让
 * 整份清单载不进来。
 */
export function parseChunkText(text: string): ParsedChunkFile {
  let data: unknown
  try {
    data = JSON.parse(text)
  } catch (e) {
    throw new Error(`不是合法的 JSON：${e instanceof Error ? e.message : String(e)}`)
  }

  const detected = detectChunkFile(data)
  const warnings: string[] = []
  const items: ChunkItem[] = []
  const seenIds = new Set<string>()

  for (let i = 0; i < detected.modulesRaw.length; i++) {
    const item = parseChunkModule(detected.modulesRaw[i], i, warnings)
    if (!item) continue
    // id 去重：重复 id 会让下游按 id 索引时互相覆盖
    if (seenIds.has(item.id)) {
      const renamed = nextChunkId(items, item.id)
      warnings.push(`块 id「${item.id}」重复，已改名为「${renamed}」`)
      item.id = renamed
    }
    seenIds.add(item.id)
    items.push(item)
  }

  if (items.length === 0) {
    throw new Error('文件里没有解析出任何块（modules 为空或全部不合法），请检查内容')
  }

  return {
    format: detected.format,
    items,
    baseUrl: detected.baseUrl,
    transform: detected.transform,
    loadConfig: detected.loadConfig,
    warnings
  }
}

interface DetectedChunks {
  format: ChunkFileFormat
  modulesRaw: unknown[]
  baseUrl?: string
  transform?: Record<string, unknown>
  loadConfig?: Record<string, unknown>
}

/** 判定文件形态并取出 modules 数组与清单级字段 */
function detectChunkFile(data: unknown): DetectedChunks {
  // 纯数组：当作 modules 列表（手工维护的清单常见这种最宽松形态）
  if (Array.isArray(data)) {
    return { format: 'runtime-manifest', modulesRaw: data }
  }
  if (!isRecord(data)) {
    throw new Error('chunk 文件顶层必须是对象或数组')
  }

  if (data.format === CHUNK_EDITOR_FORMAT) {
    return {
      format: 'editor',
      modulesRaw: requireModulesArray(data.modules, '编辑器格式的 modules'),
      baseUrl: asOptionalString(data.baseUrl),
      transform: asOptionalRecord(data.transform),
      loadConfig: asOptionalRecord(data.loadConfig)
    }
  }

  // 内联形态：直接把 `{ chunks: { modules } }` 拖进来
  // （用局部变量接一下，否则 TS 对 `data.chunks.modules` 的收窄传不到返回值里）
  const inlineWrapper = isRecord(data.chunks) ? data.chunks : null
  const inlineModules = inlineWrapper?.modules
  if (inlineWrapper && Array.isArray(inlineModules)) {
    return {
      format: 'inline',
      modulesRaw: inlineModules,
      baseUrl: asOptionalString(inlineWrapper.baseUrl),
      transform: asOptionalRecord(inlineWrapper.transform),
      loadConfig: asOptionalRecord(inlineWrapper.loadConfig)
    }
  }

  if (Array.isArray(data.modules)) {
    return {
      format: 'runtime-manifest',
      modulesRaw: data.modules,
      baseUrl: asOptionalString(data.baseUrl),
      transform: asOptionalRecord(data.transform),
      loadConfig: asOptionalRecord(data.loadConfig)
    }
  }

  throw new Error(
    '未识别的 chunk 文件：既没有 modules 数组，也没有编辑器格式标记（format: ' +
      `'${CHUNK_EDITOR_FORMAT}'）`
  )
}

/**
 * 单条 module → ChunkItem；不合法时记 warning 并返回 null。
 *
 * 导出是为了让单块 JSON 编辑（`ChunkInspector`）复用同一套校验 —— 否则会出现
 * "文件载入时严格校验、手工粘贴的不校验"这种双标准。
 */
export function parseChunkModule(
  raw: unknown,
  index = 0,
  warnings: string[] = []
): ChunkItem | null {
  const label = `第 ${index + 1} 项`
  if (!isRecord(raw)) {
    warnings.push(`${label}不是对象，已跳过`)
    return null
  }

  // origin / source 是编辑器专有字段，必须从 asset 里摘掉，否则会被当成维度字段写回
  const { id, shape, origin, source, ...asset } = raw

  const shapeError = checkBoxShape(shape)
  if (shapeError) {
    warnings.push(`${label}（id: ${String(id ?? '无')}）：${shapeError}，已跳过`)
    return null
  }

  const normalized = normalizeBoxShape(shape as Record<string, unknown>)
  if (Math.abs(normalized.width - normalized.depth) > 1e-6) {
    // 编辑器只处理正方形块：算法输出宽深相等，非正方形只能是外部数据
    warnings.push(
      `${label}（id: ${String(id ?? '无')}）的 width(${normalized.width}) ≠ depth(${normalized.depth})，` +
        '编辑器按正方形显示与编辑（以 width 为准）'
    )
  }

  return {
    id: typeof id === 'string' && id.trim() ? id : `chunk_${index + 1}`,
    shape: normalized,
    asset,
    origin: isChunkOrigin(origin) ? origin : 'loaded',
    source: source === 'spine' || source === 'fill' ? source : null
  }
}

/** 校验 box shape；返回错误文案，合法时返回 null */
function checkBoxShape(shape: unknown): string | null {
  if (!isRecord(shape)) return '缺少 shape 字段'
  if (shape.type !== 'box') {
    return `shape.type=${String(shape.type)} 不是 box（分块几何目前只支持 box）`
  }
  if (
    !isPositiveNumber(shape.width) ||
    !isPositiveNumber(shape.height) ||
    !isPositiveNumber(shape.depth)
  ) {
    return 'shape 的 width / height / depth 必须是正数'
  }
  const t = shape.transform
  if (!isRecord(t)) return 'shape 缺少 transform'
  if (!isVec3(t.position) || !isVec3(t.rotation) || !isVec3(t.scale)) {
    return 'transform 的 position / rotation / scale 必须是 3 个数字'
  }
  return null
}

/** 只保留契约字段，多余字段丢弃（box shape 在下游是 .strict() 的） */
function normalizeBoxShape(shape: Record<string, unknown>): ChunkBoxShape {
  const t = shape.transform as Record<string, unknown>
  return {
    type: 'box',
    width: shape.width as number,
    height: shape.height as number,
    depth: shape.depth as number,
    transform: {
      position: vec3(t.position),
      rotation: vec3(t.rotation),
      scale: vec3(t.scale)
    }
  }
}

function vec3(v: unknown): [number, number, number] {
  const a = v as number[]
  return [a[0], a[1], a[2]]
}

/* ============================================================
 * 导出：清单拼装 + 体检
 * ============================================================ */

/**
 * 拼装供运行时消费的清单。
 *
 * 字段顺序刻意与运行时的 canonical 样例一致（`id` → 维度字段 → `shape`），
 * 便于人工比对 diff。清单级可选字段只在载入时确实带过才写回 —— 没带过就不凭空造。
 */
export function buildChunkManifest(
  items: ChunkItem[],
  extra: Pick<ParsedChunkFile, 'baseUrl' | 'transform' | 'loadConfig'> = {}
): ChunkManifestFile {
  const modules = items.map((it) => ({ id: it.id, ...it.asset, shape: it.shape }))
  const out: ChunkManifestFile = { modules }
  if (extra.baseUrl) out.baseUrl = extra.baseUrl
  if (extra.transform) out.transform = extra.transform
  if (extra.loadConfig) out.loadConfig = extra.loadConfig
  return out
}

/**
 * 导出前体检：返回需要提示的问题（不阻断导出）。
 *
 * 为什么只提示不阻断：编辑器不知道当前是哪个维度，而各维度对字段的要求不同
 * （light 的 url 可选、collision 的 url 必填）。编辑器硬拦会把合法场景也拦掉，
 * 因此把判断交回给用户与下游校验脚本。
 *
 * 判断依据一律是**字段存在性**而不是"维度"：编辑器不猜维度，只对"声明了这个字段、
 * 但值显然不能通过下游校验"的情况发声（如 `configFile: ''`、`programs: {}`）。
 */
export function validateChunkItemsForExport(items: ChunkItem[]): string[] {
  const problems: string[] = []
  if (items.length === 0) {
    problems.push('没有任何块，导出的清单会是空清单')
    return problems
  }

  const seen = new Set<string>()
  for (const it of items) {
    if (seen.has(it.id)) problems.push(`块 id 重复：${it.id}`)
    seen.add(it.id)
    if (!isPositiveNumber(it.shape.width) || !isPositiveNumber(it.shape.height)) {
      problems.push(`块「${it.id}」的尺寸不是正数`)
    }
  }

  const noUrl = items.filter((it) => typeof it.asset.url !== 'string' || !it.asset.url)
  if (noUrl.length > 0) {
    problems.push(
      `${noUrl.length} 个块没有 url 字段（collision / terrain 等维度的资源地址，` +
        `运行时需要它才能加载块资源）`
    )
  }

  // 下面两类是"骨架给不出合法值"的字段（见 utils/chunkTemplate 的取值策略）：
  // 空骨架是有意为之，但导出前要提醒用户手工补，否则下游 zod 会拒绝整份清单
  const emptyConfigFile = items.filter(
    (it) => 'configFile' in it.asset && emptyString(it.asset.configFile)
  )
  if (emptyConfigFile.length > 0) {
    problems.push(
      `${emptyConfigFile.length} 个块的 configFile 为空（npc 区域清单要求非空路径）`
    )
  }

  const emptyPrograms = items.filter((it) => {
    const p = it.asset.programs
    return (
      p !== undefined && (typeof p !== 'object' || p === null || Object.keys(p).length === 0)
    )
  })
  if (emptyPrograms.length > 0) {
    problems.push(
      `${emptyPrograms.length} 个块的 programs 为空（program 维度要求至少 1 条 program）`
    )
  }
  return problems
}

/* ============================================================
 * 小工具
 * ============================================================ */

function isRecord(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v)
}

function isPositiveNumber(v: unknown): v is number {
  return typeof v === 'number' && Number.isFinite(v) && v > 0
}

function isVec3(v: unknown): boolean {
  return Array.isArray(v) && v.length >= 3 && v.slice(0, 3).every((n) => typeof n === 'number')
}

function isChunkOrigin(v: unknown): v is ChunkOrigin {
  return v === 'generated' || v === 'loaded' || v === 'manual'
}

/** 字符串是不是"空"（非字符串也算空） */
function emptyString(v: unknown): boolean {
  return typeof v !== 'string' || v.trim() === ''
}

function asOptionalString(v: unknown): string | undefined {
  return typeof v === 'string' && v ? v : undefined
}

function asOptionalRecord(v: unknown): Record<string, unknown> | undefined {
  return isRecord(v) ? v : undefined
}

function requireModulesArray(v: unknown, what: string): unknown[] {
  if (!Array.isArray(v)) throw new Error(`${what} 不是数组`)
  return v
}

/** 编辑器格式版本号（导出时可写入；当前导出走运行时清单，仅保留供识别用） */
export const EDITOR_FORMAT_VERSION = CHUNK_EDITOR_FORMAT_VERSION
