/**
 * useNavmeshReachabilityExport — Navmesh 起点驱动的 reachableNeighbors 导出器。
 *
 * 与 useAnchorReachabilityExport 的区别：
 *   - 数据源是 navmesh flood fill 的可达 polyRef 集合 + Detour link 表（polygon 共享边索引）
 *   - 邻接判定 = "起点连通过滤 + module 间 navmesh 直接邻接"：
 *       A↔B ⇔ navmesh 上存在跨 module 的 polygon link，且 link 两端 polyRef 都在起点
 *       flood fill 可达集合 R 内、且分别归属不同 module（centroid 命中策略与渲染层一致）
 *   - 不可达 / navmesh 未覆盖的 module 统一写 reachableNeighbors: []，与 anchor 版对齐
 *
 * 关键技术决策：
 *   - 不修改 floodFillFromPoly 的签名：邻接对收集放在本文件私有函数 collectCrossModuleAdjacencies，
 *     与 flood fill 解耦。代价是多一次同样的 link 遍历，但 R ≤ polygon 总数、且只在导出时跑一次。
 *   - 不把 polyModuleMap 加到 store：导出时即时重算 mapPolyToModule（typical < 5ms），
 *     保持 store 最小必要状态。
 *   - 跨 module 判定走 Detour link 表（recast 烘焙时建立的 polygon 共享边索引），
 *     不走 polygon 几何求交：精确、便宜、零浮点误差风险。
 *   - 顶层结构 / 字段顺序 / 文件命名前缀严格对齐 anchor 版（modules-with-navmesh-reachability-<ts>.json），
 *     下游可统一消费两套导出器的产物。
 *
 * 字段语义（与 anchor 版一致）：
 *   reachableNeighbors[m] = { n | (m,n) ∈ navmesh跨module邻接对 ∩ R_m × R_m }，
 *   字典序、去重、不含自身；不可达 / 未覆盖 → []。
 *
 * @changelog
 * | 版本   | 变更说明                                                               | 关联                                                                |
 * | v1.0.0 | 初始实现：起点驱动 + Detour link 跨 module 邻接 + manifest 克隆下载    | REQ: navmesh-reachability-export TECH: plan §核心算法 §架构设计     |
 * /@changelog
 *
 * @author fancylin
 */
import { Detour, type NavMesh } from 'recast-navigation'
import { useModulesStore } from '../stores/modules'
import { useNavmeshStore } from '../stores/navmesh'
import { mapPolyToModule } from './usePolyToModule'

/* ============================================================
 * 对外 API
 * ============================================================ */

/**
 * 在原 manifest 基础上克隆并为每个 module 附加 `reachableNeighbors` 字段（Navmesh 版本）。
 * - 顶层结构与字段保持原样
 * - 每个 module 的原字段保持不变；末尾追加 `reachableNeighbors: string[]`
 * - 数据源：当前 navmesh store 的 startPoint + reachablePolyRefs + Detour link 表
 *
 * 抛出：
 *   - 当前没有已加载 manifest
 *   - 当前没有烘焙产物（navMeshRef 为空）
 *   - 当前没有起点 / 起点 flood fill 结果为空
 */
export function buildNavmeshAnnotatedManifest(): Record<string, unknown> {
  const modulesStore = useModulesStore()
  const navmeshStore = useNavmeshStore()

  const manifest = modulesStore.manifest
  if (!manifest) {
    throw new Error('当前没有已加载的 manifest，无法导出')
  }
  const navMesh = navmeshStore.navMeshRef
  if (!navMesh) {
    throw new Error('当前没有 navmesh 烘焙产物，请先点击「应用并烘焙」')
  }
  if (!navmeshStore.startPoint || navmeshStore.reachablePolyRefs.size === 0) {
    throw new Error('当前没有起点或起点 flood fill 结果为空，请先在 3D 视口选起点')
  }

  const t0 = performance.now()
  const neighborsMap = computeNavmeshNeighborsMap()
  const elapsed = performance.now() - t0

  const modulesOut = manifest.modules.map((m) => {
    // v2.0.0：导出新写法（shape + splatTransform），不再写老的 transform / bounds
    const cloned: Record<string, unknown> = {
      name: m.name,
      shape: {
        type: 'box',
        width: m.shape.width,
        height: m.shape.height,
        depth: m.shape.depth,
        transform: {
          position: [...m.shape.transform.position] as [number, number, number],
          rotation: [...m.shape.transform.rotation] as [number, number, number],
          scale: [...m.shape.transform.scale] as [number, number, number]
        }
      },
      splatTransform: {
        rotation: [...m.splatTransform.rotation],
        scale: [...m.splatTransform.scale] as [number, number, number]
      },
      collision_name: [...m.collision_name],
      ply_name: [...m.ply_name],
      reachableNeighbors: neighborsMap.get(m.name) ?? []
    }
    return cloned
  })

  // 邻接总数 = 所有 module 的 neighbor 数之和 / 2（无向去重）
  let adjPairs = 0
  for (const list of neighborsMap.values()) adjPairs += list.length
  adjPairs = Math.round(adjPairs / 2)
  console.info(
    `[navmesh] export ok: ${modulesOut.length} modules, ${adjPairs} adjacencies, ${elapsed.toFixed(1)}ms`
  )

  return {
    baseUrl: manifest.baseUrl,
    morton: manifest.morton,
    fileType: manifest.fileType,
    modules: modulesOut
  }
}

/**
 * 触发浏览器下载：带 reachableNeighbors 字段（Navmesh 版本）的新 manifest JSON。
 * @param filename 缺省为 modules-with-navmesh-reachability-<timestamp>.json
 */
export function downloadNavmeshAnnotatedManifestJson(filename?: string): Record<string, unknown> {
  const data = buildNavmeshAnnotatedManifest()
  const json = JSON.stringify(data, null, 2)
  triggerDownload(json, filename ?? `modules-with-navmesh-reachability-${tsLabel()}.json`)
  return data
}

/* ============================================================
 * 私有：核心计算
 * ============================================================ */

/**
 * 计算每个 module 的可达邻居（按 moduleName → string[]，字典序、去重、不含自身）。
 *
 * 步骤：
 *   1) 用 mapPolyToModule(polygons, R, modules) 重算 polyModuleMap
 *   2) collectCrossModuleAdjacencies(navMesh, R, polyModuleMap) 收集无向邻接对
 *   3) 把邻接对集合展开成 Map<module, string[]>，每个 list 排序去重
 */
function computeNavmeshNeighborsMap(): Map<string, string[]> {
  const out = new Map<string, string[]>()
  const navmeshStore = useNavmeshStore()
  const modulesStore = useModulesStore()

  const navMesh = navmeshStore.navMeshRef
  if (!navMesh) return out
  const reachable = navmeshStore.reachablePolyRefs
  if (reachable.size === 0) return out

  // 1) 重算 polyModuleMap（与 setStart 时 store 内的 reachableModuleIds 同源策略）
  const mapped = mapPolyToModule(navmeshStore.polygons, reachable, modulesStore.modules)
  const polyModuleMap = mapped.polyModuleMap

  // 2) 收集跨 module 邻接对（基于 Detour link 表，仅遍历 R 内 polyRef）
  const adjacency = collectCrossModuleAdjacencies(navMesh, reachable, polyModuleMap)

  // 3) Map<string, Set<string>> → Map<string, string[]>，字典序排序
  for (const [name, set] of adjacency) {
    out.set(name, Array.from(set).sort())
  }
  return out
}

/**
 * 基于 Detour link 表收集"起点连通过滤 + 跨 module 直接邻接"的无向邻接对。
 *
 * 算法：
 *   for each ref ∈ reachablePolyRefs:
 *     mA = polyModuleMap[ref]; if !mA continue
 *     for each link in poly.links:
 *       neiRef = link.ref(); if !neiRef continue
 *       if neiRef ∉ reachablePolyRefs continue          // 起点连通过滤
 *       mB = polyModuleMap[neiRef]; if !mB continue
 *       if mA === mB continue                            // 同 module，不算邻接
 *       记录无向对 (mA, mB)
 *
 * 复杂度：O(|R| × avgLinkPerPoly)；典型 < 10ms。
 *
 * 返回：Map<moduleName, Set<moduleName>>，对每个 module 给出其邻居集合（双向写入）。
 */
function collectCrossModuleAdjacencies(
  navMesh: NavMesh,
  reachablePolyRefs: Set<number>,
  polyModuleMap: Map<number, string>
): Map<string, Set<string>> {
  const adjacency = new Map<string, Set<string>>()

  for (const ref of reachablePolyRefs) {
    const mA = polyModuleMap.get(ref)
    if (!mA) continue
    const { poly, tile } = navMesh.getTileAndPolyByRefUnsafe(ref)
    // 沿 link 链遍历，与 useNavmeshFloodFill 保持同款 idiom
    for (
      let i = poly.firstLink();
      i !== Detour.DT_NULL_LINK;
      i = tile.links(i).next()
    ) {
      const neiRef = tile.links(i).ref()
      if (!neiRef) continue
      if (!reachablePolyRefs.has(neiRef)) continue
      const mB = polyModuleMap.get(neiRef)
      if (!mB || mB === mA) continue

      // 双向写入（无向）
      let setA = adjacency.get(mA)
      if (!setA) {
        setA = new Set<string>()
        adjacency.set(mA, setA)
      }
      setA.add(mB)

      let setB = adjacency.get(mB)
      if (!setB) {
        setB = new Set<string>()
        adjacency.set(mB, setB)
      }
      setB.add(mA)
    }
  }

  return adjacency
}

/* ============================================================
 * 内部工具（与 anchor 版完全同款）
 * ============================================================ */

function tsLabel(): string {
  return new Date().toISOString().replace(/[:.]/g, '-').replace('T', '_').slice(0, 19)
}

function triggerDownload(text: string, filename: string) {
  const blob = new Blob([text], { type: 'application/json' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = filename
  document.body.appendChild(a)
  a.click()
  document.body.removeChild(a)
  setTimeout(() => URL.revokeObjectURL(url), 1000)
}
