<script setup lang="ts">
/**
 * ChunkListDropdown — 地块列表下拉（chunk 子流程工具栏）。
 *
 * ## 为什么需要它
 *
 * 块在场景里密集重叠（相邻块按 `stepRatio` 有意overlap），选中项以外的块又是压暗的，
 * 靠鼠标在场景里点准目标块并不容易；而右栏只能显示"当前选中的块"，本身无法切换。
 * 列表是唯一可靠的切换入口，也顺便回答"这一份清单到底有多少块"。
 *
 * ## 职责边界
 *
 * 本组件只决定"选了哪一个"（写 `store.selectedChunkId`），场景高亮、右栏面板、
 * 拖动手柄的联动由父层完成 —— 那些都要 `renderHandle`，本组件不该持有。
 *
 * @changelog
 * | 版本   | 变更说明                                        | 关联                          |
 * | v1.0.0 | 初始实现：块列表下拉（含数量）+ 选中联动          | REQ: map-editor-chunk-editing |
 * /@changelog
 *
 * @author v_weiqinlin
 */
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { Boxes, Check, ChevronDown } from 'lucide-vue-next'
import { useNavmeshStore } from '../stores/navmesh'

const emit = defineEmits<{
  /** 选中了某块（父层据此重绘 3D 与同步拖动手柄） */
  (e: 'pick'): void
}>()

const store = useNavmeshStore()
const open = ref(false)
const rootRef = ref<HTMLElement | null>(null)

/** 下拉按钮上的文案：当前选中块的 id，未选中时给一个行动指引 */
const currentLabel = computed(() => store.selectedChunk?.id ?? '选择地块')

function pick(id: string) {
  store.selectChunk(id)
  open.value = false
  emit('pick')
}

// 与 SubFlowToolbar 同一套关闭范式：点外部 / 按 Esc 收起
function onDocMouseDown(e: MouseEvent) {
  if (!open.value) return
  const el = rootRef.value
  if (el && !el.contains(e.target as Node)) open.value = false
}

function onDocKeydown(e: KeyboardEvent) {
  if (e.key === 'Escape') open.value = false
}

onMounted(() => {
  document.addEventListener('mousedown', onDocMouseDown)
  document.addEventListener('keydown', onDocKeydown)
})
onBeforeUnmount(() => {
  document.removeEventListener('mousedown', onDocMouseDown)
  document.removeEventListener('keydown', onDocKeydown)
})
</script>

<template>
  <div ref="rootRef" class="relative shrink-0">
    <button
      type="button"
      class="flex items-center gap-1.5 px-2.5 py-1 rounded-md text-[11px] font-medium transition-all cursor-pointer border"
      :class="
        open
          ? 'bg-cyan-glow/10 border-cyan-glow/60 text-cyan-glow'
          : 'text-slate-300 border-white/10 hover:border-cyan-glow/40 hover:text-cyan-glow hover:bg-cyan-glow/10'
      "
      aria-haspopup="listbox"
      :aria-expanded="open"
      :title="`地块列表（共 ${store.chunkItems.length} 块）：选中后可在右侧属性面板查看与编辑`"
      @click="open = !open"
    >
      <Boxes class="w-3 h-3 shrink-0" />
      <span class="max-w-[10rem] truncate text-left font-mono">{{ currentLabel }}</span>
      <span class="shrink-0 text-slate-500">({{ store.chunkItems.length }})</span>
      <ChevronDown
        class="w-3 h-3 shrink-0 transition-transform"
        :class="open ? 'rotate-180' : ''"
      />
    </button>

    <ul
      v-if="open"
      class="absolute left-0 top-full mt-1 z-40 min-w-full max-h-[60vh] overflow-y-auto overflow-x-hidden scrollbar-thin py-1 rounded-lg border border-white/10 bg-[#0b1120]/95 backdrop-blur-glass shadow-glass animate-fade-in"
      role="listbox"
    >
      <li v-for="it in store.chunkItems" :key="it.id">
        <button
          type="button"
          class="w-full flex items-center gap-1.5 px-2.5 py-1.5 text-[11px] font-mono whitespace-nowrap transition-colors cursor-pointer"
          :class="
            it.id === store.selectedChunkId
              ? 'text-cyan-glow bg-cyan-glow/10'
              : 'text-slate-300 hover:text-slate-100 hover:bg-white/5'
          "
          role="option"
          :aria-selected="it.id === store.selectedChunkId"
          :title="it.id"
          @click="pick(it.id)"
        >
          <Check v-if="it.id === store.selectedChunkId" class="w-3 h-3 shrink-0" />
          <span v-else class="w-3 shrink-0" />
          {{ it.id }}
        </button>
      </li>
    </ul>
  </div>
</template>
