/**
 * useNavmeshRender — 把 PolyRecord[] 渲染成 Three.js 多边形覆盖层。
 *
 * 渲染策略：
 * - 一个 Group 容纳全部 navmesh 可视化：
 *   * `meshFill`     —— 全部 polygon 半透明青色填充（顶点色：可达=翠绿，不可达=青色）
 *   * `wireframe`    —— 全部 polygon 边线（白色 60% 透明）
 *   * `moduleHalos`  —— 各 module worldBox 的颜色覆盖层（绿=可达 / 红=不可达 / 灰=未涉及）
 *   * `markers`      —— 起点 / 终点小球
 *   * `pathLine`     —— funnel 平滑路径折线
 *   * `centerline`   —— 脊线（拓扑骨架，橙色，每段一条 Line）
 *
 * 关键设计：
 * - 每个 polygon 都做"扇形三角化"（顶点 0 + i + i+1），solo navmesh 的 poly 已经是凸的，
 *   扇形剖分等价于 Recast 内部的方式（detailMesh 提供更精细三角，但对实验工具足够）。
 * - 可达性着色用顶点颜色，避免每次 flood fill 都重建 geometry。flood fill 改变时只更新
 *   `BufferAttribute.color`，性能 < 5ms / 1w polygon。
 * - dispose 严格按 mesh → geometry → material 顺序释放，避免 Three.js 显存泄漏。
 *
 * @changelog
 * | 版本   | 变更说明                                                       | 关联                    |
 * | v1.0.0 | 新增 setCenterlines：navmesh 中轴骨架线渲染（橙色）             | REQ: navmesh-centerline |
 * | v2.0.0 | 下线 setVoxelGrid：体素网格显示开关已从界面移除，渲染层不再保留 | REQ: map-editor-ui-shell |
 * | v2.1.0 | 切块选中改为"压暗其余"：setChunks 按选中与否分组绘制，去掉独立高亮盒 | REQ: map-editor-chunk-editing |
 * | v2.1.1 | 其余块的压暗透明度 0.25 → 0.15，让选中项对比更明显                   | REQ: map-editor-chunk-editing |
 * | v2.2.0 | 面/棱边分开调：其余块只留轮廓（面 0.06、棱 0.35）；选中块 0.85→0.25 以看透地形 | REQ: map-editor-chunk-editing |
 * | v2.2.1 | 修：选中块 0.25 比默认 0.34 还暗（选中反而"变灰"），提到 0.5          | REQ: map-editor-chunk-editing |
 * /@changelog
 */
import {
  BoxGeometry,
  BufferGeometry,
  Color,
  DoubleSide,
  Euler,
  Float32BufferAttribute,
  Group,
  InstancedMesh,
  Line,
  LineBasicMaterial,
  LineSegments,
  Material,
  Matrix4,
  Mesh,
  MeshBasicMaterial,
  Object3D,
  SphereGeometry,
  Vector3,
  type Box3,
  Box3Helper
} from 'three'
import type { PolyRecord } from '../stores/navmesh'

/** 复用的临时欧拉角：块数可达数百，逐块 new 会白白产生一堆垃圾 */
const tmpEuler = new Euler()

/** 颜色常量 */
const COLOR_REACHABLE = new Color(0x34d399) // emerald
const COLOR_UNREACHABLE_POLY = new Color(0x22d3ee) // cyan
const COLOR_WIREFRAME = new Color(0xffffff)
const COLOR_MODULE_REACH = new Color(0x34d399)
const COLOR_MODULE_UNREACH = new Color(0xef4444)
const COLOR_MODULE_NEUTRAL = new Color(0x64748b)
const COLOR_START_MARKER = new Color(0xef4444)
const COLOR_END_MARKER = new Color(0xfbbf24)
const COLOR_PATH = new Color(0xfacc15)
const COLOR_CENTERLINE = new Color(0xf97316) // orange，导航脊线/骨架（区别于寻路黄线）
const COLOR_SELECTED = new Color(0x22d3ee) // cyan-glow，用于 minimap 选中 module 联动高亮

/** 块的面透明度（默认态，未选中任何块时） */
const CHUNK_FACE_OPACITY = 0.34
/** 块的棱边透明度（默认态） */
const CHUNK_EDGE_OPACITY = 0.95
/**
 * 选中某块时，**其余块**的面透明度 —— 压到几乎只剩一点体积感。
 *
 * 意图是"其余块只留轮廓"：面给到最低，只保留一丁点填充让它仍像个盒子，
 * 空间关系交给棱边（见 `CHUNK_DIM_EDGE_OPACITY`）去表达。
 */
const CHUNK_DIM_FACE_OPACITY = 0.06
/**
 * 选中某块时，**其余块**的棱边透明度。
 *
 * 这是"隐约能看个轮廓、方便选择其他块"的落点：面几乎透明、轮廓仍在，
 * 既不会用色块抢走注意力，也不会因为完全看不见而不知道那里有块可点。
 *
 * ⚠️ 不要跟着面一起往下压：棱边降到面的量级后，其余块在深色底上就只剩一团糊影，
 * "能选别的块"这件事就失去了视觉依据。
 */
const CHUNK_DIM_EDGE_OPACITY = 0.35
/**
 * 选中块的面透明度。
 *
 * ## 为什么卡在中间值（而不是越高越好或越低越好）
 *
 * 它同时决定两件方向相反的事：
 * - **越高越醒目** —— 一眼看出正在编辑哪一块
 * - **越低越透** —— 看得见它盖住的那片地形（选中块常常正是为了核对自己与地形的关系）
 *
 * 所以它必须**高于默认的 `CHUNK_FACE_OPACITY`（0.34）**、又**明显低于"填实"**：
 * - 一度压到 0.25（比默认还低）实测是错的：选中那一刻那块反而暗下去，而且近白色的面
 *   在 0.25 的 alpha 下被深色背景稀释成灰，"亮白"变成了"发灰"
 * - 一度用 0.85 也是错的：块成了实心盒子，把地形完全挡住
 *
 * 0.5 是两者的折中：比默认亮（有明确的"被选中"感）、又留了一半透光（地形可见）。
 */
const CHUNK_ACTIVE_OPACITY = 0.5
/** 选中块的棱边透明度：直接拉满，让轮廓最清晰 */
const CHUNK_ACTIVE_EDGE_OPACITY = 1
/** 手动补线颜色（lime）：与自动骨架橙、路径黄、可达绿都不撞色 */
const COLOR_SPINE_GUIDE = new Color(0x84cc16)

/** 切块立方体的 8 个顶点（单位立方体 [-0.5, 0.5]，按 比例 缩放后即为实际块） */
const CUBE_CORNERS: Array<[number, number, number]> = [
  [-0.5, -0.5, -0.5],
  [0.5, -0.5, -0.5],
  [0.5, -0.5, 0.5],
  [-0.5, -0.5, 0.5],
  [-0.5, 0.5, -0.5],
  [0.5, 0.5, -0.5],
  [0.5, 0.5, 0.5],
  [-0.5, 0.5, 0.5]
]

/** 单位立方体的 12 条棱（顶点索引对） */
const CUBE_EDGE_IDX: Array<[number, number]> = [
  [0, 1],
  [1, 2],
  [2, 3],
  [3, 0],
  [4, 5],
  [5, 6],
  [6, 7],
  [7, 4],
  [0, 4],
  [1, 5],
  [2, 6],
  [3, 7]
]

export interface NavmeshRenderHandle {
  /** 挂载到主 scene 的根 group */
  root: Group
  /** 重建 navmesh 几何（烘焙完成后调用） */
  setPolygons(polys: PolyRecord[]): void
  /** flood fill 结果更新（仅更新顶点色，不重建 geometry） */
  setReachable(reachable: Set<number>): void
  /** 设置/清除起点 marker */
  setStartMarker(point: { x: number; y: number; z: number } | null): void
  /** 设置/清除终点 marker */
  setEndMarker(point: { x: number; y: number; z: number } | null): void
  /** 更新 module worldBox 高亮层 */
  setModuleHalos(
    items: Array<{
      name: string
      box: Box3
      state: 'reach' | 'unreach' | 'neutral'
    }>
  ): void
  /** 更新路径折线（flat xyz array） */
  setPath(points: Float32Array): void
  /** 更新脊线（每段一条折线，flat xyz） */
  setCenterlines(lines: Float32Array[]): void
  /**
   * 手动补线（用户手绘的脊线段，lime 色，与自动骨架区分）。传空数组清除。返回段数。
   */
  setSpineGuides(lines: Float32Array[]): number
  /**
   * 手动补线的"已选第一点"锚点标记（小球）；null = 清除。
   *
   * 为什么需要：补线是"两次点击成一段"，第一次点击后必须给用户**可见的反馈**，
   * 否则用户不知道点有没有生效、点在哪了。
   */
  setSpineAnchor(point: { x: number; y: number; z: number } | null): void
  /**
   * 切块可视化：把块画成半透明着色立方体。传空数组清除。返回绘制的块数。
   *
   * `selectedIndex` 指定的块保持正常显示，**其余块整体压暗**（单块编辑时凸显选中项）。
   */
  setChunks(
    chunks: Array<{
      center: { x: number; y: number; z: number }
      size: number
      height: number
      /** 姿态（弧度，X/Y/Z 顺序）。手性修正已在 `itemToRenderChunk` 做过 */
      rotation: [number, number, number]
      /** 来源：骨架布块 / 覆盖补块（补块用醒目色渲染） */
      source?: 'spine' | 'fill'
    }>,
    selectedIndex?: number
  ): number
  /** 设置/清除"被选中 module"的高亮框（minimap → 3D 联动） */
  setSelectedModule(box: Box3 | null): void
  /** 全量清空（不释放 root） */
  clear(): void
  /** 彻底释放：从父节点摘除 + dispose 所有资源 */
  dispose(): void
}

/**
 * 把每个 polygon 按"扇形三角化"展开为 (v0, vi, vi+1) 三角形，输出 flat positions 与颜色。
 * 同时构建线框（每条 polygon 边一条 LineSegment）。
 */
function buildFillGeometry(polys: PolyRecord[]): {
  fillGeo: BufferGeometry
  wireGeo: BufferGeometry
  /** polyIndex → fill 三角形顶点起始索引（用于 setReachable 快速染色） */
  fillVertexRange: Array<{ start: number; count: number }>
} {
  let triVertCount = 0
  let lineVertCount = 0
  for (const p of polys) {
    const n = p.vertices.length / 3
    triVertCount += (n - 2) * 3
    lineVertCount += n * 2
  }

  const fillPos = new Float32Array(triVertCount * 3)
  const fillCol = new Float32Array(triVertCount * 3)
  const linePos = new Float32Array(lineVertCount * 3)
  const fillVertexRange: Array<{ start: number; count: number }> = new Array(polys.length)

  let fpW = 0
  let fcW = 0
  let lpW = 0
  let vertexCursor = 0

  for (let pi = 0; pi < polys.length; pi++) {
    const verts = polys[pi].vertices
    const n = verts.length / 3
    const triCount = n - 2
    const triVerts = triCount * 3
    fillVertexRange[pi] = { start: vertexCursor, count: triVerts }
    vertexCursor += triVerts

    // 扇形三角化
    const x0 = verts[0]
    const y0 = verts[1]
    const z0 = verts[2]
    for (let i = 1; i < n - 1; i++) {
      // v0
      fillPos[fpW++] = x0
      fillPos[fpW++] = y0 + 0.05 // 微抬高，避免和地表 z-fighting
      fillPos[fpW++] = z0
      // vi
      fillPos[fpW++] = verts[i * 3]
      fillPos[fpW++] = verts[i * 3 + 1] + 0.05
      fillPos[fpW++] = verts[i * 3 + 2]
      // vi+1
      fillPos[fpW++] = verts[(i + 1) * 3]
      fillPos[fpW++] = verts[(i + 1) * 3 + 1] + 0.05
      fillPos[fpW++] = verts[(i + 1) * 3 + 2]
      // 默认色：不可达
      for (let k = 0; k < 3; k++) {
        fillCol[fcW++] = COLOR_UNREACHABLE_POLY.r
        fillCol[fcW++] = COLOR_UNREACHABLE_POLY.g
        fillCol[fcW++] = COLOR_UNREACHABLE_POLY.b
      }
    }

    // 闭合线框
    for (let i = 0; i < n; i++) {
      const a = i
      const b = (i + 1) % n
      linePos[lpW++] = verts[a * 3]
      linePos[lpW++] = verts[a * 3 + 1] + 0.06
      linePos[lpW++] = verts[a * 3 + 2]
      linePos[lpW++] = verts[b * 3]
      linePos[lpW++] = verts[b * 3 + 1] + 0.06
      linePos[lpW++] = verts[b * 3 + 2]
    }
  }

  const fillGeo = new BufferGeometry()
  fillGeo.setAttribute('position', new Float32BufferAttribute(fillPos, 3))
  fillGeo.setAttribute('color', new Float32BufferAttribute(fillCol, 3))

  const wireGeo = new BufferGeometry()
  wireGeo.setAttribute('position', new Float32BufferAttribute(linePos, 3))

  return { fillGeo, wireGeo, fillVertexRange }
}

function disposeObject3D(obj: Object3D) {
  obj.traverse((child) => {
    const m = child as Mesh
    if ((m as Mesh).geometry) (m as Mesh).geometry.dispose()
    const mat = (m as Mesh).material
    if (Array.isArray(mat)) mat.forEach((mm) => (mm as Material).dispose())
    else if (mat) (mat as Material).dispose()
  })
}

export function createNavmeshRender(): NavmeshRenderHandle {
  const root = new Group()
  root.name = 'NavmeshRenderRoot'

  // 子分组（便于按需重建）
  const fillGroup = new Group()
  fillGroup.name = 'navmesh-fill'
  const wireGroup = new Group()
  wireGroup.name = 'navmesh-wire'
  const moduleHaloGroup = new Group()
  moduleHaloGroup.name = 'module-halos'
  const selectedHaloGroup = new Group()
  selectedHaloGroup.name = 'selected-halo'
  const markersGroup = new Group()
  markersGroup.name = 'markers'
  const pathGroup = new Group()
  pathGroup.name = 'path'
  const centerlineGroup = new Group()
  centerlineGroup.name = 'centerline'
  const guideGroup = new Group()
  guideGroup.name = 'spine-guides'
  const guideAnchorGroup = new Group()
  guideAnchorGroup.name = 'spine-guide-anchor'
  const chunkGroup = new Group()
  chunkGroup.name = 'chunks'
  root.add(
    fillGroup,
    wireGroup,
    chunkGroup,
    moduleHaloGroup,
    selectedHaloGroup,
    markersGroup,
    pathGroup,
    centerlineGroup,
    guideGroup,
    guideAnchorGroup
  )

  // 缓存当前几何对应的 fillVertexRange，用于 setReachable
  let currentPolys: PolyRecord[] = []
  let currentRanges: Array<{ start: number; count: number }> = []
  let currentFillMesh: Mesh | null = null
  let currentWireMesh: LineSegments | null = null
  // polyRef → polyIndex 映射
  let polyRefIndex = new Map<number, number>()

  function clearGroup(g: Group) {
    while (g.children.length > 0) {
      const c = g.children[0]
      g.remove(c)
      disposeObject3D(c)
    }
  }

  function setPolygons(polys: PolyRecord[]) {
    clearGroup(fillGroup)
    clearGroup(wireGroup)
    currentPolys = polys
    polyRefIndex = new Map(polys.map((p, idx) => [p.ref, idx]))

    if (polys.length === 0) {
      currentRanges = []
      currentFillMesh = null
      currentWireMesh = null
      return
    }

    const { fillGeo, wireGeo, fillVertexRange } = buildFillGeometry(polys)
    currentRanges = fillVertexRange

    const fillMat = new MeshBasicMaterial({
      vertexColors: true,
      transparent: true,
      opacity: 0.28,
      side: DoubleSide,
      depthWrite: false
    })
    const fillMesh = new Mesh(fillGeo, fillMat)
    fillMesh.renderOrder = 1
    fillGroup.add(fillMesh)
    currentFillMesh = fillMesh

    const wireMat = new LineBasicMaterial({
      color: COLOR_WIREFRAME,
      transparent: true,
      opacity: 0.55,
      depthWrite: false
    })
    const wireMesh = new LineSegments(wireGeo, wireMat)
    wireMesh.renderOrder = 2
    wireGroup.add(wireMesh)
    currentWireMesh = wireMesh
  }

  function setReachable(reachable: Set<number>) {
    if (!currentFillMesh || currentPolys.length === 0) return
    const colAttr = currentFillMesh.geometry.getAttribute('color') as Float32BufferAttribute
    const arr = colAttr.array as Float32Array
    for (let pi = 0; pi < currentPolys.length; pi++) {
      const range = currentRanges[pi]
      const reach = reachable.has(currentPolys[pi].ref)
      const c = reach ? COLOR_REACHABLE : COLOR_UNREACHABLE_POLY
      const opacityBoost = reach ? 1 : 1
      const base = range.start * 3
      for (let v = 0; v < range.count; v++) {
        arr[base + v * 3] = c.r * opacityBoost
        arr[base + v * 3 + 1] = c.g * opacityBoost
        arr[base + v * 3 + 2] = c.b * opacityBoost
      }
    }
    colAttr.needsUpdate = true
    // 给可达态加点不透明度
    const mat = currentFillMesh.material as MeshBasicMaterial
    mat.opacity = reachable.size > 0 ? 0.4 : 0.28
    mat.needsUpdate = true
  }

  function makeMarker(
    point: { x: number; y: number; z: number },
    color: Color,
    radius: number
  ) {
    const geo = new SphereGeometry(radius, 16, 12)
    const mat = new MeshBasicMaterial({ color, transparent: true, opacity: 0.95 })
    const m = new Mesh(geo, mat)
    m.position.set(point.x, point.y + radius * 1.5, point.z)
    return m
  }

  let startMesh: Mesh | null = null
  let endMesh: Mesh | null = null

  function estimateMarkerRadius(): number {
    if (currentPolys.length === 0) return 0.5
    // 用 polygons 总 bbox 估一个合理半径
    let mn = Infinity
    let mx = -Infinity
    for (const p of currentPolys) {
      mn = Math.min(mn, p.bmin.x, p.bmin.z)
      mx = Math.max(mx, p.bmax.x, p.bmax.z)
    }
    const span = mx - mn
    return Math.min(1.5, Math.max(0.25, span * 0.004))
  }

  function setStartMarker(point: { x: number; y: number; z: number } | null) {
    if (startMesh) {
      markersGroup.remove(startMesh)
      disposeObject3D(startMesh)
      startMesh = null
    }
    if (point) {
      startMesh = makeMarker(point, COLOR_START_MARKER, estimateMarkerRadius())
      markersGroup.add(startMesh)
    }
  }

  function setEndMarker(point: { x: number; y: number; z: number } | null) {
    if (endMesh) {
      markersGroup.remove(endMesh)
      disposeObject3D(endMesh)
      endMesh = null
    }
    if (point) {
      endMesh = makeMarker(point, COLOR_END_MARKER, estimateMarkerRadius())
      markersGroup.add(endMesh)
    }
  }

  function setModuleHalos(
    items: Array<{ name: string; box: Box3; state: 'reach' | 'unreach' | 'neutral' }>
  ) {
    clearGroup(moduleHaloGroup)
    for (const it of items) {
      if (it.box.isEmpty()) continue
      const color =
        it.state === 'reach'
          ? COLOR_MODULE_REACH
          : it.state === 'unreach'
            ? COLOR_MODULE_UNREACH
            : COLOR_MODULE_NEUTRAL
      const helper = new Box3Helper(it.box, color)
      const mat = helper.material as LineBasicMaterial
      mat.transparent = true
      mat.opacity = it.state === 'neutral' ? 0.2 : it.state === 'reach' ? 0.85 : 0.7
      helper.userData.moduleName = it.name
      moduleHaloGroup.add(helper)
    }
  }

  function setPath(points: Float32Array) {
    clearGroup(pathGroup)
    if (points.length < 6) return
    // 微抬高
    const lifted = new Float32Array(points.length)
    for (let i = 0; i < points.length; i += 3) {
      lifted[i] = points[i]
      lifted[i + 1] = points[i + 1] + 0.15
      lifted[i + 2] = points[i + 2]
    }
    const geo = new BufferGeometry()
    geo.setAttribute('position', new Float32BufferAttribute(lifted, 3))
    const mat = new LineBasicMaterial({
      color: COLOR_PATH,
      transparent: true,
      opacity: 0.95,
      linewidth: 3
    })
    const line = new Line(geo, mat)
    line.renderOrder = 3
    pathGroup.add(line)

    // 端点 + 中间点小球点缀
    const r = estimateMarkerRadius() * 0.6
    const dotGeo = new SphereGeometry(r, 10, 8)
    const dotMat = new MeshBasicMaterial({ color: COLOR_PATH, transparent: true, opacity: 0.9 })
    const v = new Vector3()
    for (let i = 0; i < lifted.length; i += 3) {
      v.set(lifted[i], lifted[i + 1], lifted[i + 2])
      const m = new Mesh(dotGeo, dotMat)
      m.position.copy(v)
      pathGroup.add(m)
    }
  }

  /**
   * 绘制脊线：每段一条独立 Line（段与段之间不相连，故不用 LineSegments）。
   * 抬升 0.18（略高于寻路路径的 0.15），避免两者重叠时闪烁。
   */
  function setCenterlines(lines: Float32Array[]) {
    clearGroup(centerlineGroup)
    if (lines.length === 0) return

    for (const points of lines) {
      if (points.length < 6) continue

      const lifted = new Float32Array(points.length)
      for (let i = 0; i < points.length; i += 3) {
        lifted[i] = points[i]
        lifted[i + 1] = points[i + 1] + 0.18
        lifted[i + 2] = points[i + 2]
      }

      const geo = new BufferGeometry()
      geo.setAttribute('position', new Float32BufferAttribute(lifted, 3))
      // 每段独立 material：避免多段共享导致 dispose 时重复释放同一对象
      const mat = new LineBasicMaterial({
        color: COLOR_CENTERLINE,
        transparent: true,
        opacity: 0.95,
        linewidth: 2
      })
      const line = new Line(geo, mat)
      line.renderOrder = 4
      line.frustumCulled = false
      centerlineGroup.add(line)
    }
  }

  /**
   * 手动补线：与脊线同样的画法，但换 lime 色 + 抬升 0.26（压在自动骨架之上）。
   *
   * 为什么要单独一组、单独颜色：自动骨架（橙）与手动补线（黄绿）语义不同 ——
   * 前者是算法产物、重算即失效；后者是用户劳动成果、必须一眼可辨且不被覆盖。
   */
  function setSpineGuides(lines: Float32Array[]): number {
    clearGroup(guideGroup)
    let drawn = 0

    for (const points of lines) {
      if (points.length < 6) continue

      const lifted = new Float32Array(points.length)
      for (let i = 0; i < points.length; i += 3) {
        lifted[i] = points[i]
        lifted[i + 1] = points[i + 1] + 0.26
        lifted[i + 2] = points[i + 2]
      }

      const geo = new BufferGeometry()
      geo.setAttribute('position', new Float32BufferAttribute(lifted, 3))
      const mat = new LineBasicMaterial({
        color: COLOR_SPINE_GUIDE,
        transparent: true,
        opacity: 1,
        linewidth: 3
      })
      const line = new Line(geo, mat)
      line.renderOrder = 6
      line.frustumCulled = false
      guideGroup.add(line)
      drawn++
    }

    return drawn
  }

  /** 手动补线的"已选第一点"锚点：一个 lime 小球，让用户看清第一点落在哪 */
  function setSpineAnchor(point: { x: number; y: number; z: number } | null) {
    clearGroup(guideAnchorGroup)
    if (!point) return
    const m = makeMarker(point, COLOR_SPINE_GUIDE, estimateMarkerRadius() * 0.8)
    m.renderOrder = 7
    guideAnchorGroup.add(m)
  }

  /**
   * 切块可视化：每个块画成**半透明着色立方体 + 高亮边框**。
   *
   * 为什么必须画边框：块之间默认重叠 50%，只有半透明面的话相邻块会糊成一片色块，
   * 完全看不出"一块一块"。加上每块的 12 条棱边后，切分关系一眼可辨。
   *
   * 颜色按黄金比步进（hue += 0.618）取色 —— 相邻块色相差异最大，便于分辨。
   * 面用 InstancedMesh（单 draw call），边合并成一条 LineSegments（单 draw call）。
   */
  function setChunks(
    chunks: Array<{
      center: { x: number; y: number; z: number }
      size: number
      height: number
      /**
       * 姿态（弧度，X/Y/Z 顺序，Three 手性）。
       *
       * ⚠️ **不要在这里再做手性修正**：编辑器的 `rotation[1]` 与 Three 的 Y 旋转手性相反，
       * 那个取负已经在 `itemToRenderChunk` 里做过一次了。渲染与拾取都吃同一个
       * `RenderChunk`，修正在一处做完，两边才不会各偏一次、正好抵消成"看起来是对的"。
       */
      rotation: [number, number, number]
      /** 来源：骨架布块 / 覆盖补块（补块用醒目色，便于定位"骨架没覆盖到"的地方） */
      source?: 'spine' | 'fill'
    }>,
    /**
     * 选中块的下标（单块编辑用）：该块改用近白高亮色。
     *
     * 为什么用下标而不是 id：渲染层不认识编辑器的 id 语义，让调用方把"哪个 id"
     * 翻成"第几个"更干净 —— 渲染层只管画。
     */
    selectedIndex = -1
  ): number {
    clearGroup(chunkGroup)
    if (chunks.length === 0) return 0

    // ① 面与 ② 棱边都按「选中 / 未选中」拆成两组分别绘制。
    //
    // 为什么必须拆：InstancedMesh 的面材质是**共享**的，没法逐实例改透明度；而选中某块时
    // 要把其余块整体压暗（选中项才凸显）。拆成两批各多一个 draw call，代价可忽略。
    const geo = new BoxGeometry(1, 1, 1)
    const m4 = new Matrix4()
    const scaleVec = new Vector3()
    const color = new Color()

    // ⚠️ 只有"确实选中了某块"才压暗其余。未选中时 selectedIndex = -1，
    // 若照旧判定，全部块都会落进压暗组 —— 表现为"什么都没选，块却一直是淡的"。
    const hasSelection = selectedIndex >= 0 && selectedIndex < chunks.length
    const activeIdx: number[] = []
    const dimIdx: number[] = []
    for (let i = 0; i < chunks.length; i++) {
      if (hasSelection && i !== selectedIndex) dimIdx.push(i)
      else activeIdx.push(i)
    }

    const buildFaces = (indices: number[], opacity: number, order: number) => {
      if (indices.length === 0) return
      const mesh = new InstancedMesh(
        geo,
        new MeshBasicMaterial({
          transparent: true,
          opacity,
          side: DoubleSide,
          depthWrite: false
        }),
        indices.length
      )
      for (let k = 0; k < indices.length; k++) {
        const i = indices[k]
        const c = chunks[i]
        // 先局部缩放 → 再按姿态旋转 → 最后平移到块心。
        // `rotation` 已是 Three 手性（手性修正在 itemToRenderChunk 做过），这里直接用。
        tmpEuler.set(c.rotation[0], c.rotation[1], c.rotation[2], 'XYZ')
        m4.makeRotationFromEuler(tmpEuler)
        m4.scale(scaleVec.set(c.size, c.height, c.size))
        m4.setPosition(c.center.x, c.center.y, c.center.z)
        mesh.setMatrixAt(k, m4)
        // 配色仍按「第几块」取（骨架块黄金比、补块警示色），压暗前后色相一致
        if (c.source === 'fill') color.setHSL(0.02, 0.85, 0.55)
        else color.setHSL((i * 0.618) % 1, 0.75, 0.58)
        mesh.setColorAt(k, color)
      }
      mesh.instanceMatrix.needsUpdate = true
      if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true
      mesh.renderOrder = order
      mesh.frustumCulled = false
      chunkGroup.add(mesh)
    }

    // 未选中任何块 → 全部按默认透明度；选中 → 选中项保留（半透明，能看透到地形）、其余只留轮廓
    buildFaces(activeIdx, hasSelection ? CHUNK_ACTIVE_OPACITY : CHUNK_FACE_OPACITY, 1)
    buildFaces(dimIdx, CHUNK_DIM_FACE_OPACITY, 0)

    // 棱边：同样按组拆。顶点色只有 RGB，逐顶点 alpha 要靠 three 的隐式 USE_COLOR_ALPHA，
    // 不如分组直白可靠 —— 每组各自展开成一条 LineSegments。
    const buildEdges = (indices: number[], opacity: number, order: number) => {
      if (indices.length === 0) return
      const segs = indices.length * CUBE_EDGE_IDX.length
      const pos = new Float32Array(segs * 2 * 3)
      const colr = new Float32Array(segs * 2 * 3)
      const edgeColor = new Color()
      let w = 0

      for (const i of indices) {
        const c = chunks[i]
        // 棱边直接写世界坐标，必须套一遍与实例矩阵**完全相同**的姿态旋转
        tmpEuler.set(c.rotation[0], c.rotation[1], c.rotation[2], 'XYZ')
        m4.makeRotationFromEuler(tmpEuler)
        const e = m4.elements
        if (c.source === 'fill') edgeColor.setHSL(0.02, 1, 0.75)
        else edgeColor.setHSL((i * 0.618) % 1, 0.85, 0.78)

        for (const [ia, ib] of CUBE_EDGE_IDX) {
          for (const vi of [ia, ib]) {
            const corner = CUBE_CORNERS[vi]
            // corner 分量是 ±0.5，乘 c.size / c.height 即得 ±(size/2) / ±(height/2)
            const lx = corner[0] * c.size
            const ly = corner[1] * c.height
            const lz = corner[2] * c.size
            // 列主序：world = e[0]·lx + e[4]·ly + e[8]·lz（再平移）
            pos[w++] = c.center.x + e[0] * lx + e[4] * ly + e[8] * lz
            pos[w++] = c.center.y + e[1] * lx + e[5] * ly + e[9] * lz
            pos[w++] = c.center.z + e[2] * lx + e[6] * ly + e[10] * lz
            colr[w - 3] = edgeColor.r
            colr[w - 2] = edgeColor.g
            colr[w - 1] = edgeColor.b
          }
        }
      }

      const g = new BufferGeometry()
      g.setAttribute('position', new Float32BufferAttribute(pos, 3))
      g.setAttribute('color', new Float32BufferAttribute(colr, 3))
      const lines = new LineSegments(
        g,
        new LineBasicMaterial({ vertexColors: true, transparent: true, opacity })
      )
      lines.renderOrder = order
      lines.frustumCulled = false
      chunkGroup.add(lines)
    }

    buildEdges(activeIdx, hasSelection ? CHUNK_ACTIVE_EDGE_OPACITY : CHUNK_EDGE_OPACITY, 3)
    buildEdges(dimIdx, CHUNK_DIM_EDGE_OPACITY, 2)

    return chunks.length
  }

  function setSelectedModule(box: Box3 | null) {
    clearGroup(selectedHaloGroup)
    if (!box || box.isEmpty()) return
    // 主体粗框：cyan-glow，比 module halo 显眼
    const helper = new Box3Helper(box, COLOR_SELECTED)
    const mat = helper.material as LineBasicMaterial
    mat.transparent = true
    mat.opacity = 0.95
    mat.depthTest = false
    helper.renderOrder = 5
    selectedHaloGroup.add(helper)
  }

  function clear() {
    clearGroup(fillGroup)
    clearGroup(wireGroup)
    clearGroup(moduleHaloGroup)
    clearGroup(selectedHaloGroup)
    clearGroup(markersGroup)
    clearGroup(pathGroup)
    clearGroup(centerlineGroup)
    clearGroup(guideGroup)
    clearGroup(guideAnchorGroup)
    clearGroup(chunkGroup)
    currentPolys = []
    currentRanges = []
    currentFillMesh = null
    currentWireMesh = null
    startMesh = null
    endMesh = null
    polyRefIndex.clear()
  }

  function dispose() {
    clear()
    root.parent?.remove(root)
  }

  // 暴露给外部一个查 polyIndex 的 helper（path render 用不到，但保留 API 完整性）
  void polyRefIndex
  void currentWireMesh

  return {
    root,
    setPolygons,
    setReachable,
    setStartMarker,
    setEndMarker,
    setModuleHalos,
    setPath,
    setCenterlines,
    setSpineGuides,
    setSpineAnchor,
    setChunks,
    setSelectedModule,
    clear,
    dispose
  }
}
