/**
 * useNavmeshSkeleton — 在 navmesh 的 **poly 邻接图**上构建连通骨架。
 *
 * ## 解决什么问题
 *
 * Voronoi 中轴是**几何量**：它要过四道过滤（外心有效 / 半径 ≥ minRadius / 外心在区域内 /
 * Voronoi 边全程在区域内），任何一道不过就断。于是**楼梯（窄）**与**空旷区（大）**这两类
 * 几何极端情形必然断线 —— 这是方法的固有性质，调参堵不完。
 *
 * 本模块改用**拓扑**方式：以 polygon 为节点、Detour link 为边建图，取**生成树**作为骨架。
 *
 * | | Voronoi 中轴 | 本模块（图骨架） |
 * |---|---|---|
 * | 连通性 | ❌ 会断 | ✅ **生成树，数学上不可能断** |
 * | 覆盖率 | ❌ 窄/大处没有 | ✅ **覆盖每一个 poly**（含楼梯） |
 * | 位置 | ✅ 严格等距脊线 | 🟡 门（共享边中点）之间连线 |
 *
 * ## 关键设计：枢纽是「门」而不是「质心」
 *
 * **每个 poly 的进出都经过"门"**（= 它与相邻 poly 的**共享边中点**，即通道横断面中心）：
 *
 * ```
 * 入点 = 与父 poly 的门    出点 = 与各子 poly 的门
 *
 * 度 2（走廊）    入点 ────── 出点         ← 一条直线，天然沿通道
 * 度 3+（分叉）   入点 ─┬──── 出点1
 *                      ├──── 出点2         ← 分叉点落在"门"上，星芒只有门到门的弦长
 *                      └──── 出点3
 * 叶子            入点 ────── 质心
 * 根              质心 ──┬─── 出点1
 *                       └─── 出点2
 * ```
 *
 * 如果改成"所有邻居都连到质心"，大 poly 里就会甩出**贯穿整个 poly 的长星芒**，
 * 视觉上像一团放射线 —— 这正是本设计要避免的。
 *
 * ## 输出
 *
 * 相邻段共享同一个"门"点 ⇒ 整体视觉连续、无断口。
 * 连通分量数 > 1 时，各分量各成一棵树（本来就不通，不该连）。
 *
 * @changelog
 * | 版本   | 变更说明                                                     | 关联                    |
 * | v1.0.0 | 初始实现：poly 邻接图生成树 + 共享边中点 → 连通骨架            | REQ: navmesh-chunking   |
 * | v1.1.0 | 枢纽由「poly 质心」改为「门（共享边中点）」：消除大 poly 的长星芒 | REQ: navmesh-chunking   |
 * /@changelog
 *
 * @author v_weiqinlin
 */
import { Detour, type NavMesh } from 'recast-navigation'
import type { PolyRecord } from '../stores/navmesh'

/** 骨架抬升（米）：略高于 navmesh 填充，避免 z-fighting */
const SKELETON_LIFT = 0.12

/** 判定"同一顶点"的 XZ 容差平方（0.05m） */
const VERTEX_MATCH_EPS2 = 0.0025

interface Vec3 {
  x: number
  y: number
  z: number
}

export interface SkeletonResult {
  /** 骨架折线（每段 2 点，flat xyz） */
  lines: Float32Array[]
  /** poly 总数 */
  polyCount: number
  /** 树边数（= 门数） */
  edgeCount: number
  /** navmesh 连通分量数（每个分量一棵树） */
  componentCount: number
  /** 未能取到共享边、退回质心直连的门数 */
  fallbackEdges: number
  elapsedMs: number
}

/**
 * 构建连通骨架（生成树 + 门之间连线）。
 *
 * @param navMesh 烘焙产物（只读，不修改）
 * @param polys   navmesh polygon 列表
 */
export function buildGraphSkeleton(navMesh: NavMesh, polys: PolyRecord[]): SkeletonResult {
  const t0 = performance.now()
  const result: SkeletonResult = {
    lines: [],
    polyCount: polys.length,
    edgeCount: 0,
    componentCount: 0,
    fallbackEdges: 0,
    elapsedMs: 0
  }
  if (polys.length === 0) return result

  const byRef = new Map<number, PolyRecord>()
  for (const p of polys) byRef.set(p.ref, p)

  // ① 邻接图（Detour link → ref，过滤掉不在 PolyRecord 里的）
  const adj = new Map<number, number[]>()
  for (const p of polys) {
    const nbrs: number[] = []
    for (const r of collectLinkedRefs(navMesh, p.ref)) {
      if (byRef.has(r)) nbrs.push(r)
    }
    adj.set(p.ref, nbrs)
  }

  // ② "门"缓存：同一对 poly 无论从哪个方向问，都得到同一个点 ⇒ 保证视觉连通
  const portalCache = new Map<string, Vec3>()
  const portal = (a: PolyRecord, b: PolyRecord): Vec3 => {
    const key = a.ref < b.ref ? `${a.ref}_${b.ref}` : `${b.ref}_${a.ref}`
    const hit = portalCache.get(key)
    if (hit) return hit

    const mid = sharedEdgeMidpoint(a, b)
    const pt = mid ?? midOfCentroids(a, b)
    if (!mid) result.fallbackEdges++
    portalCache.set(key, pt)
    return pt
  }

  // ③ 逐连通分量 BFS：记录 parent（生成树），再按"门 → 门"铺线
  const visited = new Set<number>()
  for (const start of adj.keys()) {
    if (visited.has(start)) continue
    result.componentCount++

    visited.add(start)
    const parentOf = new Map<number, number>()
    const childrenOf = new Map<number, number[]>()
    const queue: number[] = [start]
    let head = 0

    while (head < queue.length) {
      const cur = queue[head++]
      for (const nb of adj.get(cur) ?? []) {
        if (visited.has(nb)) continue
        visited.add(nb)
        parentOf.set(nb, cur)
        const kids = childrenOf.get(cur)
        if (kids) kids.push(nb)
        else childrenOf.set(cur, [nb])
        queue.push(nb)
      }
    }

    // ③a 根：质心 → 各子门
    const root = byRef.get(start)
    if (root) {
      const rc = liftedCentroid(root)
      for (const child of childrenOf.get(start) ?? []) {
        const pc = byRef.get(child)
        if (!pc) continue
        result.lines.push(segmentXZ(rc, portal(root, pc)))
      }
    }

    // ③b 非根节点：入点（与父的门）→ 各子门；叶子则为 入点 → 质心
    for (const [ref, parentRef] of parentOf) {
      const node = byRef.get(ref)
      const parent = byRef.get(parentRef)
      if (!node || !parent) continue

      const entry = portal(parent, node)
      const kids = childrenOf.get(ref) ?? []
      result.edgeCount++

      if (kids.length === 0) {
        result.lines.push(segmentXZ(entry, liftedCentroid(node)))
        continue
      }
      for (const child of kids) {
        const pc = byRef.get(child)
        if (!pc) continue
        result.lines.push(segmentXZ(entry, portal(node, pc)))
      }
    }
  }

  result.elapsedMs = performance.now() - t0
  return result
}

/** 两点成段（带抬升，flat xyz） */
function segmentXZ(a: Vec3, b: Vec3): Float32Array {
  return new Float32Array([
    a.x,
    a.y + SKELETON_LIFT,
    a.z,
    b.x,
    b.y + SKELETON_LIFT,
    b.z
  ])
}

function liftedCentroid(p: PolyRecord): Vec3 {
  return { x: p.centroid.x, y: p.centroid.y, z: p.centroid.z }
}

function midOfCentroids(a: PolyRecord, b: PolyRecord): Vec3 {
  return {
    x: (a.centroid.x + b.centroid.x) / 2,
    y: (a.centroid.y + b.centroid.y) / 2,
    z: (a.centroid.z + b.centroid.z) / 2
  }
}

/** 遍历某 poly 的 Detour link，收集直接相连的 polyRef */
function collectLinkedRefs(navMesh: NavMesh, polyRef: number): number[] {
  const out: number[] = []
  try {
    const { poly, tile } = navMesh.getTileAndPolyByRefUnsafe(polyRef)
    for (let i = poly.firstLink(); i !== Detour.DT_NULL_LINK; i = tile.links(i).next()) {
      const neiRef = tile.links(i).ref()
      if (neiRef) out.push(neiRef)
    }
  } catch {
    // 取不到 tile 的 ref（罕见）：当作无邻居
  }
  return out
}

/**
 * 两块相邻 poly 共享边的中点（= 通道横断面中心）。
 *
 * 做法：找出 a 中与 b **XZ 重合**的顶点（相邻 poly 共享边即共享这两个顶点），取其中点。
 * 找不到（几何不共顶点）返回 null，调用方退回质心中点。
 */
function sharedEdgeMidpoint(a: PolyRecord, b: PolyRecord): Vec3 | null {
  const av = a.vertices
  const bv = b.vertices
  const na = av.length / 3
  const nb = bv.length / 3

  let sx = 0
  let sy = 0
  let sz = 0
  let count = 0

  for (let i = 0; i < na; i++) {
    const ax = av[i * 3]
    const az = av[i * 3 + 2]
    for (let j = 0; j < nb; j++) {
      const dx = ax - bv[j * 3]
      const dz = az - bv[j * 3 + 2]
      if (dx * dx + dz * dz <= VERTEX_MATCH_EPS2) {
        sx += ax
        sy += av[i * 3 + 1]
        sz += az
        count++
        break
      }
    }
  }

  if (count === 0) return null
  return { x: sx / count, y: sy / count, z: sz / count }
}
