<script setup lang="ts">
/**
 * PropGroup — 属性树里的嵌套分组（对象 / 数组节点）。
 *
 * 折叠交互照 meta 的 `CollapseSection`（点整行切换、箭头转 90°、可带 badge），
 * 但视觉上做了减法：**不刷背景色阶**，只用左侧竖线 + 缩进表达层级。
 * 右栏本身只有 300px 左右、又是深色底，叠几层背景色会在暗色里糊成一片、
 * 反而看不出层级；一条竖线在深色下更清楚。
 *
 * ## 默认展开状态由调用方给
 *
 * 树是递归的，折叠状态属于"渲染策略"而不是节点自身的属性 —— 由 `PropTree`
 * 按深度决定（浅层展开、深层收起），见那边的注释。
 *
 * ## 字号与列宽是四处联动的
 *
 * 见 `PropRow` 的同名说明：本组件的 `6rem` / `text-[14px]` 要与
 * `PropRow` / `PropKeyList` / `PropTree` 保持一致。
 *
 * @changelog
 * | 版本   | 变更说明                                        | 关联                          |
 * | v1.0.0 | 初始实现：可折叠分组（竖线缩进 + badge）          | REQ: map-editor-chunk-editing |
 * | v1.1.0 | 新增 unset：未配置分组的 key 用灰色              | REQ: map-editor-chunk-editing |
 * | v1.2.0 | 字号放大到 14px，左列 4.5rem→6rem               | REQ: map-editor-chunk-editing |
 * /@changelog
 *
 * @author v_weiqinlin
 */
import { ref } from 'vue'
import { ChevronRight } from 'lucide-vue-next'

const props = withDefaults(
  defineProps<{
    label: string
    /** 收起时显示的摘要（如数组的「3 项」） */
    badge?: string
    defaultExpanded?: boolean
    /** 契约里有、数据里还没有的分组：key 用灰色（badge 通常是「未配置」） */
    unset?: boolean
  }>(),
  { defaultExpanded: false }
)

const open = ref(props.defaultExpanded)
</script>

<template>
  <div class="border-b border-white/5">
    <button
      type="button"
      class="w-full grid grid-cols-[6rem_minmax(0,1fr)] gap-2 items-center min-h-[30px] py-1 text-left cursor-pointer transition-colors hover:bg-white/[0.03]"
      :title="label"
      @click="open = !open"
    >
      <span class="min-w-0 flex items-center gap-1">
        <ChevronRight
          class="w-3.5 h-3.5 shrink-0 text-slate-500 transition-transform"
          :class="open ? 'rotate-90' : ''"
        />
        <span
          class="min-w-0 truncate font-mono text-[14px]"
          :class="unset ? 'text-slate-500' : 'text-slate-300'"
          >{{ label }}</span
        >
      </span>
      <span class="min-w-0 flex items-center gap-2">
        <span v-if="badge" class="shrink-0 font-mono text-[13px] text-slate-500">{{
          badge
        }}</span>
        <span v-else-if="!open" class="min-w-0 truncate font-mono text-[13px] text-slate-600">
          {{ '{…}' }}
        </span>
      </span>
    </button>

    <!-- 内容区：左侧竖线 + 缩进表达层级（不刷背景色，见组件头注释） -->
    <div v-if="open" class="ml-1.5 pl-3 border-l border-white/10">
      <slot />
    </div>
  </div>
</template>
