/** 该维度的字段形状表（属性面板据此列出「未配置」行） */
export function fieldsForKind(kind: ChunkKind): Record<string, FieldSpec> {
  return KIND_FIELDS[kind] ?? {}
}

/** light 的 10 个参数通道（识别维度用；与 `KIND_FIELDS.light` 的键一致） */
const LIGHT_CHANNEL_KEYS = [
  'ambient',
  'sky',
  'hdri',
  'shadow',
  'lightProbeVolume',
  'lightSchedules',
  'lightCulling',
  'directional',
  'points',
  'lightMeshes'
]

/**
 * 从块数据反推维度。
 *
 * ## 什么时候用
 *
 * 维度是**整份清单**的属性（一份清单不可能混两种类型，混了下游直接拒），所以编辑器手里
 * 这个值只有两个来源：第一次生成 / 新增块时用户选的那一次，或者**从已有清单反推**。
 * 后者就是本函数 —— 载入的清单没有维度标记（manifest 里只有 `baseUrl` + `modules`），
 * 只能按字段特征认。
 *
 * ## 两级依据
 *
 * 1. **独有字段**（可靠）：出现即锁定该维度，见下面的分支。
 * 2. **`url` 的扩展名**（兜底）：只剩 `url` 时，`collision` 与 `terrain` 靠字段区分不了
 *    （两者都必有 `url`），但资源类型不同 —— 碰撞是模型（`.glb` / `.gltf`），
 *    地形是高度图（`.r16` / `.raw` / `.bin`）。这一条只能算启发式，错了也只是面板多列
 *    或少列几行「未配置」字段，不会损坏数据。
 *
 * ## 认不出就返回 null（认错比认不出更糟）
 *
 * 认错会让属性面板按**错误的契约**列出「未配置」字段，用户可能真去填，然后被下游
 * `.strict()` 拒绝 —— 比"不列"难查得多。`null` 时面板退化为"只展示数据里已有的字段"，
 * 在任何维度下都是对的；工具栏会显示「类型未识别」，且**可以点它补选一次**（见
 * `NavmeshView` 的类型指示），所以认不出不等于没救。
 */
export function guessKind(asset: Record<string, unknown>): ChunkKind | null {
  const has = (k: string) => k in asset
  if (has('programs')) return 'program'
  if (has('configFile')) return 'npc'
  if (LIGHT_CHANNEL_KEYS.some(has)) return 'light'
  if (has('uvRegion') || has('resolution')) return 'terrain'
  if (has('opacity') || has('cloneAsLightMesh')) return 'collision'

  // 只剩 url：按资源扩展名兜底（见注释"两级依据"）
  if (typeof asset.url === 'string') {
    const u = asset.url.toLowerCase()
    if (u.includes('.glb') || u.includes('.gltf')) return 'collision'
    if (/\.(r16|raw|bin|hgt)/.test(u)) return 'terrain'
  }
  return null
}

/**
 * 指定维度的最小合法骨架：取 `required` 字段，给"契约可接受的空值"。
 *
 * ⚠️ 返回值是导出合法性的下限（如 collision 的 `url` 缺了会被下游 zod 拒整份清单），
 * 改字段表时务必实测"生成块后 asset 仍是 `{ url: '' }` / `{ programs: {} }` / `{}` /
 * `{ configFile: '' }`"。
 */
export function skeletonForKind(kind: ChunkKind): Record<string, unknown> {
  return requiredSkeleton(fieldsForKind(kind))
}

/** 取形状表里所有 `required` 字段，按类型给空值 */
function requiredSkeleton(fields: Record<string, FieldSpec>): Record<string, unknown> {
  const out: Record<string, unknown> = {}
  for (const [key, spec] of Object.entries(fields)) {
    if (spec.required) out[key] = emptyValueFor(spec)
  }
  return out
}

/** 某个形状的"空值"（见文件头的取值策略：空值而非"立刻合法"） */
function emptyValueFor(spec: FieldSpec): unknown {
  switch (spec.kind) {
    case 'string':
      return ''
    case 'number':
      return 0
    case 'boolean':
      return false
    case 'array':
      return []
    case 'vec': {
      if (spec.as === 'object') {
        const out: Record<string, number> = {}
        for (let i = 0; i < spec.size; i++) out[['x', 'y', 'z'][i]] = 0
        return out
      }
      return new Array(spec.size).fill(0)
    }
    case 'object':
      return requiredSkeleton(spec.fields)
  }
}

/**
 * 从已有块推断骨架：**只取键名，值一律清空**。
 *
 * ⚠️ 不能照抄值：`url` 是每个块各自的资源地址，抄过来新块就指向别人的模型，
 * 而且这种错很难发现（能显示、校验也过）。
 *
 * `preferredId` 传当前选中的块 —— "选中哪块、新增的就照哪块"，直观可控；
 * 比"取所有块的并集"安全（并集会把个别块才有的字段也带上）。
 */
export function skeletonFromItems(
  items: ChunkItem[],
  preferredId?: string | null
): Record<string, unknown> {
  if (items.length === 0) return {}
  const ref = (preferredId && items.find((it) => it.id === preferredId)) || items[0]
  return zeroedClone(ref.asset) as Record<string, unknown>
}

/** 按已有值的形态生成"同结构、值清空"的副本 */
function zeroedClone(value: unknown): unknown {
  if (Array.isArray(value)) return []
  if (value !== null && typeof value === 'object') {
    const out: Record<string, unknown> = {}
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      out[k] = zeroedClone(v)
    }
    return out
  }
  if (typeof value === 'string') return ''
  if (typeof value === 'number') return 0
  if (typeof value === 'boolean') return false
  return value
}

/**
 * 解析本次新建块该用的骨架。
 *
 * - `kind` 有值（这份清单的维度已定）：用该维度的骨架
 * - `kind` 为 `null`：跟随已有块（照抄键名、值清空）；**一个块都没有时返回空对象** ——
 *   调用方应在"没有块也没有维度"时先问用户选一次（见 `NavmeshView.requireKind`）
 *
 * `kind` 不再是"每块一次的选择"：一份清单只有一个维度，详见 store 里 `chunkKind` 的注释。
 */
export function resolveSkeleton(
  kind: ChunkKind | null,
  items: ChunkItem[],
  preferredId?: string | null
): Record<string, unknown> {
  if (kind) return skeletonForKind(kind)
  return skeletonFromItems(items, preferredId)
}
