<script setup lang="ts">
import { computed, ref } from 'vue'
import { Upload, FileBox, Trash2, Loader2, RotateCw, ChevronDown, FlipHorizontal2 } from 'lucide-vue-next'
import { loadGLBFiles } from '../composables/useGLBLoader'
import { useTerrainStore } from '../stores/terrain'
import { useThreeScene } from '../composables/useThreeScene'

const store = useTerrainStore()
const { addObject, removeObject } = useThreeScene()
const fileInputRef = ref<HTMLInputElement | null>(null)
const isDragging = ref(false)

/** 哪些 terrain 展开了旋转面板 */
const expandedRotation = ref<Set<string>>(new Set())

const progressText = computed(() => {
  if (!store.isLoading) return ''
  return `加载中 ${Math.round(store.loadingProgress * 100)}%`
})

function pickFiles() {
  fileInputRef.value?.click()
}

async function onInputChange(e: Event) {
  const input = e.target as HTMLInputElement
  if (!input.files || input.files.length === 0) return
  await handleFiles(input.files)
  input.value = ''
}

function onDragOver(e: DragEvent) {
  e.preventDefault()
  isDragging.value = true
}

function onDragLeave() {
  isDragging.value = false
}

async function onDrop(e: DragEvent) {
  e.preventDefault()
  isDragging.value = false
  const files = e.dataTransfer?.files
  if (!files || files.length === 0) return
  await handleFiles(files)
}

async function handleFiles(files: FileList | File[]) {
  store.setLoading(true)
  const items = await loadGLBFiles(files, (loaded, total) => {
    store.setProgress(loaded / total)
  })
  for (const item of items) {
    addObject(item.object3D)
    store.addTerrain(item)
  }
  store.setLoading(false)
}

function onRemove(id: string) {
  const target = store.terrains.find((t) => t.id === id)
  if (!target) return
  removeObject(target.object3D)
  store.removeTerrain(id)
  expandedRotation.value.delete(id)
}

function toggleRotation(id: string) {
  const next = new Set(expandedRotation.value)
  if (next.has(id)) next.delete(id)
  else next.add(id)
  expandedRotation.value = next
}

function onRotationInput(id: string, axis: 0 | 1 | 2, value: string) {
  const target = store.terrains.find((t) => t.id === id)
  if (!target) return
  const num = Number(value)
  const safe = Number.isFinite(num) ? num : 0
  const cur = target.rotationDeg
  const next: [number, number, number] = [cur[0], cur[1], cur[2]]
  next[axis] = safe
  store.setTerrainRotation(id, next)
}

function onResetRotation(id: string) {
  store.setTerrainRotation(id, [0, 0, 0])
}

/**
 * 切换某个轴的翻转（沿该轴镜像）。
 * 典型用例：rome_navmesh_3.glb 这种"挖空型"碰撞简化体，正面/法线朝下，
 * 翻转 Y 轴可让"地面"朝上，从而被栅格化为可走区域。
 */
function onToggleFlip(id: string, axis: 0 | 1 | 2) {
  const target = store.terrains.find((t) => t.id === id)
  if (!target) return
  const next: [boolean, boolean, boolean] = [
    target.flip[0],
    target.flip[1],
    target.flip[2]
  ]
  next[axis] = !next[axis]
  store.setTerrainFlip(id, next)
}

function onResetFlip(id: string) {
  store.setTerrainFlip(id, [false, false, false])
}

function formatSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
  return `${(bytes / 1024 / 1024).toFixed(2)} MB`
}

function formatDimensions(item: { size: { x: number; y: number; z: number } }) {
  const { x, y, z } = item.size
  return `${x.toFixed(1)} × ${y.toFixed(1)} × ${z.toFixed(1)}`
}
</script>

<template>
  <div class="glass-card p-3 flex flex-col gap-3 max-h-[55vh]">
    <!-- 上传区 -->
    <div
      class="relative rounded-lg border-2 border-dashed transition-all cursor-pointer"
      :class="
        isDragging
          ? 'border-cyan-glow bg-cyan-glow/10 shadow-cyan-glow'
          : 'border-white/15 hover:border-cyan-glow/60 hover:bg-white/5'
      "
      @click="pickFiles"
      @dragover="onDragOver"
      @dragleave="onDragLeave"
      @drop="onDrop"
    >
      <input
        ref="fileInputRef"
        type="file"
        accept=".glb,.gltf"
        multiple
        class="hidden"
        @change="onInputChange"
      />
      <div class="px-4 py-5 flex flex-col items-center text-center">
        <div
          class="w-10 h-10 rounded-lg bg-white/5 border border-white/10 flex items-center justify-center mb-2"
          :class="{ 'animate-pulse-glow': isDragging }"
        >
          <Loader2 v-if="store.isLoading" class="w-5 h-5 text-cyan-glow animate-spin" />
          <Upload v-else class="w-5 h-5 text-cyan-glow" />
        </div>
        <div class="text-sm font-medium text-slate-100">
          {{ store.isLoading ? progressText : '上传 GLB 地形' }}
        </div>
        <div class="text-[11px] text-slate-400 mt-0.5">
          点击或拖入 .glb / .gltf · 支持多文件
        </div>
      </div>
      <!-- 进度条 -->
      <div
        v-if="store.isLoading"
        class="absolute left-0 bottom-0 h-0.5 bg-cyan-glow transition-all"
        :style="{ width: `${store.loadingProgress * 100}%` }"
      />
    </div>

    <!-- 已上传列表 -->
    <div v-if="!store.isEmpty" class="flex flex-col gap-1.5 overflow-auto scrollbar-thin pr-1">
      <div
        v-for="item in store.terrains"
        :key="item.id"
        class="group flex flex-col gap-1.5 px-2.5 py-2 rounded-md bg-white/[0.03] border border-white/5 hover:border-cyan-glow/30 hover:bg-white/[0.06] transition-colors animate-fade-in"
      >
        <div class="flex items-center gap-2.5">
          <div
            class="w-7 h-7 rounded bg-gradient-to-br from-cyan-500/30 to-indigo-500/30 border border-cyan-glow/30 flex items-center justify-center shrink-0"
          >
            <FileBox class="w-3.5 h-3.5 text-cyan-glow" />
          </div>
          <div class="min-w-0 flex-1">
            <div class="text-xs font-medium text-slate-100 truncate" :title="item.name">
              {{ item.name }}
            </div>
            <div class="text-[10px] text-slate-400 flex items-center gap-2">
              <span>{{ formatSize(item.fileSize) }}</span>
              <span class="text-slate-600">·</span>
              <span class="font-mono">{{ formatDimensions(item) }}</span>
            </div>
          </div>
          <button
            class="btn-ghost shrink-0"
            :class="
              expandedRotation.has(item.id)
                ? 'text-cyan-glow bg-cyan-glow/10'
                : 'opacity-60 group-hover:opacity-100'
            "
            :title="expandedRotation.has(item.id) ? '收起旋转' : '调整旋转'"
            @click.stop="toggleRotation(item.id)"
          >
            <RotateCw class="w-3.5 h-3.5" />
            <ChevronDown
              class="w-3 h-3 transition-transform"
              :class="{ 'rotate-180': expandedRotation.has(item.id) }"
            />
          </button>
          <button
            class="btn-ghost shrink-0 opacity-0 group-hover:opacity-100"
            :title="`移除 ${item.name}`"
            @click.stop="onRemove(item.id)"
          >
            <Trash2 class="w-3.5 h-3.5" />
          </button>
        </div>

        <!-- 旋转 / 翻转 编辑区 -->
        <div
          v-if="expandedRotation.has(item.id)"
          class="rounded-md bg-black/20 border border-white/5 px-2.5 py-2 flex flex-col gap-2 animate-fade-in"
        >
          <div class="flex items-center justify-between">
            <span class="text-[10px] text-slate-400 uppercase tracking-wider">旋转 (度)</span>
            <button
              class="text-[10px] text-slate-400 hover:text-cyan-glow transition-colors"
              :title="'重置为 0,0,0'"
              @click.stop="onResetRotation(item.id)"
            >
              重置
            </button>
          </div>
          <div class="grid grid-cols-3 gap-1.5">
            <label
              v-for="(label, axis) in (['X', 'Y', 'Z'] as const)"
              :key="`rot-${label}`"
              class="flex items-center gap-1 bg-white/[0.04] border border-white/10 rounded px-1.5 py-1 focus-within:border-cyan-glow/60 transition-colors"
            >
              <span class="text-[10px] font-mono text-slate-400 w-3 shrink-0">{{ label }}</span>
              <input
                type="number"
                step="1"
                :value="item.rotationDeg[axis]"
                class="w-full bg-transparent text-xs font-mono text-slate-100 outline-none [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
                @input="onRotationInput(item.id, axis as 0 | 1 | 2, ($event.target as HTMLInputElement).value)"
              />
            </label>
          </div>

          <!-- 翻转 -->
          <div class="flex items-center justify-between mt-0.5">
            <span class="text-[10px] text-slate-400 uppercase tracking-wider flex items-center gap-1">
              <FlipHorizontal2 class="w-3 h-3" />
              翻转 (镜像)
            </span>
            <button
              v-if="item.flip[0] || item.flip[1] || item.flip[2]"
              class="text-[10px] text-slate-400 hover:text-cyan-glow transition-colors"
              title="清除所有翻转"
              @click.stop="onResetFlip(item.id)"
            >
              重置
            </button>
          </div>
          <div class="grid grid-cols-3 gap-1.5">
            <button
              v-for="(label, axis) in (['X', 'Y', 'Z'] as const)"
              :key="`flip-${label}`"
              type="button"
              class="flex items-center justify-center gap-1 rounded px-1.5 py-1 text-xs font-mono border transition-colors"
              :class="
                item.flip[axis]
                  ? 'bg-cyan-glow/15 border-cyan-glow/60 text-cyan-glow shadow-[0_0_0_1px_rgba(34,211,238,0.25)_inset]'
                  : 'bg-white/[0.04] border-white/10 text-slate-300 hover:border-cyan-glow/40 hover:text-slate-100'
              "
              :title="`沿 ${label} 轴镜像（scale.${label.toLowerCase()} = ${item.flip[axis] ? '+1' : '-1'}）`"
              @click.stop="onToggleFlip(item.id, axis as 0 | 1 | 2)"
            >
              <span class="text-[10px] text-slate-400">翻转</span>
              <span>{{ label }}</span>
            </button>
          </div>

          <div class="text-[10px] text-slate-500 leading-tight">
            修改后会重算 AABB；如已生成 anchor 邻接，需重新计算。<br />
            提示：若 GLB 是"挖空型"碰撞体（法线朝下导致小地图全黑），可尝试翻转 Y。
          </div>
        </div>
      </div>
    </div>
  </div>
</template>
