<script setup lang="ts">
/**
 * ChunkInspector — 右栏「单个地块」的数据查看与编辑面板。
 *
 * ## 两种编辑形态
 *
 * - **属性树**（默认）：按「左 key / 右 value」逐字段列出整条块对象，嵌套对象折叠缩进
 * - **JSON**：整条块对象原文，用于维护属性树不便表达的冷门字段
 *
 * ## 为什么主形态是通用属性树，而不是 id / 位置 / 尺寸 的表单
 *
 * 块的字段来自五个下游维度，差异极大：collision 只有 5 个平铺字段、无嵌套；而 light 有
 * 10 个可选子块（`sky` 10 个字段、`shadow → followDirectional → shadow → camera` 嵌套
 * 4 层、`points` / `directional` 是对象数组）。按维度逐个写死表单，做不完也维护不动 ——
 * 每加一个维度都要改一遍 UI。
 *
 * 因此这里改成「按值的形态渲染」的通用树（见 `PropTree`）：任意维度、任意深度、
 * 连编辑器不认识的字段都能显示与编辑。JSON 模式保留，作为补充手段而非主路径。
 *
 * ## 字段保真
 *
 * 树只覆盖被编辑的那一个节点，其余字段（含不认识的自定义字段）原样写回 —— 见
 * `utils/setIn.ts` 的浅拷贝更新。编辑器不是 schema 的真相来源，只做搬运与局部修改。
 *
 * ## 未配置字段（契约里有、块数据里还没有）
 *
 * 块数据里只装"已经配过的"字段，于是面板原先只能显示这些 —— 用户看不出这个维度还能配
 * 什么（collision 的 `opacity` / `cloneAsLightMesh` / `global` 就是这样"消失"的）。
 *
 * 现在按**这份清单的维度**（`store.chunkKind`）取该维度的字段名单（`utils/chunkTemplate`），
 * 数据里缺的列成「未配置」行，用户填了才写入。三条边界：
 *
 * - **维度是整份清单的属性**：第一次生成 / 新增块时选一次，之后沿用；载入清单时按字段特征
 *   反推。反推不出来（`chunkKind` 为 `null`）就没有名单，退化为"只展示数据里有的字段"。
 * - **绝不预填默认值**：`opacity = 0` 会让块全透明、`intensity = 0` 会关灯，凭空补值是
 *   数据污染。未配置字段在填写前不会出现在数据里，导出因此天然干净。
 * - **绝不为未配置对象写空壳**：`shadow` 这类内部含必填子字段，写 `{}` 会被下游拒。
 *   用户填了某个叶子时直接走 `setIn`（它已实现"沿途容器缺失时自动补"），父对象按需创建。
 *
 * ## 与 store 的关系
 *
 * 控件在 `@change`（失焦 / 回车）时才写回，不做逐字符同步 —— 避免每敲一个键就重绘整批块。
 * 任何编辑都会把 `origin` 从 `generated` 提升为 `manual`：手工动过的块不该被
 * 「应用并生成切块」重算冲掉。
 *
 * @changelog
 * | 版本   | 变更说明                                                       | 关联                          |
 * | v1.0.0 | 初始实现：表单 + JSON 双形态编辑、删除块、来源回显              | REQ: map-editor-chunk-editing |
 * | v1.1.0 | JSON 切换与删除移到标题行（原在面板底部，离作用对象太远）        | REQ: map-editor-chunk-editing |
 * | v1.1.1 | 删除的二次确认由父层统一负责（键盘 Delete 与按钮共用同一层）      | REQ: map-editor-chunk-editing |
 * | v2.0.0 | 固定表单换成通用属性树（左 key 右 value、嵌套折叠），支持任意维度 | REQ: map-editor-chunk-editing |
 * | v2.1.0 | 改为两段式：上=顶层字段清单，下=选中字段的值（照 meta 的场景层级+属性面板）| REQ: map-editor-chunk-editing |
 * | v2.1.1 | JSON 模式说明 origin / source 是编辑器内部状态（不属于导出契约）        | REQ: map-editor-chunk-editing |
 * | v2.1.2 | shape.type 改只读展示；空容器给「（空）」提示，避免下层空白像故障      | REQ: map-editor-chunk-editing |
 * | v2.2.0 | 修：url 不再恒显示（只在数据里真的有时出现），与"不做字段增删"一致      | REQ: map-editor-chunk-editing |
 * | v2.3.0 | 修：改 id 会被当成"新增一块"（upsert 按新 id 找不到）；并拦截重名         | REQ: map-editor-chunk-editing |
 * | v2.3.1 | 几何说明不再常驻面板底部，改为只在选中 shape 时显示于其属性下方           | REQ: map-editor-chunk-editing |
 * | v2.4.0 | 按工具栏模板列出契约里尚未配置的字段（灰色「未配置」行，填了才写入）        | REQ: map-editor-chunk-editing |
 * | v2.4.1 | 名单来源从"工具栏模板"改为"这份清单的维度"（chunkKind，首次选择 / 载入反推）    | REQ: map-editor-chunk-editing |
 * | v2.4.2 | 字段清单分两组：id / shape（块级）在上，维度字段在下，中间画分隔线            | REQ: map-editor-chunk-editing |
 * | v2.4.3 | 修：改 position / rotation / scale 无反应（三维量被 Number() 判成非法而整条拒收） | REQ: map-editor-chunk-editing |
 * /@changelog
 *
 * @author v_weiqinlin
 */
import { computed, ref, watch } from 'vue'
import { Boxes, Braces, Trash2 } from 'lucide-vue-next'
import { useNavmeshStore } from '../stores/navmesh'
import { parseChunkModule, roundCm } from '../composables/useChunkIO'
import { setIn, type PropPath } from '../utils/setIn'
import {
  isContainer,
  mergeFieldEntries,
  type FieldSpec,
  type PropEntry
} from '../utils/propValue'
import { fieldsForKind } from '../utils/chunkTemplate'
import PropTree from './PropTree.vue'
import PropKeyList from './PropKeyList.vue'
import type { ChunkItem } from '../types/chunk'

const emit = defineEmits<{
  /** 块数据已变化（父层据此重绘 3D 与同步拖动手柄） */
  (e: 'change'): void
  /** 请求删除某块：删除是破坏性操作，交给父层统一二次确认 + 重绘 */
  (e: 'remove', id: string): void
}>()

const store = useNavmeshStore()

/** 当前选中的块（store 的派生） */
const item = computed(() => store.selectedChunk)

const jsonMode = ref(false)
const jsonText = ref('')
const jsonError = ref<string | null>(null)

watch(
  item,
  () => {
    jsonError.value = null
    if (jsonMode.value && item.value) jsonText.value = toJson(item.value)
  },
  { immediate: true }
)

/** 来源回显文案 */
const originLabel = computed(() => {
  const it = item.value
  if (!it) return ''
  if (it.origin === 'generated')
    return it.source === 'fill' ? '算法生成 · 覆盖补块' : '算法生成 · 骨架布块'
  if (it.origin === 'loaded') return '文件载入'
  return '手工调整'
})

/** 该块是否已经"动过"（重算时会保留） */
const isEdited = computed(() => item.value !== null && item.value.origin !== 'generated')

/**
 * 这份清单**维度**的字段形状表（该维度契约里有哪些字段）。
 *
 * `chunkKind` 为 `null` → 没有名单：维度还没定（一个块都没有），或从载入的清单里认不出来。
 * 此时面板退化为"只展示块数据里已有的字段"—— 那在任何维度下都不会错，比按错误的契约列出
 * 「未配置」字段安全（用户可能真去填，然后被下游 `.strict()` 拒）。
 */
const templateFields = computed<Record<string, FieldSpec> | undefined>(() =>
  store.chunkKind ? fieldsForKind(store.chunkKind) : undefined
)

/**
 * 属性面板的字段行（上半段清单用它，下半段取选中行也从这里查）。
 *
 * 分两组，面板会在两组之间画一条分隔线：
 *
 * 1. **块级字段**：`id` 与 `shape` —— 五个维度都有，恒显示
 * 2. **维度字段**：这份清单维度特有的字段。`url` 排首位（它是该维度最主要的字段：
 *    collision / terrain 必填，而 light / npc 用不到，所以不算块级），其余按数据原顺序，
 *    契约里还没配的追加为「未配置」行（见 `mergeFieldEntries`）
 *
 * 分组不是装饰：两类混排时看不出"哪些字段每块都有、哪些是这个维度才有的"，而这两类
 * 的来源与可编辑后果并不一样。
 */
const treeRoot = computed<PropEntry[]>(() => {
  const it = item.value
  if (!it) return []
  const fields = templateFields.value

  // 第一组：块级字段
  const blockLevel: PropEntry[] = [
    { key: 'id', value: it.id },
    { key: 'shape', value: it.shape }
  ]

  // 第二组：维度字段
  const rest: Record<string, unknown> = {}
  let urlValue: unknown
  let hasUrl = false
  for (const [k, v] of Object.entries(it.asset)) {
    if (k === 'url') {
      urlValue = v
      hasUrl = true
      continue
    }
    rest[k] = v
  }
  const restFields = fields ? { ...fields } : undefined
  // url 单独排首位，从名单里摘掉，免得合并时又追加一行
  if (restFields) delete restFields.url

  const dimension: PropEntry[] = []
  if (hasUrl) dimension.push({ key: 'url', value: urlValue })
  else if (fields?.url) dimension.push({ key: 'url', value: undefined, unset: true })
  dimension.push(...mergeFieldEntries(rest, restFields))
  // 第一行标为组首，面板据此在上方画分隔线
  if (dimension.length > 0) dimension[0].groupStart = true

  return [...blockLevel, ...dimension]
})

/**
 * 上层清单当前选中的字段（下半段显示它的值）。
 *
 * 默认 `id`（块的第一行）。切换块时若原选中键在新块里不存在 —— 五个维度的字段集不同，
 * 从 light 块切到 collision 块就没有 `sky` 了 —— 回落到第一个字段；否则下层会是一片空白，
 * 看着像面板坏了。**回落范围是"已配置 ∪ 未配置"的全部行**，否则选中一个未配置字段后
 * 会被立刻弹走（它不在数据里）。
 */
const selectedKey = ref('id')

watch(
  treeRoot,
  (rows) => {
    if (!rows.some((r) => String(r.key) === selectedKey.value)) {
      selectedKey.value = rows[0] ? String(rows[0].key) : ''
    }
  },
  { immediate: true }
)

/** 当前选中的字段行 */
const selectedEntry = computed(() =>
  treeRoot.value.find((r) => String(r.key) === selectedKey.value)
)

/** 选中字段的值（未配置时为 undefined） */
const selectedValue = computed(() => selectedEntry.value?.value)

/**
 * 选中字段的契约形状。
 *
 * `shape` 是块级数据（不在维度字段表里），恒返回 undefined —— 它按值形态渲染即可。
 */
const selectedSpec = computed<FieldSpec | undefined>(() =>
  selectedKey.value === 'shape' ? undefined : templateFields.value?.[selectedKey.value]
)

/** 下半段的一行：字段行 + 该字段的契约形状（传给 `PropTree` 补出未配置子行） */
interface ChildRow extends PropEntry {
  spec?: FieldSpec
}

/**
 * 下半段要渲染的子项：选中字段是容器时列出它的字段（**从第二层开始**才用左 key 右 value，
 * 不再包一层同名的分组头），否则返回 null 走单行渲染。
 *
 * ⚠️ 三维量必须走单行：`position` 是 `[x,y,z]`（或 `{x,y,z}`），拆成 x / y / z 三行会丢掉
 * "这是一个坐标"的整体语义，也多占两行。`isContainer` 已把三维量排除在外。
 */
const selectedChildren = computed<ChildRow[] | null>(() => {
  const entry = selectedEntry.value
  if (!entry) return null
  const spec = selectedSpec.value

  // 未配置：对象按契约列出子字段（同样未配置）；标量 / 元组 / 数组走单行控件
  if (entry.unset) {
    if (spec?.kind !== 'object') return null
    return mergeFieldEntries(undefined, spec.fields).map((e) => ({
      ...e,
      spec: spec.fields[String(e.key)]
    }))
  }

  if (!isContainer(entry.value)) return null
  if (Array.isArray(entry.value)) return entry.value.map((val, i) => ({ key: i, value: val }))
  // 已存在的对象：数据里的子项 + 契约里还缺的子字段（部分配置的对象也能补出未配置行）
  const fields = spec?.kind === 'object' ? spec.fields : undefined
  return mergeFieldEntries(entry.value as Record<string, unknown>, fields).map((e) => ({
    ...e,
    spec: fields?.[String(e.key)]
  }))
})

/**
 * 契约里是**字面量**（只有一个合法值）的字段 → 只读展示。
 *
 * `shape.type` 只能是 `'box'`（契约是 `z.literal('box')`）。给它一个可编辑输入框没有意义：
 * 改成别的值会被 `normalizeShapeValue` 拒收、输入框回滚，用户白折腾一次。
 *
 * 目前只有这一个；将来出现别的字面量字段往这里加即可（用点分路径标识）。
 */
const READONLY_PATHS = new Set(['shape.type'])

/** 该路径是否为只读字段（传向下层树的 `readonly`） */
function isReadonlyPath(segments: PropPath): boolean {
  return READONLY_PATHS.has(segments.join('.'))
}

/** 编辑过的块：origin 从 `generated` 提升为 `manual`（重算时保留手工成果） */
function markEdited(it: ChunkItem): ChunkItem['origin'] {
  return it.origin === 'generated' ? 'manual' : it.origin
}

/**
 * 几何数值的落库前处理：取整到厘米；宽 / 高 / 深必须为正。
 *
 * 返回 `undefined` 表示这个值不接受（调用方保持原数据不动）。
 *
 * ## ⚠️ 只对**标量**判非法，三维量要按元素处理
 *
 * `shape` 子树里除了标量还有 `transform.position` / `rotation` / `scale` 这类**三维量**
 * （数组或 `{x,y,z}` 对象）。对它们直接 `Number(value)` 会得到 `NaN`，被下面的判据当成
 * 非法值 → **整条更新被拒收**，表现为"改 position / rotation / scale 完全没反应"。
 *
 * 为什么在这里做而不是在 `PropTree` 里：这是**数据语义**（几何必须厘米级、尺寸不能为 0），
 * 树的职责只是"把值原样呈现与回传"。维度字段里的数字（light 的强度等）不该被取整，
 * 两条规则不同，只有知道路径含义的这一层才能区分。
 */
function normalizeShapeValue(rest: PropPath, value: unknown): unknown {
  // 三维量数组：逐个元素取整（`rotation` 是角度、`position` 是坐标，都该是厘米级整洁值）
  if (Array.isArray(value)) {
    return value.map((v) => (typeof v === 'number' ? roundCm(v) : v))
  }
  // `{x,y,z}` 形态的三维量：同样按元素取整
  if (value !== null && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value as Record<string, unknown>).map(([k, v]) => [
        k,
        typeof v === 'number' ? roundCm(v) : v
      ])
    )
  }
  const n = Number(value)
  if (!Number.isFinite(n)) return undefined
  const key = rest.length === 1 ? rest[0] : null
  // 宽 / 高 / 深为 0 或负数时：块的 OBB 半宽为 0，永远选不中、也永远不参与定位 ——
  // 「填错一个数就静默失效」是最难查的故障形态，这里直接拒收（UI 保持原值）
  if ((key === 'width' || key === 'depth' || key === 'height') && n <= 0) return undefined
  return roundCm(n)
}

/**
 * 属性树写回的**唯一入口**，按路径首位分三路。
 */
function onTreeUpdate(path: PropPath, value: unknown) {
  const it = item.value
  if (!it) return
  const [head, ...rest] = path

  // 1) 标识
  if (head === 'id') {
    const newId = String(value ?? '').trim() || it.id
    if (newId === it.id) return
    // id 必须唯一：同 id 会让选中 / 拖动 / 导出都指向不明（查找只认第一个），
    // 属于会损坏数据的输入，直接拒收并说明原因
    if (store.chunkItems.some((c) => c.id === newId)) {
      store.setError(`已存在同名块「${newId}」，id 必须唯一`)
      return
    }
    // ⚠️ 必须把旧 id 一起传下去：store 按 id 查找，用新 id 会找不到、被当成"新增一块"
    store.upsertChunkItem({ ...it, id: newId, origin: markEdited(it) }, it.id)
    store.selectChunk(newId)
    emit('change')
    return
  }

  // 2) 几何：走取整与正数校验
  if (head === 'shape') {
    const normalized = normalizeShapeValue(rest, value)
    if (normalized === undefined) return
    store.upsertChunkItem({
      ...it,
      shape: setIn(it.shape, rest, normalized),
      origin: markEdited(it)
    })
    emit('change')
    return
  }

  // 3) 其余一律归 asset（url / opacity / global / programs / 各维度字段…）
  //
  // ⚠️ 这里必须用**完整 path** 而不是 `rest`：asset 的字段就在路径第一层，`rest` 会把
  //    第一个键吃掉，`setIn` 收到空路径时语义是"整体替换" —— 改 opacity 会把整个 asset
  //    换成那个数值，块的其余字段（url / points / shadow…）全部丢失。
  const asset = setIn(it.asset, path, value) as Record<string, unknown>
  // url 是维度字段（collision / terrain 必需、light 可选）：清空即删除该字段，
  // 而不是留一个空串 —— 空串会被下游当成"有 url 但地址为空"，比缺字段更糟
  if (head === 'url' && typeof value === 'string' && !value.trim()) delete asset.url
  store.upsertChunkItem({ ...it, asset, origin: markEdited(it) })
  emit('change')
}

/** 块对象 → JSON 文本（含编辑器专有字段，便于来回编辑） */
function toJson(it: ChunkItem): string {
  return JSON.stringify(
    { id: it.id, ...it.asset, shape: it.shape, origin: it.origin, source: it.source },
    null,
    2
  )
}

function enterJsonMode() {
  const it = item.value
  if (!it) return
  jsonText.value = toJson(it)
  jsonError.value = null
  jsonMode.value = true
}

/** JSON → store（整条替换；解析失败只在面板内报错，不动数据） */
function applyJson() {
  const it = item.value
  if (!it) return
  let raw: unknown
  try {
    raw = JSON.parse(jsonText.value)
  } catch (e) {
    jsonError.value = `JSON 解析失败：${e instanceof Error ? e.message : String(e)}`
    return
  }

  const warnings: string[] = []
  const parsed = parseChunkModule(raw, 0, warnings)
  if (!parsed) {
    jsonError.value = warnings.join('；') || '数据不合法：缺少合法的 shape'
    return
  }

  // 重名与 id 分支同样的处理：JSON 里改了 id 也要按旧 id 替换，否则会多出一块
  if (parsed.id !== it.id && store.chunkItems.some((c) => c.id === parsed.id)) {
    jsonError.value = `已存在同名块「${parsed.id}」，id 必须唯一`
    return
  }
  store.upsertChunkItem(
    { ...parsed, origin: it.origin === 'generated' ? 'manual' : it.origin },
    it.id
  )
  if (parsed.id !== it.id) store.selectChunk(parsed.id)
  jsonError.value = null
  jsonMode.value = false
  emit('change')
}

function removeSelf() {
  const it = item.value
  if (!it) return
  // 不在面板内直接删：交给父层，删除才能和键盘 Delete 走同一条路（二次确认 + 重绘 + 收手柄）
  emit('remove', it.id)
}
</script>

<template>
  <!-- 外层 PropertyPanel 已经是卡片容器，这里不再叠一层 glass-card -->
  <section class="flex flex-col gap-3 min-w-0">
    <!-- 未选中：空态 -->
    <div
      v-if="!item"
      class="h-full flex flex-col items-center justify-center gap-2 text-center py-6"
    >
      <div
        class="w-10 h-10 rounded-lg bg-white/5 border border-white/10 flex items-center justify-center"
      >
        <Boxes class="w-5 h-5 text-slate-500" :stroke-width="1.6" />
      </div>
      <div class="text-[14px] text-slate-400">未选中地块</div>
      <div class="text-[12px] text-slate-500 leading-snug max-w-[180px]">
        在场景里点一个块即可选中，随后可改数值、拖动调整或编辑 JSON。
      </div>
    </div>

    <template v-else>
      <!--
        标题行 = 块标识 + 来源 + 视图切换 / 删除。
        按钮放这里而不是面板底部：底部离"这一块"太远，尤其 JSON 模式下面板很长，
        要滚到底才能切回；且删除的作用对象正是标题所指的块，贴着标题更符合直觉。
      -->
      <header class="flex items-center gap-2 shrink-0">
        <Boxes class="w-3.5 h-3.5 shrink-0 text-violet-300" />
        <span class="min-w-0 truncate text-violet-300 text-[14px] font-semibold">{{
          item.id
        }}</span>
        <span
          class="shrink-0 text-[12px] px-1.5 py-0.5 rounded border"
          :class="
            isEdited
              ? 'bg-amber-400/15 text-amber-300 border-amber-400/30'
              : 'bg-white/5 text-slate-400 border-white/10'
          "
          :title="
            isEdited
              ? '手工调整过的块，重新生成切块时会保留'
              : '算法生成的块，重新生成时会被刷新'
          "
        >
          {{ originLabel }}
        </span>

        <div class="ml-auto flex items-center gap-1 shrink-0">
          <button
            v-if="!jsonMode"
            type="button"
            class="px-1.5 py-1 rounded border border-white/10 bg-white/5 text-[12px] font-medium text-slate-300 hover:bg-white/10 flex items-center gap-1 cursor-pointer transition-all"
            title="编辑整条块对象的 JSON"
            @click="enterJsonMode"
          >
            <Braces class="w-3 h-3" />
            JSON
          </button>
          <button
            v-else
            type="button"
            class="px-1.5 py-1 rounded border border-violet-400/40 bg-violet-500/15 text-[12px] font-medium text-violet-200 hover:bg-violet-500/25 cursor-pointer transition-all"
            title="返回属性树"
            @click="jsonMode = false"
          >
            返回属性
          </button>
          <button
            type="button"
            class="px-1.5 py-1 rounded border border-transparent text-[12px] font-medium text-slate-400 hover:text-red-300 hover:bg-red-500/10 flex items-center gap-1 cursor-pointer transition-all"
            title="删除这个块"
            @click="removeSelf"
          >
            <Trash2 class="w-3 h-3" />
            删除
          </button>
        </div>
      </header>

      <!--
        属性面板：上 = 字段清单，下 = 选中字段的值。
        这是照 meta 编辑器「场景层级 + 属性面板」的两段式 —— 上层先给该块的全部顶层字段
        一眼看全（带值摘要），点哪一个、下面就编辑哪一个。
      -->
      <template v-if="!jsonMode">
        <!-- 上半段：顶层字段清单 -->
        <div class="rounded-md border border-white/5 bg-white/[0.02] px-1 py-1.5">
          <PropKeyList
            :entries="treeRoot"
            :selected="selectedKey"
            @select="selectedKey = $event"
          />
        </div>

        <!--
          下半段：选中字段的值。
          容器直接列出子项（第二层起才用左 key 右 value，不再包一层同名的分组头）；
          标量 / 三维量走单行。
          key 里带上 item.id 与 selectedKey：切换块或切换字段时重建，折叠状态随之复位 ——
          否则上一个字段展开的分支会带着新字段的内容一起展开，看着像状态错乱。
        -->
        <div class="rounded-md border border-white/5 bg-white/[0.02] px-2 py-1.5">
          <template v-if="selectedChildren">
            <PropTree
              v-for="child in selectedChildren"
              :key="`${item.id}:${selectedKey}:${child.key}`"
              :label="String(child.key)"
              :value="child.value"
              :spec="child.spec"
              :unset="child.unset"
              :path="[selectedKey, child.key]"
              :depth="0"
              :readonly="isReadonlyPath([selectedKey, child.key])"
              @update="onTreeUpdate"
            />
            <!-- 空容器：不给提示的话下层是一片空白，会让人以为面板坏了 -->
            <p
              v-if="selectedChildren.length === 0"
              class="py-1 font-mono text-[13px] text-slate-600"
            >
              （空）
            </p>
          </template>
          <PropTree
            v-else
            :key="`${item.id}:${selectedKey}`"
            :label="selectedKey"
            :value="selectedValue"
            :spec="selectedSpec"
            :unset="selectedEntry?.unset"
            :path="[selectedKey]"
            :depth="0"
            :readonly="isReadonlyPath([selectedKey])"
            @update="onTreeUpdate"
          />

          <!--
            几何说明只在看 shape 时出现：它讲的是 width / depth 的关系，挂在别的字段下面
            属于纯干扰 —— 看 id / opacity 时也会读到，还容易以为跟当前字段有关。
          -->
          <p
            v-if="selectedKey === 'shape'"
            class="mt-1.5 pt-1.5 border-t border-white/5 text-[12px] text-slate-500 leading-snug"
          >
            块在 XZ 上是正方形：width 同时决定宽与深。改动失焦即生效，并随导出写回清单。
          </p>
        </div>
      </template>

      <!-- JSON 模式 -->
      <template v-else>
        <div class="text-[12px] text-slate-500 leading-snug">
          整条块对象：属性树不便表达的冷门字段在这里维护（字段名须符合下游契约，多余字段会被下游拒绝）。
        </div>
        <!--
          origin / source 是编辑器内部加的（块文件里本来没有），必须说明：
          它们在编辑框里可见是为了让 JSON 往返不丢内部状态，但**不属于导出契约** ——
          不解释的话，用户会以为是自己文件里带的，甚至去手改 origin（改了会让块被重算冲掉）。
        -->
        <div class="text-[12px] text-slate-500 leading-snug">
          <span class="font-mono text-slate-400">origin</span> /
          <span class="font-mono text-slate-400">source</span> 是编辑器内部状态，<span
            class="text-slate-400"
            >不会写进导出清单</span
          >：origin 决定重算时是否保留（manual / loaded 保留，generated 会被刷新），source
          只影响生成块的分色。从文件载入的块固定为 origin=loaded、source=null。
        </div>
        <textarea
          v-model="jsonText"
          spellcheck="false"
          rows="14"
          class="w-full bg-black/40 border border-white/10 rounded p-2 text-[13px] text-slate-100 font-mono leading-snug outline-none focus:border-violet-400/50 resize-y"
        />
        <p v-if="jsonError" class="text-[12px] text-red-300 leading-snug">{{ jsonError }}</p>
        <button
          type="button"
          class="w-full px-2 py-1.5 rounded-md bg-violet-500/15 border border-violet-400/40 text-[13px] font-medium text-violet-200 hover:bg-violet-500/25 cursor-pointer transition-all"
          @click="applyJson"
        >
          应用 JSON
        </button>
      </template>
    </template>
  </section>
</template>
