/**
 * download — 触发浏览器下载（唯一实现）。
 *
 * 为什么独立成模块：`.bin`（navmesh 导航数据）、`.json`（可达区 manifest）、
 * `.navmap.zip`（主流程存档）都要下载，各自写一遍 a[download] 就是三份重复；
 * 集中一处顺带统一 ObjectURL 的释放时机。
 *
 * @changelog
 * | 版本   | 变更说明                                          | 关联                     |
 * | v1.0.0 | 从 useNavmeshDataExport 抽出，供各类导出共用       | REQ: map-editor-ui-shell |
 * /@changelog
 *
 * @author linfan
 */

/** 触发下载；`filename` 需自带扩展名 */
export function triggerDownload(blob: Blob, filename: string): void {
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = filename
  document.body.appendChild(a)
  a.click()
  document.body.removeChild(a)
  // 立即 revoke 会让部分浏览器取消下载，延后释放
  setTimeout(() => URL.revokeObjectURL(url), 1000)
}
