/**
 * setIn — 按路径对 JSON 值做不可变更新（属性树写回用）。
 *
 * ## 为什么需要它
 *
 * 属性树是递归渲染的，控件只知道"我这一层改了哪个下标 / 哪个键"，从叶子到根要一层层
 * 拼回完整对象。手写多层展开（`{ ...a, b: { ...a.b, c: ... } }`）在嵌套 4 层时既难读
 * 也容易漏拷贝。
 *
 * ## 为什么是浅拷贝而不是深拷贝
 *
 * 块的 `asset` 里可能有 `programs` 这种大表（几十条 program 描述符）。若每次改一个数值
 * 都深拷贝整份数据，连续调数值（拖动 / 反复试数）时开销白白翻倍。浅拷贝只复制**路径上的
 * 那一串容器**，其余子树按引用共享 —— 没有被动到的分支不会被复制。
 *
 * ## 路径约定
 *
 * 元素为 `number` 时按数组下标处理，其余按对象键。路径为空即"整个替换"。
 *
 * @changelog
 * | 版本   | 变更说明                                            | 关联                          |
 * | v1.0.0 | 初始实现：浅拷贝沿途的不可变路径写入                 | REQ: map-editor-chunk-editing |
 * /@changelog
 *
 * @author v_weiqinlin
 */

/** 路径元素：对象键或数组下标 */
export type PropPath = Array<string | number>

/**
 * 沿路径写入 `value`，返回**新**根对象。
 *
 * 沿途容器不存在时会自动补一个（对象或数组，按下一位是否是数字判断）——
 * 属性树允许在"路径指向的容器还没建好"的情况下写入，容器形态由路径自行推断。
 */
export function setIn<T>(root: T, path: PropPath, value: unknown): T {
  if (path.length === 0) return value as T
  const [head, ...rest] = path

  if (Array.isArray(root)) {
    const next = root.slice()
    next[head as number] = setIn(root[head as number], rest, value)
    return next as unknown as T
  }

  // 沿途容器缺失时按"下一位是不是数字"推断补数组还是对象
  const src = (root ?? (typeof head === 'number' ? [] : {})) as Record<string, unknown>
  return { ...src, [head]: setIn(src[head as string], rest, value) } as unknown as T
}
