/**
 * useNavmeshBoundary — navmesh 的「外轮廓边界边」提取工具。
 *
 * ## 为什么独立成模块
 *
 * `collectBoundaryEdges` 原本挂在 `useNavmeshCenterline`（Voronoi 中轴）里，但它
 * **与中轴算法无关**：只被一个 poly 使用的边即外轮廓 —— **切块**用它做局部半宽查询，
 * 用来决定块的边长。中轴功能删除后它仍被消费，故抽出成独立模块，不依赖任何中轴代码。
 *
 * @changelog
 * | 版本   | 变更说明                                                       | 关联                    |
 * | v1.0.0 | 从 useNavmeshCenterline 抽出：边界边提取 + 脊线可达裁剪           | REQ: navmesh-chunking   |
 * | v2.0.0 | 下线 clipCenterlinesByReachability（「仅可达」显示开关已移除）    | REQ: map-editor-ui-shell |
 * /@changelog
 *
 * @author v_weiqinlin
 */
import type { PolyRecord } from '../stores/navmesh'

/** 顶点量化精度（米）：用于边 key / 点去重，消除浮点误差 */
const VERTEX_EPS = 1e-3

export interface BoundaryEdge {
  ax: number
  ay: number
  az: number
  bx: number
  by: number
  bz: number
}

/**
 * 提取区域外轮廓边：只被**一个** poly 使用的边即外轮廓。
 *
 * 用「顶点量化后的无向 key」计数，天然消除遍历方向差异，也不需要 Detour 邻接表
 * （纯顶点坐标即可判定共享）。
 */
export function collectBoundaryEdges(polys: PolyRecord[]): BoundaryEdge[] {
  const counts = new Map<string, number>()
  const firstSeen = new Map<string, BoundaryEdge>()

  for (const poly of polys) {
    const v = poly.vertices
    const n = v.length / 3
    for (let i = 0; i < n; i++) {
      const j = (i + 1) % n
      const key = edgeKey2D(v[i * 3], v[i * 3 + 2], v[j * 3], v[j * 3 + 2])
      counts.set(key, (counts.get(key) ?? 0) + 1)
      if (!firstSeen.has(key)) {
        firstSeen.set(key, {
          ax: v[i * 3],
          ay: v[i * 3 + 1],
          az: v[i * 3 + 2],
          bx: v[j * 3],
          by: v[j * 3 + 1],
          bz: v[j * 3 + 2]
        })
      }
    }
  }

  const out: BoundaryEdge[] = []
  for (const [key, count] of counts) {
    if (count === 1) {
      const edge = firstSeen.get(key)
      if (edge) out.push(edge)
    }
  }
  return out
}

/** 2D 无向边 key（顶点量化 + 端点排序，消除方向差异） */
function edgeKey2D(x1: number, z1: number, x2: number, z2: number): string {
  const a = `${Math.round(x1 / VERTEX_EPS)},${Math.round(z1 / VERTEX_EPS)}`
  const b = `${Math.round(x2 / VERTEX_EPS)},${Math.round(z2 / VERTEX_EPS)}`
  return a < b ? `${a}|${b}` : `${b}|${a}`
}
