/**
 * useNavmeshBaker — 把当前 useTerrainStore 中的 GLB 几何喂给 Recast，烘焙出 NavMesh。
 *
 * 关键设计：
 * - `ensureRecastInited()`：模块级 promise 单例。recast-navigation 的 `init()` 必须 await
 *   一次后 Raw API 才能用，这里做 lazy 单例避免重复加载 wasm。
 * - 几何收集：遍历 terrainStore.terrains[].object3D，递归收集所有 Mesh，把每个三角形按
 *   `mesh.matrixWorld` 转换到世界坐标，输出 flat Float32Array(positions) + Uint32Array(indices)。
 * - bakeToken：调用方在调用前 store.bumpBakeToken() 拿到 token，烘焙完成后比对，若不一致
 *   则丢弃结果（避免参数狂调时旧任务"晚到"覆盖新结果）。
 * - poly 提取：烘焙完后遍历 NavMesh 的 tile.polys()，按 poly.vertCount() 拿顶点序号，对照
 *   tile.verts() 转出每个 polygon 的世界坐标顶点 + centroid，存为 PolyRecord[]。
 * - dispose：调用方负责 NavMesh.destroy() / NavMeshQuery.destroy()；这里 wasm 是常驻进程。
 */
import {
  Mesh,
  Vector3,
  type BufferGeometry,
  type Object3D,
  type NormalBufferAttributes
} from 'three'
import {
  NavMeshQuery,
  init as recastInit,
  type NavMesh
} from 'recast-navigation'
import { generateSoloNavMesh } from 'recast-navigation/generators'
import type { TerrainItem } from '../types'
import type { NavmeshBakeParams, PolyRecord } from '../stores/navmesh'

/** Recast wasm 模块级初始化单例 */
let _initPromise: Promise<void> | null = null
export function ensureRecastInited(): Promise<void> {
  if (!_initPromise) {
    const t0 = performance.now()
    _initPromise = recastInit().then(() => {
      console.info(
        `[navmesh] recast wasm initialized in ${(performance.now() - t0).toFixed(0)}ms`
      )
    })
  }
  return _initPromise
}

export interface BakeInput {
  terrains: TerrainItem[]
  params: NavmeshBakeParams
}

export interface BakeOutput {
  navMesh: NavMesh
  navQuery: NavMeshQuery
  polygons: PolyRecord[]
  /** 烘焙耗时（不含 wasm init） */
  bakeMs: number
  /** 输入几何统计 */
  triangleCount: number
  vertexCount: number
}

/**
 * 收集所有 terrain 的世界坐标三角形几何。
 * 返回 positions (Float32Array, x/y/z flat) + indices (Uint32Array)。
 * 多个 mesh 合并到同一组数组，indices 累加偏移。
 */
function collectWorldGeometry(terrains: TerrainItem[]): {
  positions: Float32Array
  indices: Uint32Array
  triCount: number
  vertCount: number
} {
  type AnyGeometry = BufferGeometry<NormalBufferAttributes>
  // 先扫一遍统计总量，避免反复 push
  let totalVerts = 0
  let totalTris = 0
  const meshes: Mesh[] = []

  for (const t of terrains) {
    t.object3D.updateMatrixWorld(true)
    t.object3D.traverse((obj: Object3D) => {
      const m = obj as Mesh
      if (!m.isMesh || !m.geometry) return
      const g = m.geometry as AnyGeometry
      const posAttr = g.getAttribute('position')
      if (!posAttr) return
      const vCount = posAttr.count
      const iAttr = g.getIndex()
      const triCount = iAttr ? iAttr.count / 3 : vCount / 3
      totalVerts += vCount
      totalTris += triCount
      meshes.push(m)
    })
  }

  const positions = new Float32Array(totalVerts * 3)
  const indices = new Uint32Array(totalTris * 3)

  let vOffset = 0
  let iWrite = 0
  const tmpVec = new Vector3()

  for (const m of meshes) {
    const g = m.geometry as AnyGeometry
    const posAttr = g.getAttribute('position')
    const iAttr = g.getIndex()
    const vCount = posAttr.count

    // 把顶点搬到世界坐标
    for (let i = 0; i < vCount; i++) {
      tmpVec.set(posAttr.getX(i), posAttr.getY(i), posAttr.getZ(i))
      tmpVec.applyMatrix4(m.matrixWorld)
      const base = (vOffset + i) * 3
      positions[base] = tmpVec.x
      positions[base + 1] = tmpVec.y
      positions[base + 2] = tmpVec.z
    }

    // 索引整体偏移
    if (iAttr) {
      const triCount = iAttr.count / 3
      for (let t = 0; t < triCount; t++) {
        indices[iWrite++] = iAttr.getX(t * 3) + vOffset
        indices[iWrite++] = iAttr.getX(t * 3 + 1) + vOffset
        indices[iWrite++] = iAttr.getX(t * 3 + 2) + vOffset
      }
    } else {
      // 无索引：每 3 个顶点构成一个三角形
      const triCount = vCount / 3
      for (let t = 0; t < triCount; t++) {
        indices[iWrite++] = vOffset + t * 3
        indices[iWrite++] = vOffset + t * 3 + 1
        indices[iWrite++] = vOffset + t * 3 + 2
      }
    }

    vOffset += vCount
  }

  return { positions, indices, triCount: totalTris, vertCount: totalVerts }
}

/**
 * 从烘焙好的 NavMesh 中提取每个 polygon 的轻量化记录。
 *
 * Solo navmesh 只有 1 个 tile，但我们仍按通用 maxTiles 遍历保险。
 * 每个 poly 的顶点序号通过 poly.verts(i) 拿到（i ∈ [0, vertCount)），
 * 实际世界坐标 = tile.verts(idx * 3 + {0,1,2})。
 *
 * 跳过：
 * - getType() === 1（off-mesh connection，本工程不用）
 * - flags === 0（默认 prune 后被 disable 的 poly；首次烘焙时所有可用 poly 默认 flag=1）
 */
function extractPolygons(navMesh: NavMesh): PolyRecord[] {
  const polys: PolyRecord[] = []
  const maxTiles = navMesh.getMaxTiles()

  for (let tileIdx = 0; tileIdx < maxTiles; tileIdx++) {
    const tile = navMesh.getTile(tileIdx)
    const header = tile.header()
    if (!header) continue
    const polyCount = header.polyCount()
    const base = navMesh.getPolyRefBase(tile)

    for (let pi = 0; pi < polyCount; pi++) {
      const poly = tile.polys(pi)
      if (poly.getType() === 1) continue
      if (poly.flags() === 0) continue
      const vCount = poly.vertCount()
      if (vCount < 3) continue

      const verts = new Float32Array(vCount * 3)
      let cx = 0
      let cy = 0
      let cz = 0
      let bminX = Infinity
      let bminY = Infinity
      let bminZ = Infinity
      let bmaxX = -Infinity
      let bmaxY = -Infinity
      let bmaxZ = -Infinity

      for (let vi = 0; vi < vCount; vi++) {
        const vIdx = poly.verts(vi)
        const x = tile.verts(vIdx * 3)
        const y = tile.verts(vIdx * 3 + 1)
        const z = tile.verts(vIdx * 3 + 2)
        verts[vi * 3] = x
        verts[vi * 3 + 1] = y
        verts[vi * 3 + 2] = z
        cx += x
        cy += y
        cz += z
        if (x < bminX) bminX = x
        if (y < bminY) bminY = y
        if (z < bminZ) bminZ = z
        if (x > bmaxX) bmaxX = x
        if (y > bmaxY) bmaxY = y
        if (z > bmaxZ) bmaxZ = z
      }

      const inv = 1 / vCount
      polys.push({
        ref: base | pi,
        centroid: { x: cx * inv, y: cy * inv, z: cz * inv },
        bmin: { x: bminX, y: bminY, z: bminZ },
        bmax: { x: bmaxX, y: bmaxY, z: bmaxZ },
        vertices: verts
      })
    }
  }

  return polys
}

/**
 * 主烘焙入口。同步阻塞执行（wasm init 已 await）。
 * 调用方应：
 *   1) await ensureRecastInited()
 *   2) const token = store.bumpBakeToken()
 *   3) const out = bakeNavmesh(input)
 *   4) if (!store.isTokenAlive(token)) { dispose(out); return }
 *   5) store.setBakeResult(...)
 */
export function bakeNavmesh(input: BakeInput): BakeOutput {
  const { terrains, params } = input
  if (terrains.length === 0) {
    throw new Error('没有可烘焙的几何：请先在 Anchor 视图上传 GLB')
  }

  const t0 = performance.now()
  const geo = collectWorldGeometry(terrains)
  if (geo.triCount === 0) {
    throw new Error('几何收集结果为空（未发现 Mesh 三角形）')
  }
  const tCollect = performance.now() - t0
  console.info(
    `[navmesh] collect geometry: ${geo.vertCount} verts, ${geo.triCount} tris in ${tCollect.toFixed(0)}ms`
  )

  const t1 = performance.now()
  const result = generateSoloNavMesh(geo.positions, geo.indices, {
    cs: params.cs,
    ch: params.ch,
    walkableSlopeAngle: params.walkableSlopeAngle,
    walkableHeight: params.walkableHeight,
    walkableRadius: params.walkableRadius,
    walkableClimb: params.walkableClimb,
    minRegionArea: params.minRegionArea,
    mergeRegionArea: params.mergeRegionArea
  })
  if (!result.success || !result.navMesh) {
    throw new Error(
      `Recast 烘焙失败：${'error' in result && result.error ? result.error : '未知错误'}`
    )
  }
  const navMesh = result.navMesh

  const navQuery = new NavMeshQuery(navMesh)
  const polys = extractPolygons(navMesh)
  const bakeMs = performance.now() - t1

  console.info(
    `[navmesh] bake done: ${polys.length} polys in ${bakeMs.toFixed(0)}ms (cs=${params.cs}, slope=${params.walkableSlopeAngle}°)`
  )

  return {
    navMesh,
    navQuery,
    polygons: polys,
    bakeMs,
    triangleCount: geo.triCount,
    vertexCount: geo.vertCount
  }
}

/** dispose 烘焙产物（被废弃的 stale 结果用） */
export function disposeBake(out: BakeOutput): void {
  out.navQuery.destroy()
  out.navMesh.destroy()
}
