import { Box3, Vector3 } from 'three'
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js'
import type { TerrainItem } from '../types'

const loader = new GLTFLoader()

/**
 * 加载单个 GLB 文件并返回 TerrainItem
 *
 * 额外保留一份原始字节（`rawBytes`）供「存档」写出 GLB 原文件 —— 走 ObjectURL 加载后
 * 原始 File 就取不到了，只能在读取阶段留一份。
 */
export async function loadGLBFile(file: File): Promise<TerrainItem | null> {
  if (!file.name.toLowerCase().endsWith('.glb') && !file.name.toLowerCase().endsWith('.gltf')) {
    console.error(`[GLBLoader] 文件类型不支持: ${file.name}`)
    return null
  }

  // 读字节失败不阻断加载：只是这次的地形无法进存档，模型本身照常可用
  let rawBytes: Uint8Array | undefined
  try {
    rawBytes = new Uint8Array(await file.arrayBuffer())
  } catch (err) {
    console.error(`[GLBLoader] 读取原始字节失败（该地形将无法进存档）: ${file.name}`, err)
  }

  const url = URL.createObjectURL(file)
  try {
    const gltf = await loader.loadAsync(url)
    const root = gltf.scene
    root.name = file.name

    // 更新世界矩阵后再计算 AABB
    root.updateMatrixWorld(true)
    const box = new Box3().setFromObject(root)
    const size = new Vector3()
    if (!box.isEmpty()) box.getSize(size)

    const item: TerrainItem = {
      id: createId(),
      name: file.name,
      fileSize: file.size,
      object3D: root,
      box,
      size,
      rotationDeg: [0, 0, 0],
      flip: [false, false, false],
      loadedAt: Date.now(),
      rawBytes
    }
    return item
  } catch (err) {
    console.error(`[GLBLoader] 加载失败: ${file.name}`, err)
    return null
  } finally {
    URL.revokeObjectURL(url)
  }
}

/**
 * 从原始字节重建地形（存档载入用）。
 *
 * 为什么不复用 `loadGLBFile`：那边收的是 `File`（来自用户选择），而存档里的 GLB 是从
 * zip 解出来的字节，且 `GLTFLoader.parseAsync` 直接吃 ArrayBuffer，无需 ObjectURL。
 * 返回结构与 `loadGLBFile` 一致；`rotationDeg` / `flip` 为初值，由载入流程回填存档里
 * 记录的值（旋转与镜像属于用户调整，必须还原）。
 *
 * 与 `loadGLBFile` 相同的限制：`.gltf` 若引用**外部**资源（bin / 贴图）会解析失败 ——
 * 两种加载方式都拿不到那些相对路径资源，行为一致。
 */
export async function loadGLBFromBytes(
  bytes: Uint8Array,
  name: string
): Promise<TerrainItem | null> {
  try {
    // parseAsync 要求独立 ArrayBuffer；bytes 可能是带 offset 的视图，故显式切片
    const buffer = bytes.buffer.slice(
      bytes.byteOffset,
      bytes.byteOffset + bytes.byteLength
    ) as ArrayBuffer
    const gltf = await loader.parseAsync(buffer, '')
    const root = gltf.scene
    root.name = name

    root.updateMatrixWorld(true)
    const box = new Box3().setFromObject(root)
    const size = new Vector3()
    if (!box.isEmpty()) box.getSize(size)

    return {
      id: createId(),
      name,
      fileSize: bytes.byteLength,
      object3D: root,
      box,
      size,
      rotationDeg: [0, 0, 0],
      flip: [false, false, false],
      loadedAt: Date.now(),
      rawBytes: bytes
    }
  } catch (err) {
    console.error(`[GLBLoader] 从存档字节重建地形失败: ${name}`, err)
    return null
  }
}

/**
 * 批量加载 GLB
 */
export async function loadGLBFiles(
  files: FileList | File[],
  onProgress?: (loaded: number, total: number) => void
): Promise<TerrainItem[]> {
  const list = Array.from(files)
  const result: TerrainItem[] = []
  for (let i = 0; i < list.length; i++) {
    const item = await loadGLBFile(list[i])
    if (item) result.push(item)
    onProgress?.(i + 1, list.length)
  }
  return result
}

function createId(): string {
  if (typeof crypto !== 'undefined' && 'randomUUID' in crypto) {
    return crypto.randomUUID()
  }
  return `t_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`
}
