<script setup lang="ts">
/**
 * TitleBar — 场景导航编辑器 · 标题栏。
 *
 * ## 组成
 *
 * - 左：品牌（图标 + 「场景导航编辑器」+ 副标题）
 * - 中：`#actions` 插槽 —— **整体工作区层面**的动作（存档保存 / 载入、清除编辑成果）
 * - 右：状态指示器（地形 / modules / polys / reach / 烘焙耗时）
 *
 * ## 为什么中部承载"工作区"动作
 *
 * 保存 / 载入 / 清除既不是主流程的某一步，也不属于任何子流程 —— 它们作用于**整个工作区**。
 * 放左栏会打断"① 加载 → ② 生成 navmesh → ③ 生成中线"这条自上而下的流程阅读；
 * 放子流程工具栏则会让"切流程就换一组按钮"的语义被污染。放标题栏中部：
 * 与左栏的流程步骤、工具栏的子流程产物各自分层，用户不必判断"这个按钮属于哪一层"。
 *
 * ## 为什么状态指示器放这里而不是 `App.vue`
 *
 * 原先在 `App.vue` 的 header 内。标题栏拆成组件后，指示器随之一并迁入 —— 它读的是
 * store（与 `NavmeshParamsPanel` 等面板直接读 store 的项目约定一致），不需要外部传参。
 *
 * @changelog
 * | 版本   | 变更说明                                                                 | 关联                  |
 * | v1.0.0 | 从 App.vue 抽出 header 并改名「场景导航编辑器」；新增文件操作占位与 #actions 槽 | REQ: map-editor-ui-shell |
 * | v2.0.0 | 存档入口移交主流程区：移除文件操作占位组，本栏只留品牌 / 全局动作 / 状态 | REQ: map-editor-ui-shell |
 * | v2.1.0 | 顶栏不再承载动作：移除 #actions 插槽，「清除」移交左栏 ⓪ 工作区            | REQ: map-editor-ui-shell |
 * | v2.2.0 | 重新引入 #actions 插槽：承载"整体工作区"动作（存档 / 清除），与左栏流程步骤分层 | REQ: map-editor-ui-shell |
 * /@changelog
 *
 * @author linfan
 */
import { Boxes, Compass } from 'lucide-vue-next'
import { useTerrainStore } from '../stores/terrain'
import { useModulesStore } from '../stores/modules'
import { useNavmeshStore } from '../stores/navmesh'

const terrainStore = useTerrainStore()
const modulesStore = useModulesStore()
const navmeshStore = useNavmeshStore()
</script>

<template>
  <header
    class="shrink-0 h-12 flex items-center gap-4 px-5 border-b border-white/5 backdrop-blur-glass bg-black/20 z-10"
  >
    <!-- 品牌 -->
    <div class="flex items-center gap-2.5 shrink-0">
      <div
        class="w-7 h-7 rounded-md bg-gradient-to-br from-emerald-400 to-cyan-500 flex items-center justify-center shadow-cyan-glow"
      >
        <Boxes class="w-4 h-4 text-slate-900" :stroke-width="2.4" />
      </div>
      <div>
        <div
          class="text-sm font-semibold leading-tight tracking-wide flex items-center gap-1.5"
        >
          <Compass class="w-3.5 h-3.5 text-cyan-glow" />
          场景导航编辑器
        </div>
        <div class="text-[10px] text-slate-400 leading-tight">
          导入 GLB → 烘焙 navmesh → 生成脊线 → 导出导航 / 可达区 / chunk
        </div>
      </div>
    </div>

    <!--
      「整体工作区」层面的动作（存档保存 / 载入、清除编辑成果）由编排层注入。
      它们既不是主流程的某一步、也不属于任何子流程，放这里与左栏的流程步骤区分开：
      左栏自上而下就是"导入 → 烘焙 → 中线"的顺序，中间插一组存档按钮会打断阅读。
    -->
    <div class="flex-1 min-w-0 flex items-center gap-1">
      <slot name="actions" />
    </div>

    <!-- 状态指示器 -->
    <div class="hidden lg:flex items-center gap-3 text-[11px] text-slate-400 shrink-0">
      <span v-if="terrainStore.count > 0" class="flex items-center gap-1.5">
        <span class="w-1.5 h-1.5 rounded-full bg-slate-400" />
        {{ terrainStore.count }} 地形
      </span>
      <span v-if="modulesStore.hasManifest" class="flex items-center gap-1.5">
        <span class="w-1.5 h-1.5 rounded-full bg-emerald-400" />
        {{ modulesStore.loadedModuleCount }} / {{ modulesStore.moduleCount }} modules
      </span>
      <span v-if="navmeshStore.polyCount > 0" class="flex items-center gap-1.5 text-cyan-glow">
        <span class="w-1.5 h-1.5 rounded-full bg-cyan-glow" />
        {{ navmeshStore.polyCount }} polys
      </span>
      <span
        v-if="navmeshStore.reachableModuleIds.size > 0"
        class="flex items-center gap-1.5 text-emerald-300"
      >
        <span class="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse" />
        {{ navmeshStore.reachableModuleIds.size }} reach
      </span>
      <span v-if="navmeshStore.lastBakeMs > 0" class="font-mono text-slate-500">
        {{ navmeshStore.lastBakeMs.toFixed(0) }}ms
      </span>
    </div>
  </header>
</template>
