import type { BoxShape, ModuleSpec, ModulesManifest } from '../types/modules'

export interface ManifestParseResult {
  ok: boolean
  manifest?: ModulesManifest
  error?: string
}

/**
 * 解析 + 校验 modules JSON 文本。
 * 仅做轻量手写校验，避免引入 zod/yup 等依赖。
 *
 * v2.0.0：几何归一 —— 同时接受新写法（`shape` + `splatTransform`）与老写法
 * （`transform` + `bounds`），统一归一成 `shape` + `splatTransform` 交给下游。
 * 老 `bounds` 的轴向歧义（y=深度、z=高度）在 `normalizeGeometry` 内一次处理掉，
 * 下游不再关心两种写法（详见该函数注释）。
 */
export function parseManifestText(text: string): ManifestParseResult {
  if (!text || !text.trim()) {
    return { ok: false, error: 'JSON 为空' }
  }
  let raw: unknown
  try {
    raw = JSON.parse(text)
  } catch (err) {
    console.error('[ManifestLoader] JSON 解析失败', err)
    return { ok: false, error: `JSON 格式非法：${(err as Error).message}` }
  }
  if (typeof raw !== 'object' || raw === null) {
    return { ok: false, error: '根节点必须是对象' }
  }
  const r = raw as Record<string, unknown>
  // baseUrl 在「忽略 collision_name」模式下不强制；缺省给空串，仅作展示
  const baseUrlRaw = typeof r.baseUrl === 'string' ? r.baseUrl : ''
  if (!Array.isArray(r.modules) || r.modules.length === 0) {
    return { ok: false, error: 'modules 必须是非空数组' }
  }

  const modules: ModuleSpec[] = []
  for (let i = 0; i < r.modules.length; i++) {
    const item = r.modules[i] as Record<string, unknown>
    const idx = `modules[${i}]`
    if (!item || typeof item !== 'object') {
      return { ok: false, error: `${idx} 必须是对象` }
    }
    if (typeof item.name !== 'string') {
      return { ok: false, error: `${idx}.name 缺失或非字符串` }
    }
    const collisions = item.collision_name
    if (collisions !== undefined && (!Array.isArray(collisions) || collisions.some((s) => typeof s !== 'string'))) {
      return { ok: false, error: `${idx}.collision_name 必须是字符串数组（或省略）` }
    }
    const plys = item.ply_name
    if (plys !== undefined && (!Array.isArray(plys) || plys.some((s) => typeof s !== 'string'))) {
      return { ok: false, error: `${idx}.ply_name 必须是字符串数组（或省略）` }
    }

    // ── 几何：新写法（shape）优先，老写法（transform + bounds）归一为 shape ──
    const geometry = normalizeGeometry(item, idx)
    if (!geometry.ok) return { ok: false, error: geometry.error }

    modules.push({
      name: item.name,
      shape: geometry.shape,
      splatTransform: geometry.splatTransform,
      collision_name: (collisions ?? []) as string[],
      ply_name: (plys ?? []) as string[]
    })
  }

  let baseUrl = baseUrlRaw
  if (baseUrl && !baseUrl.endsWith('/')) baseUrl += '/'

  const manifest: ModulesManifest = {
    baseUrl,
    morton: Boolean(r.morton),
    fileType: typeof r.fileType === 'string' ? r.fileType : 'splat',
    modules
  }
  return { ok: true, manifest }
}

function readNumberArr(v: unknown, len: number): number[] | null {
  if (!Array.isArray(v) || v.length !== len) return null
  const out: number[] = []
  for (const n of v) {
    if (typeof n !== 'number' || !Number.isFinite(n)) return null
    out.push(n)
  }
  return out
}

type GeometryResult =
  | { ok: true; shape: BoxShape; splatTransform: ModuleSpec['splatTransform'] }
  | { ok: false; error: string }

/**
 * 几何归一：把两种写法都归一成 `shape` + `splatTransform`。
 *
 * - **新写法**：直接读 `shape`（块盒子）+ `splatTransform`（点云摆放）；
 * - **老写法**：`transform` + `bounds` → 换算
 *   | 新 | 老 |
 *   |---|---|
 *   | `shape.width` / `height` / `depth` | `bounds.x` / `bounds.z` / `bounds.y` |
 *   | `shape.transform.position` | `transform.position`（Y 是盒子中心） |
 *   | `shape.transform.rotation` | `[0,0,0]`（块无旋转） |
 *   | `shape.transform.scale` | `transform.scale` |
 *   | `splatTransform.rotation` / `.scale` | `transform.rotation` / `transform.scale` |
 *
 * ⚠️ 老 `bounds` 的字段名与实际含义不一致：`y` 是**深度**、`z` 是**高度**，必须换轴。
 * ⚠️ `transform.rotation` 是四元数，按 **[x, y, z, w]** 读（`[1,0,0,0]` = 上下翻面）。
 */
function normalizeGeometry(item: Record<string, unknown>, idx: string): GeometryResult {
  const transform = item.transform as Record<string, unknown> | undefined
  const shapeRaw = item.shape as Record<string, unknown> | undefined

  // 老写法下 transform.rotation / scale 归 splatTransform；新写法直接读 splatTransform
  const stRaw = item.splatTransform as Record<string, unknown> | undefined
  const legacyRot = transform ? readNumberArr(transform.rotation, 4) : null
  const legacyScl = transform ? readNumberArr(transform.scale, 3) : null
  const stRot = stRaw ? readNumberArr(stRaw.rotation, 4) : null
  const stScl = stRaw ? readNumberArr(stRaw.scale, 3) : null
  const splatTransform: ModuleSpec['splatTransform'] = {
    rotation: stRot ?? legacyRot ?? [1, 0, 0, 0],
    scale: (stScl ?? legacyScl ?? [1, 1, 1]) as [number, number, number]
  }

  // ── 新写法 ──
  if (shapeRaw && shapeRaw.type === 'box') {
    const width = shapeRaw.width
    const height = shapeRaw.height
    const depth = shapeRaw.depth
    const st = shapeRaw.transform as Record<string, unknown> | undefined
    const position = st ? readNumberArr(st.position, 3) : null
    if (
      typeof width !== 'number' ||
      typeof height !== 'number' ||
      typeof depth !== 'number' ||
      !position
    ) {
      return {
        ok: false,
        error: `${idx}.shape 必须是 {type:'box', width, height, depth, transform:{position,rotation,scale}}`
      }
    }
    const rotation = (st ? readNumberArr(st.rotation, 3) : null) ?? [0, 0, 0]
    const scale = (st ? readNumberArr(st.scale, 3) : null) ?? [1, 1, 1]
    return {
      ok: true,
      shape: {
        type: 'box',
        width,
        height,
        depth,
        transform: {
          position: position as [number, number, number],
          rotation: rotation as [number, number, number],
          scale: scale as [number, number, number]
        }
      },
      splatTransform
    }
  }

  // ── 老写法 ──
  if (!transform || typeof transform !== 'object') {
    return { ok: false, error: `${idx} 缺少几何：需要 shape（推荐）或 transform + bounds` }
  }
  const pos = readNumberArr(transform.position, 3)
  const scl = legacyScl
  if (!pos) return { ok: false, error: `${idx}.transform.position 必须是 3 个数` }
  if (!legacyRot) return { ok: false, error: `${idx}.transform.rotation 必须是 4 个数（[x,y,z,w]）` }
  if (!scl) return { ok: false, error: `${idx}.transform.scale 必须是 3 个数` }

  const b = item.bounds as Record<string, unknown> | undefined
  if (!b || typeof b.x !== 'number' || typeof b.y !== 'number' || typeof b.z !== 'number') {
    return { ok: false, error: `${idx}.bounds 必须是 {x,y,z} 三个数` }
  }

  return {
    ok: true,
    shape: {
      type: 'box',
      // ★换轴：bounds.y 是深度（→ depth），bounds.z 是高度（→ height）
      width: b.x,
      height: b.z,
      depth: b.y,
      transform: {
        position: pos as [number, number, number],
        // 块盒子无旋转（配置里的四元数描述点云内容，已归入 splatTransform）
        rotation: [0, 0, 0],
        scale: scl as [number, number, number]
      }
    },
    splatTransform
  }
}
