import type { NavmeshBakeParams } from '../stores/navmesh'

/**
 * 存档（.navmap.zip）的数据结构定义。
 *
 * 读写两侧共用同一份定义与条目名常量，避免"写的时候叫 A、读的时候找 B"这类漂移。
 *
 * ## 存档内容边界
 *
 * 存：GLB 原文件、烘焙参数、生成骨架、手动补线、可选的 GS Module manifest。
 * 不存：navmesh（可由 GLB + 参数重算）、子流程产物（bin / 可达区 / chunk）。
 *
 * @changelog
 * | 版本   | 变更说明                                                     | 关联                     |
 * | v1.0.0 | 初始定义：配置清单 + 地形元信息 + 脊线折线，含 formatVersion  | REQ: map-editor-ui-shell |
 * /@changelog
 *
 * @author linfan
 */

/** 当前存档格式版本；读取时不匹配直接报错，不做"尽力而为"的猜测 */
export const ARCHIVE_FORMAT_VERSION = 1

/** 存档内的配置清单条目名 */
export const ARCHIVE_ENTRY_MANIFEST = 'manifest.json'

/** 存档内的 GS Module manifest 条目名（可选） */
export const ARCHIVE_ENTRY_GS_MODULE = 'gs-module.json'

/** 存档内地形文件所在目录前缀 */
export const ARCHIVE_TERRAIN_DIR = 'terrains/'

/** 存档内每份地形的元信息（几何本身以同名的 zip 条目存放） */
export interface ArchiveTerrainMeta {
  /** zip 内该 GLB 的条目路径 */
  entry: string
  /** 原始文件名 */
  name: string
  /** 文件字节数 */
  fileSize: number
  /** 用户调整的旋转（度，XYZ） */
  rotationDeg: [number, number, number]
  /** 用户调整的镜像（沿各轴 scale = -1） */
  flip: [boolean, boolean, boolean]
}

/** 配置清单（manifest.json）的 v1 结构 */
export interface ArchiveManifestV1 {
  formatVersion: number
  /** 保存时间（ISO 字符串，仅作信息展示） */
  savedAt: string
  /** 烘焙参数原样保存，载入后回填 store */
  bakeParams: NavmeshBakeParams
  terrains: ArchiveTerrainMeta[]
  /** 自动骨架折线（每段一条，flat XYZ） */
  spines: number[][]
  /** 手动补线折线 */
  spineGuides: number[][]
  /** 骨架生成树的边数（图例"树边"回显用，需与折线一起还原） */
  spineTreeEdges: number
  /** 是否携带 GS Module manifest 文本 */
  hasGsModule: boolean
}

/** 内存中的一份地形数据（打包输入 / 解包输出共用） */
export interface ArchiveTerrainData {
  /** 原始文件名 */
  name: string
  /** 文件字节数 */
  fileSize: number
  /** 用户调整的旋转（度，XYZ） */
  rotationDeg: [number, number, number]
  /** 用户调整的镜像（沿各轴 scale = -1） */
  flip: [boolean, boolean, boolean]
  /** GLB 原始字节 */
  bytes: Uint8Array
  /** zip 内条目路径：仅解包时回填，打包时由 IO 层生成 */
  entry?: string
}

/** 打包输入 / 解包输出共用的内存结构 */
export interface ArchivePayload {
  bakeParams: NavmeshBakeParams
  terrains: ArchiveTerrainData[]
  spines: Float32Array[]
  spineGuides: Float32Array[]
  spineTreeEdges: number
  /** 未携带时为 null */
  gsModuleText: string | null
}
