import { strFromU8, strToU8, unzip, zip, type Unzipped, type Zippable } from 'fflate'
import {
  ARCHIVE_ENTRY_GS_MODULE,
  ARCHIVE_ENTRY_MANIFEST,
  ARCHIVE_FORMAT_VERSION,
  ARCHIVE_TERRAIN_DIR,
  type ArchiveManifestV1,
  type ArchivePayload,
  type ArchiveTerrainData
} from '../types/archive'

/**
 * useArchiveIO — 存档的打包 / 解包（纯转换层）。
 *
 * ## 职责边界
 *
 * 只做「内存结构 ↔ zip 字节」的转换：不读 store、不碰 Three、不决定恢复顺序。
 * "清空什么、按什么顺序恢复、何时提示"留在编排层（`NavmeshView`），与 `applyBake`
 * 的分层一致 —— 工具模块不反向依赖业务状态。
 *
 * ## 存档内结构
 *
 * ```
 * manifest.json          配置清单（formatVersion / 烘焙参数 / 地形元信息 / 脊线折线）
 * terrains/<n>_<name>    GLB 原文件（可能有多个）
 * gs-module.json         GS Module manifest 文本（有则写，没有就不写这个条目）
 * ```
 *
 * ## 为什么 GLB 用 level 0
 *
 * GLB 内部已经是压缩过的二进制，再 deflate 一遍几乎压不动，只是白耗 CPU；
 * 而 manifest 是文本，照常压缩。
 *
 * ## 错误策略
 *
 * 缺条目 / 版本不符 / JSON 损坏一律**抛错**，由编排层捕获后提示用户，
 * 不做"跳过坏数据继续加载"——半个存档恢复出来的现场比失败更难排查。
 *
 * @changelog
 * | 版本   | 变更说明                                                 | 关联                     |
 * | v1.0.0 | 初始实现：zip 打包/解包 + formatVersion 校验 + 折线序列化 | REQ: map-editor-ui-shell |
 * | v1.1.0 | 折线坐标按毫米取整（3 位小数）：去掉 Float32 浮点噪声，manifest 显著变小 | REQ: map-editor-ui-shell |
 * /@changelog
 *
 * @author linfan
 */

/** 条目名：按序号前缀保证唯一（同名地形不会互相覆盖），并过滤文件名里的非法字符 */
function entryName(name: string, index: number): string {
  const base = name.replace(/[\\/:*?"<>|]+/g, '_').trim() || 'terrain.glb'
  return `${ARCHIVE_TERRAIN_DIR}${index}_${base}`
}

/** 把内存结构打成 zip 字节 */
export function buildArchive(payload: ArchivePayload): Promise<Uint8Array> {
  const manifest: ArchiveManifestV1 = {
    formatVersion: ARCHIVE_FORMAT_VERSION,
    savedAt: new Date().toISOString(),
    bakeParams: payload.bakeParams,
    terrains: payload.terrains.map((t, i) => ({
      entry: entryName(t.name, i),
      name: t.name,
      fileSize: t.fileSize,
      rotationDeg: t.rotationDeg,
      flip: t.flip
    })),
    spines: payload.spines.map(toMillimeterLine),
    spineGuides: payload.spineGuides.map(toMillimeterLine),
    spineTreeEdges: payload.spineTreeEdges,
    hasGsModule: payload.gsModuleText !== null
  }

  const entries: Zippable = {
    [ARCHIVE_ENTRY_MANIFEST]: [strToU8(JSON.stringify(manifest)), { level: 6 }]
  }
  payload.terrains.forEach((t, i) => {
    // level 0 = store，不再压（GLB 已是压缩格式）
    entries[entryName(t.name, i)] = [t.bytes, { level: 0 }]
  })
  if (payload.gsModuleText !== null) {
    entries[ARCHIVE_ENTRY_GS_MODULE] = [strToU8(payload.gsModuleText), { level: 6 }]
  }

  return new Promise((resolve, reject) => {
    zip(entries, {}, (err, data) => {
      if (err) {
        reject(new Error(`打包存档失败：${err.message}`))
        return
      }
      resolve(data)
    })
  })
}

/** 解析 zip 字节为内存结构；失败时抛出的错误文案可直接展示给用户 */
export function readArchive(bytes: Uint8Array): Promise<ArchivePayload> {
  return new Promise((resolve, reject) => {
    unzip(bytes, (err, files) => {
      if (err) {
        reject(new Error(`解包存档失败：${err.message}`))
        return
      }
      try {
        resolve(parseEntries(files))
      } catch (e) {
        reject(e instanceof Error ? e : new Error(String(e)))
      }
    })
  })
}

function parseEntries(files: Unzipped): ArchivePayload {
  const manifestBytes = files[ARCHIVE_ENTRY_MANIFEST]
  if (!manifestBytes) {
    throw new Error(`存档缺少 ${ARCHIVE_ENTRY_MANIFEST}，可能不是本工具的存档文件`)
  }

  let manifest: ArchiveManifestV1
  try {
    manifest = JSON.parse(strFromU8(manifestBytes)) as ArchiveManifestV1
  } catch {
    throw new Error(`${ARCHIVE_ENTRY_MANIFEST} 解析失败（JSON 已损坏）`)
  }

  if (manifest.formatVersion !== ARCHIVE_FORMAT_VERSION) {
    throw new Error(
      `存档格式版本不支持：期望 ${ARCHIVE_FORMAT_VERSION}，实际 ${manifest.formatVersion}`
    )
  }

  const terrains: ArchiveTerrainData[] = manifest.terrains.map((meta) => {
    const data = files[meta.entry]
    if (!data) throw new Error(`存档缺少地形文件 ${meta.entry}（${meta.name}）`)
    return {
      entry: meta.entry,
      name: meta.name,
      fileSize: meta.fileSize,
      rotationDeg: meta.rotationDeg,
      flip: meta.flip,
      bytes: data
    }
  })

  const gsBytes = files[ARCHIVE_ENTRY_GS_MODULE]
  return {
    bakeParams: manifest.bakeParams,
    terrains,
    spines: toLines(manifest.spines),
    spineGuides: toLines(manifest.spineGuides),
    spineTreeEdges: manifest.spineTreeEdges ?? 0,
    gsModuleText: manifest.hasGsModule && gsBytes ? strFromU8(gsBytes) : null
  }
}

/** number[][] → Float32Array[]（渲染层与骨架逻辑都用 Float32Array 折线） */
function toLines(raw: number[][]): Float32Array[] {
  if (!Array.isArray(raw)) return []
  return raw.map((line) => Float32Array.from(line))
}

/**
 * 折线坐标按**毫米取整**（保留 3 位小数）后落盘。
 *
 * 为什么必须做：折线是 `Float32Array`，直接 `Array.from` 会把 Float32 的完整十进制展开
 * 写进 JSON —— `12.345678329467773`、`0.30000001192092896`、`-9.999999974752427e-7`，
 * 其中绝大多数位是浮点噪声。实测同一组坐标，取整后字节数只有原来的 1/4，
 * 而 manifest 的体积大头正是这些折线。
 *
 * 取整到 1 毫米对米级场景的导航骨架完全够用（骨架的用途是布块与给人看走向）。
 * 载入侧仍走 `toLines` → `Float32Array`，精度损失只在这一步，不影响后续算法。
 */
function toMillimeterLine(line: Float32Array): number[] {
  const out = new Array<number>(line.length)
  for (let i = 0; i < line.length; i++) {
    out[i] = Math.round(line[i] * 1000) / 1000
  }
  return out
}
