<script setup lang="ts">
/**
 * NavmeshParamsPanel — Recast 烘焙参数面板。
 *
 * 设计要点：
 * - 8 个 Recast 参数按"几何精度 / agent 物理 / region 合并"三组排版，便于理解
 * - 字段做范围校验（min/max），超界自动钳制
 * - "重置默认值"立即生效，"应用"按钮触发外部 emit('apply')
 * - 面板内部 draft 与 store 隔离：只有点 Apply 才同步到 store，避免每次 input 都触发烘焙
 */
import { computed, ref, watch } from 'vue'
import { RotateCcw, Play, Loader2, Settings2 } from 'lucide-vue-next'
import {
  useNavmeshStore,
  DEFAULT_BAKE_PARAMS,
  type NavmeshBakeParams
} from '../stores/navmesh'

const emit = defineEmits<{
  (e: 'apply', params: NavmeshBakeParams): void
}>()

const store = useNavmeshStore()

/** 编辑中的草稿：与 store.bakeParams 隔离 */
const draft = ref<NavmeshBakeParams>({ ...store.bakeParams })

/** store 端如果被外部改了（resetParams 等），同步到 draft */
watch(
  () => store.bakeParams,
  (v) => {
    draft.value = { ...v }
  },
  { deep: true }
)

interface ParamMeta {
  key: keyof NavmeshBakeParams
  label: string
  desc: string
  min: number
  max: number
  step: number
  /** 单位提示 */
  hint?: string
}

const groupGeometry: ParamMeta[] = [
  {
    key: 'cs',
    label: 'cellSize',
    desc: 'XZ 体素大小，越小越精细但越慢',
    min: 0.05,
    max: 2,
    step: 0.05,
    hint: 'm/cell'
  },
  {
    key: 'ch',
    label: 'cellHeight',
    desc: 'Y 方向体素高度',
    min: 0.05,
    max: 2,
    step: 0.05,
    hint: 'm/cell'
  }
]

const groupAgent: ParamMeta[] = [
  {
    key: 'walkableSlopeAngle',
    label: 'walkableSlopeAngle',
    desc: '可走最大坡度（度）',
    min: 0,
    max: 89,
    step: 1,
    hint: '°'
  },
  {
    key: 'walkableHeight',
    label: 'walkableHeight',
    desc: 'agent 高度，实际 = 此值 × ch',
    min: 1,
    max: 50,
    step: 1,
    hint: 'cells'
  },
  {
    key: 'walkableRadius',
    label: 'walkableRadius',
    desc: 'agent 半径，实际 = 此值 × cs',
    min: 0,
    max: 20,
    step: 1,
    hint: 'cells'
  },
  {
    key: 'walkableClimb',
    label: 'walkableClimb',
    desc: '能跨过的最大台阶高度',
    min: 0,
    max: 20,
    step: 1,
    hint: 'cells'
  }
]

const groupRegion: ParamMeta[] = [
  {
    key: 'minRegionArea',
    label: 'minRegionArea',
    desc: '小于此面积的 region 丢弃',
    min: 0,
    max: 200,
    step: 1,
    hint: 'voxels'
  },
  {
    key: 'mergeRegionArea',
    label: 'mergeRegionArea',
    desc: '低于此值的相邻 region 合并',
    min: 0,
    max: 500,
    step: 1
  }
]

function clamp(v: number, min: number, max: number): number {
  if (!Number.isFinite(v)) return min
  return Math.min(max, Math.max(min, v))
}

function onInput(meta: ParamMeta, val: string) {
  const n = Number(val)
  draft.value[meta.key] = clamp(n, meta.min, meta.max)
}

function reset() {
  draft.value = { ...DEFAULT_BAKE_PARAMS }
  store.resetParams()
}

function apply() {
  // 写回 store 并通知外部触发烘焙
  store.setParams(draft.value)
  emit('apply', { ...draft.value })
}

const isDirty = computed(() => {
  const a = draft.value
  const b = store.bakeParams
  return (Object.keys(a) as Array<keyof NavmeshBakeParams>).some((k) => a[k] !== b[k])
})

const canApply = computed(() => !store.loading)
</script>

<template>
  <!--
    布局说明：本面板原先用 h-full + overflow-hidden + 内部 flex-1 min-h-0 overflow-y-auto
    做"双层滚动"（外 aside 滚 + 内面板自滚），但放进父 aside（已是 overflow-y-auto）后，
    h-full 在 overflow-y-auto 容器中等于"容器高度"而非"剩余空间"，导致本面板被撑成视口高，
    内部滚动区压到极小，aside 滚到底部时只能看到本面板的标题，看不到 Recast 参数表单和应用按钮。

    修复：移除 h-full / overflow-hidden / 内部独立滚动条，让本面板按内容自然撑开高度，
    与同 aside 内的其他面板（Minimap / Upload / Manifest）一致，统一由父 aside 单层滚动。
  -->
  <section class="glass-card p-3 flex flex-col gap-3">
    <header class="flex items-center justify-between shrink-0">
      <div class="flex items-center gap-2 text-cyan-glow text-[12px] font-semibold">
        <Settings2 class="w-3.5 h-3.5" />
        Recast 烘焙参数
      </div>
      <span
        v-if="isDirty"
        class="text-[10px] px-1.5 py-0.5 rounded bg-amber-400/15 text-amber-300 border border-amber-400/30"
      >
        未应用
      </span>
    </header>

    <div class="space-y-3">
      <!-- 几何精度 -->
      <div class="space-y-2">
        <div class="text-[10px] uppercase tracking-wider text-slate-500">几何精度</div>
        <div
          v-for="m in groupGeometry"
          :key="m.key"
          class="rounded-md border border-white/5 bg-white/[0.02] p-2 hover:border-cyan-glow/30 transition-colors"
        >
          <div class="flex items-center justify-between mb-1">
            <label class="text-[11px] font-medium text-slate-200 font-mono">{{ m.label }}</label>
            <span class="text-[10px] text-slate-500 font-mono">
              {{ m.min }} ~ {{ m.max }}{{ m.hint ? ` · ${m.hint}` : '' }}
            </span>
          </div>
          <input
            type="number"
            :step="m.step"
            :min="m.min"
            :max="m.max"
            :value="draft[m.key]"
            class="w-full bg-black/30 border border-white/10 rounded px-2 py-1 text-[11px] text-slate-100 font-mono outline-none focus:border-cyan-glow/50 focus:ring-1 focus:ring-cyan-glow/30"
            @input="onInput(m, ($event.target as HTMLInputElement).value)"
          />
          <p class="text-[10px] text-slate-500 mt-1 leading-snug">{{ m.desc }}</p>
        </div>
      </div>

      <!-- Agent 物理 -->
      <div class="space-y-2">
        <div class="text-[10px] uppercase tracking-wider text-slate-500">Agent 物理</div>
        <div
          v-for="m in groupAgent"
          :key="m.key"
          class="rounded-md border border-white/5 bg-white/[0.02] p-2 hover:border-cyan-glow/30 transition-colors"
        >
          <div class="flex items-center justify-between mb-1">
            <label class="text-[11px] font-medium text-slate-200 font-mono">{{ m.label }}</label>
            <span class="text-[10px] text-slate-500 font-mono">
              {{ m.min }} ~ {{ m.max }}{{ m.hint ? ` · ${m.hint}` : '' }}
            </span>
          </div>
          <input
            type="number"
            :step="m.step"
            :min="m.min"
            :max="m.max"
            :value="draft[m.key]"
            class="w-full bg-black/30 border border-white/10 rounded px-2 py-1 text-[11px] text-slate-100 font-mono outline-none focus:border-cyan-glow/50 focus:ring-1 focus:ring-cyan-glow/30"
            @input="onInput(m, ($event.target as HTMLInputElement).value)"
          />
          <p class="text-[10px] text-slate-500 mt-1 leading-snug">{{ m.desc }}</p>
        </div>
      </div>

      <!-- Region 合并 -->
      <div class="space-y-2">
        <div class="text-[10px] uppercase tracking-wider text-slate-500">Region 合并</div>
        <div
          v-for="m in groupRegion"
          :key="m.key"
          class="rounded-md border border-white/5 bg-white/[0.02] p-2 hover:border-cyan-glow/30 transition-colors"
        >
          <div class="flex items-center justify-between mb-1">
            <label class="text-[11px] font-medium text-slate-200 font-mono">{{ m.label }}</label>
            <span class="text-[10px] text-slate-500 font-mono">
              {{ m.min }} ~ {{ m.max }}{{ m.hint ? ` · ${m.hint}` : '' }}
            </span>
          </div>
          <input
            type="number"
            :step="m.step"
            :min="m.min"
            :max="m.max"
            :value="draft[m.key]"
            class="w-full bg-black/30 border border-white/10 rounded px-2 py-1 text-[11px] text-slate-100 font-mono outline-none focus:border-cyan-glow/50 focus:ring-1 focus:ring-cyan-glow/30"
            @input="onInput(m, ($event.target as HTMLInputElement).value)"
          />
          <p class="text-[10px] text-slate-500 mt-1 leading-snug">{{ m.desc }}</p>
        </div>
      </div>
    </div>

    <footer class="shrink-0 flex items-center gap-2 pt-2 border-t border-white/5">
      <button
        type="button"
        class="flex-1 flex items-center justify-center gap-1.5 py-1.5 rounded-md border border-white/10 bg-white/5 text-[11px] text-slate-300 hover:bg-white/10 hover:text-slate-100 transition-colors cursor-pointer"
        @click="reset"
      >
        <RotateCcw class="w-3 h-3" />
        重置默认值
      </button>
      <button
        type="button"
        :disabled="!canApply"
        class="flex-1 flex items-center justify-center gap-1.5 py-1.5 rounded-md text-[11px] font-semibold transition-all"
        :class="
          canApply
            ? 'bg-emerald-400/20 text-emerald-300 border border-emerald-400/40 hover:bg-emerald-400/30 cursor-pointer shadow-cyan-glow'
            : 'bg-white/5 text-slate-500 border border-white/5 cursor-not-allowed'
        "
        @click="apply"
      >
        <Loader2 v-if="store.loading" class="w-3 h-3 animate-spin" />
        <Play v-else class="w-3 h-3" />
        {{ store.loading ? '烘焙中…' : '应用并烘焙' }}
      </button>
    </footer>
  </section>
</template>
