    icon: Trash2,
    hint: '清空编辑成果（起点终点 / 可达 / 骨架 / 补线 / 切块），地形与烘焙参数保留'
  }
] as const

/** 工作区动作标识（由 workspaceActions 派生，避免手写联合类型与数据漂移） */
type WorkspaceActionKey = (typeof workspaceActions)[number]['key']

/** 渲染句柄（markRaw 防止响应式 proxy 干扰 Three 对象） */
let renderHandle: NavmeshRenderHandle | null = null

/* ---------- 3D 预览：拾取回调 ---------- */
function handlePick(point: { x: number; y: number; z: number }) {
  const mode = store.pickMode
  if (mode === 'off') return
  if (!store.navMeshRef || !store.navQueryRef) return
  if (mode === 'start') {
    setStart(point)
  } else if (mode === 'end') {
    setEnd(point)
  } else if (mode === 'spine') {
    handleSpinePick(point)
  }
}

const { focusBox, chunkGizmo, project, onAfterRender } = useNavmeshPreview({
  canvasRef: () => canvasRef.value,
  containerRef: () => containerRef.value,
  onPick: handlePick,
  // 叠加物优先：点中切块就选中它（否则块浮在地表上永远点不中）
  onPickOverlay,
  onPickMiss
})

/* ---------- 烘焙 ---------- */
async function applyBake(params: NavmeshBakeParams) {
  if (terrainStore.terrains.length === 0) {
    store.setError('请先在左侧上传 navmesh GLB（或几何 GLB）')
    return
  }
  // 重新烘焙 = 重建依赖链的根：沿旧脊线布出来的块会失效被清（手工调整 / 文件载入的块
  // 不依赖 navmesh，会保留 —— 见 dropGeneratedChunks）。被清的是算法成果、保留的是用户
  // 劳动成果，所以这份"会丢什么"必须先说清楚再问一次。
  const generatedCount = store.chunkItems.filter((it) => it.origin === 'generated').length
  if (generatedCount > 0) {
    const keepCount = store.chunkItems.length - generatedCount
    const ok = window.confirm(
      `重新烘焙会重建 navmesh：${generatedCount} 个算法生成的块将失效并被清除` +
        (keepCount > 0 ? `；${keepCount} 个手工调整 / 文件载入的块会保留` : '') +
        '。继续？'
    )
    if (!ok) return
  }
  store.setError(null)
  store.setLoading(true, '初始化 Recast wasm…')
  // 取 token 用于"丢弃 stale 结果"
  const token = store.bumpBakeToken()
  let out: BakeOutput | null = null
  try {
    await ensureRecastInited()
    if (!store.isTokenAlive(token)) return
    store.setLoading(true, '烘焙 navmesh…')
    // 同步阻塞，但前面已 setLoading，UI 会先重绘 mask 再阻塞
    await new Promise((r) => setTimeout(r, 0)) // 让出一帧给 UI 渲染 loading mask
    if (!store.isTokenAlive(token)) return
    out = bakeNavmesh({ terrains: terrainStore.terrains, params })
    if (!store.isTokenAlive(token)) {
      disposeBake(out)
      return
    }
    // 旧实例释放（store.setBakeResult 不会 destroy 旧的，需手动）
    if (store.navMeshRef) {
      try {
        store.navQueryRef?.destroy()
        store.navMeshRef.destroy()
      } catch (err) {
        console.warn('[navmesh] dispose old navmesh failed', err)
      }
    }
    store.setBakeResult(out.navMesh, out.navQuery, out.polygons, out.bakeMs)
    // 渲染层：重建 navmesh polygon
    if (renderHandle) {
      renderHandle.setPolygons(out.polygons)
      renderHandle.setReachable(new Set())
      renderHandle.setStartMarker(null)
      renderHandle.setEndMarker(null)
      renderHandle.setPath(new Float32Array(0))
      // 脊线在 navmesh 重建后可能失效：默认清掉骨架 + 手动补线。
      // 例外：**存档载入后的首次烘焙** —— 若参数与地形都与存档一致，重烘焙得到的 navmesh
      // 与存档时等价，恢复出来的脊线依然对得上，此时必须保留，否则"载入即恢复"就白做了。
      const keepRestoredSpines = restoredSpinesStillValid()
      if (keepRestoredSpines) {
        applySpineRendering()
        updateSpineInfo()
      } else {
        renderHandle.setCenterlines([])
        lastSpineLines = []
        resetManualSpine()
        store.setSpineInfo(null)
        restoredSpineContext = null
      }
      // 切块基于旧 navmesh：算法生成的块随之失效；手工 / 载入的块与 navmesh 无关，保留
      const dropped = dropGeneratedChunks()
      if (dropped > 0 && store.chunkItems.length > 0) {
        flashSuccess(
          `navmesh 已重建：清掉 ${dropped} 个算法生成的块，` +
            `保留 ${store.chunkItems.length} 个手工 / 载入的块`
        )
      }
      // module halo 默认 neutral
      updateModuleHalos()
    }
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e)
    console.error('[navmesh] bake failed', e)
    store.setError(`烘焙失败：${msg}`)
    if (out) disposeBake(out)
  } finally {
    if (store.isTokenAlive(token)) store.setLoading(false)
  }
}

/* ---------- 起点 / 终点 / flood fill / 寻路 ---------- */
function setStart(point: { x: number; y: number; z: number }) {
  if (!store.navMeshRef || !store.navQueryRef) return
  store.setError(null)
  // findNearestPoly
  const halfExtents = { x: 2, y: 4, z: 2 }
  const res = store.navQueryRef.findNearestPoly(point, { halfExtents })
  if (!res.success || !res.nearestRef) {
    store.setError('起点未吸附到任何 polygon（请点击在 navmesh 覆盖区域内）')
    return
  }
  const polyRef = res.nearestRef
  store.setStart(point, polyRef)
  // flood fill
  const reachable = floodFillFromPoly(store.navMeshRef, polyRef)
  // poly → module 映射
  const mapped = mapPolyToModule(store.polygons, reachable, modulesStore.modules)
  store.setReachable(
    reachable,
    mapped.reachableModuleIds,
    mapped.unreachableModuleIds,
    mapped.crossModulePolyCount
  )
  // 渲染更新
  if (renderHandle) {
    renderHandle.setStartMarker(point)
    renderHandle.setReachable(reachable)
    // 可达区变了 → 「仅可达」模式下脊线需要重新裁剪
    applySpineRendering()
    updateModuleHalos()
  }
  console.info(
    `[navmesh] flood fill: ${reachable.size}/${store.polyCount} polys, ${mapped.reachableModuleIds.size} modules reachable`
  )
}

function setEnd(point: { x: number; y: number; z: number }) {
  if (!store.navMeshRef || !store.navQueryRef) return
  if (!store.startPoint) {
    store.setError('请先选起点再选终点')
    return
  }
  store.setError(null)
  const res = store.navQueryRef.findNearestPoly(point, {
    halfExtents: { x: 2, y: 4, z: 2 }
  })
  if (!res.success || !res.nearestRef) {
    store.setError('终点未吸附到任何 polygon')
    return
  }
  store.setEnd(point, res.nearestRef)
  const path = findPath(store.navQueryRef, store.startPoint, point)
  if (!path.ok) {
    store.setError(`寻路失败：${path.error || '路径不可达'}`)
    if (renderHandle) {
      renderHandle.setEndMarker(point)
      renderHandle.setPath(new Float32Array(0))
    }
    return
  }
  store.setPath(path.points)
  if (renderHandle) {
    renderHandle.setEndMarker(point)
    renderHandle.setPath(path.points)
  }
}

function updateModuleHalos() {
  if (!renderHandle) return
  const items = modulesStore.modules
    .filter((m) => !m.worldBox.isEmpty())
    .map((m) => {
      let state: 'reach' | 'unreach' | 'neutral' = 'neutral'
      if (store.reachableModuleIds.has(m.name)) state = 'reach'
      else if (store.unreachableModuleIds.has(m.name)) state = 'unreach'
      return { name: m.name, box: m.worldBox, state }
    })
  renderHandle.setModuleHalos(items)
}

/* ---------- 模式切换 / 清除 ---------- */
function setPickMode(m: 'start' | 'end' | 'spine' | 'off') {
  // 离开补线模式时清掉半成品锚点，避免下次进来还挂着一个旧点
  if (m !== 'spine' && manualSpineAnchor.value) {
    manualSpineAnchor.value = null
    renderHandle?.setSpineAnchor(null)
  }
  store.setPickMode(m)
}

/**
 * 切换拾取模式（按钮入口）：点已被激活的那个 → 关闭。
 *
 * 为什么需要单独一层：按钮原先直接调 `setPickMode('spine' | 'start' | 'end')`，
 * 那是**设置**语义 —— 点开之后无论点多少次都还是该模式，**没法关闭**，
 * 只能靠切换子流程或重新烘焙被动退出。这里补上"再点一次退出"的开关语义。
 */
function togglePickMode(m: 'start' | 'end' | 'spine') {
  setPickMode(store.pickMode === m ? 'off' : m)
}

/* ---------- 键盘：ESC 退出拾取模式 ---------- */

/** 拾取模式的中文名（退出提示用） */
const PICK_MODE_LABEL: Record<'start' | 'end' | 'spine', string> = {
  start: '选起点',
  end: '选终点',
  spine: '补线'
}

/**
 * ESC 退出当前拾取模式（补线 / 选起点 / 选终点）。
 *
 * 为什么需要：拾取模式是"场景点击被接管"的状态，退出入口原先只有按钮本身。
 * 用户在场景里连点几下后鼠标已在画面中央，按 ESC 比移回左栏再点一次顺手得多。
 *
 * 为什么三处都接而不是只接补线：它们是同一类"拾取中"状态，只给补线配快捷键
 * 反而要多记一套规则；且 ESC 对"取消当前操作"的直觉是一致的。
 */
function onKeyDown(e: KeyboardEvent) {
  // 输入框 / 可编辑区里的按键属于控件自身（删字符、还原取值），不要抢
  const el = e.target as HTMLElement | null
  if (el && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA' || el.isContentEditable))
    return

  // Delete / Backspace：删掉选中的块（仅在 chunk 流程且确实有选中时）
  if (
    (e.key === 'Delete' || e.key === 'Backspace') &&
    store.subFlow === 'chunk' &&
    store.selectedChunk
  ) {
    e.preventDefault()
    removeChunkById(store.selectedChunk.id)
    return
  }

  if (e.key !== 'Escape') return
  const mode = store.pickMode
  if (mode === 'off') return
  const label = PICK_MODE_LABEL[mode]
  setPickMode('off')
  flashSuccess(`已退出${label}模式（ESC）`)
}

// 挂在 window 上：鼠标在场景（canvas）里时按 ESC 也要生效
onMounted(() => window.addEventListener('keydown', onKeyDown))
onBeforeUnmount(() => window.removeEventListener('keydown', onKeyDown))

function clearAll() {
  store.clearFloodAndPath()
  if (renderHandle) {
    renderHandle.setReachable(new Set())
    renderHandle.setStartMarker(null)
    renderHandle.setEndMarker(null)
    renderHandle.setPath(new Float32Array(0))
    renderHandle.setCenterlines([])
    lastSpineLines = []
    resetManualSpine()
    // 脊线都被清了，存档快照随之失效
    restoredSpineContext = null
    clearChunks()
    store.setSpineInfo(null)
    updateModuleHalos()
  }
  // 全清后回到第一个子流程：数据都没了，停在哪个子流程都没有意义
  store.setSubFlow('bin')
}

/* ---------- ⓪ 存档：保存 / 载入 ---------- */

/**
 * 载入存档时记下的"脊线有效性依据"：烘焙参数 + 地形指纹。
 *
 * 为什么需要：navmesh 不入存档，所以载入后必须重新烘焙；而烘焙在"navmesh 变了、
 * 旧脊线坐标可能已失效"的假设下会清空骨架与手动补线。但对**载入后什么都没改**的情况，
 * GLB 与参数都与存档时一致 —— 重烘焙得到的 navmesh 与存档时等价，恢复出来的脊线
 * 依然对得上。这里用这份快照把这种情况区分出来，否则"载入恢复骨架"会被随后的烘焙抹掉。
 *
 * ⚠️ 为什么必须连地形一起比对：骨架是 `f(GLB, 参数)` 的产物。只比参数的话，
 * 用户载入后**增删地形**（参数没动）再烘焙，会得到完全不同的 navmesh，
 * 而这批骨架却被当成"仍然有效"保留下来 —— 那就是悬空的假数据。
 */
let restoredSpineContext: { params: NavmeshBakeParams; terrains: string } | null = null

/** 逐字段比对两组烘焙参数（全为数字，直接 === 即可） */
function sameBakeParams(a: NavmeshBakeParams, b: NavmeshBakeParams): boolean {
  return (Object.keys(a) as Array<keyof NavmeshBakeParams>).every((k) => a[k] === b[k])
}

/** 当前地形指纹（id + 名称 + 字节数）：任一地形被增删都会变化 */
function terrainFingerprint(): string {
  return terrainStore.terrains.map((t) => `${t.id}:${t.name}:${t.fileSize}`).join('|')
}

/** 存档恢复的脊线在当前环境下是否仍然有效（参数与地形都未被改动） */
function restoredSpinesStillValid(): boolean {
  const ctx = restoredSpineContext
  if (!ctx) return false
  return sameBakeParams(ctx.params, store.bakeParams) && ctx.terrains === terrainFingerprint()
}

/** 存档文件选择框（模板内的隐藏 input） */
const archiveInputRef = ref<HTMLInputElement | null>(null)

/** 存档文件名时间戳（YYYYMMDD_HHMMSS，本地时区，便于按时间排序） */
function archiveStamp(): string {
  const d = new Date()
  const p = (n: number) => String(n).padStart(2, '0')
  return (
    `${d.getFullYear()}${p(d.getMonth() + 1)}${p(d.getDate())}` +
    `_${p(d.getHours())}${p(d.getMinutes())}${p(d.getSeconds())}`
  )
}

/**
 * 工作区按钮的禁用规则：
 * - 任何工作区动作（或烘焙）进行中都禁用 —— 打包 / 解包期间连点会重复触发下载、
 *   或重复弹出文件选择框；
 * - 「保存」要求至少有一个地形（没有地形就没有可存的东西）；
 * - 「清除」只在"确实有东西可清"时可点，避免空点。
 */
function workspaceActionDisabled(key: WorkspaceActionKey): boolean {
  if (store.loading) return true
  if (key === 'save') return terrainStore.isEmpty
  if (key === 'clear') return !hasClearableContent()
  return false
}

function onWorkspaceAction(key: WorkspaceActionKey) {
  if (key === 'save') void saveArchive()
  else if (key === 'load') archiveInputRef.value?.click()
  else clearWorkspaceContents()
}

/** 是否有"可清除的编辑成果"（决定「清除」是否可点） */
function hasClearableContent(): boolean {
  return (
    store.startPoint !== null ||
    store.endPoint !== null ||
    lastSpineLines.length > 0 ||
    manualSpineLines.length > 0 ||
    store.chunkItems.length > 0
  )
}

/**
 * 清除编辑成果（地形与烘焙参数保留）。
 *
 * 为什么加二次确认：它会一次丢掉起点终点、可达染色、整份骨架与手动补线 —— 都是
 * 不可逆的劳动成果，误点的代价远大于多按一次确认。
 */
function clearWorkspaceContents() {
  const ok = window.confirm(
    '清除会清空当前的编辑成果（起点终点 / 可达 / 骨架 / 补线 / 切块），地形与烘焙参数保留。确定继续？'
  )
  if (!ok) return
  clearAll()
  flashSuccess('已清除编辑成果（地形与烘焙参数保留）')
}

/**
 * 保存存档：把主流程的**输入**（GLB / 参数 / manifest）与**成果**（骨架 / 补线）打包下载。
 *
 * 因为不存 navmesh，这里只需要地形就绪，不要求已烘焙 —— 参数在 store 里始终有值。
 */
async function saveArchive() {
  const items = terrainStore.terrains
  if (items.length === 0) {
    store.setError('没有可保存的地形：请先在 ① 加载里上传 GLB')
    return
  }
  const missing = items.filter((t) => !t.rawBytes)
  if (missing.length > 0) {
    store.setError(
      `以下地形缺少原始文件字节，无法进存档：${missing.map((t) => t.name).join('、')}`
    )
    return
  }

  try {
    store.setError(null)
    store.setLoading(true, '打包存档…')
    const bytes = await buildArchive({
      bakeParams: { ...store.bakeParams },
      terrains: items.map((t) => ({
        name: t.name,
        fileSize: t.fileSize,
        rotationDeg: [...t.rotationDeg] as [number, number, number],
        flip: [...t.flip] as [boolean, boolean, boolean],
        bytes: t.rawBytes as Uint8Array
      })),
      spines: lastSpineLines,
      spineGuides: manualSpineLines,
      spineTreeEdges: lastSpineTreeEdges,
      gsModuleText: modulesStore.manifest ? JSON.stringify(modulesStore.manifest) : null
    })
    // 切成独立 ArrayBuffer：Blob 直接吃 Uint8Array 在部分 TS 配置下会因
    // ArrayBufferLike（可能为 SharedArrayBuffer）而不满足 BlobPart
    const buffer = bytes.buffer.slice(
      bytes.byteOffset,
      bytes.byteOffset + bytes.byteLength
    ) as ArrayBuffer
    triggerDownload(
      new Blob([buffer], { type: 'application/zip' }),
      `navmap-${archiveStamp()}.navmap.zip`
    )
    flashSuccess(
      `存档已导出：地形 ${items.length} 个 · 骨架 ${lastSpineLines.length} 段 · ` +
        `补线 ${manualSpineLines.length} 段${modulesStore.manifest ? ' · 含 GS Module' : ''}`
    )
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e)
    console.error('[archive] 保存失败', e)
    store.setError(`保存存档失败：${msg}`)
  } finally {
    store.setLoading(false)
  }
}

async function onArchiveFileChange(e: Event) {
  const input = e.target as HTMLInputElement
  const file = input.files?.[0]
  input.value = ''
  if (file) await loadArchive(file)
}

/**
 * 载入存档：清空当前工作区后按顺序恢复。
 *
 * 顺序有讲究（每一步都依赖上一步）：
 * ① 清空 → ② 重建地形（Object3D + 回填旋转/镜像）→ ③ 回填烘焙参数
 * → ④ 恢复骨架 / 补线并渲染 → ⑤ 可选恢复 GS Module → ⑥ 回主流程并提示重新烘焙。
 *
 * 为什么提示而不是自动烘焙：navmesh 不入存档（既定取舍），而补线吸附与切块都依赖它，
 * 所以载入后处于"数据齐了、navmesh 还没有"的状态，需要用户点一次「应用并烘焙」。
 */
async function loadArchive(file: File) {
  const hasContent =
    terrainStore.count > 0 ||
    store.hasNavmesh ||
    lastSpineLines.length > 0 ||
    manualSpineLines.length > 0
  if (
    hasContent &&
    !window.confirm('载入存档会清空当前工作区（地形 / 参数 / 骨架 / 补线），确定继续？')
  ) {
    return
  }

  try {
    store.setError(null)
    store.setLoading(true, '载入存档…')
    const payload = await readArchive(new Uint8Array(await file.arrayBuffer()))

    // ① 先在内存里把"这份存档到底能不能恢复"验完：地形重建 + manifest 解析。
    //    ⚠️ 必须在动当前工作区**之前** —— 否则中途失败时，用户原来的现场已经清掉、
    //    而存档又没恢复成功，等于两头空。
    const rebuilt: Array<{ item: TerrainItem; data: ArchiveTerrainData }> = []
    for (const t of payload.terrains) {
      const item = await loadGLBFromBytes(t.bytes, t.name)
      if (!item) throw new Error(`地形重建失败：${t.name}`)
      rebuilt.push({ item, data: t })
    }
    let parsedManifest: ModulesManifest | null = null
    if (payload.gsModuleText) {
      const parsed = parseManifestText(payload.gsModuleText)
      if (!parsed.ok || !parsed.manifest) {
        throw new Error(parsed.error ?? 'GS Module manifest 解析失败')
      }
      parsedManifest = parsed.manifest
    }

    // ② 预检通过 → 现在才清空当前工作区并逐项落位
    clearWorkspace()

    // 地形：进场景 + 进 store，并回填用户调整过的旋转 / 镜像
    for (const { item, data } of rebuilt) {
      addObject(item.object3D)
      terrainStore.addTerrain(item)
      if (data.rotationDeg.some((v) => v !== 0)) {
        terrainStore.setTerrainRotation(item.id, data.rotationDeg)
      }
      if (data.flip.some(Boolean)) {
        terrainStore.setTerrainFlip(item.id, data.flip)
      }
    }

    // ③ 烘焙参数
    store.setParams({ ...payload.bakeParams })

    // ④ 骨架 / 补线：复用既有渲染入口，不另写一套；manualSpineCount 必须同步，
    //    否则「撤销 / 清除」按钮不会出现
    lastSpineLines = payload.spines
    lastSpineTreeEdges = payload.spineTreeEdges
    manualSpineLines = payload.spineGuides
    manualSpineCount.value = manualSpineLines.length
    // 记下这批脊线的有效性依据（参数 + 当时的地形指纹）：载入后若直接重烘焙且两者都未变，
    // 脊线应当保留（见 applyBake）。地形指纹必须在这批地形重建完之后取。
    restoredSpineContext = { params: { ...payload.bakeParams }, terrains: terrainFingerprint() }
    applySpineRendering()
    updateSpineInfo()

    // ⑤ GS Module（存档里有才恢复；解析已在预检阶段完成，这里只落位）
    if (parsedManifest) {
      const manifest = parsedManifest
      modulesStore.setManifest(manifest)
      await loadCollisionsFromManifest(manifest)
    }

    // ⑥ 把视角对准恢复出来的地形。
    // ⚠️ 这里**不切子流程**：bin / reach 的初始画面会隐藏脊线，而"刚恢复的骨架"正是
    // 用户此刻最想确认的东西；保持当前流程，让恢复结果如实呈现。
    store.setPickMode('off')
    const merged = terrainStore.mergedBox
    if (merged) focusBox(merged)
    flashSuccess(
      `存档已载入：地形 ${payload.terrains.length} 个 · 骨架 ${payload.spines.length} 段 · ` +
        `补线 ${payload.spineGuides.length} 段 · 请点击「应用并烘焙」重建 navmesh`
    )
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e)
    console.error('[archive] 载入失败', e)
    store.setError(`载入存档失败：${msg}`)
  } finally {
    store.setLoading(false)
  }
}

/**
 * 载入前的清空：比 `clearAll` 更宽 —— 连地形与 GS Module 一起清。
 *
 * 为什么不直接扩 `clearAll`：那个的语义是"清空编辑成果"（保留已加载的地形），
 * 而这里要换掉整个工作区，两件事不能混成一个函数。
 *
 * 移除地形沿用 `UploadPanel` 的配对规则：`removeObject`（出场景 + 释放 GPU）与
 * `removeTerrain`（出 store）必须成对，只做一半会让场景与数据失配。
 */
function clearWorkspace() {
  for (const t of [...terrainStore.terrains]) {
    removeObject(t.object3D)
    terrainStore.removeTerrain(t.id)
  }
  renderHandle?.clear()
  store.clearBakeResult()
  clearAll()
  modulesStore.clearAll()
}

/* ---------- 脊线渲染（唯一入口） ---------- */

/** 最近一次生成的脊线折线（未裁剪） */
let lastSpineLines: Float32Array[] = []

/** 渲染当前脊线（唯一入口）：自动骨架 + 手动补线 */
function applySpineRendering() {
  if (!renderHandle) return
  renderHandle.setCenterlines(lastSpineLines)
  renderHandle.setSpineGuides(manualSpineLines)
}

/* ---------- 手动补线：两点成段 + 吸附游离端点 ---------- */

/**
 * 手动补的脊线段（用户手绘）。
 *
 * 与 `lastSpineLines`（算法产物）**分开存**，原因有三：
 * ① 撤销/清除手动线不能碰到自动骨架；
 * ② 渲染用不同颜色（lime），让用户一眼分清"哪些是我画的"；
 * ③ 重新生成骨架会整体替换自动线，而手动线必须保留。
 */
let manualSpineLines: Float32Array[] = []

/** 手动补线段数的响应式镜像（模板条件渲染用；数据本身留在普通数组里，避免被抓成 Proxy） */
const manualSpineCount = ref(0)

/** 手动补线已选的第一个点（等待第二个点成段）；null = 未开始 */
const manualSpineAnchor = ref<{ x: number; y: number; z: number } | null>(null)

/** 自动骨架的生成树边数（回显到 SpineInfo 用） */
let lastSpineTreeEdges = 0

/** 骨架 + 手动补线：**切块**用的完整脊线 */
function spineLines(): Float32Array[] {
  return manualSpineLines.length > 0 ? [...lastSpineLines, ...manualSpineLines] : lastSpineLines
}

/** 同步脊线信息到 store（图例据此显示段数） */
function updateSpineInfo() {
  if (lastSpineLines.length === 0 && manualSpineLines.length === 0) {
    store.setSpineInfo(null)
    return
  }
  store.setSpineInfo({
    source: 'skeleton',
    segments: lastSpineLines.length,
    treeEdges: lastSpineTreeEdges,
    manualSegments: manualSpineLines.length
  })
}

/** 手动补线吸附半径（米）：断口通常很近，2.5m 够用且不会误吸远处端点 */
const SPINE_SNAP_RADIUS = 2.5

/**
 * 把点击点吸附到最近的「游离端点」。
 *
 * 游离端点 = 只被**一条**脊线段用到的端点（度 1）。骨架的断口两侧正是游离端点，
 * 所以吸附过去能保证两段**严格接上**（不留缝），而且顺带拿到**正确的高度 Y** ——
 * 点击落点是地表射线交点，高度可能与骨架端点不一致。
 *
 * @param maxDist XZ 平面上的吸附半径（米）
 */
function snapToFreeEndpoint(
  p: { x: number; y: number; z: number },
  maxDist: number
): { x: number; y: number; z: number } | null {
  const lines = spineLines()
  if (lines.length === 0) return null

  const EPS = 1e-3
  const keyOf = (x: number, y: number, z: number) =>
    `${Math.round(x / EPS)},${Math.round(y / EPS)},${Math.round(z / EPS)}`

  const used = new Map<string, number>()
  const points = new Map<string, { x: number; y: number; z: number }>()

  for (const line of lines) {
    const n = line.length / 3
    if (n < 2) continue
    for (const idx of [0, n - 1]) {
      const x = line[idx * 3]
      const y = line[idx * 3 + 1]
      const z = line[idx * 3 + 2]
      const k = keyOf(x, y, z)
      used.set(k, (used.get(k) ?? 0) + 1)
      if (!points.has(k)) points.set(k, { x, y, z })
    }
  }

  let best: { x: number; y: number; z: number } | null = null
  let bestD = maxDist
  for (const [k, count] of used) {
    if (count !== 1) continue
    const pt = points.get(k)
    if (!pt) continue
    const d = Math.hypot(pt.x - p.x, pt.z - p.z)
    if (d < bestD) {
      bestD = d
      best = pt
    }
  }
  return best
}

/**
 * 手动补线的一次点击：第 1 次记锚点，第 2 次成段。
 *
 * **不做"连续折线"**（第二次点击自动变成下一段起点）：两击一段行为确定、易撤销，
 * 不会出现"点歪一下就粘住"的困惑。要画折线连点几段即可。
 */
function handleSpinePick(point: { x: number; y: number; z: number }) {
  const snapped = snapToFreeEndpoint(point, SPINE_SNAP_RADIUS)
  const target = snapped ?? point
  const anchor = manualSpineAnchor.value

  if (!anchor) {
    manualSpineAnchor.value = target
    renderHandle?.setSpineAnchor(target)
    flashSuccess(
      `补线：已选第 1 点（${target.x.toFixed(2)}, ${target.y.toFixed(2)}, ${target.z.toFixed(2)}）` +
        `${snapped ? ' · 已吸附到骨架游离端点' : ''} —— 再点一下第 2 点连成一段`
    )
    return
  }

  manualSpineLines.push(
    new Float32Array([anchor.x, anchor.y, anchor.z, target.x, target.y, target.z])
  )
  manualSpineCount.value = manualSpineLines.length
  manualSpineAnchor.value = null
  renderHandle?.setSpineAnchor(null)

  // 脊线变了 → 旧切块过期，清掉（避免块与脊线错位）
  clearChunks()
  applySpineRendering()
  updateSpineInfo()

  flashSuccess(
    `补线：已补第 ${manualSpineLines.length} 段（脊线共 ${spineLines().length} 段）· ` +
      `「生成切块」会沿补线后的脊线布块`
  )
}

/** 撤销最后一段手动补线 */
function undoManualSpine() {
  if (manualSpineLines.length === 0) return
  manualSpineLines.pop()
  manualSpineCount.value = manualSpineLines.length
  manualSpineAnchor.value = null
  renderHandle?.setSpineAnchor(null)
  // 脊线变了 → 算法块失效；手工 / 载入的块保留（见 dropGeneratedChunks）
  dropGeneratedChunks()
  applySpineRendering()
  updateSpineInfo()
  flashSuccess(`补线：已撤销最后一段，剩余 ${manualSpineLines.length} 段手动补线`)
}

/** 清空全部手动补线（自动骨架不受影响） */
function clearManualSpine() {
  const n = manualSpineLines.length
  manualSpineLines = []
  manualSpineCount.value = 0
  manualSpineAnchor.value = null
  renderHandle?.setSpineAnchor(null)
  // 脊线变了 → 算法块失效；手工 / 载入的块保留（见 dropGeneratedChunks）
  dropGeneratedChunks()
  applySpineRendering()
  updateSpineInfo()
  flashSuccess(`补线：已清除 ${n} 段手动补线（自动骨架保留）`)
}

/** 清空手动补线的数据与渲染（重新烘焙 / 全清时调用） */
function resetManualSpine() {
  manualSpineLines = []
  manualSpineCount.value = 0
  manualSpineAnchor.value = null
  renderHandle?.setSpineGuides([])
  renderHandle?.setSpineAnchor(null)
}

/* ---------- 切块：生成 / 渲染 ---------- */

/**
 * 把 store 里的块渲染出来（唯一渲染入口）。
 *
 * 选中块按**下标**交给渲染层高亮：store 里存的是 id，换算放在这里 ——
 * 渲染层不认 id 语义（见 `setChunks` 的注释）。
 */
function renderChunks() {
  if (!renderHandle) return
  const items = store.chunkItems
  const selectedId = store.selectedChunkId
  const selectedIndex = selectedId ? items.findIndex((it) => it.id === selectedId) : -1
  renderHandle.setChunks(itemsToRenderChunks(items), selectedIndex)
}

/* ---------- 清单维度：第一次生成 / 新增块时选一次 ---------- */

/** 类型选择弹层是否打开 */
const kindPickerOpen = ref(false)

/** 选完类型后要继续的动作（用户点的是「生成切块」还是「新增块」） */
let kindPickThen: (() => void) | null = null

/**
 * 类型前置：确保"这份清单的维度"已确定，再执行 `then`。
 *
 * 两种情况都不问：
 * - 维度已定（本会话第一次生成 / 新增时选过）
 * - 手里已有块（照抄已有块的字段名单即可，用户零操作）
 *
 * 只有"一个块都没有、也不知道维度"时才弹一次 —— 此时没有任何可跟随的数据。
 * 这么做是因为维度是**整份清单**的属性（混两种类型下游会拒），不该做成逐块的选择。
 */
function requireKind(then: () => void) {
  if (store.chunkKind || store.chunkItems.length > 0) {
    then()
    return
  }
  kindPickThen = then
  kindPickerOpen.value = true
}

/** 弹层选定维度：记下来，并把刚才中断的动作接上 */
function onKindPicked(k: ChunkKind) {
  store.setChunkKind(k)
  kindPickerOpen.value = false
  const next = kindPickThen
  kindPickThen = null
  next?.()
}

/** 「应用并生成切块」入口：缺维度时先问一次，再走原来的切块流程 */
function onApplyChunking() {
  requireKind(applyChunking)
}

/**
 * 「新增块」按钮：直接在**选中块的位置**放一块；没选中就放在原点。
 *
 * ## 为什么不再走"点场景放块"的拾取模式
 *
 * - 那个模式下按钮会一直亮着激活态，看着像状态卡住了；而放一块要点两次
 *   （先点按钮、再点场景），常见诉求却是"照着这块再摆一块""连点几下补几块"。
 * - 现在一次点击就是一块，连点即连增。
 *
 * 新增的块会被自动选中，所以连点时后续几块都落在同一位置 —— 有意为之：
 * 需要并排就从同一位置拖开，比每次重新瞄准落点更可控、也不会手抖放偏。
 */
function onAddChunkClick() {
  const p = store.selectedChunk?.shape.transform.position
  const point = p ? { x: p[0], y: p[1], z: p[2] } : { x: 0, y: 0, z: 0 }
  requireKind(() => addChunkAt(point))
}

/** 工具栏的类型指示：跟着这份清单的维度走 */
const kindLabel = computed(() =>
  store.chunkKind ? CHUNK_KIND_LABELS[store.chunkKind] : '类型未识别'
)
const kindHint = computed(() =>
  store.chunkKind
    ? `这份清单的维度是 ${store.chunkKind}：生成 / 新增的块都用它的字段名单（一份清单只能有一个维度，不在这里改）`
    : '没能从字段里认出这份清单的维度（collision 与 terrain 只靠 url 区分不了，资源扩展名也不典型）：点这里指定一次，属性面板就会列出该维度还没配的字段'
)

/**
 * 点类型指示：只有"未识别"时才打开补选层。
 *
 * 已确定维度时不给改 —— 一份清单只能有一个维度，已有块之后换维度会让块的字段与新契约
 * 直接矛盾（下游 `.strict()` 拒）。要换就清空块重来。
 */
function onKindTagClick() {
  if (store.chunkKind) return
  kindPickerOpen.value = true
}

/** 切块参数面板「应用并生成切块」入口 */
function applyChunking() {
  if (!renderHandle) return
  if (lastSpineLines.length === 0 && manualSpineLines.length === 0) {
    flashSuccess('请先生成骨架（或用「补线」手动画线）—— 切块沿脊线布置，没有脊线无法布块')
    return
  }

  const r = generateChunks(store.polygons, spineLines(), { ...store.chunkParams })

  // 新建块统一套「清单维度的字段名单」（见 utils/chunkTemplate）：空 asset 导出的块只有
  // { id, shape }，对 collision / terrain 这类 url 必填的维度会被下游 zod 拒绝
  const skeleton = resolveSkeleton(store.chunkKind, store.chunkItems, store.selectedChunkId)

  // 重算只刷新「算法生成的块」：载入的与手工调整过的块是用户的劳动成果，原样保留
  // （否则调一次参数就把摆好的块冲掉）
  const kept = store.chunkItems.filter((it) => it.origin !== 'generated')
  const items: ChunkItem[] = [...kept]
  for (let i = 0; i < r.chunks.length; i++) {
    const item = chunkToItem(r.chunks[i], `chunk_${i + 1}`, 'generated')
    // 生成块的默认 id 可能与保留块重名，逐个避开
    if (items.some((it) => it.id === item.id)) item.id = nextChunkId(items)
    // 每个块拿独立副本：骨架里的嵌套对象不能跨块共享引用，否则改一块会连带改到所有块
    item.asset = structuredClone(skeleton)
    items.push(item)
  }

  store.setChunkItems(items)
  // 算法生成的结果不是从文件来的，清掉上一次载入的文件名（避免"显示着 A 文件、内容却是生成块"）
  store.setChunkSourceName(null)
  renderChunks()
  // 生成块的几何/尺寸都变了，手柄必须跟着挪 —— 否则它会停在上一次的旧位置上
  syncGizmo()
  // 参数已生效：收起弹层，让用户立刻看到场景里的结果（要用可再点开）
  chunkPanelOpen.value = false
  store.setChunkStats({
    total: r.chunks.length,
    coverageBefore: r.coverageBefore,
    fillCount: r.fillCount,
    uncoveredFinal: r.uncoveredFinal,
    redundantSkipped: r.redundantSkipped,
    chainCount: r.chainCount,
    elapsedMs: r.elapsedMs
  })

  if (r.chunks.length === 0) {
    flashSuccess('切块：未生成任何块（脊线为空？）')
    return
  }
  const spineCount = r.chunks.length - r.fillCount
  flashSuccess(
    `切块：${r.chunks.length} 块（骨架 ${spineCount} + 补块 ${r.fillCount}）· ` +
      `骨架覆盖率 ${(r.coverageBefore * 100).toFixed(1)}% · ` +
      `脊线串成 ${r.chainCount} 条链 · 抑制冗余 ${r.redundantSkipped} 块 · ` +
      `间距 = 块边长 × stepRatio(${store.chunkParams.stepRatio.toFixed(2)}) · ` +
      `未覆盖残留 ${r.uncoveredFinal} 格（${r.elapsedMs.toFixed(0)}ms）` +
      (kept.length > 0 ? ` · 已保留 ${kept.length} 个手工 / 载入的块` : '')
  )
}

/* ---------- 连通骨架（拓扑图）：保证不断 ---------- */

/**
 * 生成**连通骨架**：poly 邻接图 → 生成树 → 共享边中点。
 *
 * 与 Voronoi 中轴的区别：中轴是几何量（楼梯/空旷区必断），骨架走拓扑图（**不可能断**）。
 * 生成后它即成为脊线 —— 渲染它，且「生成切块」会沿它布块。
 */
function generateSkeleton() {
  if (!renderHandle || !store.navMeshRef) return

  const r = buildGraphSkeleton(store.navMeshRef, store.polygons)
  if (r.lines.length === 0) {
    flashSuccess('生成骨架：未生成任何骨架段（navmesh 为空？）')
    return
  }

  lastSpineLines = r.lines
  lastSpineTreeEdges = r.edgeCount
  // 新生成的骨架不属于"存档恢复"那一份，快照作废
  restoredSpineContext = null
  // 脊线换了一批 → 沿旧脊线布出的块失效；手工补线 / 手工块 / 载入的块都是用户的东西，保留
  // （与 applyBake / applyChunking 同一条规则，见 dropGeneratedChunks）
  const dropped = dropGeneratedChunks()
  applySpineRendering()
  updateSpineInfo()

  const manualNote =
    manualSpineLines.length > 0 ? ` · 已保留 ${manualSpineLines.length} 段手动补线` : ''
  const keptNote =
    dropped > 0 && store.chunkItems.length > 0
      ? ` · 已保留 ${store.chunkItems.length} 个手工 / 载入的块（清掉 ${dropped} 个算法生成的块）`
      : ''
  flashSuccess(
    `已生成连通骨架（拓扑图）：${r.lines.length} 段 / 树边 ${r.edgeCount} · ` +
      `覆盖 ${r.polyCount} polys · 连通分量 ${r.componentCount} · ` +
      `门（共享边中点）${r.edgeCount - r.fallbackEdges}/${r.edgeCount}` +
      (r.fallbackEdges > 0 ? `（${r.fallbackEdges} 个门退回质心中点）` : '') +
      `${manualNote}${keptNote}（${r.elapsedMs.toFixed(0)}ms）。骨架由 poly 邻接图生成，枢纽在「门」上。`
  )
}

/** 清除全部块（含选中与统计），并收起拖动手柄 */
function clearChunks() {
  store.clearChunkItems()
  chunkGizmo.setTarget(null)
  if (renderHandle) renderHandle.setChunks([])
}

/**
 * 「重置切块」按钮：清空全部块，回到"还没切块"的状态。
 *
 * ## 为什么叫"重置"而不是"清除"
 *
 * 它清掉的不是垃圾 —— 切块随时能沿脊线重新生成，清掉后是回到可重算的起点，而不是
 * 丢了一堆需要抢救的东西。名字与"清除"（工作区那种清空编辑成果）区分开，用户才敢点。
 *
 * ## 为什么仍然要二次确认
 *
 * 因为它一次清掉的是**全部**块，其中手工调整过的与从文件载入的**不是算法能重算出来的**
 * —— 那两类误删一次就真没了。确认文案里报出总数与这两类的数量，用户才知道将要失去什么。
 */
function onResetChunks() {
  const items = store.chunkItems
  if (items.length === 0) return
  const edited = items.filter((it) => it.origin !== 'generated').length
  const generated = items.length - edited
  const ok = window.confirm(
    `重置切块会清空全部 ${items.length} 个块（算法生成 ${generated} 个` +
      (edited > 0 ? ` · 手工调整 / 文件载入 ${edited} 个，清掉后无法恢复` : '') +
      '）。切块可以再沿脊线重新生成。继续？'
  )
  if (!ok) return
  clearChunks()
  flashSuccess(`已重置切块：清空 ${items.length} 个块`)
}

/**
 * 重新烘焙后丢弃「算法生成的块」，保留手工调整 / 文件载入的块，返回被清掉的块数。
 *
 * ## 为什么不是全清（原先就是全清，用户反馈"重新烘焙后原有地块丢失"）
 *
 * 依赖链是 `烘焙 → 骨架 → 切块`，**只有 `generated` 块**的位置依据来自那条链 ——
 * navmesh 一换、脊线就重生成，旧脊线布出来的块落在哪儿已经没有意义。
 *
 * 而 `manual`（手工改过 / 新增）与 `loaded`（从文件载入的清单）与 navmesh 没有关系：
 * 前者是用户摆出来的，后者是数据文件本身的内容。把它们一起清掉是把用户的劳动成果
 * 连带删了。这与「应用并生成切块」的保留策略也是同一条规则
 * （见 `applyChunking`：`kept = chunkItems.filter(it => it.origin !== 'generated')`）。
 */
function dropGeneratedChunks(): number {
  const generated = store.chunkItems.filter((it) => it.origin === 'generated')
  if (generated.length === 0) return 0
  const kept = store.chunkItems.filter((it) => it.origin !== 'generated')
  if (kept.length === 0) {
    clearChunks() // 全清：顺带清掉块统计与来源文件名
  } else {
    store.setChunkItems(kept)
    // 统计描述的是"上一次生成切块的结果"，navmesh 已换 → 留着会误导
    store.setChunkStats(null)
    renderChunks()
    syncGizmo()
  }
  return generated.length
}

/* ---------- chunk：载入 / 导出 ---------- */

/** chunk 文件选择框（模板内的隐藏 input） */
const chunkInputRef = ref<HTMLInputElement | null>(null)

function openChunkFile() {
  chunkInputRef.value?.click()
}

/**
 * 载入 chunk 文件：自动识别运行时清单 / 内联清单 / 编辑器格式三种形态。
 *
 * 载入是**整批替换**而不是合并：文件代表一份完整清单，合并会立刻带来
 * "两份清单的块混在一起"的语义问题（id 冲突、谁覆盖谁都不明确）。
 */
async function onChunkFileChange(e: Event) {
  const input = e.target as HTMLInputElement
  const file = input.files?.[0]
  input.value = ''
  if (!file) return
  try {
    store.setError(null)
    store.setLoading(true, '载入 chunk…')
    const parsed = parseChunkText(await file.text())
    store.setChunkManifestExtra({
      baseUrl: parsed.baseUrl,
      transform: parsed.transform,
      loadConfig: parsed.loadConfig
    })
    store.setChunkItems(parsed.items)
    // 记下来源文件名：工具栏会显示它，用户才知道当前这份块数据出自哪个文件
    store.setChunkSourceName(file.name)
    // 反推这份清单的维度：载入的清单没有维度标记，只能按字段特征认。认不出就是 null ——
    // 属性面板随之退化为"只展示块数据里已有的字段"（比按错误的契约列字段安全），
    // 工具栏的类型指示会变成可点的「类型未识别」，让用户补选一次。
    const guessed = parsed.items.length > 0 ? guessKind(parsed.items[0].asset) : null
    store.setChunkKind(guessed)
    renderChunks()
    // 载入的块若与当前选中同名，选中会被保留 —— 手柄也要跟着换到新块上
    syncGizmo()
    // 载入的块不是算法产物，覆盖率统计对它没有意义
    store.setChunkStats(null)
    if (parsed.warnings.length > 0) console.warn('[chunk] 载入提示', parsed.warnings)
    flashSuccess(
      `已载入 ${CHUNK_FORMAT_LABELS[parsed.format]}：${parsed.items.length} 块 · 类型 ` +
        (guessed ? CHUNK_KIND_LABELS[guessed] : '未识别（可点工具栏类型处指定）') +
        (parsed.warnings.length > 0 ? ` · ${parsed.warnings.length} 条提示（见控制台）` : '')
    )
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err)
    console.error('[chunk] 载入失败', err)
    store.setError(`载入 chunk 失败：${msg}`)
  } finally {
    store.setLoading(false)
  }
}

/**
 * 导出运行时可直接消费的清单：`{ baseUrl?, modules: [{ id, ...维度字段, shape }] }`。
 *
 * 体检结果**只提示不阻断**：编辑器不知道当前是哪个维度，而各维度对 url 的要求不同
 * （light 的 url 可选、collision 必填），硬拦会把合法场景也拦掉。
 */
function exportChunks() {
  const items = store.chunkItems
  if (items.length === 0) {
    store.setError('没有可导出的块：请先生成切块，或载入一份 chunk 文件')
    return
  }
  const problems = validateChunkItemsForExport(items)
  const manifest = buildChunkManifest(items, store.chunkManifestExtra)
  triggerDownload(
    new Blob([JSON.stringify(manifest, null, 2)], { type: 'application/json' }),
    `chunk-manifest-${archiveStamp()}.json`
  )
  if (problems.length > 0) {
    console.warn('[chunk] 导出体检', problems)
    store.setError(`chunk 已导出，但有 ${problems.length} 处需确认：${problems.join('；')}`)
  } else {
    store.setError(null)
    flashSuccess(`chunk 已导出：${items.length} 块（运行时可直接消费的清单）`)
  }
}

/* ---------- chunk：单块新增 / 选中 / 拖动 ---------- */

/** 拖动模式（平移 / 绕 Y 旋转 / 缩放） */
const gizmoMode = ref<ChunkGizmoMode>('translate')

/** 拖动模式按钮（工具栏渲染用；只影响选中块） */
const GIZMO_MODES: Array<{ key: ChunkGizmoMode; label: string; icon: unknown; hint: string }> =
  [
    { key: 'translate', label: '平移', icon: Move, hint: '拖动平移（X / Y / Z）' },
    { key: 'rotate', label: '旋转', icon: RotateCw, hint: '绕 X / Y / Z 任意轴旋转块' },
    {
      key: 'scale',
      label: '缩放',
      icon: Maximize2,
      hint: '缩放边长与高度（XZ 同步，保持正方形）'
    }
  ]

/** 把选中块同步到拖动手柄；未选中或不在 chunk 流程时收起 */
function syncGizmo() {
  const it = store.selectedChunk
  if (!it || store.subFlow !== 'chunk') {
    chunkGizmo.setTarget(null)
    return
  }
  const rc = itemToRenderChunk(it)
  chunkGizmo.setTarget(
    {
      center: rc.center,
      size: rc.size,
      height: rc.height,
      // RenderChunk 的 rotation 已是 Three 手性、与 gizmo 同约定 → 直接透传，不再转
      rotation: { x: rc.rotation[0], y: rc.rotation[1], z: rc.rotation[2] }
    },
    gizmoMode.value
  )
}

/** 把拖动结果写回块（位置 / 尺寸 / 朝向） */
function applyGizmoPatch(item: ChunkItem, p: ChunkGizmoPatch): ChunkItem {
  return {
    ...item,
    // 手工动过 → 不再是"可重算的产物"，重新生成切块时必须保留
    origin: item.origin === 'generated' ? 'manual' : item.origin,
    shape: {
      ...item.shape,
      // 拖动产生的是浮点长串，统一取整到厘米级（见 roundCm 的说明）
      width: roundCm(p.size),
      depth: roundCm(p.size),
      height: roundCm(p.height),
      transform: {
        ...item.shape.transform,
        position: [roundCm(p.center.x), roundCm(p.center.y), roundCm(p.center.z)],
        // 弧度 → 角度落库；Y 再取负回到编辑器手性（手性转换只在进出数据的两个边界做，
        // 另一个边界是 itemToRenderChunk）
        rotation: [
          roundCm((p.rotation.x * 180) / Math.PI),
          roundCm((-p.rotation.y * 180) / Math.PI),
          roundCm((p.rotation.z * 180) / Math.PI)
        ]
      }
    }
  }
}

/** 拖动中：只重绘 3D（不写 store），避免每帧触发响应式与面板重渲染 */
function previewGizmoDrag(patch: ChunkGizmoPatch) {
  const it = store.selectedChunk
  if (!it || !renderHandle) return
  const items = store.chunkItems.map((x) => (x.id === it.id ? applyGizmoPatch(x, patch) : x))
  renderHandle.setChunks(
    itemsToRenderChunks(items),
    items.findIndex((x) => x.id === it.id)
  )
}

/** 拖动结束：写回 store 并刷新手柄 */
function commitGizmoDrag(patch: ChunkGizmoPatch) {
  const it = store.selectedChunk
  if (!it) return
  store.upsertChunkItem(applyGizmoPatch(it, patch))
  renderChunks()
  syncGizmo()
}

chunkGizmo.onDrag(previewGizmoDrag)
chunkGizmo.onCommit(commitGizmoDrag)

/** 右侧面板改完块数据：重绘 + 同步手柄 */
function onChunkItemChanged() {
  renderChunks()
  syncGizmo()
}

/** 工具栏的地块列表选中了某块：与"场景点选"走同一套联动（高亮 + 面板 + 手柄） */
function onChunkPicked() {
  renderChunks()
  syncGizmo()
}

/* ---------- 地块名字标签 ---------- */

/** 显示名字开关（工具栏 checkbox，v-model 用） */
const showChunkLabels = computed({
  get: () => store.chunkLabelsVisible,
  set: (v: boolean) => store.setChunkLabelsVisible(v)
})

/**
 * 标签是否真的在显示。
 *
 * 除了勾选开关，还要求当前在 chunk 子流程 —— 块本身只在那个流程里可见，
 * 否则切走后屏幕上会剩下一堆漂浮的名字，指向看不见的块。
 */
const chunkLabelsOn = computed(() => showChunkLabels.value && store.subFlow === 'chunk')

/**
 * 标签 DOM 表：块 id → 元素。
 *
 * 为什么手管 DOM 而不是做成响应式数组：标签要**每帧**跟着相机更新位置，走响应式意味着
 * 每秒几十次 Vue 补丁 —— 几百个标签下会明显掉帧。这里让 `v-for` 只负责"有哪些标签"
 * （随块列表变化，低频），位置一律直接写 `style.transform`。
 */
const labelEls = new Map<string, HTMLElement>()

function setLabelRef(id: string, el: unknown) {
  if (el) labelEls.set(id, el as HTMLElement)
  else labelEls.delete(id)
}

/**
 * 每帧定位标签（由 `onAfterRender` 在渲染循环内调用）。
 *
 * 锚点取**块顶面中心**而不是几何中心：块是半透明的，名字压在块中间会和棱边糊在一起，
 * 抬到顶面之上更接近"标注"的读法。
 */
function layoutChunkLabels() {
  if (!chunkLabelsOn.value) return
  for (const it of store.chunkItems) {
    const el = labelEls.get(it.id)
    if (!el) continue
    const rc = itemToRenderChunk(it)
    const s = project({ x: rc.center.x, y: rc.center.y + rc.height / 2, z: rc.center.z })
    // behind：投影点落在相机背后，坐标是镜像值，不隐藏会跑到屏幕另一侧
    if (!s || s.behind) {
      el.style.display = 'none'
      continue
    }
    el.style.display = ''
    el.style.transform = `translate(${s.x}px, ${s.y}px) translate(-50%, -100%)`
  }
}

// 注册进渲染循环：位置必须与刚渲染的那一帧同帧算，否则相机一动标签就"漂"在后面
onAfterRender(layoutChunkLabels)

/** 相机飞到选中块（工具栏「定位」）：块小或离得远时，靠 WASD 挪过去太费事 */
function focusSelectedChunk() {
  const it = store.selectedChunk
  if (!it) return
  const aabb = chunkAABB(itemToRenderChunk(it))
  focusBox(
    new Box3(
      new Vector3(aabb.min.x, aabb.min.y, aabb.min.z),
      new Vector3(aabb.max.x, aabb.max.y, aabb.max.z)
    ),
    true
  )
}

/**
 * 删除指定块 —— 右栏面板的「删除」按钮与键盘 Delete 共用这一条路，
 * 保证两者行为一致（都有确认、都重绘、都收起手柄）。
 *
 * 为什么加二次确认：删除不可撤销，而块在场景里是密集重叠的，误点的概率不低；
 * 键盘 Delete / Backspace 更容易误触（想删输入框里的字却删了块）。
 * 确认放在这一层而不是面板内，是为了让键盘入口一并覆盖 —— 键盘不经过面板按钮。
 */
function removeChunkById(id: string) {
  // 键盘入口可能在选中已消失后才触发，先确认块还在，避免弹一个空确认
  if (!store.chunkItems.some((c) => c.id === id)) return
  const ok = window.confirm(`删除块 ${id}？该操作不可撤销。`)
  if (!ok) return
  store.removeChunkItem(id)
  renderChunks()
  syncGizmo()
  flashSuccess(`已删除块 ${id}`)
}

/**
 * 在地形上放一个新块。
 *
 * 默认尺寸取参数面板的固定尺寸；自适应模式用一个中庸值（夹在 min / max 之间）——
 * 目标不是"刚好"的块，而是**可继续调整的起点**：放下即可选中、改数值、拖动。
 */
function addChunkAt(point: { x: number; y: number; z: number }) {
  const p = store.chunkParams
  const size =
    p.sizeMode === 'fixed' ? p.fixedSize : Math.min(p.maxSize, Math.max(p.minSize, 4))
  const item: ChunkItem = {
    id: nextChunkId(store.chunkItems),
    shape: {
      type: 'box',
      width: size,
      height: p.boxHeight,
      depth: size,
      transform: {
        position: [point.x, point.y, point.z],
        rotation: [0, 0, 0],
        scale: [1, 1, 1]
      }
    },
    // 字段模板：跟随已有块（照抄键名、值清空）或工具栏指定的维度骨架
    asset: structuredClone(
      resolveSkeleton(store.chunkKind, store.chunkItems, store.selectedChunkId)
    ),
    origin: 'manual',
    source: null
  }
  store.setChunkItems([...store.chunkItems, item])
  store.selectChunk(item.id)
  renderChunks()
  syncGizmo()
  const fieldCount = Object.keys(item.asset).length
  flashSuccess(
    `已新增块 ${item.id}（边长 ${size.toFixed(1)}m，${fieldCount} 个字段）—— 右侧改数值，或直接拖动`
  )
}

/**
 * 场景点击的叠加物优先拾取：命中块 → 选中；点空白 → 取消选中。
 *
 * 返回 true 表示本次点击已被消费。为什么"点块"要优先于"点地面"：块浮在地表上方，
 * 用户点它显然是想选它；若先做地表拾取，块就永远选不中。
 */
function onPickOverlay(ray: {
  origin: { x: number; y: number; z: number }
  dir: { x: number; y: number; z: number }
}): boolean {
  // 只有 chunk 子流程接管点击：别的流程里点场景不该选中块
  if (store.subFlow !== 'chunk') return false
  const items = store.chunkItems
  const idx = pickChunkIndex(itemsToRenderChunks(items), ray.origin, ray.dir)
  if (idx < 0) {
    if (store.selectedChunkId) {
      store.selectChunk(null)
      renderChunks()
      syncGizmo()
    }
    // 没命中块就不消费：仍要允许地表拾取（放新块 / 补线）
    return false
  }
  store.selectChunk(items[idx].id)
  renderChunks()
  syncGizmo()
  return true
}

/**
 * 点击没落到地面（天空 / 场景外）时的兜底：收起选中与坐标轴。
 *
 * 为什么需要单独一条路：`onPickOverlay` 在放块模式下会主动让路（见那里的注释），
 * 于是"点空白"就没人处理了 —— 选中与手柄会一直挂在那儿，点什么都没反应。
 */
function onPickMiss() {
  if (!store.selectedChunkId) return
  store.selectChunk(null)
  renderChunks()
  syncGizmo()
}

// 选中项 / 拖动模式变化都要重同步手柄
watch(
  () => store.selectedChunkId,
  () => syncGizmo()
)
watch(gizmoMode, () => syncGizmo())

/* ---------- 导出：带 reachableNeighbors 的 manifest ---------- */
