  try {
    store.setError(null)
    downloadNavmeshAnnotatedManifestJson()
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e)
    console.error('[navmesh] export failed', e)
    store.setError(`导出失败：${msg}`)
  }
}

/* ---------- 导出：Detour navmesh 导航数据（.bin） ---------- */

/** 导出结果提示（自动消失）。.bin 肉眼不可检查，故把自校验结果显式回显。 */
const successMsg = ref('')
let successTimer: ReturnType<typeof setTimeout> | null = null

function flashSuccess(msg: string) {
  successMsg.value = msg
  if (successTimer) clearTimeout(successTimer)
  successTimer = setTimeout(() => {
    successMsg.value = ''
  }, 5000)
}

function exportNavmeshBin() {
  if (!store.navMeshRef) return
  store.setError(null)
  try {
    const result = exportNavmeshData(store.navMeshRef)
    const kb = (result.bytes / 1024).toFixed(1)
    const verifyText = result.verified
      ? `自校验通过（反序列化得 ${result.polyCount} polys）`
      : '⚠ 自校验未通过：反序列化失败或未读到 polygon'
    flashSuccess(`已导出导航数据：${store.polygons.length} polys / ${kb} KB · ${verifyText}`)
    console.info(
      `[navmesh] export bin ok: ${store.polygons.length} polys, ${result.bytes} bytes, verified=${result.verified}(${result.polyCount} polys)`
    )
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e)
    console.error('[navmesh] export bin failed', e)
    store.setError(`导出导航数据失败：${msg}`)
  }
}

