/* ---------- 派生展示态 ---------- */
const hasGeometry = computed(() => terrainStore.terrains.length > 0)
const showEmpty = computed(() => !hasGeometry.value && !store.hasNavmesh)

/* ---------- 可拖拽列宽（左：主流程区 / 右：属性面板） ---------- */

/**
 * 拖拽目标。左右两侧各有一条分隔条，用同一个状态机驱动 —— 避免两份重复的
 * addEventListener / localStorage 逻辑（它们最容易改一边忘一边）。
 */
type DragTarget = 'left' | 'right'

/**
 * localStorage key。
 *
 * 左侧沿用旧 key（`gtm.navmesh.sidebar.width`）：界面重构前用户已经调好的宽度不该被重置。
 * 右侧是新增列，用新 key。
 */
const LEFT_WIDTH_KEY = 'gtm.navmesh.sidebar.width'
const RIGHT_WIDTH_KEY = 'gtm.navmesh.property.width'

const LEFT_MIN_W = 280
const LEFT_MAX_W = 480
const LEFT_DEFAULT_W = 320
const RIGHT_MIN_W = 240
const RIGHT_MAX_W = 520
const RIGHT_DEFAULT_W = 300

const leftWidth = ref<number>(loadWidth(LEFT_WIDTH_KEY, LEFT_DEFAULT_W, LEFT_MIN_W, LEFT_MAX_W))
const rightWidth = ref<number>(
  loadWidth(RIGHT_WIDTH_KEY, RIGHT_DEFAULT_W, RIGHT_MIN_W, RIGHT_MAX_W)
)

/**
 * 正在拖拽的目标；`null` = 未拖拽。
 *
 * 直接把目标存进 ref，而不是"一个 boolean + 一个局部变量"：模板要用它决定哪条分隔条
 * 高亮（`:active="dragging === 'left'"`），顺带也充当"是否正在拖拽"的判据，少一份状态。
 */
const dragging = ref<DragTarget | null>(null)

/**
 * 拖拽起点快照：按下时的鼠标 X 与当时的宽度。
 *
 * ## 为什么按"位移量"换算，而不是按"鼠标绝对坐标 → 宽度"
 *
 * 分隔条本身有宽度（8px）且与两侧留 gap，所以鼠标按下的位置**并不等于**容器边界：
 * 若直接用 `clientX - 容器左边界` 当宽度，mousedown 瞬间宽度就会**凭空跳变**（左列 -8px、
 * 右列 +8px），拖起来会有"一碰就窜"的突兀感。
 * 记录起点后只累加位移量，则"鼠标移动多少、边界就移动多少"，手感一致且无需读 DOM 尺寸。
 */
let dragOriginX = 0
let dragOriginW = 0

function loadWidth(key: string, def: number, min: number, max: number): number {
  const raw = localStorage.getItem(key)
  const n = raw ? Number(raw) : NaN
  if (!Number.isFinite(n)) return def
  return Math.min(max, Math.max(min, n))
}

function onDragMove(e: MouseEvent) {
  const target = dragging.value
  if (!target) return
  const dx = e.clientX - dragOriginX
  if (target === 'left') {
    leftWidth.value = Math.min(LEFT_MAX_W, Math.max(LEFT_MIN_W, dragOriginW + dx))
    return
  }
  // 右列在容器右侧：鼠标往左拖（dx < 0）应当变宽，故取负
  rightWidth.value = Math.min(RIGHT_MAX_W, Math.max(RIGHT_MIN_W, dragOriginW - dx))
}

function endDrag() {
  const target = dragging.value
  if (!target) return
  dragging.value = null
  document.body.style.cursor = ''
  document.body.style.userSelect = ''
  window.removeEventListener('mousemove', onDragMove)
  window.removeEventListener('mouseup', endDrag)
  try {
    if (target === 'left')
      localStorage.setItem(LEFT_WIDTH_KEY, String(Math.round(leftWidth.value)))
    else localStorage.setItem(RIGHT_WIDTH_KEY, String(Math.round(rightWidth.value)))
  } catch {
    /* ignore */
  }
}

function startDrag(target: DragTarget, e: MouseEvent) {
  e.preventDefault()
  dragging.value = target
  dragOriginX = e.clientX
  dragOriginW = target === 'left' ? leftWidth.value : rightWidth.value
  document.body.style.cursor = 'col-resize'
  document.body.style.userSelect = 'none'
  window.addEventListener('mousemove', onDragMove)
  window.addEventListener('mouseup', endDrag)
}

/* ---------- 子流程：工具栏参数弹层 ---------- */

/**
 * chunk 参数弹层是否展开。
 *
 * 参数面板（尺寸 / 位置 / 朝向 / 覆盖率回显）体积大、压不进工具栏横条，故以弹出卡片承载；
 * 切换子流程时收起（见下方 watch），避免悬在别的流程上。
 */
const chunkPanelOpen = ref(false)

/**
 * GS Module（manifest）弹层是否展开。
 *
 * 为什么也放工具栏而不是左栏：manifest 是**可达区子流程**的数据输入（导出时要标注
 * 可达 / 不可达 module），主流程的「导入 GLB → 烘焙 → 生成中线」并不需要它。
 * 与 chunk 的切块参数同理：切到哪个子流程，才出现那个子流程要用的东西。
 */
const manifestPanelOpen = ref(false)

/* ---------- 子流程：图像附加物可见性 ---------- */

/**
 * 每个子流程**默认可见**的图像附加物。
 *
 * | 流程 | 脊线 | 补线 | 切块 | 说明 |
 * |---|---|---|---|---|
 * | 导出 bin | ❌ | ❌ | ❌ | 只看 navmesh，画面最干净 |
 * | 可达区 | ❌ | ❌ | ❌ | 只看 navmesh + 可达染色 + 路径 |
 * | chunk | ✅ | ✅ | ✅ | 必须看得到脊线与块，否则无法编辑 |
 *
 * ⚠️ 这张表只在**用户主动切子流程**时生效（`watch(subFlow)`）。左栏主流程里生成骨架 /
 * 补线、或载入存档恢复成果时都会直接渲染，不受此表影响 —— 否则"刚生成的东西看不见"。
 *
 * ## 为什么 chunk 流程不"全隐藏"
 *
 * 用户诉求是"切换子流程时隐藏查看区附加物"。但若做成**持久抑制**，
 * 在 chunk 流程里点「生成切块」将看不到块，功能直接不可用。
 * 因此这里把"隐藏"定义为**切换动作发生时按目标流程的表重放渲染**——
 * 是"初始画面"而不是"永久屏蔽"；切换之后的操作照常渲染。
 */
const SUBFLOW_OVERLAYS: Record<SubFlow, { spine: boolean; guides: boolean; chunks: boolean }> =
  {
    bin: { spine: false, guides: false, chunks: false },
    reach: { spine: false, guides: false, chunks: false },
    chunk: { spine: true, guides: true, chunks: true }
  }

/**
 * 按目标子流程重放图像附加物的渲染。
 *
 * 关键：**只重放渲染，不清数据、不重算**。数据源（`lastSpineLines` /
 * `manualSpineLines` / `store.chunkItems`）始终保留，因此切回主流程只是把既有成果
 * 重新画出来，不会丢失、也不需要重跑算法。
 */
function applyOverlayVisibility(flow: SubFlow) {
  if (!renderHandle) return
  const vis = SUBFLOW_OVERLAYS[flow]

  renderHandle.setCenterlines(vis.spine ? lastSpineLines : [])
  renderHandle.setSpineGuides(vis.guides ? manualSpineLines : [])
  // 走 renderChunks 而不是直接 setChunks：它同时负责选中高亮的下标换算
  if (vis.chunks) renderChunks()
  else renderHandle.setChunks([])
}

/**
 * 子流程切换副作用。
 *
 * 除了重放附加物，还要**取消进行中的拾取模式**：各拾取模式归属不同子流程
 * （起点/终点属可达区、补线属主流程），若不取消，切到别的流程后点击画布
 * 仍会触发上一个流程的拾取，行为难以预期。
 */
watch(
  () => store.subFlow,
  (flow) => {
    if (store.pickMode !== 'off') store.setPickMode('off')
    applyOverlayVisibility(flow)
    // 两个弹层各归属自己的子流程：切走后必须收起，否则会悬在别的流程上
    chunkPanelOpen.value = false
    manifestPanelOpen.value = false
    // 拖动手柄同样只在 chunk 流程出现（切走时收起）
    syncGizmo()
  }
)
</script>

