          <!-- 顶部错误 banner -->
          <div
            v-if="store.error"
            class="absolute top-2 left-2 right-2 flex items-start gap-2 px-3 py-2 rounded-md bg-red-500/15 border border-red-400/40 text-[11px] text-red-200 backdrop-blur-glass animate-fade-in"
          >
            <AlertCircle class="w-3.5 h-3.5 mt-0.5 shrink-0" />
            <div class="flex-1 break-words">{{ store.error }}</div>
            <button
              type="button"
              class="shrink-0 hover:text-white cursor-pointer"
              @click="store.setError(null)"
            >
              <X class="w-3.5 h-3.5" />
            </button>
          </div>

          <!-- 导出结果提示条（自校验回显，5s 自动消失）；top-14 避让 error banner -->
          <div
            v-if="successMsg"
            class="absolute top-14 left-2 right-2 flex items-start gap-2 px-3 py-2 rounded-md bg-emerald-500/15 border border-emerald-400/40 text-[11px] text-emerald-200 backdrop-blur-glass animate-fade-in"
          >
            <CheckCircle2 class="w-3.5 h-3.5 mt-0.5 shrink-0" />
            <div class="flex-1 break-words">{{ successMsg }}</div>
            <button
              type="button"
              class="shrink-0 hover:text-white cursor-pointer"
              @click="successMsg = ''"
            >
              <X class="w-3.5 h-3.5" />
            </button>
          </div>

          <!-- 操作提示：让"可以用键盘移动视角"这件事可被发现（否则只能靠猜） -->
          <div
            v-if="hasGeometry || store.hasNavmesh"
            class="absolute bottom-3 right-3 text-[10px] text-slate-500 pointer-events-none select-none"
          >
            WASD 移动 · Q/E 升降 · Shift 加速
          </div>

          <!-- 空状态 -->
          <div
            v-if="showEmpty"
            class="absolute inset-0 flex flex-col items-center justify-center pointer-events-none animate-fade-in"
          >
            <div
              class="w-20 h-20 rounded-2xl bg-white/5 border border-white/10 flex items-center justify-center mb-5 shadow-glass"
            >
              <Hexagon class="w-10 h-10 text-cyan-glow" :stroke-width="1.4" />
            </div>
            <div class="text-base font-medium text-slate-200 mb-1.5">先上传 navmesh GLB</div>
            <div class="text-xs text-slate-400">
              左侧上传 .glb / .gltf · 然后点击「应用并烘焙」生成 navmesh
            </div>
          </div>

          <!-- 烘焙未完成 / 已烘焙未选起点提示 -->
          <div
            v-else-if="hasGeometry && !store.hasNavmesh && !store.loading"
            class="absolute bottom-3 left-3 px-3 py-2 rounded-md glass-card text-[11px] text-slate-300 pointer-events-none animate-fade-in"
          >
            几何已就绪 · 请在左侧调参后点击「应用并烘焙」
          </div>
          <div
            v-else-if="store.hasNavmesh && !store.startPoint && !store.loading"
            class="absolute bottom-3 left-3 px-3 py-2 rounded-md glass-card text-[11px] text-cyan-glow pointer-events-none animate-fade-in"
          >
            在 3D 视口点击地面选起点 · 自动 flood fill 高亮可达 module
          </div>

          <!-- 当前起点坐标 -->
          <div
            v-if="store.startPoint"
            class="absolute bottom-3 left-3 px-3 py-1.5 rounded-md bg-emerald-400/15 border border-emerald-400/30 text-[11px] text-emerald-200 font-mono backdrop-blur-glass"
          >
            起点：({{ store.startPoint.x.toFixed(1) }}, {{ store.startPoint.y.toFixed(1) }},
            {{ store.startPoint.z.toFixed(1) }})
          </div>

          <!-- Loading mask -->
          <div
            v-if="store.loading"
            class="absolute inset-0 flex items-center justify-center bg-black/50 backdrop-blur-glass pointer-events-auto"
          >
            <div class="flex flex-col items-center gap-3 px-6 py-5 rounded-xl glass-card">
              <Loader2 class="w-7 h-7 text-cyan-glow animate-spin" />
              <div class="text-[12px] text-slate-200">{{ store.loadingText || '处理中…' }}</div>
            </div>
          </div>

          <!-- 图例 / 统计 -->
          <NavmeshLegend v-if="store.hasNavmesh" />
        </section>

        <!-- 拖拽条（右：属性面板宽度） -->
        <SplitHandle
          :active="dragging === 'right'"
          title="拖动调整属性面板宽度"
          @drag-start="startDrag('right', $event)"
        />

        <!-- 属性面板：承载"选中对象的属性"；chunk 子流程下即单块数据查看与编辑 -->
        <div class="shrink-0 min-h-0" :style="{ width: rightWidth + 'px' }">
          <PropertyPanel>
            <ChunkInspector
              v-if="store.subFlow === 'chunk'"
              @change="onChunkItemChanged"
              @remove="removeChunkById"
            />
          </PropertyPanel>
        </div>
      </div>
    </div>

    <div v-if="dragging" class="fixed inset-0 z-50 cursor-col-resize" />
  </main>
</template>
