/**
 * Navmesh 实验页 pinia store。
 *
 * 设计要点：
 * - NavMesh / NavMeshQuery / polygons 数组都用 markRaw 包装，避免 Vue 响应式 proxy 把 wasm
 *   对象内部 raw 指针搞坏（这是 recast-navigation-js 的硬性要求）。
 * - bakeToken 用于异步烘焙的"丢弃旧结果"判定：每次 startBake 自增，旧任务回来后若 token
 *   不匹配则直接丢弃（不更新状态、不渲染）。
 * - 与 useModulesStore / useTerrainStore 完全独立，不共享任何字段；切到 NavmeshView 时
 *   靠这里的 state 驱动所有 UI / 渲染层。
 */
import { defineStore } from 'pinia'
import { computed, markRaw, ref, shallowRef, triggerRef } from 'vue'
import type { NavMesh, NavMeshQuery } from 'recast-navigation'
import { DEFAULT_CHUNK_PARAMS, type ChunkParams } from '../composables/useNavmeshChunking'
import type { ChunkItem, ChunkManifestExtra } from '../types/chunk'
import type { ChunkKind } from '../utils/chunkTemplate'

export interface NavmeshBakeParams {
  /** XZ 平面体素大小，控制 navmesh 细度，越小越精细但越慢 */
  cs: number
  /** Y 方向体素高度 */
  ch: number
  /** 可走坡度（度） */
  walkableSlopeAngle: number
  /** agent 高度（cell 数量）— 实际 = walkableHeight * ch */
  walkableHeight: number
  /** agent 半径（cell 数量）— 实际 = walkableRadius * cs */
  walkableRadius: number
  /** 能跨多高的台阶（cell 数量） */
  walkableClimb: number
  /** 小于此面积的 region 丢弃 */
  minRegionArea: number
  /** 合并 region 阈值 */
  mergeRegionArea: number
}

export const DEFAULT_BAKE_PARAMS: NavmeshBakeParams = {
  cs: 0.3,
  ch: 0.2,
  walkableSlopeAngle: 45,
  walkableHeight: 10, // = 10 * ch = 2.0m
  walkableRadius: 2, // = 2  * cs = 0.6m
  walkableClimb: 2, // = 2  * ch = 0.4m
  minRegionArea: 8,
  mergeRegionArea: 20
}

/** 切块统计（生成后回显，供调参参考） */
export interface ChunkStats {
  total: number
  /** 骨架阶段覆盖率（0~1） */
  coverageBefore: number
  /** 覆盖自检补出的块数 */
  fillCount: number
  /** 补块后仍未覆盖的采样格数 */
  uncoveredFinal: number
  /** 因与已有块过近被抑制的冗余块数（骨架分叉汇聚处） */
  redundantSkipped: number
  /** 脊线串链后的链数 */
  chainCount: number
  elapsedMs: number
}

/**
 * 当前脊线来源与规模。
 *
 * 脊线由「生成骨架」产出，「生成切块」沿它布块。这里显式记下来，供图例显示 ——
 * 否则屏幕上只有一堆橙线，看不出它是什么、覆盖了多少。
 */
export interface SpineInfo {
  /** 脊线来源。当前只有拓扑骨架一种；保留该字段便于将来接入其他生成方式 */
  source: 'skeleton'
  /** 自动骨架的段数 */
  segments: number
  /** 生成树边数（= 门的数量） */
  treeEdges: number
  /** 手动补线段数（用户手绘） */
  manualSegments: number
}

/** 烘焙得到的每个 polygon 的轻量化记录（用于 flood fill / 渲染 / 映射） */
export interface PolyRecord {
  /** Detour 内部 polyRef（用于 NavMeshQuery API） */
  ref: number
  /** XZ + Y 几何中心 */
  centroid: { x: number; y: number; z: number }
  /** AABB（XZ 平面，Y 仅供高度参考），用于 polygon→module 映射的快速剪枝 */
  bmin: { x: number; y: number; z: number }
  bmax: { x: number; y: number; z: number }
  /** 此 poly 的所有顶点（世界坐标，逆时针），用于自渲染。3 个一组 = 三角扇 */
  vertices: Float32Array
}

/**
 * 选点模式：起点 / 终点 / 补线 / 关闭。
 *
 * 都是"点场景取一个位置"的语义，故并在一套状态里而不是各开开关 —— ESC 退出、
 * 切换子流程复位都能直接复用。
 *
 * ⚠️ 曾经的 `chunkAdd`（点场景放一块）已移除：新增块改成按钮直接落在选中块的位置
 * （见 `NavmeshView.onAddChunkClick`），不再需要"先开模式、再点场景"两步。
 */
export type PickMode = 'start' | 'end' | 'spine' | 'off'

/**
 * 子流程：按**产物**划分（对应流程图的三条子流程）。
 *
 * ⚠️ 这里**不含"主流程"**：主流程（导入 GLB → 烘焙 navmesh → 生成中线）恒定显示在左栏，
 * 它是"主流程"而不是"子流程"，混进下拉会让人以为它也能被切走、切走后又不知道回哪儿。
 * 下拉的当前值因此直接落在第一个子流程上。
 *
 * 为什么放在 store 而不是 NavmeshView 局部：
 * - 子流程工具栏是独立组件，需要自读自写（与 NavmeshParamsPanel 等面板直接读写 store 的约定一致）；
 * - 编排层需要 `watch` 它来驱动「场景查看区图像附加物」的隐藏 / 恢复。
 */
export type SubFlow = 'bin' | 'reach' | 'chunk'

/** 子流程顺序（工具栏下拉按此顺序渲染） */
export const SUB_FLOW_ORDER: SubFlow[] = ['bin', 'reach', 'chunk']

/** 子流程显示名 */
export const SUB_FLOW_LABELS: Record<SubFlow, string> = {
  bin: '导出 bin',
  reach: '可达区',
  chunk: 'chunk'
}

export const useNavmeshStore = defineStore('navmesh', () => {
  /* ---------- 烘焙参数 ---------- */
  const bakeParams = ref<NavmeshBakeParams>({ ...DEFAULT_BAKE_PARAMS })

  /* ---------- 切块参数与统计 ---------- */
  const chunkParams = ref<ChunkParams>({ ...DEFAULT_CHUNK_PARAMS })
  const chunkStats = ref<ChunkStats | null>(null)

  /* ---------- 切块列表与单块编辑（载入 / 编辑 / 导出共用同一份数据） ---------- */
  /**
   * 当前工作区的块列表。
   *
   * 用 `shallowRef` + **整体替换**（而不是 `ref` 的深响应）：块数可达数千，给每个块的
   * position 数组套 proxy 既没必要、也会拖慢拖动时的重绘。所有写入都走
   * `setChunkItems` / `upsertChunkItem`，元素对象新建。
   */
  const chunkItems = shallowRef<ChunkItem[]>([])
  /** 选中块 id；null = 未选中 */
  const selectedChunkId = ref<string | null>(null)
  /** 载入时带出的清单级字段（baseUrl / transform / loadConfig），导出时原样写回 */
  const chunkManifestExtra = ref<ChunkManifestExtra>({})
  /** 是否在场景里显示地块名字（工具栏 checkbox） */
  const chunkLabelsVisible = ref(false)
  /**
   * **这份清单的维度**（整份清单的属性，不是"每块一次"的选择）。
   *
   * ## 为什么是单值
   *
   * 导出的清单是**一个维度一份**：两种类型混在一起下游会直接拒。所以工具栏不该常驻一个
   * "这次新建用哪种"的下拉 —— 那是把清单级属性当成了逐块属性。正确做法是：
   *
   * - 第一次生成 / 新增块（手里一个块都没有）→ 问一次，记在这里
   * - 之后所有块**沿用**它（`resolveSkeleton(kind, ...)`），不再问
   * - 从文件载入清单 → 按字段特征反推（`guessKind`）；认不出就是 `null`
   * - 块被清空 → 一起清掉（下次再问；`null` 时属性面板不列「未配置」字段，退化为只展示
   *   数据里已有的字段 —— 那在任何维度下都不会错）
   */
  const chunkKind = ref<ChunkKind | null>(null)
  /**
   * 当前块列表的来源文件名（载入 chunk 时记下）。
   *
   * 为什么需要：块可能是"算法生成的"也可能是"从文件载入的"，两者的后续动作不同
   * （生成块会被重算刷新、载入块不会），界面上得让用户一眼看出自己在编辑哪一份数据。
   * 用手工 / 算法生成时置空 —— 它不是从文件来的。
   */
  const chunkSourceName = ref<string | null>(null)

  /* ---------- 当前脊线来源（图例显示"现在走的是哪套"）---------- */
  const spineInfo = ref<SpineInfo | null>(null)

  /* ---------- 子流程（工具栏下拉切换）---------- */
  // 默认落在第一个子流程：主流程不占下拉项（见 SubFlow 的说明）
  const subFlow = ref<SubFlow>('bin')

  /* ---------- 烘焙产物（markRaw 防止 Vue reactive 干扰 wasm 对象）---------- */
  const navMeshRef = shallowRef<NavMesh | null>(null)
  const navQueryRef = shallowRef<NavMeshQuery | null>(null)
  const polygons = shallowRef<PolyRecord[]>([])

  /* ---------- Flood fill / 寻路 / module 高亮结果 ---------- */
  /** 起点 worldPos */
  const startPoint = ref<{ x: number; y: number; z: number } | null>(null)
  /** 终点 worldPos */
  const endPoint = ref<{ x: number; y: number; z: number } | null>(null)
  /** 起点拾取到的 polyRef（findNearestPoly 结果） */
  const startPolyRef = ref<number>(0)
  /** 终点拾取到的 polyRef */
  const endPolyRef = ref<number>(0)
  /** 可达 polyRef 集合（flood fill 结果） */
  const reachablePolyRefs = shallowRef<Set<number>>(new Set())
  /** 可达 module 集合（按 ModuleRuntime.name 索引） */
  const reachableModuleIds = shallowRef<Set<string>>(new Set())
  /** 不可达但被 navmesh 覆盖到的 module（绿/红对比用） */
  const unreachableModuleIds = shallowRef<Set<string>>(new Set())
  /** 跨 module 边界的 polygon 数量（仅作 UI 提示） */
  const crossModulePolyCount = ref<number>(0)
  /** 路径点（funnel 直线路径，世界坐标） */
  const pathPoints = shallowRef<Float32Array>(new Float32Array(0))

  /* ---------- 选点模式 ---------- */
  const pickMode = ref<PickMode>('start')

  /* ---------- 二维小地图选中的 module（用于联动 3D 聚焦/高亮） ---------- */
  const selectedModuleId = ref<string | null>(null)

  /* ---------- 异步 / 状态 ---------- */
  const loading = ref(false)
  const loadingText = ref('')
  const error = ref<string | null>(null)
  const lastBakeMs = ref(0)
  const bakeToken = ref(0)

  /* ---------- computed ---------- */
  const polyCount = computed(() => polygons.value.length)
  const hasNavmesh = computed(() => navMeshRef.value !== null && polygons.value.length > 0)
  const hasFloodFill = computed(() => reachablePolyRefs.value.size > 0)
  const hasPath = computed(() => pathPoints.value.length >= 6)
  /** 选中的块（单块编辑面板用） */
  const selectedChunk = computed(
    () => chunkItems.value.find((it) => it.id === selectedChunkId.value) ?? null
  )
  /**
   * 非生成块的数量（载入的 / 手工新增的 / 手工调整过的）。
   *
   * 「应用并生成切块」只刷新生成块、保留这些块，重算前用它提示影响范围。
   */
  const chunkEditCount = computed(
    () => chunkItems.value.filter((it) => it.origin !== 'generated').length
  )

  /* ---------- actions ---------- */
  function setParams(patch: Partial<NavmeshBakeParams>) {
    bakeParams.value = { ...bakeParams.value, ...patch }
  }
  function resetParams() {
    bakeParams.value = { ...DEFAULT_BAKE_PARAMS }
  }
  function setChunkParams(patch: Partial<ChunkParams>) {
    chunkParams.value = { ...chunkParams.value, ...patch }
  }
  function resetChunkParams() {
    chunkParams.value = { ...DEFAULT_CHUNK_PARAMS }
  }
  function setChunkStats(s: ChunkStats | null) {
    chunkStats.value = s
  }

  /* ---------- 切块列表 actions ---------- */
  /** 整体替换块列表；选中项若已不存在则清空，避免面板指向已经消失的块 */
  function setChunkItems(items: ChunkItem[]) {
    chunkItems.value = items
    if (selectedChunkId.value && !items.some((it) => it.id === selectedChunkId.value)) {
      selectedChunkId.value = null
    }
  }

  /**
   * 新增或替换单个块（单块编辑、手工新增、拖动结束回写都走这里）。
   *
   * `prevId` 用于**改了 id** 的场景：默认按 `item.id` 查找，但改 id 时新 id 还不在列表里，
   * `findIndex` 会返回 -1、被误判成"新增" —— 表现为「改个名字却多出一块」。
   * 传上旧 id 才能定位到真正要替换的那一项。
   */
  function upsertChunkItem(item: ChunkItem, prevId?: string) {
    const list = chunkItems.value
    const idx = list.findIndex((it) => it.id === (prevId ?? item.id))
    setChunkItems(idx >= 0 ? list.map((it, i) => (i === idx ? item : it)) : [...list, item])
    // 改了 id 时选中项要跟着换名：否则 setChunkItems 的兜底（选中 id 不存在就清空）
    // 会把选中清掉，面板闪一下空白，得等调用方再 selectChunk 才恢复
    if (prevId && selectedChunkId.value === prevId) selectedChunkId.value = item.id
  }

  function removeChunkItem(id: string) {
    setChunkItems(chunkItems.value.filter((it) => it.id !== id))
  }

  function selectChunk(id: string | null) {
    selectedChunkId.value = id
  }

  /**
   * 清空块列表（含统计与维度）：重新烘焙、载入存档、全清时调用。
   *
   * 连维度一起清：维度是"这批块"的属性，块都没了就不该留着上一次的记忆 ——
   * 否则下次生成会静默沿用旧类型，用户以为重新开始了、其实没有。
   */
  function clearChunkItems() {
    chunkItems.value = []
    selectedChunkId.value = null
    chunkStats.value = null
    chunkSourceName.value = null
    chunkKind.value = null
  }

  function setChunkSourceName(n: string | null) {
    chunkSourceName.value = n
  }

  function setChunkLabelsVisible(v: boolean) {
    chunkLabelsVisible.value = v
  }

  function setChunkKind(k: ChunkKind | null) {
    chunkKind.value = k
  }

  function setChunkManifestExtra(extra: ChunkManifestExtra) {
    chunkManifestExtra.value = extra
  }
  function setSpineInfo(s: SpineInfo | null) {
    spineInfo.value = s
  }
  function setSubFlow(f: SubFlow) {
    subFlow.value = f
  }

  function setLoading(v: boolean, text = '') {
    loading.value = v
    loadingText.value = v ? text : ''
  }
  function setError(msg: string | null) {
    error.value = msg
  }
  function bumpBakeToken(): number {
    bakeToken.value += 1
    return bakeToken.value
  }
  function isTokenAlive(token: number): boolean {
    return token === bakeToken.value
  }

  /**
   * 设置烘焙产物。NavMesh / NavMeshQuery 在调用前必须已经被 markRaw（这里再保险一次）。
   * 同时清空起点/终点/可达集合 —— 拓扑变了，旧的 polyRef 全部失效。
   */
  function setBakeResult(
    nm: NavMesh,
    nq: NavMeshQuery,
    polys: PolyRecord[],
    elapsedMs: number
  ) {
    navMeshRef.value = markRaw(nm)
    navQueryRef.value = markRaw(nq)
    polygons.value = markRaw(polys)
    triggerRef(polygons)
    lastBakeMs.value = elapsedMs
    // 拓扑变了 → 清空所有依赖 polyRef 的状态
    clearFloodAndPath()
  }

  function clearBakeResult() {
    if (navQueryRef.value) navQueryRef.value.destroy()
    if (navMeshRef.value) navMeshRef.value.destroy()
    navMeshRef.value = null
    navQueryRef.value = null
    polygons.value = []
    triggerRef(polygons)
    lastBakeMs.value = 0
    clearFloodAndPath()
  }

  function setStart(point: { x: number; y: number; z: number } | null, polyRef = 0) {
    startPoint.value = point
    startPolyRef.value = polyRef
    // 起点变 → 路径作废，flood fill 结果需要重新算
    pathPoints.value = new Float32Array(0)
    reachablePolyRefs.value = new Set()
    reachableModuleIds.value = new Set()
    unreachableModuleIds.value = new Set()
    crossModulePolyCount.value = 0
  }

  function setEnd(point: { x: number; y: number; z: number } | null, polyRef = 0) {
    endPoint.value = point
    endPolyRef.value = polyRef
    pathPoints.value = new Float32Array(0)
  }

  function setReachable(
    polyRefs: Set<number>,
    moduleIds: Set<string>,
    unreachableIds: Set<string>,
    crossCount: number
  ) {
    reachablePolyRefs.value = polyRefs
    reachableModuleIds.value = moduleIds
    unreachableModuleIds.value = unreachableIds
    crossModulePolyCount.value = crossCount
  }

  function setPath(points: Float32Array) {
    pathPoints.value = points
  }

  function clearFloodAndPath() {
    startPoint.value = null
    endPoint.value = null
    startPolyRef.value = 0
    endPolyRef.value = 0
    reachablePolyRefs.value = new Set()
    reachableModuleIds.value = new Set()
    unreachableModuleIds.value = new Set()
    crossModulePolyCount.value = 0
    pathPoints.value = new Float32Array(0)
  }

  function setPickMode(m: PickMode) {
    pickMode.value = m
  }

  function setSelectedModule(name: string | null) {
    selectedModuleId.value = name
  }

  return {
    // state
    bakeParams,
    chunkParams,
    chunkStats,
    spineInfo,
    subFlow,
    navMeshRef,
    navQueryRef,
    polygons,
    startPoint,
    endPoint,
    startPolyRef,
    endPolyRef,
    reachablePolyRefs,
    reachableModuleIds,
    unreachableModuleIds,
    crossModulePolyCount,
    pathPoints,
    pickMode,
    selectedModuleId,
    loading,
    loadingText,
    error,
    lastBakeMs,
    bakeToken,
    // computed
    polyCount,
    hasNavmesh,
    hasFloodFill,
    hasPath,
    // actions
    setParams,
    resetParams,
    setChunkParams,
    resetChunkParams,
    setChunkStats,
    chunkItems,
    selectedChunkId,
    chunkManifestExtra,
    chunkSourceName,
    chunkLabelsVisible,
    chunkKind,
    selectedChunk,
    chunkEditCount,
    setChunkItems,
    upsertChunkItem,
    removeChunkItem,
    selectChunk,
    clearChunkItems,
    setChunkManifestExtra,
    setChunkSourceName,
    setChunkLabelsVisible,
    setChunkKind,
    setSpineInfo,
    setSubFlow,
    setLoading,
    setError,
    bumpBakeToken,
    isTokenAlive,
    setBakeResult,
    clearBakeResult,
    setStart,
    setEnd,
    setReachable,
    setPath,
    clearFloodAndPath,
    setPickMode,
    setSelectedModule
  }
})
