<script setup lang="ts">
/**
 * NavmeshLegend — 图例 + 实时统计悬浮卡片。
 *
 * 展示：
 * - 颜色含义：navmesh / 可达 polygon / 可达 module / 不可达 module / 起点 / 终点 / 路径
 * - 实时统计：polygon 总数 / 可达 polygon 数 / 可达 module 数 / 跨模块 polygon 数 / 烘焙耗时
 */
import { computed } from 'vue'
import { Activity, Info } from 'lucide-vue-next'
import { useNavmeshStore } from '../stores/navmesh'

const store = useNavmeshStore()

const reachablePolyCount = computed(() => store.reachablePolyRefs.size)
const reachRatio = computed(() => {
  if (store.polyCount === 0) return 0
  return reachablePolyCount.value / store.polyCount
})

/**
 * 当前脊线标签。
 *
 * 脊线由「生成骨架」产出、「生成切块」消费。这里显式标出来源与规模 ——
 * 否则屏幕上只有一堆橙线，看不出它是什么、覆盖了多少。
 */
const spineLabel = computed(() => {
  const s = store.spineInfo
  if (!s) return { text: '未生成', cls: 'text-slate-500' }
  const manual = s.manualSegments > 0 ? ` + 手动${s.manualSegments}` : ''
  return { text: `骨架 ${s.segments}段${manual}`, cls: 'text-cyan-300' }
})
</script>

<template>
  <div
    class="absolute right-3 bottom-3 w-[240px] glass-card p-3 text-[11px] text-slate-300 space-y-2.5 pointer-events-auto"
  >
    <div class="flex items-center gap-1.5 text-cyan-glow text-[12px] font-semibold">
      <Info class="w-3.5 h-3.5" />
      图例 / 实时统计
    </div>

    <!-- 颜色图例 -->
    <div class="space-y-1.5">
      <div class="flex items-center gap-2">
        <span class="w-3 h-3 rounded-sm bg-cyan-400/40 border border-cyan-300/60" />
        <span class="text-slate-400">navmesh polygon</span>
      </div>
      <div class="flex items-center gap-2">
        <span class="w-3 h-3 rounded-sm bg-emerald-400/60 border border-emerald-300" />
        <span class="text-slate-400">可达 polygon</span>
      </div>
      <div class="flex items-center gap-2">
        <span class="w-3 h-3 rounded-sm border-2 border-emerald-400" />
        <span class="text-slate-400">可达 module</span>
      </div>
      <div class="flex items-center gap-2">
        <span class="w-3 h-3 rounded-sm border-2 border-red-500" />
        <span class="text-slate-400">不可达 module</span>
      </div>
      <div class="flex items-center gap-2">
        <span class="w-3 h-3 rounded-full bg-red-500" />
        <span class="text-slate-400">起点</span>
      </div>
      <div class="flex items-center gap-2">
        <span class="w-3 h-3 rounded-full bg-amber-400" />
        <span class="text-slate-400">终点</span>
      </div>
      <div class="flex items-center gap-2">
        <span class="w-6 h-0.5 bg-amber-400 rounded-full" />
        <span class="text-slate-400">funnel 平滑路径</span>
      </div>
      <div class="flex items-center gap-2">
        <span class="w-6 h-0.5 bg-orange-400 rounded-full" />
        <span class="text-slate-400">脊线（拓扑骨架）</span>
      </div>
      <div class="flex items-center gap-2">
        <span class="w-6 h-0.5 bg-lime-400 rounded-full" />
        <span class="text-slate-400">手动补线</span>
      </div>
    </div>

    <!-- 实时统计 -->
    <div class="pt-2 border-t border-white/5 space-y-1 font-mono">
      <div class="flex items-center justify-between">
        <span class="text-slate-500">脊线来源</span>
        <span :class="spineLabel.cls">{{ spineLabel.text }}</span>
      </div>
      <div class="flex items-center justify-between">
        <span class="text-slate-500">polygons</span>
        <span class="text-slate-100">{{ store.polyCount }}</span>
      </div>
      <div class="flex items-center justify-between">
        <span class="text-slate-500">reachable</span>
        <span class="text-emerald-300">
          {{ reachablePolyCount }}
          <span class="text-slate-500 text-[10px]"
            >({{ (reachRatio * 100).toFixed(0) }}%)</span
          >
        </span>
      </div>
      <div class="flex items-center justify-between">
        <span class="text-slate-500">reach modules</span>
        <span class="text-emerald-300">{{ store.reachableModuleIds.size }}</span>
      </div>
      <div class="flex items-center justify-between">
        <span class="text-slate-500">unreach modules</span>
        <span class="text-red-300">{{ store.unreachableModuleIds.size }}</span>
      </div>
      <div class="flex items-center justify-between">
        <span class="text-slate-500">cross-module polys</span>
        <span class="text-amber-300">{{ store.crossModulePolyCount }}</span>
      </div>
      <div class="flex items-center justify-between">
        <span class="text-slate-500 flex items-center gap-1">
          <Activity class="w-2.5 h-2.5" />bake
        </span>
        <span class="text-cyan-glow">{{ store.lastBakeMs.toFixed(0) }}ms</span>
      </div>
    </div>

    <p
      v-if="store.crossModulePolyCount > 0"
      class="text-[10px] text-amber-400/80 leading-snug pt-1 border-t border-white/5"
    >
      ⚠ 跨模块 polygon 按 centroid 归属，边界处归属为参考值。
    </p>
  </div>
</template>
