/**
 * polygonContainment — navmesh polygon 的点包含判定工具（纯函数，无副作用）。
 *
 * ## 为什么独立成模块
 *
 * 「点是否落在 navmesh 可行走域内」被两处消费：
 * - `useNavmeshBoundary`：脊线按可达区裁剪时判定点归属
 * - `useNavmeshRender`：体素网格栅格化（只画格心落在区域内的格子）
 *
 * 放在 `utils/` 而非某个 composable 内，是为了让渲染层不必反向依赖算法层。
 *
 * ## 判定语义
 *
 * 「区域」= 所有 polygon 的并集（不做任何空间分块）。判定分三级粗筛，避免 O(N) 遍历：
 * 1. 空间网格（`GRID_CELL_SIZE` 米一格）→ 只取可能相交的 poly 候选
 * 2. AABB 快速排除（XZ 范围 + Y 容差 ±1m，容忍地形起伏与楼层差）
 * 3. 2D 射线法（XZ 平面，忽略 Y）
 *
 * 注意第 3 步只看 XZ：这意味着**上下两层的 navmesh 在 XZ 投影重叠时会互相命中**，
 * 故第 2 步的 Y 容差是必要的粗筛，但不足以区分楼层 —— 本工程为单层地图，够用。
 *
 * @changelog
 * | 版本   | 变更说明                                                        | 关联                    |
 * | v1.0.0 | 从 useNavmeshCenterline 抽出；新增 findContainingPolyByXZ 供体素栅格化 | REQ: navmesh-centerline |
 * | v1.1.0 | 消费方改为 useNavmeshBoundary（中轴模块已下线）                        | REQ: navmesh-chunking   |
 * /@changelog
 *
 * @author v_weiqinlin
 */
import type { PolyRecord } from '../stores/navmesh'

/** 空间网格边长（米）：越大候选越多，越小 Map 越大 */
export const GRID_CELL_SIZE = 4

export interface PolyGrid {
  cells: Map<string, number[]>
}

/** 按 AABB 把 polygon 索引进粗筛网格 */
export function buildPolyGrid(polys: PolyRecord[]): PolyGrid {
  const cells = new Map<string, number[]>()

  for (let i = 0; i < polys.length; i++) {
    const p = polys[i]
    const x0 = Math.floor(p.bmin.x / GRID_CELL_SIZE)
    const x1 = Math.floor(p.bmax.x / GRID_CELL_SIZE)
    const z0 = Math.floor(p.bmin.z / GRID_CELL_SIZE)
    const z1 = Math.floor(p.bmax.z / GRID_CELL_SIZE)

    for (let cx = x0; cx <= x1; cx++) {
      for (let cz = z0; cz <= z1; cz++) {
        const key = `${cx},${cz}`
        const list = cells.get(key)
        if (list) list.push(i)
        else cells.set(key, [i])
      }
    }
  }

  return { cells }
}

/**
 * 找出包含该点的 polygon（XZ 平面）。命中第一个即返回 —— polygon 互不重叠，故唯一。
 * 返回 null 表示点在可行走域之外（洞、建筑、地图外）。
 */
export function findContainingPoly(
  px: number,
  py: number,
  pz: number,
  polys: PolyRecord[],
  grid: PolyGrid
): PolyRecord | null {
  const key = `${Math.floor(px / GRID_CELL_SIZE)},${Math.floor(pz / GRID_CELL_SIZE)}`
  const candidates = grid.cells.get(key)
  if (!candidates) return null

  for (const index of candidates) {
    const poly = polys[index]
    if (px < poly.bmin.x || px > poly.bmax.x || pz < poly.bmin.z || pz > poly.bmax.z) continue
    if (py < poly.bmin.y - 1 || py > poly.bmax.y + 1) continue
    if (pointInPolygon2D(px, pz, poly.vertices)) return poly
  }

  return null
}

/** 点是否落在任一 polygon 内（XZ 平面；网格粗筛 + AABB 粗筛 + 射线法） */
export function isPointInsideAnyPoly(
  px: number,
  py: number,
  pz: number,
  polys: PolyRecord[],
  grid: PolyGrid
): boolean {
  return findContainingPoly(px, py, pz, polys, grid) !== null
}

/**
 * 俯视命中：**忽略 Y**，只按 XZ 找包含该点的 polygon，多层重叠时取 Y 最高者。
 *
 * 用途：体素栅格化 —— 从正上方一条竖直射线打下去，命中的是"从上面看得见的那层地面"。
 * 与 `findContainingPoly` 的区别是不做 Y 粗筛，故不需要调用方先猜一个高度。
 */
export function findContainingPolyByXZ(
  px: number,
  pz: number,
  polys: PolyRecord[],
  grid: PolyGrid
): PolyRecord | null {
  const key = `${Math.floor(px / GRID_CELL_SIZE)},${Math.floor(pz / GRID_CELL_SIZE)}`
  const candidates = grid.cells.get(key)
  if (!candidates) return null

  let best: PolyRecord | null = null
  for (const index of candidates) {
    const poly = polys[index]
    if (px < poly.bmin.x || px > poly.bmax.x || pz < poly.bmin.z || pz > poly.bmax.z) continue
    if (!pointInPolygon2D(px, pz, poly.vertices)) continue
    if (!best || poly.centroid.y > best.centroid.y) best = poly
  }

  return best
}

/** XZ 平面上点到线段的最短距离**平方**（省一次 sqrt，比较时用平方即可） */
export function pointSegmentDistanceXZ2(
  px: number,
  pz: number,
  ax: number,
  az: number,
  bx: number,
  bz: number
): number {
  const dx = bx - ax
  const dz = bz - az
  const lenSq = dx * dx + dz * dz
  if (lenSq < 1e-12) {
    const ex = px - ax
    const ez = pz - az
    return ex * ex + ez * ez
  }
  let t = ((px - ax) * dx + (pz - az) * dz) / lenSq
  t = t < 0 ? 0 : t > 1 ? 1 : t
  const ex = px - (ax + dx * t)
  const ez = pz - (az + dz * t)
  return ex * ex + ez * ez
}

/** 2D 射线法：点是否在多边形内（忽略 Y） */
export function pointInPolygon2D(px: number, pz: number, vertices: Float32Array): boolean {
  const n = vertices.length / 3
  let inside = false

  for (let i = 0, j = n - 1; i < n; j = i++) {
    const xi = vertices[i * 3]
    const zi = vertices[i * 3 + 2]
    const xj = vertices[j * 3]
    const zj = vertices[j * 3 + 2]

    if (zi > pz !== zj > pz && px < ((xj - xi) * (pz - zi)) / (zj - zi) + xi) {
      inside = !inside
    }
  }

  return inside
}
