/**
 * chunkPick — 用射线挑出命中的块（单块选中用）。
 *
 * ## 为什么不用 three 的 Raycaster
 *
 * 全局通过 `bootstrapBVH` 把 `Mesh.prototype.raycast` 换成了 acceleratedRaycast，
 * 而没有 `boundsTree` 的 mesh 会走 fallback 并抛 "Fallback raycast function not found"。
 * 切块的 InstancedMesh 每次重绘都是新建的、没有 BVH，直接 raycast 会报错；给它建 BVH
 * 又不划算（每改一个块就要重建）。
 *
 * 况且"块"就是**旋转盒**，与射线求交是纯解析计算：一次点击 O(块数) 的 slab 判定足够快
 * （数千块 < 1ms），还省掉一次场景遍历。
 *
 * ## 姿态
 *
 * 直接用 `RenderChunk.rotation`（Three 手性的欧拉角）构建旋转矩阵，把射线变换到块的局部
 * 空间再做轴对齐 slab 判定 —— 任意姿态都成立，不必按轴写旋转公式（此前只支持绕 Y，正是
 * 因为直接手算了 cos/sin）。
 *
 * ⚠️ 手性修正已在 `itemToRenderChunk` 里做过一次（那里把编辑器角度换成 Three 手性），
 * 这里不再重复：两处各修一次会正好抵消成"看起来是对的"，之后改任何一处都会突然崩掉。
 *
 * @changelog
 * | 版本   | 变更说明                                                  | 关联                          |
 * | v1.0.0 | 初始实现：旋转盒 slab 求交，返回最近命中块下标             | REQ: map-editor-chunk-editing |
 * | v1.1.0 | 新增 chunkAABB（相机定位选择块时算包围盒）                 | REQ: map-editor-chunk-editing |
 * | v1.2.0 | 支持任意姿态：改用旋转矩阵变换射线；chunkAABB 取 8 角点包盒 | REQ: map-editor-chunk-editing |
 * /@changelog
 *
 * @author v_weiqinlin
 */
import { Euler, Matrix4 } from 'three'
import type { RenderChunk } from '../composables/useChunkIO'

type Vec3 = { x: number; y: number; z: number }

/**
 * 射线与所有块求交，返回**最近**命中块的下标；全部未命中返回 -1。
 *
 * `origin` / `dir` 为世界坐标下射线的起点与方向（方向不必归一化）。
 */
export function pickChunkIndex(chunks: RenderChunk[], origin: Vec3, dir: Vec3): number {
  let best = -1
  let bestT = Infinity
  for (let i = 0; i < chunks.length; i++) {
    const t = rayBoxDistance(chunks[i], origin, dir)
    if (t !== null && t < bestT) {
      bestT = t
      best = i
    }
  }
  return best
}

/**
 * 块的轴对齐包围盒（世界坐标）。相机"飞到该块"用。
 *
 * 为什么不直接用 `center ± size/2`：块可以有姿态，转 45° 后真实占地会胀到 √2 倍，
 * 拿未旋转的盒子去定位会让相机贴得过近、块被裁掉一半。这里把块自转后的 8 个角点求 min/max，
 * 对任意姿态都是紧的。
 */
export function chunkAABB(c: {
  center: Vec3
  size: number
  height: number
  rotation: [number, number, number]
}): {
  min: Vec3
  max: Vec3
} {
  const m = rotationMatrix(c.rotation)
  const e = m.elements
  const hx = c.size / 2
  const hy = c.height / 2
  let minX = Infinity
  let minY = Infinity
  let minZ = Infinity
  let maxX = -Infinity
  let maxY = -Infinity
  let maxZ = -Infinity
  for (const sx of [-1, 1]) {
    for (const sy of [-1, 1]) {
      for (const sz of [-1, 1]) {
        // 局部角点（块在 XZ 上是正方形，故 X / Z 都用 size/2）→ 世界
        const lx = sx * hx
        const ly = sy * hy
        const lz = sz * hx
        // Matrix4 是列主序：world = e[0]·lx + e[4]·ly + e[8]·lz（再平移）
        const wx = e[0] * lx + e[4] * ly + e[8] * lz + c.center.x
        const wy = e[1] * lx + e[5] * ly + e[9] * lz + c.center.y
        const wz = e[2] * lx + e[6] * ly + e[10] * lz + c.center.z
        if (wx < minX) minX = wx
        if (wy < minY) minY = wy
        if (wz < minZ) minZ = wz
        if (wx > maxX) maxX = wx
        if (wy > maxY) maxY = wy
        if (wz > maxZ) maxZ = wz
      }
    }
  }
  return {
    min: { x: minX, y: minY, z: minZ },
    max: { x: maxX, y: maxY, z: maxZ }
  }
}

/** 复用的临时对象：求交在点击里逐块调用，避免每次新建矩阵 / 欧拉角 */
const tmpEuler = new Euler()
const tmpMat = new Matrix4()

/** 块的自转矩阵（局部 → 世界）；`rotation` 已是 Three 手性（见 `RenderChunk`） */
function rotationMatrix(rotation: [number, number, number]): Matrix4 {
  tmpEuler.set(rotation[0], rotation[1], rotation[2], 'XYZ')
  return tmpMat.makeRotationFromEuler(tmpEuler)
}

/**
 * 射线与单个块求交；返回最近交点的射线参数 t（≥ 0），未命中返回 null。
 *
 * 做法是**把射线变换到块的局部空间**，再套用轴对齐盒的 slab 判定 —— 这样任意姿态都成立，
 * 不必为每个轴写一套旋转公式（此前只支持绕 Y，就是因为直接手算了 cos/sin）。
 */
function rayBoxDistance(c: RenderChunk, o: Vec3, d: Vec3): number | null {
  const halfW = c.size / 2
  const halfH = c.height / 2
  const e = rotationMatrix(c.rotation).elements

  // 世界 → 块局部：先平移到块心，再乘旋转矩阵的转置（正交矩阵的逆）。
  // 列主序下，R^T 的第 i 行 = R 的第 i 列 = (e[i], e[i+4], e[i+8])。
  const px = o.x - c.center.x
  const py = o.y - c.center.y
  const pz = o.z - c.center.z
  const lox = e[0] * px + e[1] * py + e[2] * pz
  const loy = e[4] * px + e[5] * py + e[6] * pz
  const loz = e[8] * px + e[9] * py + e[10] * pz
  const ldx = e[0] * d.x + e[1] * d.y + e[2] * d.z
  const ldy = e[4] * d.x + e[5] * d.y + e[6] * d.z
  const ldz = e[8] * d.x + e[9] * d.y + e[10] * d.z

  let tNear = 0
  let tFar = Infinity

  /** 单轴的 slab 判定；不通过时返回 false */
  const slab = (lo: number, ld: number, half: number): boolean => {
    if (Math.abs(ld) < 1e-9) return lo >= -half && lo <= half
    let t1 = (-half - lo) / ld
    let t2 = (half - lo) / ld
    if (t1 > t2) {
      const tmp = t1
      t1 = t2
      t2 = tmp
    }
    if (t1 > tNear) tNear = t1
    if (t2 < tFar) tFar = t2
    return tNear <= tFar
  }

  if (!slab(lox, ldx, halfW)) return null
  if (!slab(loy, ldy, halfH)) return null
  if (!slab(loz, ldz, halfW)) return null
  return tNear
}
