<script setup lang="ts">
/**
 * ChunkKindPicker — 「这份清单是什么维度」的一次性选择（弹层）。
 *
 * ## 为什么是弹层，而不是工具栏上常驻的下拉
 *
 * 维度是**整份清单**的属性：导出的是"一个维度一份清单"，两种类型混在一起下游会拒。
 * 常驻下拉会把它伪装成"这次新建用哪种"的逐块选择，容易让人以为一份清单里能混着放。
 * 改成"第一次生成 / 新增块时问一次、之后沿用已有块的类型"，位置才与语义对上。
 *
 * ## 什么时候弹
 *
 * 只在"手里一个块都没有、也不知道清单维度"时弹（见 `NavmeshView.requireKind`）：
 * 已有块 → 照抄已有块的字段，用户零操作；载入清单 → 按字段特征反推。
 *
 * ## 为什么没有"随便，先跳过"
 *
 * 生成 / 新增块必须有字段名单才能产出合法数据（collision 缺 `url` 会被下游 zod 直接拒），
 * 所以这里只有"选一个"与"取消"：取消 = 本次不生成，不会留下一个没有名单的块。
 *
 * @changelog
 * | 版本   | 变更说明                                              | 关联                          |
 * | v1.0.0 | 从 ChunkTemplateDropdown 改造：常驻下拉 → 一次性弹层     | REQ: map-editor-chunk-editing |
 * | v1.0.1 | 修：改用 Teleport 挂到 body —— 原来挂在工具栏里，祖先的 backdrop-filter 会让 fixed 相对祖先定位（弹层跑到工具栏旁、遮罩铺不满） | REQ: map-editor-chunk-editing |
 * /@changelog
 *
 * @author v_weiqinlin
 */
import { LayoutTemplate, X } from 'lucide-vue-next'
import { CHUNK_KINDS, CHUNK_KIND_LABELS, type ChunkKind } from '../utils/chunkTemplate'

defineProps<{
  /** 是否显示 */
  open: boolean
}>()

const emit = defineEmits<{
  /** 选定了维度 */
  (e: 'pick', kind: ChunkKind): void
  /** 放弃（本次不生成 / 不新增） */
  (e: 'close'): void
}>()

/** 每个维度的说明：帮用户对上手头的清单该选哪个 */
const HINTS: Record<ChunkKind, string> = {
  collision: '碰撞网格：url 必填，另有 opacity / cloneAsLightMesh / global',
  terrain: '地形高度图：url 必填，另有 resolution / uvRegion',
  light: '光照参数通道：ambient / sky / hdri / shadow 等 10 个可选块',
  program: '玩法程序表：programs 至少 1 条（编辑器编不出，导出前需补）',
  npc: 'NPC 区域：configFile 必填，另有 global / unloadable'
}
</script>

<template>
  <!--
    ★必须 Teleport 到 body：调用方把它放在子流程工具栏里，而工具栏祖先带 `backdrop-filter`
    （玻璃拟态）。该属性会让后代的 `position: fixed` 相对**那个祖先**而不是视口定位 ——
    表现为弹层贴着工具栏乱放、遮罩也铺不满整屏。挂到 body 后与祖先的渲染上下文无关。
  -->
  <Teleport to="body">
    <div v-if="open" class="fixed inset-0 z-[60] flex items-center justify-center">
      <!--
        遮罩不响应点击关闭：这一步必须明确"选一个"或"取消"。
        点空白处就消失的话，用户容易以为自己已经选好了，接着发现块没生成。
      -->
      <div class="absolute inset-0 bg-black/60 backdrop-blur-[2px]" />

      <div
        class="relative w-[min(92vw,26rem)] max-h-[86vh] overflow-y-auto rounded-xl border border-white/10 bg-[#0b1120] shadow-glass p-4"
      >
        <header class="flex items-start gap-2">
          <LayoutTemplate class="w-4 h-4 mt-0.5 shrink-0 text-cyan-glow" />
          <div class="min-w-0 flex-1">
            <h3 class="text-[13px] font-semibold text-slate-100">这份清单是什么维度？</h3>
            <p class="mt-1 text-[11px] leading-snug text-slate-500">
              一份清单只能有一个维度。选定后，本次生成 / 新增的块都用它的字段名单，之后不再询问
              —— 已有块时会直接沿用那些块的类型。
            </p>
          </div>
          <button
            type="button"
            class="shrink-0 p-1 rounded text-slate-500 hover:text-slate-200 hover:bg-white/10 cursor-pointer transition-all"
            title="取消（本次不生成 / 不新增）"
            @click="emit('close')"
          >
            <X class="w-3.5 h-3.5" />
          </button>
        </header>

        <ul class="mt-3 flex flex-col gap-1">
          <li v-for="k in CHUNK_KINDS" :key="k">
            <button
              type="button"
              class="w-full text-left px-2.5 py-2 rounded-md border border-white/10 bg-white/5 hover:border-cyan-glow/40 hover:bg-cyan-glow/10 cursor-pointer transition-all"
              @click="emit('pick', k)"
            >
              <span class="block font-mono text-[12px] text-slate-200">{{
                CHUNK_KIND_LABELS[k]
              }}</span>
              <span class="block mt-0.5 text-[10px] leading-snug text-slate-500">{{
                HINTS[k]
              }}</span>
            </button>
          </li>
        </ul>
      </div>
    </div>
  </Teleport>
</template>
