<script setup lang="ts">
/**
 * PropTree — 把一个任意 JSON 值渲染成「左 key / 右 value」的属性行树（递归组件）。
 *
 * ## 为什么是通用渲染，而不是每个字段写死的表单
 *
 * 块的字段来自五个下游维度，差异极大：collision 只有 5 个平铺字段、无嵌套；而 light 有
 * 10 个可选子块 —— `sky` 10 个字段、`shadow → followDirectional → shadow → camera` 嵌套
 * 4 层、`points` / `directional` / `lightSchedules` 是对象数组。逐个维度写死表单既不现实，
 * 每加一个维度还要改一遍 UI。
 *
 * 这里只按**值的形态**分派，因此任意维度、任意深度、连编辑器不认识的字段都能显示与编辑。
 *
 * ## 分派规则
 *
 * | 值的形态 | 渲染 |
 * |---|---|
 * | string / number / boolean | 对应控件 |
 * | 长度 ≤3 且全为 number 的数组 | 横排 X / Y / Z |
 * | 恰好含 x / y / z 三个 number 键的对象 | **同样横排** |
 * | 普通对象 | 折叠分组 + 递归缩进 |
 * | 其它数组 | 折叠分组（badge 显示项数）+ 逐项递归，key 用下标 |
 *
 * 为什么两种三维写法都要认：契约里**两种混着用** —— `shadow.followDirectional.offset`
 * 是元组 `[-6,10,6]`，而 `direction` / `position` 是对象 `{x,y,z}`，同一个清单里都有。
 *
 * ## 折叠默认状态
 *
 * `depth < AUTO_OPEN_DEPTH` 展开、更深收起。刻意不是"全展开"：光 `shadow` 一条链
 * 展开就有 4 层、几十个字段，全开会把面板撑到几千像素，反而找不到前面的字段。
 *
 * ## 写回
 *
 * 控件 `emit('update', path, value)`，`path` 是**从树根算起**的绝对路径（父层传下来时
 * 已拼好，子节点直接用 `props.path`），由 `ChunkInspector` 统一落到 store。
 * 本组件不做校验、不取整 —— 那些属于数据语义，见 `ChunkInspector` 的注释。
 *
 * ## 未配置节点（`spec` / `unset`）
 *
 * 契约里有、块数据里还没有的字段（`unset`）渲染成**空控件**：文本 / 数字给空输入框，
 * boolean 给未勾选的 checkbox，对象给可展开的折叠组，数组给一行提示。
 *
 * 关键是**填写前不写入任何值**：`opacity = 0` 会让块全透明、`intensity = 0` 会关灯，
 * 预填默认值是数据污染。所以未配置的文本 / 数字在空输入时不落库（见 `commitUnsetText`），
 * 而定长元组因为契约要求定长，填任一分量时把缺的分量补 0（坐标的中性值，见
 * `commitUnsetVec`）。写入后该节点就有值了、自动转为普通节点渲染。
 *
 * @changelog
 * | 版本   | 变更说明                                                    | 关联                          |
 * | v1.0.0 | 初始实现：按值形态递归渲染（标量 / 三维 / 对象 / 数组）        | REQ: map-editor-chunk-editing |
 * | v1.1.0 | 修数字框：清空不再被当成 0；父层拒收时回填真实值；支持只读标量    | REQ: map-editor-chunk-editing |
 * | v1.2.0 | 新增 spec / unset：渲染契约里尚未配置的字段（填了才写入）        | REQ: map-editor-chunk-editing |
 * | v1.2.1 | 修：输入值后输入框弹回旧值（syncBack 的显示值改为延迟求值，见注释）    | REQ: map-editor-chunk-editing |
 * /@changelog
 *
 * @author v_weiqinlin
 */
import { computed, nextTick } from 'vue'
import PropRow from './PropRow.vue'
import PropGroup from './PropGroup.vue'
import type { PropPath } from '../utils/setIn'
import {
  isVec3,
  isXyzObject,
  isNumericTuple,
  mergeFieldEntries,
  type FieldSpec,
  type PropEntry
} from '../utils/propValue'

const props = defineProps<{
  /** 左侧显示的字段名（原始契约 key） */
  label: string
  /** 本节点当前值 */
  value: unknown
  /** 从树根到本节点的绝对路径 */
  path: PropPath
  /** 嵌套深度（0 = 顶层），决定默认展开 */
  depth: number
  /**
   * 标量是否只读展示（如 `shape.type` 契约里是 `z.literal('box')`，只有一个合法值）。
   * 只影响标量；对象 / 数组仍可展开 —— 只读的是"这个值不能改"，不是"不许看"。
   */
  readonly?: boolean
  /**
   * 本节点的契约形状（由 `utils/chunkTemplate` 按维度提供）。
   *
   * 两个用途：① 未配置节点按它决定给什么控件；② **对象已存在但缺子字段**时靠它把缺的
   * 子字段补成「未配置」子行（如 `ambient` 只填了 `intensity`，`color` 也要能看见并补上）。
   * 没有它（如 `shape` 这类块级数据）就退化为"只渲染数据里已有的键"。
   */
  spec?: FieldSpec
  /** 契约里有、块数据里还没有：本节点显示空控件，用户填了才写入（见 `ChunkInspector`） */
  unset?: boolean
}>()

const emit = defineEmits<{
  /** 某个叶子被改动：path 为绝对路径，value 为新值 */
  (e: 'update', path: PropPath, value: unknown): void
}>()

/** 横排三维量的轴标签 */
const AXES = ['X', 'Y', 'Z'] as const

/** 深度小于此值的分组默认展开（见组件头注释） */
const AUTO_OPEN_DEPTH = 2

type NodeKind = 'vec3' | 'object' | 'array' | 'string' | 'number' | 'boolean' | 'null'

const kind = computed<NodeKind>(() => {
  const v = props.value
  if (v === null || v === undefined) return 'null'
  if (typeof v === 'boolean') return 'boolean'
  if (typeof v === 'number') return 'number'
  if (typeof v === 'string') return 'string'
  if (isVec3(v)) return 'vec3'
  if (Array.isArray(v)) return 'array'
  return 'object'
})

/** 三维量的三个分量（按原形态取，写回时也按原形态还回去） */
const vecValues = computed<number[]>(() => {
  const v = props.value
  if (isXyzObject(v)) return [v.x, v.y, v.z]
  return isNumericTuple(v) ? [...v] : [0, 0, 0]
})

/** 本节点契约里的子字段（形状不是对象时为 undefined） */
const objectFields = computed<Record<string, FieldSpec> | undefined>(() =>
  props.spec?.kind === 'object' ? props.spec.fields : undefined
)

/**
 * 子节点列表：对象按键顺序、数组按下标，并**在契约里补齐还缺的子字段**（标 `unset`）。
 *
 * 为什么要补：对象已存在、但只配了部分子字段是很常见的状态（`ambient` 只填了 `intensity`）。
 * 不补的话用户看不到还没配的那些，得靠记住契约才知道缺什么。
 */
const children = computed<PropEntry[]>(() => {
  const v = props.value
  if (Array.isArray(v)) return v.map((val, i) => ({ key: i, value: val }))
  if (typeof v === 'object' && v !== null) {
    return mergeFieldEntries(v as Record<string, unknown>, objectFields.value)
  }
  return []
})

/** 子行的形状：对象取字段表里对应项；数组元素没有名单（元素增删不在面板范围） */
function childSpec(key: string | number): FieldSpec | undefined {
  return objectFields.value?.[String(key)]
}

/**
 * 收起时显示的项数摘要。
 *
 * 只数**数据里真实存在**的项：把未配置的契约字段也算进去会让空对象显示成"8 项"，
 * 而实际一个值都没有。
 */
const badgeText = computed(() => {
  const v = props.value
  const n = Array.isArray(v)
    ? v.length
    : v && typeof v === 'object'
      ? Object.keys(v as object).length
      : 0
  return n ? `${n} 项` : ''
})

/** 子树的 update 原样往上抛（path 已经是绝对的，不需要再拼） */
function forward(path: PropPath, value: unknown) {
  emit('update', path, value)
}

/** 写入本节点的整体值 */
function commit(value: unknown) {
  emit('update', props.path, value)
}

/**
 * 读取数字输入框的值；空串与非法输入返回 null（= 不落库）。
 *
 * ⚠️ `Number('')` 是 **0** 而不是 NaN —— 直接用 `Number()` 会把"清空输入框"
 * 当成"改成 0"（用户多半只是想重打一遍）。所以空串必须先单独拦掉。
 */
function readNumber(el: HTMLInputElement): number | null {
  if (el.value.trim() === '') return null
  const n = Number(el.value)
  return Number.isFinite(n) ? n : null
}

/**
 * 把输入框的显示值拉回真实数据。
 *
 * 父层可以**拒收**一个值（几何尺寸必须为正）。拒收时不落库，但 DOM 会停在用户输入的
 * 非法值上，与真实数据不一致 —— 看着像"改成功了但没生效"，比直接报错还难查。
 * 等本帧结束再回填（此时 `props.value` 已是父层最终接受的值）：落库成功就是新值、
 * 被拒就是原值，输入框永远显示真实数据。
 *
 * ⚠️ `shown` 必须是**取值函数**，不能是取好的字符串。Vue 的 prop 更新是异步的，提交
 * 那一瞬 `props.value` 还是旧值 —— 若在调用处就求值，等 `nextTick` 时回填的仍是旧值，
 * 表现为"输入框永远弹回原值"（用户报过：改了 `rotation`、3D 也转了，但面板看着没变），
 * 而数据其实早已写入。求值必须推迟到 `nextTick` 内部，才能拿到父层最终接受的值。
 */
function syncBack(el: HTMLInputElement, shown: () => string) {
  nextTick(() => {
    el.value = shown()
  })
}

/** 数字输入：空串 / 乱写不落库，并回填真实数据 */
function commitNumber(e: Event) {
  const el = e.target as HTMLInputElement
  const n = readNumber(el)
  if (n !== null) commit(n)
  syncBack(el, () =>
    props.value === null || props.value === undefined ? '' : String(props.value)
  )
}

/**
 * 三维量的单个分量。
 *
 * ★按**原形态**写回：对象进、对象出，数组进、数组出 —— 契约里这两种写法是等价的，
 * 但若把 `{x,y,z}` 写成 `[x,y,z]`，下游按对象取值的代码就会读到 undefined。
 */
function commitVec(i: number, e: Event) {
  const el = e.target as HTMLInputElement
  const n = readNumber(el)
  if (n !== null) {
    if (isXyzObject(props.value)) {
      const key = (['x', 'y', 'z'] as const)[i]
      commit({ ...props.value, [key]: n })
    } else {
      const next = vecValues.value.slice()
      next[i] = n
      commit(next)
    }
  }
  syncBack(el, () => String(vecValues.value[i] ?? ''))
}

/* ---------- 未配置节点（契约里有、数据里还没有）---------- */

/** 定长元组的轴标签：vec2 → X/Y，vec3 → X/Y/Z */
function axesOf(size: number): string[] {
  return AXES.slice(0, size)
}

/**
 * 未配置文本字段：空值不落库。
 *
 * 与"清空一个已有的值"不同 —— 这里本来就是"还没配置"，空输入等于没填。写空串进去会
 * 凭空造出一个字段（`url` 另有"空串即删除"的规则，但那是已配置字段的语义）。
 */
function commitUnsetText(e: Event) {
  const el = e.target as HTMLInputElement
  if (el.value.trim() === '') {
    nextTick(() => {
      el.value = ''
    })
    return
  }
  commit(el.value)
}

/**
 * 未配置的定长元组：整个元组一起写（契约要求定长，没填的分量取 0）。
 *
 * 0 是坐标 / 偏移的中性值，和 `opacity = 0`（会让块全透明）不是一回事。写入后本节点
 * 就有值了、转成普通节点，用户接着改其余分量即可。
 */
function commitUnsetVec(spec: FieldSpec, i: number, e: Event) {
  if (spec.kind !== 'vec') return
  const el = e.target as HTMLInputElement
  const n = readNumber(el)
  if (n === null) {
    nextTick(() => {
      el.value = ''
    })
    return
  }
  if (spec.as === 'object') {
    const out: Record<string, number> = {}
    for (let k = 0; k < spec.size; k++) out[AXES[k].toLowerCase()] = k === i ? n : 0
    commit(out)
  } else {
    const out = new Array<number>(spec.size).fill(0)
    out[i] = n
    commit(out)
  }
}
</script>

<template>
  <!--
    未配置：契约里有、块数据里还没有。只给"收集输入"的控件，填了才写入 —— 预先补
    0 / false 之类的默认值是数据污染，且部分字段的 0 有实际语义（opacity = 全透明）。
  -->
  <template v-if="unset && spec">
    <!-- 对象：折叠分组，展开后按契约递归（子字段同样未配置） -->
    <PropGroup
      v-if="spec.kind === 'object'"
      :label="label"
      badge="未配置"
      unset
      :default-expanded="depth < AUTO_OPEN_DEPTH"
    >
      <PropTree
        v-for="(childSpec, key) in spec.fields"
        :key="key"
        :label="String(key)"
        :value="undefined"
        :spec="childSpec"
        unset
        :path="[...path, key]"
        :depth="depth + 1"
        @update="forward"
      />
    </PropGroup>

    <!-- 数组：元素增删不在面板范围（见组件头注释），故给一行提示而不是一个走不通的空表 -->
    <PropRow v-else-if="spec.kind === 'array'" :label="label" unset>
      <span class="font-mono text-[13px] text-slate-600">未配置 · 元素请在 JSON 模式维护</span>
    </PropRow>

    <!-- 定长数字元组：几个分量一起给，填任一个即写入（缺的取 0） -->
    <PropRow v-else-if="spec.kind === 'vec'" :label="label" unset>
      <span
        v-for="(axis, i) in axesOf(spec.size)"
        :key="axis"
        class="flex items-center gap-0.5 min-w-0 flex-1"
      >
        <span class="shrink-0 font-mono text-[12px] text-slate-600">{{ axis }}</span>
        <input
          type="number"
          step="0.1"
          placeholder="未配置"
          class="num-input min-w-0 w-full bg-black/30 border border-white/10 rounded px-1 py-0.5 text-[13px] text-slate-100 font-mono outline-none focus:border-violet-400/50 placeholder:text-slate-600"
          @change="commitUnsetVec(spec, i, $event)"
        />
      </span>
    </PropRow>

    <!-- 标量 -->
    <PropRow v-else :label="label" unset>
      <input
        v-if="spec.kind === 'boolean'"
        type="checkbox"
        class="w-3 h-3 accent-violet-400 cursor-pointer"
        title="勾选即写入 true（不勾则不写入）"
        @change="commit(($event.target as HTMLInputElement).checked)"
      />
      <input
        v-else-if="spec.kind === 'number'"
        type="number"
        step="0.1"
        placeholder="未配置"
        class="num-input min-w-0 w-full bg-black/30 border border-white/10 rounded px-1.5 py-0.5 text-[14px] text-slate-100 font-mono outline-none focus:border-violet-400/50 placeholder:text-slate-600"
        @change="commitNumber"
      />
      <input
        v-else
        type="text"
        placeholder="未配置"
        class="min-w-0 w-full bg-black/30 border border-white/10 rounded px-1.5 py-0.5 text-[14px] text-slate-100 font-mono outline-none focus:border-violet-400/50 placeholder:text-slate-600"
        @change="commitUnsetText"
      />
    </PropRow>
  </template>

  <!-- 三维量：横排 X / Y / Z -->
  <PropRow v-else-if="kind === 'vec3'" :label="label">
    <span
      v-for="(axis, i) in AXES"
      :key="axis"
      class="flex items-center gap-0.5 min-w-0 flex-1"
    >
      <span class="shrink-0 font-mono text-[12px] text-slate-600">{{ axis }}</span>
      <input
        type="number"
        step="0.1"
        :value="vecValues[i]"
        class="num-input min-w-0 w-full bg-black/30 border border-white/10 rounded px-1 py-0.5 text-[13px] text-slate-100 font-mono outline-none focus:border-violet-400/50"
        @change="commitVec(i, $event)"
      />
    </span>
  </PropRow>

  <!-- 对象 / 数组：折叠分组 + 递归（对象会补齐契约里还缺的子字段，见 children） -->
  <PropGroup
    v-else-if="kind === 'object' || kind === 'array'"
    :label="label"
    :badge="badgeText"
    :default-expanded="depth < AUTO_OPEN_DEPTH"
  >
    <PropTree
      v-for="child in children"
      :key="child.key"
      :label="String(child.key)"
      :value="child.value"
      :spec="childSpec(child.key)"
      :unset="child.unset"
      :path="[...path, child.key]"
      :depth="depth + 1"
      @update="forward"
    />
  </PropGroup>

  <!-- 标量 -->
  <PropRow v-else :label="label">
    <input
      v-if="kind === 'boolean'"
      type="checkbox"
      class="w-3 h-3 accent-violet-400 cursor-pointer"
      :checked="value === true"
      @change="commit(($event.target as HTMLInputElement).checked)"
    />
    <input
      v-else-if="kind === 'number'"
      type="number"
      step="0.1"
      :value="value"
      class="num-input min-w-0 w-full bg-black/30 border border-white/10 rounded px-1.5 py-0.5 text-[14px] text-slate-100 font-mono outline-none focus:border-violet-400/50"
      @change="commitNumber"
    />
    <!-- 只读：唯一合法值的字面量字段（如 shape.type = box），给输入框没意义 -->
    <span v-else-if="readonly" class="font-mono text-[14px] text-slate-500">
      {{ String(value) }}
    </span>
    <input
      v-else-if="kind === 'string'"
      type="text"
      :value="value"
      class="min-w-0 w-full bg-black/30 border border-white/10 rounded px-1.5 py-0.5 text-[14px] text-slate-100 font-mono outline-none focus:border-violet-400/50"
      @change="commit(($event.target as HTMLInputElement).value)"
    />
    <span v-else class="font-mono text-[13px] text-slate-600">null</span>
  </PropRow>
</template>

<style scoped>
/**
 * 隐藏数字输入框自带的上下箭头。
 *
 * 右栏宽度紧张，那两个箭头要占掉约 12px —— 实测 5.5rem 列宽时 `rotation` 的 `90`
 * 被挤成了可见的 `9`。而它的步进值（0.1）对本场景的数值范围（坐标动辄上千）也没什么用：
 * 真要精确调数值会直接键入，不会去点那个箭头。
 */
.num-input::-webkit-outer-spin-button,
.num-input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

.num-input {
  -moz-appearance: textfield;
  appearance: textfield;
}
</style>
