/**
 * chunk（分块）编辑器侧的契约定义。
 *
 * ## 为什么内存里存 shape 形态，而不是沿用算法里的 Chunk
 *
 * 切块算法（`useNavmeshChunking`）内部用 `Chunk { center, size, height, yaw }`：
 * yaw 是**弧度**、XZ 是正方形（宽 = 深），便于布块与覆盖判定。
 * 而下游运行时的 chunk 契约是 `shape: { type:'box', width, height, depth, transform }`，
 * 其中 rotation 是**角度制**，并携带 `id` 与各维度业务字段。
 *
 * 两者是"算法中间量"与"落盘契约"的区别。若沿用算法结构，导出、载入、字段编辑三处
 * 都要各自做一次隐式换算，迟早对不上。因此：
 * - 编辑器内存里只存 shape 形态（`ChunkItem`），算法产出后立刻转换一次；
 * - 渲染层要的 `{ center, size, height, yaw }` 由 `itemToRenderChunk` 反向导出；
 * - 换算集中在 `useChunkIO`，不散落到 UI 代码里。
 *
 * ## 字段保真
 *
 * `asset` 存放该维度除 `id` / `shape` 之外的全部字段，**载入时原样收下、导出时原样写回**。
 * 五个维度（collision / terrain / light / program / npc）字段差异很大（light 有 7 个通道
 * 参数、program 有整张 programs 表），编辑器不理解的字段也不能丢 —— 否则配置过一遍编辑器
 * 就被削平了。
 *
 * @changelog
 * | 版本   | 变更说明                                              | 关联                          |
 * | v1.0.0 | 初始定义：ChunkItem / box shape / 编辑器格式标记       | REQ: map-editor-chunk-editing |
 * /@changelog
 *
 * @author v_weiqinlin
 */

/** box shape 的 transform；rotation 为**角度制**（与运行时契约一致，勿存弧度） */
export interface ChunkBoxTransform {
  position: [number, number, number]
  rotation: [number, number, number]
  scale: [number, number, number]
}

/** 块几何：box（运行时分块首版只放开 box，编辑器同样只产这一种） */
export interface ChunkBoxShape {
  type: 'box'
  /** X 方向尺寸（米） */
  width: number
  /** Y 方向尺寸（米） */
  height: number
  /** Z 方向尺寸（米） */
  depth: number
  transform: ChunkBoxTransform
}

/**
 * 块来源。
 *
 * - `generated`：切块算法产出（`source` 记录是骨架布块还是覆盖补块）
 * - `loaded`：从文件载入
 * - `manual`：场景里手工新增
 *
 * 决定**重算策略**：重新生成切块只刷新 `generated` 的块，另外两类是用户的劳动成果，
 * 一律保留（否则调一次参数就把手工摆的块冲掉）。
 */
export type ChunkOrigin = 'generated' | 'loaded' | 'manual'

/** 编辑器内存中的一个块 */
export interface ChunkItem {
  id: string
  shape: ChunkBoxShape
  /** 除 id / shape 外的维度字段，原样保留（见文件头「字段保真」） */
  asset: Record<string, unknown>
  origin: ChunkOrigin
  /** 生成块的算法来源（骨架布块 / 覆盖补块），用于分色显示；载入与手工块为 null */
  source: 'spine' | 'fill' | null
}

/** 清单级可选字段：载入时带出、导出时写回；编辑器不解释其内容 */
export interface ChunkManifestExtra {
  /** 块资源的 url 前缀 */
  baseUrl?: string
  /** 整份清单的变换（运行时可选字段） */
  transform?: Record<string, unknown>
  /** 流式加载配置（运行时可选字段） */
  loadConfig?: Record<string, unknown>
}

/** 导出清单：对齐运行时 `ChunkedManifestShape` 的最小必要集，其余字段透传 */
export interface ChunkManifestFile extends ChunkManifestExtra {
  /** 块数组，每项 = `{ id, ...asset, shape }` */
  modules: Array<Record<string, unknown>>
}

/** 编辑器格式的顶层标记（写在 `format` 字段，用于载入时识别） */
export const CHUNK_EDITOR_FORMAT = 'map-editor-chunks'

/** 编辑器格式版本 */
export const CHUNK_EDITOR_FORMAT_VERSION = 1
