import { defineStore } from 'pinia'
import { computed, ref, shallowRef, triggerRef } from 'vue'
import { Box3, MathUtils, Mesh, type Object3D, Vector3 } from 'three'
import type { TerrainItem, MinimapResolution } from '../types'

/**
 * 给一个 terrain 根对象下的所有 mesh.geometry 构建 BVH boundsTree。
 * - 已构建过的 geometry 跳过（避免重复 200~600ms 开销）
 * - 仅在 main.ts 通过 bootstrapBVH 注入 BufferGeometry.computeBoundsTree 之后才生效
 * - 200~600ms（50w 面）一次性开销，换来后续 raycast 10~50× 提速
 */
function buildBVHForTerrain(root: Object3D): void {
  const t0 = performance.now()
  let built = 0
  let total = 0
  root.traverse((obj) => {
    const m = obj as Mesh
    if (!m.isMesh || !m.geometry) return
    total++
    const geom = m.geometry as unknown as {
      boundsTree?: unknown
      computeBoundsTree?: () => void
    }
    if (geom.boundsTree) return
    if (typeof geom.computeBoundsTree === 'function') {
      geom.computeBoundsTree()
      built++
    }
  })
  if (built > 0) {
    console.log(
      `[BVH] terrain built: ${built}/${total} meshes in ${(performance.now() - t0).toFixed(0)}ms`
    )
  }
}

/** 卸载 terrain 时释放 BVH 内存。 */
function disposeBVHForTerrain(root: Object3D): void {
  root.traverse((obj) => {
    const m = obj as Mesh
    if (!m.isMesh || !m.geometry) return
    const geom = m.geometry as unknown as {
      boundsTree?: unknown
      disposeBoundsTree?: () => void
    }
    if (geom.boundsTree && typeof geom.disposeBoundsTree === 'function') {
      geom.disposeBoundsTree()
    }
  })
}

export const useTerrainStore = defineStore('terrain', () => {
  // 使用 shallowRef 避免 Vue 对 Object3D 等大对象做深度响应式追踪
  const terrains = shallowRef<TerrainItem[]>([])
  const isLoading = ref(false)
  const loadingProgress = ref(0)
  const minimapResolution = ref<MinimapResolution>(512)
  /** 小地图脏标记：true 表示需要重渲一帧 */
  const minimapDirty = ref(true)

  const count = computed(() => terrains.value.length)
  const isEmpty = computed(() => terrains.value.length === 0)

  /** 合并所有地形的世界 AABB；空时返回 null */
  const mergedBox = computed<Box3 | null>(() => {
    if (terrains.value.length === 0) return null
    const merged = new Box3()
    let inited = false
    for (const t of terrains.value) {
      if (t.box.isEmpty()) continue
      if (!inited) {
        merged.copy(t.box)
        inited = true
      } else {
        merged.union(t.box)
      }
    }
    return inited ? merged : null
  })

  const mergedCenter = computed<Vector3 | null>(() => {
    const box = mergedBox.value
    if (!box) return null
    const c = new Vector3()
    box.getCenter(c)
    return c
  })

  const mergedSize = computed<Vector3 | null>(() => {
    const box = mergedBox.value
    if (!box) return null
    const s = new Vector3()
    box.getSize(s)
    return s
  })

  function addTerrain(item: TerrainItem) {
    // 一次性构建 BVH（在 add 时机做，让"计算邻接 / 栅格化"等后续 raycast 路径无感加速）
    buildBVHForTerrain(item.object3D)
    terrains.value = [...terrains.value, item]
    triggerRef(terrains)
    markMinimapDirty()
  }

  function removeTerrain(id: string) {
    const removed = terrains.value.find((t) => t.id === id)
    if (removed) disposeBVHForTerrain(removed.object3D)
    terrains.value = terrains.value.filter((t) => t.id !== id)
    triggerRef(terrains)
    markMinimapDirty()
  }

  /**
   * 设置某个 terrain 的旋转（欧拉角，单位：度，顺序 XYZ）。
   * - 直接修改 object3D.rotation（同一引用，主预览/小地图同步生效）
   * - 重算 worldBox 与 size
   * - 触发 minimap dirty
   * 注意：调用方在旋转后通常需要让 walkableMap 失效，由调用方负责（store 层不耦合 modulesStore）
   */
  function setTerrainRotation(id: string, rot: [number, number, number]) {
    const list = terrains.value
    const idx = list.findIndex((t) => t.id === id)
    if (idx < 0) return
    const t = list[idx]
    t.object3D.rotation.set(
      MathUtils.degToRad(rot[0]),
      MathUtils.degToRad(rot[1]),
      MathUtils.degToRad(rot[2])
    )
    t.object3D.updateMatrixWorld(true)
    const newBox = new Box3().setFromObject(t.object3D)
    const newSize = new Vector3()
    if (!newBox.isEmpty()) newBox.getSize(newSize)
    const updated: TerrainItem = {
      ...t,
      rotationDeg: [rot[0], rot[1], rot[2]],
      box: newBox,
      size: newSize
    }
    list[idx] = updated
    terrains.value = [...list]
    triggerRef(terrains)
    markMinimapDirty()
  }

  /**
   * 设置某个 terrain 的翻转（沿 X / Y / Z 轴镜像）。
   * - 通过 object3D.scale = ±1 实现镜像
   * - 镜像 Y 会让原本朝下的法线朝上（适合修复"navmesh 简化碰撞体反向"问题）
   * - 重算 worldBox 与 size，并 markMinimapDirty
   * - 注意：调用方应让 walkableMap 失效（与 setTerrainRotation 一致）
   */
  function setTerrainFlip(id: string, flip: [boolean, boolean, boolean]) {
    const list = terrains.value
    const idx = list.findIndex((t) => t.id === id)
    if (idx < 0) return
    const t = list[idx]
    t.object3D.scale.set(
      flip[0] ? -1 : 1,
      flip[1] ? -1 : 1,
      flip[2] ? -1 : 1
    )
    t.object3D.updateMatrixWorld(true)
    const newBox = new Box3().setFromObject(t.object3D)
    const newSize = new Vector3()
    if (!newBox.isEmpty()) newBox.getSize(newSize)
    const updated: TerrainItem = {
      ...t,
      flip: [flip[0], flip[1], flip[2]],
      box: newBox,
      size: newSize
    }
    list[idx] = updated
    terrains.value = [...list]
    triggerRef(terrains)
    markMinimapDirty()
  }

  function setLoading(v: boolean) {
    isLoading.value = v
    if (!v) loadingProgress.value = 0
  }

  function setProgress(v: number) {
    loadingProgress.value = v
  }

  function setResolution(r: MinimapResolution) {
    minimapResolution.value = r
    markMinimapDirty()
  }

  function markMinimapDirty() {
    minimapDirty.value = true
  }

  function clearMinimapDirty() {
    minimapDirty.value = false
  }

  return {
    terrains,
    isLoading,
    loadingProgress,
    minimapResolution,
    minimapDirty,
    count,
    isEmpty,
    mergedBox,
    mergedCenter,
    mergedSize,
    addTerrain,
    removeTerrain,
    setTerrainRotation,
    setTerrainFlip,
    setLoading,
    setProgress,
    setResolution,
    markMinimapDirty,
    clearMinimapDirty
  }
})
