<script setup lang="ts">
/**
 * ChunkParamsPanel — 切块（chunk）参数面板。
 *
 * ## 用途
 *
 * 沿脊线（拓扑骨架）把地块切成方块，块用于 chunk 化。面板提供**尺寸 / 位置**两类微调旋钮，
 * 并回显**覆盖率**与**补块数**，让调参是"看着指标调"而不是盲调。
 *
 * ## 两类参数
 *
 * - 尺寸：`sizeMode`（自适应/固定）、`sizeScale`、`fixedSize`、`minSize/maxSize`、`boxHeight`
 * - 位置：`stepRatio`（间距/重叠）、`phase`（沿骨架相位）、`offsetX/offsetZ`（整体平移）
 *
 * 交互对齐其它参数面板：本地 draft 与 store 隔离，改完点「应用并生成切块」才生效。
 *
 * @changelog
 * | 版本   | 变更说明                                                   | 关联                  |
 * | v1.0.0 | 初始实现：尺寸 / 位置参数 + 覆盖率与补块数回显              | REQ: navmesh-chunking |
 * | v1.1.0 | 新增「块朝向」开关（轴对齐 / 沿切线）+ 板层说明           | REQ: navmesh-chunking |
 * /@changelog
 *
 * @author v_weiqinlin
 */
import { computed, ref, watch } from 'vue'
import { Boxes, Play, RotateCcw } from 'lucide-vue-next'
import { useNavmeshStore } from '../stores/navmesh'
import { DEFAULT_CHUNK_PARAMS, type ChunkParams } from '../composables/useNavmeshChunking'

const emit = defineEmits<{
  (e: 'apply', params: ChunkParams): void
}>()

const store = useNavmeshStore()

/** 编辑中的草稿：与 store.chunkParams 隔离，点应用才写回 */
const draft = ref<ChunkParams>({ ...store.chunkParams })

watch(
  () => store.chunkParams,
  (v) => {
    draft.value = { ...v }
  },
  { deep: true }
)

function clamp(v: number, min: number, max: number): number {
  if (!Number.isFinite(v)) return min
  return Math.min(max, Math.max(min, v))
}

function apply() {
  store.setChunkParams(draft.value)
  emit('apply', { ...draft.value })
}

function reset() {
  draft.value = { ...DEFAULT_CHUNK_PARAMS }
  store.resetChunkParams()
}

const isDirty = computed(() =>
  (Object.keys(draft.value) as Array<keyof ChunkParams>).some(
    (k) => draft.value[k] !== store.chunkParams[k]
  )
)

const canApply = computed(() => store.hasNavmesh && !store.loading)

/** 覆盖率显示（百分比） */
const coveragePct = computed(() => {
  const s = store.chunkStats
  if (!s) return null
  return (s.coverageBefore * 100).toFixed(1)
})
</script>

<template>
  <!--
    背景不透明度单独调高（`glass-card` 默认只有 55%）：这个面板浮在 3D 视口正中，背后的
    navmesh 是浅蓝色、又带满屏线框，55% 时浅色透上来会把标签糊得看不清。
    图例面板用的是同一个类，但它停在右下角深色地面上，观感没问题，故不动全局值。
  -->
  <section class="glass-card bg-[rgba(17,24,39,0.95)] p-3 flex flex-col gap-3">
    <header class="flex items-center justify-between shrink-0">
      <div class="flex items-center gap-2 text-violet-300 text-[12px] font-semibold">
        <Boxes class="w-3.5 h-3.5" />
        切块参数
      </div>
      <span
        v-if="isDirty"
        class="text-[10px] px-1.5 py-0.5 rounded bg-amber-400/15 text-amber-300 border border-amber-400/30"
      >
        未应用
      </span>
    </header>

    <p class="text-[10px] text-slate-500 leading-snug">
      沿脊线（骨架）布块，块心保证可走；覆盖自检会把漏掉的可达区补上。
    </p>

    <!-- 尺寸模式 -->
    <div class="rounded-md border border-white/5 bg-white/[0.02] p-2">
      <div class="text-[10px] uppercase tracking-wider text-slate-500 mb-1.5">尺寸模式</div>
      <div class="flex gap-1.5">
        <button
          type="button"
          class="flex-1 px-2 py-1 rounded text-[11px] cursor-pointer transition-all border"
          :class="
            draft.sizeMode === 'adaptive'
              ? 'bg-violet-500/20 text-violet-200 border-violet-400/40'
              : 'text-slate-400 border-transparent hover:bg-white/5'
          "
          @click="draft.sizeMode = 'adaptive'"
        >
          自适应
        </button>
        <button
          type="button"
          class="flex-1 px-2 py-1 rounded text-[11px] cursor-pointer transition-all border"
          :class="
            draft.sizeMode === 'fixed'
              ? 'bg-violet-500/20 text-violet-200 border-violet-400/40'
              : 'text-slate-400 border-transparent hover:bg-white/5'
          "
          @click="draft.sizeMode = 'fixed'"
        >
          固定
        </button>
      </div>
    </div>

    <!-- 尺寸参数 -->
    <div class="rounded-md border border-white/5 bg-white/[0.02] p-2 space-y-2">
      <div class="text-[10px] uppercase tracking-wider text-slate-500">尺寸</div>

      <div v-if="draft.sizeMode === 'adaptive'" class="flex items-center gap-2">
        <label class="text-[11px] text-slate-300 font-mono w-20 shrink-0">sizeScale</label>
        <input
          type="range"
          min="1"
          max="3"
          step="0.05"
          :value="draft.sizeScale"
          class="flex-1 accent-violet-400 cursor-pointer"
          @input="
            draft.sizeScale = clamp(Number(($event.target as HTMLInputElement).value), 1, 3)
          "
        />
        <span class="text-[10px] text-violet-300 font-mono w-10 text-right">
          ×{{ draft.sizeScale.toFixed(2) }}
        </span>
      </div>
      <p v-if="draft.sizeMode === 'adaptive'" class="text-[10px] text-slate-500 leading-snug">
        边长 = 2 × 局部半宽 × sizeScale（越大块越富余），再夹到 [minSize, maxSize]
      </p>
      <p v-else class="text-[10px] text-slate-500 leading-snug">
        全部块统一用 fixedSize（minSize / maxSize 对固定模式不生效）
      </p>

      <div v-if="draft.sizeMode === 'fixed'" class="flex items-center gap-2">
        <label class="text-[11px] text-slate-300 font-mono w-20 shrink-0">fixedSize</label>
        <input
          type="range"
          min="1"
          max="30"
          step="0.5"
          :value="draft.fixedSize"
          class="flex-1 accent-violet-400 cursor-pointer"
          @input="
            draft.fixedSize = clamp(Number(($event.target as HTMLInputElement).value), 1, 30)
          "
        />
        <span class="text-[10px] text-violet-300 font-mono w-10 text-right">
          {{ draft.fixedSize.toFixed(1) }}m
        </span>
      </div>

      <div class="flex items-center gap-2">
        <label class="text-[11px] text-slate-300 font-mono w-20 shrink-0">minSize</label>
        <input
          type="number"
          min="0.5"
          max="20"
          step="0.5"
          :value="draft.minSize"
          class="flex-1 bg-black/30 border border-white/10 rounded px-1.5 py-0.5 text-[11px] text-slate-100 font-mono outline-none focus:border-violet-400/50"
          @input="
            draft.minSize = clamp(Number(($event.target as HTMLInputElement).value), 0.5, 20)
          "
        />
      </div>

      <div class="flex items-center gap-2">
        <label class="text-[11px] text-slate-300 font-mono w-20 shrink-0">maxSize</label>
        <input
          type="number"
          min="1"
          max="60"
          step="0.5"
          :value="draft.maxSize"
          class="flex-1 bg-black/30 border border-white/10 rounded px-1.5 py-0.5 text-[11px] text-slate-100 font-mono outline-none focus:border-violet-400/50"
          @input="
            draft.maxSize = clamp(Number(($event.target as HTMLInputElement).value), 1, 60)
          "
        />
      </div>

      <div class="flex items-center gap-2">
        <label class="text-[11px] text-slate-300 font-mono w-20 shrink-0">boxHeight</label>
        <input
          type="range"
          min="1"
          max="20"
          step="0.5"
          :value="draft.boxHeight"
          class="flex-1 accent-violet-400 cursor-pointer"
          @input="
            draft.boxHeight = clamp(Number(($event.target as HTMLInputElement).value), 1, 20)
          "
        />
        <span class="text-[10px] text-violet-300 font-mono w-10 text-right">
          {{ draft.boxHeight.toFixed(1) }}m
        </span>
      </div>
      <p class="text-[10px] text-slate-500 leading-snug">
        以落脚面为中心上下各一半；多层场景靠它区分上下层
      </p>
    </div>

    <!-- 位置 / 朝向参数 -->
    <div class="rounded-md border border-white/5 bg-white/[0.02] p-2 space-y-2">
      <div class="text-[10px] uppercase tracking-wider text-slate-500">位置 / 朝向</div>

      <!-- 块朝向 -->
      <div class="flex gap-1.5">
        <button
          type="button"
          class="flex-1 px-2 py-1 rounded text-[11px] cursor-pointer transition-all border"
          :class="
            draft.orientMode === 'axis'
              ? 'bg-violet-500/20 text-violet-200 border-violet-400/40'
              : 'text-slate-400 border-transparent hover:bg-white/5'
          "
          @click="draft.orientMode = 'axis'"
        >
          轴对齐
        </button>
        <button
          type="button"
          class="flex-1 px-2 py-1 rounded text-[11px] cursor-pointer transition-all border"
          :class="
            draft.orientMode === 'tangent'
              ? 'bg-violet-500/20 text-violet-200 border-violet-400/40'
              : 'text-slate-400 border-transparent hover:bg-white/5'
          "
          @click="draft.orientMode = 'tangent'"
        >
          沿切线
        </button>
      </div>
      <p class="text-[10px] text-slate-500 leading-snug">
        沿切线：块绕 Y 轴旋到脊线走向上（斜走廊 /
        弧形通道更贴合，补块继承就近块朝向）；轴对齐便于 AABB 索引
      </p>

      <div class="flex items-center gap-2">
        <label class="text-[11px] text-slate-300 font-mono w-20 shrink-0">stepRatio</label>
        <input
          type="range"
          min="0.2"
          max="1"
          step="0.05"
          :value="draft.stepRatio"
          class="flex-1 accent-violet-400 cursor-pointer"
          @input="
            draft.stepRatio = clamp(Number(($event.target as HTMLInputElement).value), 0.2, 1)
          "
        />
        <span class="text-[10px] text-violet-300 font-mono w-12 text-right">
          重叠{{ Math.round((1 - draft.stepRatio) * 100) }}%
        </span>
      </div>

      <div class="flex items-center gap-2">
        <label class="text-[11px] text-slate-300 font-mono w-20 shrink-0">phase</label>
        <input
          type="range"
          min="0"
          max="1"
          step="0.05"
          :value="draft.phase"
          class="flex-1 accent-violet-400 cursor-pointer"
          @input="draft.phase = clamp(Number(($event.target as HTMLInputElement).value), 0, 1)"
        />
        <span class="text-[10px] text-violet-300 font-mono w-12 text-right">
          {{ draft.phase.toFixed(2) }}
        </span>
      </div>
      <p class="text-[10px] text-slate-500 leading-snug">
        phase：沿骨架整体前后挪（0~1 倍步长）
      </p>

      <div class="flex items-center gap-2">
        <label class="text-[11px] text-slate-300 font-mono w-20 shrink-0">offset X/Z</label>
        <input
          type="number"
          step="0.5"
          :value="draft.offsetX"
          class="flex-1 bg-black/30 border border-white/10 rounded px-1.5 py-0.5 text-[11px] text-slate-100 font-mono outline-none focus:border-violet-400/50"
          @input="draft.offsetX = Number(($event.target as HTMLInputElement).value) || 0"
        />
        <input
          type="number"
          step="0.5"
          :value="draft.offsetZ"
          class="flex-1 bg-black/30 border border-white/10 rounded px-1.5 py-0.5 text-[11px] text-slate-100 font-mono outline-none focus:border-violet-400/50"
          @input="draft.offsetZ = Number(($event.target as HTMLInputElement).value) || 0"
        />
      </div>
    </div>

    <!-- 覆盖自检 -->
    <label class="flex items-center gap-2 cursor-pointer select-none">
      <input
        type="checkbox"
        :checked="draft.fillGaps"
        class="accent-violet-400 cursor-pointer"
        @change="draft.fillGaps = ($event.target as HTMLInputElement).checked"
      />
      <span class="text-[11px] text-slate-300">覆盖自检补块</span>
      <span class="text-[10px] text-slate-500">（关掉可对比骨架布块本身覆盖多少）</span>
    </label>

    <!-- 统计回显 -->
    <div
      v-if="store.chunkStats"
      class="rounded-md border border-violet-400/20 bg-violet-500/[0.06] p-2 space-y-1 font-mono text-[10px]"
    >
      <div class="flex justify-between">
        <span class="text-slate-400">块数</span>
        <span class="text-slate-100">{{ store.chunkStats.total }}</span>
      </div>
      <div class="flex justify-between">
        <span class="text-slate-400">骨架覆盖率</span>
        <span
          :class="
            store.chunkStats.coverageBefore >= 0.95 ? 'text-emerald-300' : 'text-amber-300'
          "
        >
          {{ coveragePct }}%
        </span>
      </div>
      <div class="flex justify-between">
        <span class="text-slate-400">补块数</span>
        <span :class="store.chunkStats.fillCount === 0 ? 'text-emerald-300' : 'text-amber-300'">
          {{ store.chunkStats.fillCount }}
        </span>
      </div>
      <div class="flex justify-between">
        <span class="text-slate-400">未覆盖残留</span>
        <span
          :class="store.chunkStats.uncoveredFinal === 0 ? 'text-emerald-300' : 'text-red-300'"
        >
          {{ store.chunkStats.uncoveredFinal }}
        </span>
      </div>
      <div class="flex justify-between">
        <span class="text-slate-400" title="骨架串链后的连续折线条数">脊线链数</span>
        <span class="text-slate-100">{{ store.chunkStats.chainCount }}</span>
      </div>
      <div class="flex justify-between">
        <span class="text-slate-400" title="与已有块过近而被抑制的块（骨架分叉汇聚处）"
          >抑制冗余</span
        >
        <span class="text-slate-100">{{ store.chunkStats.redundantSkipped }}</span>
      </div>
    </div>

    <div class="flex items-center gap-2 shrink-0">
      <button
        type="button"
        class="flex-1 px-2 py-1.5 rounded-md bg-violet-500/15 border border-violet-400/40 text-[11px] font-medium text-violet-200 hover:bg-violet-500/25 flex items-center justify-center gap-1.5 cursor-pointer transition-all disabled:opacity-40 disabled:cursor-not-allowed"
        :disabled="!canApply"
        @click="apply"
      >
        <Play class="w-3 h-3" />
        应用并生成切块
      </button>
      <button
        type="button"
        class="px-2 py-1.5 rounded-md bg-white/5 border border-white/10 text-[11px] text-slate-300 hover:bg-white/10 flex items-center gap-1.5 cursor-pointer transition-all"
        title="恢复默认参数"
        @click="reset"
      >
        <RotateCcw class="w-3 h-3" />
      </button>
    </div>
  </section>
</template>
